 * 역할별 맞춤 가이드:
 *   seller / host / vendor / admin / superadmin
 *
 * - visible 기본값 TRUE → 무조건 보임
 * - dismiss 시에만 숨김 (localStorage 기반)
 */

// ── 역할별 가이드 단계 정의 ──
const GUIDE_STEPS = {
    seller: [
