            .catch(() => { });
    }, []);

    // ═══════════════════════════════════════════
    // LAYER 1: Event Blocking (이벤트 차단)
    // ═══════════════════════════════════════════

    const blockEvent = useCallback((e) => {
        e.preventDefault();
        e.stopPropagation();
        return false;
    }, []);

    useEffect(() => {
        // If devtools are allowed by admin setting, skip Layer 1
        if (devtoolsAllowed) return;

