                                                    case 'name': return dir * a.label.localeCompare(b.label, 'ko');
                                                    case 'count': return dir * ((a.count || 0) - (b.count || 0));
                                                    case 'price': return dir * ((a.avgPrice || 0) - (b.avgPrice || 0));
