                                        {user.category && (
                                            <span className="flex items-center gap-1.5 text-xs text-indigo-600 bg-indigo-50 px-3 py-1.5 rounded-lg font-medium">
                                                <Tag size={12} />
                                                {user.category}
                                            </span>
