                                        <TrendingUp size={16} className="text-emerald-500" />
                                    </div>
                                    <span className="text-emerald-600 text-xs font-bold">+24%</span>
                                </div>
                                <div className="h-2 bg-gray-100 dark:bg-gray-700 rounded-full mb-1.5 w-full" />
