                                icon: <Shield size={24} />,
                                title: t('servicesSection.taxSupport'),
                                desc: t('servicesSection.taxSupportDesc'),
                                accent: 'violet'
                            },
                            {
                                icon: <MapPin size={24} />,
                                title: t('servicesSection.spaceSearch'),
                                desc: t('servicesSection.spaceSearchDesc'),
                                accent: 'emerald'
                            },
