    home_top: 'slotHomeTop', home_a: 'slotHomeA', home_a2: 'slotHomeA2',
    home_b: 'slotHomeB', home_b2: 'slotHomeB2', home_b3: 'slotHomeB3', home_b4: 'slotHomeB4',
