                    </div>

                    {/* Daily avg */}
                    <div className="bg-indigo-50 rounded-2xl p-4 flex items-center gap-6">
                        <TrendingUp size={20} className="text-indigo-500" />
                        <div className="flex-1 grid grid-cols-2 gap-4 text-sm">
