    const [showCampaignForm, setShowCampaignForm] = useState(false);
    const [editingCampaign, setEditingCampaign] = useState(null);
    const [campaignForm, setCampaignForm] = useState({ name: '', advertiser: '', budget: '', start_date: '', end_date: '', status: 'active', memo: '', target_countries: 'all' });
    const [campaignReportId, setCampaignReportId] = useState(null);
    const [assigningCampaignId, setAssigningCampaignId] = useState(null);
    const [assignSelectedAds, setAssignSelectedAds] = useState(new Set());
    const [campaignSearch, setCampaignSearch] = useState('');

    const [form, setForm] = useState({
        slot_id: 'home_a', title: '', click_url: '',
        start_date: '', end_date: '', is_active: 1, priority: 0, target_countries: 'all',
    });
    const [imageFile, setImageFile] = useState(null);
    const [imagePreview, setImagePreview] = useState(null);
    const [submitting, setSubmitting] = useState(false);

    const [adsenseForm, setAdsenseForm] = useState({ client_id: '', is_enabled: 0, slot_configs: {} });

    const showToast = useCallback((message, type = 'success') => { setToast({ message, type }); }, []);

    const fetchAds = useCallback(async () => {
        try {
            const params = new URLSearchParams();
            if (filterSlot) params.set('slot_id', filterSlot);
            if (countryFilter && countryFilter !== 'all') params.set('country', countryFilter);
            const qs = params.toString();
            const url = `${API_BASE}/list_ads.php${qs ? '?' + qs : ''}`;
            const res = await fetch(url, { credentials: 'include' });
            const data = await res.json();
            if (data.success) setAds(data.ads || []);
        } catch { showToast(t('adsPage.loadFailed'), 'error'); }
        finally { setLoading(false); }
    }, [filterSlot, countryFilter, showToast]);

    const fetchAdsenseConfig = useCallback(async () => {
        try {
            const res = await fetch(`${API_BASE}/adsense_config.php`, { credentials: 'include' });
            const data = await res.json();
            if (data.success && data.config) {
                setAdsenseForm({ client_id: data.config.client_id || '', is_enabled: data.config.is_enabled || 0, slot_configs: data.config.slot_configs || {} });
            }
        } catch { /* silent */ }
    }, []);

    const fetchCampaigns = useCallback(async () => {
        try {
            const res = await fetch(`${API_BASE}/campaign_api.php?action=list`, { credentials: 'include' });
            const data = await res.json();
            if (data.success) {
                setCampaigns(data.campaigns || []);
                setUnassignedAds(data.unassigned_ads || []);
            }
        } catch { /* silent */ }
    }, []);

    useEffect(() => { fetchAds(); }, [fetchAds]);
    useEffect(() => { fetchAdsenseConfig(); }, [fetchAdsenseConfig]);
    useEffect(() => { fetchCampaigns(); }, [fetchCampaigns]);

    const handleCampaignSubmit = async () => {
        if (!campaignForm.name.trim()) { showToast(t('adsPage.campaignNameRequired'), 'error'); return; }
        try {
            const res = await fetch(`${API_BASE}/campaign_api.php`, {
                method: 'POST', credentials: 'include',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ action: editingCampaign ? 'update' : 'create', id: editingCampaign?.id, ...campaignForm, budget: campaignForm.budget || null })
            });
            const data = await res.json();
            showToast(data.message || (data.success ? t('adsPage.done') : t('adsPage.failed')), data.success ? 'success' : 'error');
            if (data.success) { setShowCampaignForm(false); setEditingCampaign(null); setCampaignForm({ name: '', advertiser: '', budget: '', start_date: '', end_date: '', status: 'active', memo: '', target_countries: 'all' }); fetchCampaigns(); }
        } catch { showToast(t('adsPage.errorOccurred'), 'error'); }
    };

    const handleCampaignDelete = (c) => {
        setConfirmModal({
            title: t('adsPage.deleteCampaign'), message: t('adsPage.deleteCampaignMsg', { name: c.name }), type: 'danger',
            onConfirm: async () => {
                const res = await fetch(`${API_BASE}/campaign_api.php`, { method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ action: 'delete', id: c.id }) });
                const data = await res.json();
                showToast(data.message, data.success ? 'success' : 'error');
                if (data.success) fetchCampaigns();
                setConfirmModal(null);
            }
        });
    };

    const handleAssignAds = async (campaignId) => {
        if (assignSelectedAds.size === 0) { showToast(t('adsPage.selectAdsToAssign'), 'error'); return; }
        try {
            const res = await fetch(`${API_BASE}/campaign_api.php`, {
                method: 'POST', credentials: 'include',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ action: 'assign', campaign_id: campaignId, ad_ids: [...assignSelectedAds] })
            });
            const data = await res.json();
            showToast(data.message, data.success ? 'success' : 'error');
            if (data.success) { setAssigningCampaignId(null); setAssignSelectedAds(new Set()); fetchCampaigns(); fetchAds(); }
        } catch { showToast(t('adsPage.errorOccurred'), 'error'); }
    };

    const handleUnassignAd = async (adId) => {
        try {
            const res = await fetch(`${API_BASE}/campaign_api.php`, {
                method: 'POST', credentials: 'include',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ action: 'assign', campaign_id: null, ad_ids: [adId] })
            });
            const data = await res.json();
            if (data.success) { fetchCampaigns(); fetchAds(); }
        } catch { /* silent */ }
    };

    const resetForm = () => {
        setForm({ slot_id: 'home_a', title: '', click_url: '', start_date: '', end_date: '', is_active: 1, priority: 0, target_countries: 'all' });
        setImageFile(null); setImagePreview(null); setEditingAd(null);
    };

    const handleOpenForm = (ad = null) => {
        if (ad) {
            setEditingAd(ad);
            setForm({ slot_id: ad.slot_id, title: ad.title, click_url: ad.click_url || '', start_date: ad.start_date || '', end_date: ad.end_date || '', is_active: ad.is_active, priority: ad.priority || 0, target_countries: ad.target_countries || 'all' });
            setImagePreview(ad.image_url);
        } else { resetForm(); }
        setShowForm(true);
    };

    const handleImageChange = (e) => {
        const file = e.target.files[0]; if (!file) return;
        setImageFile(file);
        const reader = new FileReader();
        reader.onload = (ev) => setImagePreview(ev.target.result);
        reader.readAsDataURL(file);
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        if (!form.title.trim()) { showToast(t('adsPage.adTitleRequired'), 'error'); return; }
        if (!editingAd && !imageFile) { showToast(t('adsPage.uploadImage'), 'error'); return; }
        setSubmitting(true);
        const formData = new FormData();
        if (editingAd) formData.append('id', editingAd.id);
        Object.entries(form).forEach(([k, v]) => formData.append(k, v));
        if (imageFile) formData.append('image', imageFile);
        try {
            const url = editingAd ? `${API_BASE}/update_ad.php` : `${API_BASE}/create_ad.php`;
            const res = await fetch(url, { method: 'POST', credentials: 'include', body: formData });
            const data = await res.json();
            if (data.success) { showToast(editingAd ? t('adsPage.adUpdated') : t('adsPage.adCreated')); setShowForm(false); resetForm(); fetchAds(); }
            else showToast(data.message || t('adsPage.errorOccurred'), 'error');
        } catch { showToast(t('adsPage.serverError'), 'error'); }
        finally { setSubmitting(false); }
    };

    const handleDelete = (ad) => {
        setConfirmModal({
            title: t('adsPage.deleteAd'), message: t('adsPage.deleteAdMsg', { title: ad.title }), type: 'danger', confirmLabel: t('adsPage.deleteLabel'),
            onConfirm: async () => {
                setConfirmModal(null);
                try {
                    const res = await fetch(`${API_BASE}/delete_ad.php`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, credentials: 'include', body: JSON.stringify({ id: ad.id }) });
                    const data = await res.json();
                    if (data.success) { showToast(t('adsPage.adDeleted')); fetchAds(); }
                    else showToast(data.message || t('adsPage.failed'), 'error');
                } catch { showToast(t('adsPage.serverError'), 'error'); }
            }
        });
    };

    const handleToggleActive = async (ad) => {
        const formData = new FormData();
        formData.append('id', ad.id); formData.append('slot_id', ad.slot_id); formData.append('title', ad.title);
        formData.append('click_url', ad.click_url || ''); formData.append('start_date', ad.start_date || '');
        formData.append('end_date', ad.end_date || ''); formData.append('is_active', ad.is_active == 1 ? 0 : 1);
        formData.append('priority', ad.priority || 0);
        formData.append('target_countries', ad.target_countries || 'all');
        try {
            const res = await fetch(`${API_BASE}/update_ad.php`, { method: 'POST', credentials: 'include', body: formData });
            const data = await res.json();
            if (data.success) { showToast(ad.is_active == 1 ? t('adsPage.adDeactivated') : t('adsPage.adActivated')); fetchAds(); }
        } catch { showToast(t('adsPage.serverError'), 'error'); }
    };

    const handleCopyAd = async (ad) => {
        try {
            const res = await fetch(`${API_BASE}/copy_ad.php`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, credentials: 'include', body: JSON.stringify({ id: ad.id }) });
            const data = await res.json();
            if (data.success) { showToast(t('adsPage.adCopied')); fetchAds(); }
            else showToast(data.message || t('adsPage.copyFailed'), 'error');
        } catch { showToast(t('adsPage.serverError'), 'error'); }
    };

    const handleDateShortcut = (days) => {
        const today = new Date(); const end = new Date(today); end.setDate(end.getDate() + days);
        const fmt = (d) => d.toISOString().split('T')[0];
        setForm(prev => ({ ...prev, start_date: fmt(today), end_date: fmt(end) }));
    };

    const handleBatchEditOpen = () => {
        setBatchEditForm({
            target_countries: { enabled: false, value: 'all' },
            slot_id: { enabled: false, value: 'home_a' },
            priority: { enabled: false, value: 0 },
            start_date: { enabled: false, value: '' },
            end_date: { enabled: false, value: '' },
            is_active: { enabled: false, value: 1 },
        });
        setShowBatchEdit(true);
    };

    const handleBatchEditSubmit = async () => {
        const fields = {};
        Object.entries(batchEditForm).forEach(([key, { enabled, value }]) => {
            if (enabled) fields[key] = value;
        });
        if (Object.keys(fields).length === 0) {
            showToast(t('adsPage.noFieldsSelected'), 'error');
            return;
        }
        try {
            const res = await fetch(`${API_BASE}/batch_update_ads.php`, {
                method: 'POST', credentials: 'include',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ ids: [...selectedIds], fields })
            });
            const data = await res.json();
            if (data.success) {
                showToast(data.message || t('adsPage.batchEditSuccess'));
                setShowBatchEdit(false);
                setSelectedIds(new Set());
                fetchAds();
            } else {
                showToast(data.message || t('adsPage.errorOccurred'), 'error');
            }
        } catch { showToast(t('adsPage.serverError'), 'error'); }
    };

    const handleSaveAdsense = async () => {
        try {
            const res = await fetch(`${API_BASE}/adsense_config.php`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, credentials: 'include', body: JSON.stringify(adsenseForm) });
            const data = await res.json();
            if (data.success) showToast(t('adsPage.adsenseSaved'));
            else showToast(data.message || t('adsPage.saveFailed'), 'error');
        } catch { showToast(t('adsPage.serverError'), 'error'); }
    };

    const getSlotLabel = (slotId) => SLOT_OPTIONS.find(s => s.value === slotId)?.label || slotId;
    const getSlotPage = (slotId) => SLOT_OPTIONS.find(s => s.value === slotId)?.page || '';

    const handleReorder = async (ad, direction) => {
        const sameSlotAds = [...ads].filter(a => getSlotPage(a.slot_id) === getSlotPage(ad.slot_id)).sort((a, b) => (parseInt(a.priority) || 0) - (parseInt(b.priority) || 0));
        const idx = sameSlotAds.findIndex(a => a.id === ad.id);
        const swapIdx = direction === 'up' ? idx - 1 : idx + 1;
        if (swapIdx < 0 || swapIdx >= sameSlotAds.length) return;
        const orders = sameSlotAds.map((a, i) => {
            if (i === idx) return { id: a.id, priority: swapIdx };
            if (i === swapIdx) return { id: a.id, priority: idx };
            return { id: a.id, priority: i };
        });
        try {
            const res = await fetch(`${API_BASE}/reorder_ads.php`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, credentials: 'include', body: JSON.stringify({ orders }) });
            const data = await res.json();
            if (data.success) { showToast(t('adsPage.orderChanged')); fetchAds(); }
            else showToast(data.message || t('adsPage.changeFailed'), 'error');
        } catch { showToast(t('adsPage.serverError'), 'error'); }
    };

    // Computed
    const filteredAds = ads.filter(ad => { if (searchTerm) { const t = searchTerm.toLowerCase(); if (!ad.title.toLowerCase().includes(t) && !ad.slot_id.toLowerCase().includes(t)) return false; } return true; });
    const grouped = {};
    filteredAds.forEach(ad => { const page = getSlotPage(ad.slot_id); if (!grouped[page]) grouped[page] = []; grouped[page].push(ad); });
    Object.values(grouped).forEach(arr => arr.sort((a, b) => (parseInt(a.priority) || 0) - (parseInt(b.priority) || 0)));

    const totalImpressions = ads.reduce((s, a) => s + parseInt(a.view_count || 0), 0);
    const totalClicks = ads.reduce((s, a) => s + parseInt(a.click_count || 0), 0);
    const activeCount = ads.filter(a => a.is_active == 1).length;
    const overallCTR = totalImpressions > 0 ? ((totalClicks / totalImpressions) * 100).toFixed(2) : '0.00';

    const sortedAds = [...ads].sort((a, b) => {
        if (sortBy === 'views') return parseInt(b.view_count || 0) - parseInt(a.view_count || 0);
        if (sortBy === 'clicks') return parseInt(b.click_count || 0) - parseInt(a.click_count || 0);
        if (sortBy === 'ctr') {
            const ca = parseInt(a.view_count || 0) > 0 ? parseInt(a.click_count || 0) / parseInt(a.view_count || 0) : 0;
            const cb = parseInt(b.view_count || 0) > 0 ? parseInt(b.click_count || 0) / parseInt(b.view_count || 0) : 0;
            return cb - ca;
        }
        return new Date(b.created_at || 0) - new Date(a.created_at || 0);
    });

    const usedSlots = new Set(ads.filter(a => a.is_active == 1).map(a => a.slot_id));
    const usedSlotCount = [...usedSlots].filter(s => SLOT_OPTIONS.some(o => o.value === s)).length;

    return (
        <div className="max-w-7xl mx-auto">
            {/* Header */}
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
                <div className="flex items-center gap-3">
                    <div className="w-10 h-10 bg-gradient-to-br from-amber-500 to-orange-600 rounded-xl flex items-center justify-center">
                        <Megaphone className="text-white" size={22} />
                    </div>
                    <div>
                        <h1 className="text-2xl md:text-3xl font-extrabold text-gray-900">{t('adsPage.title')}</h1>
                        <p className="text-sm text-gray-500">{t('adsPage.subtitle')}</p>
                    </div>
                </div>
                <div className="flex items-center gap-2">
                    <button onClick={() => setShowAdSenseSettings(!showAdSenseSettings)} className="flex items-center gap-2 px-4 py-2.5 bg-gray-100 text-gray-700 rounded-xl font-bold text-sm hover:bg-gray-200 transition-colors">
                        <Settings size={16} /> AdSense
                    </button>
                    <button onClick={() => { setActiveTab('manage'); handleOpenForm(); }} className="flex items-center gap-2 px-4 py-2.5 bg-indigo-600 text-white rounded-xl font-bold text-sm hover:bg-indigo-700 transition-colors shadow-lg shadow-indigo-200">
                        <Plus size={16} /> {t('adsPage.addAd')}
                    </button>
                </div>
            </div>

            {/* Tabs */}
            <div className="flex gap-1 mb-6 bg-gray-100 dark:bg-gray-800 rounded-xl p-1">
                {[{ key: 'dashboard', label: t('adsPage.tabDashboard'), icon: <BarChart3 size={15} /> }, { key: 'campaigns', label: t('adsPage.tabCampaigns'), icon: <Layers size={15} /> }, { key: 'manage', label: t('adsPage.tabManage'), icon: <Settings size={15} /> }].map(tab => (
                    <button key={tab.key} onClick={() => setActiveTab(tab.key)} className={`flex-1 flex items-center justify-center gap-2 px-4 py-2.5 rounded-lg text-sm font-bold transition-all ${activeTab === tab.key ? 'bg-white dark:bg-gray-700 text-gray-900 dark:text-white shadow-sm' : 'text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-300'}`}>
                        {tab.icon} {tab.label}
                    </button>
                ))}
            </div>

            {/* ===== DASHBOARD TAB ===== */}
            {activeTab === 'dashboard' && (() => {
                // Pre-compute infographic data
                const maxViews = Math.max(...ads.map(a => parseInt(a.view_count || 0)), 1);
                const maxClicks = Math.max(...ads.map(a => parseInt(a.click_count || 0)), 1);
                const slotPct = SLOT_OPTIONS.length > 0 ? Math.round((usedSlotCount / SLOT_OPTIONS.length) * 100) : 0;
                const activePct = ads.length > 0 ? Math.round((activeCount / ads.length) * 100) : 0;
                const circumference = 2 * Math.PI * 40;

                // Page distribution
                const pageDistribution = {};
                ads.forEach(a => { const p = getSlotPage(a.slot_id) || t('adsPage.other'); pageDistribution[p] = (pageDistribution[p] || 0) + 1; });
                const pageColors = ['#6366f1', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#ec4899'];
                const pageEntries = Object.entries(pageDistribution).sort((a, b) => b[1] - a[1]);
                const totalForDist = Math.max(pageEntries.reduce((s, [, c]) => s + c, 0), 1);

                // Top 5 for bar chart
                const top5 = sortedAds.slice(0, 5);

                return (
                    <div className="space-y-6">
                        {/* KPI Cards with circular progress */}
                        <div className="grid grid-cols-2 md:grid-cols-5 gap-3">
                            {[
                                { label: t('adsPage.totalAds'), value: ads.length, suffix: t('adsPage.countSuffix'), pct: 100, icon: <Megaphone size={16} />, gradient: ['#6366f1', '#8b5cf6'] },
                                { label: t('adsPage.activeAds'), value: activeCount, suffix: t('adsPage.countSuffix'), pct: activePct, icon: <Eye size={16} />, gradient: ['#10b981', '#14b8a6'] },
                                { label: t('adsPage.totalImpressions'), value: totalImpressions.toLocaleString(), suffix: '', pct: 100, icon: <BarChart3 size={16} />, gradient: ['#3b82f6', '#6366f1'] },
                                { label: t('adsPage.totalClicks'), value: totalClicks.toLocaleString(), suffix: '', pct: totalImpressions > 0 ? Math.min(Math.round((totalClicks / totalImpressions) * 100 * 10), 100) : 0, icon: <MousePointer size={16} />, gradient: ['#f59e0b', '#ef4444'] },
                                { label: t('adsPage.overallCTR'), value: overallCTR, suffix: '%', pct: Math.min(parseFloat(overallCTR) * 10, 100), icon: <TrendingUp size={16} />, gradient: ['#8b5cf6', '#a855f7'] },
                            ].map((stat, i) => (
                                <div key={i} className="bg-white rounded-2xl p-4 border border-gray-100 shadow-sm hover:shadow-md transition-all group">
                                    <div className="flex items-start justify-between mb-3">
                                        <div className="relative w-12 h-12">
                                            <svg viewBox="0 0 100 100" className="transform -rotate-90 w-full h-full">
                                                <circle cx="50" cy="50" r="40" stroke="#f3f4f6" strokeWidth="8" fill="none" />
                                                <circle cx="50" cy="50" r="40" stroke={`url(#grad-${i})`} strokeWidth="8" fill="none"
                                                    strokeDasharray={circumference} strokeDashoffset={circumference * (1 - stat.pct / 100)}
                                                    strokeLinecap="round" className="transition-all duration-1000" />
                                                <defs><linearGradient id={`grad-${i}`} x1="0%" y1="0%" x2="100%" y2="0%">
                                                    <stop offset="0%" stopColor={stat.gradient[0]} /><stop offset="100%" stopColor={stat.gradient[1]} />
                                                </linearGradient></defs>
                                            </svg>
                                            <div className="absolute inset-0 flex items-center justify-center text-gray-600">{stat.icon}</div>
                                        </div>
                                        <span className="text-[10px] font-bold text-gray-400 bg-gray-50 px-1.5 py-0.5 rounded-md">{stat.pct}%</span>
                                    </div>
                                    <p className="text-2xl font-extrabold text-gray-900 leading-tight">{stat.value}<span className="text-sm text-gray-400 font-bold ml-0.5">{stat.suffix}</span></p>
                                    <p className="text-[11px] text-gray-400 font-medium mt-0.5">{stat.label}</p>
                                </div>
                            ))}
                        </div>

                        {/* Middle Row: Donut Chart + Page Distribution + Top 5 Bar Chart */}
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                            {/* Donut Chart — Slot Utilization */}
                            <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-5">
                                <h3 className="text-xs font-bold text-gray-500 uppercase tracking-wider mb-4 flex items-center gap-2">
                                    <Monitor size={14} className="text-indigo-500" /> {t('adsPage.slotUtilization')}
                                </h3>
                                <div className="flex items-center justify-center mb-4">
                                    <div className="relative w-36 h-36">
                                        <svg viewBox="0 0 100 100" className="w-full h-full transform -rotate-90">
                                            <circle cx="50" cy="50" r="38" stroke="#f3f4f6" strokeWidth="12" fill="none" />
                                            <circle cx="50" cy="50" r="38" stroke="url(#donut-grad)" strokeWidth="12" fill="none"
                                                strokeDasharray={2 * Math.PI * 38} strokeDashoffset={2 * Math.PI * 38 * (1 - slotPct / 100)}
                                                strokeLinecap="round" className="transition-all duration-1000" />
                                            <defs><linearGradient id="donut-grad" x1="0%" y1="0%" x2="100%" y2="0%">
                                                <stop offset="0%" stopColor="#6366f1" /><stop offset="100%" stopColor="#a855f7" />
                                            </linearGradient></defs>
                                        </svg>
                                        <div className="absolute inset-0 flex flex-col items-center justify-center">
                                            <span className="text-3xl font-black text-gray-900">{slotPct}%</span>
                                            <span className="text-[10px] text-gray-400 font-medium">{usedSlotCount}/{SLOT_OPTIONS.length}</span>
                                        </div>
                                    </div>
                                </div>
                                <div className="flex items-center justify-center gap-4 text-[11px]">
                                    <span className="flex items-center gap-1.5"><span className="w-2.5 h-2.5 rounded-full bg-indigo-500" /> {t('adsPage.inUse')} {usedSlotCount}</span>
                                    <span className="flex items-center gap-1.5"><span className="w-2.5 h-2.5 rounded-full bg-gray-200" /> {t('adsPage.unused')} {SLOT_OPTIONS.length - usedSlotCount}</span>
                                </div>
                            </div>

                            {/* Page Distribution */}
                            <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-5">
                                <h3 className="text-xs font-bold text-gray-500 uppercase tracking-wider mb-4 flex items-center gap-2">
                                    <Smartphone size={14} className="text-emerald-500" /> {t('adsPage.adDistribution')}
                                </h3>
                                {/* Stacked bar */}
                                <div className="flex rounded-full h-4 overflow-hidden mb-4">
                                    {pageEntries.map(([page, count], i) => (
                                        <div key={page} style={{ width: `${(count / totalForDist) * 100}%`, backgroundColor: pageColors[i % pageColors.length] }}
                                            className="transition-all duration-500 first:rounded-l-full last:rounded-r-full" title={`${page}: ${count}`} />
                                    ))}
                                </div>
                                <div className="space-y-2.5">
                                    {pageEntries.map(([page, count], i) => (
                                        <div key={page} className="flex items-center gap-2.5">
                                            <span className="w-2.5 h-2.5 rounded-full flex-shrink-0" style={{ backgroundColor: pageColors[i % pageColors.length] }} />
                                            <span className="text-xs text-gray-600 font-medium flex-1 truncate">{page}</span>
                                            <span className="text-xs font-bold text-gray-900">{count}</span>
                                            <span className="text-[10px] text-gray-400">{Math.round((count / totalForDist) * 100)}%</span>
                                        </div>
                                    ))}
                                </div>
                            </div>

                            {/* Top 5 Bar Chart */}
                            <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-5">
                                <h3 className="text-xs font-bold text-gray-500 uppercase tracking-wider mb-4 flex items-center gap-2">
                                    <TrendingUp size={14} className="text-orange-500" /> {t('adsPage.top5Ads')}
                                    <span className="ml-auto text-[10px] text-gray-400 font-medium normal-case">
                                        {sortBy === 'views' ? t('adsPage.sortByViews') : sortBy === 'clicks' ? t('adsPage.sortByClicks') : t('adsPage.sortByCTR')}
                                    </span>
                                </h3>
                                <div className="space-y-3">
                                    {top5.length === 0 ? (
                                        <p className="text-xs text-gray-400 text-center py-8">{t('adsPage.noData')}</p>
                                    ) : top5.map((ad, idx) => {
                                        const v = parseInt(ad.view_count || 0);
                                        const c = parseInt(ad.click_count || 0);
                                        const val = sortBy === 'views' ? v : sortBy === 'clicks' ? c : (v > 0 ? (c / v) * 100 : 0);
                                        const maxVal = sortBy === 'views' ? maxViews : sortBy === 'clicks' ? maxClicks : Math.max(...ads.map(a => { const vv = parseInt(a.view_count || 0); return vv > 0 ? parseInt(a.click_count || 0) / vv * 100 : 0; }), 1);
                                        const barPct = Math.max((val / maxVal) * 100, 2);
                                        const barColors = ['bg-indigo-500', 'bg-violet-500', 'bg-blue-500', 'bg-emerald-500', 'bg-amber-500'];
                                        return (
                                            <div key={ad.id} className="group">
                                                <div className="flex items-center gap-2 mb-1">
                                                    <span className="text-[10px] font-black text-gray-300 w-4">{idx + 1}</span>
                                                    <span className="text-xs font-bold text-gray-700 truncate flex-1">{ad.title}</span>
                                                    <span className="text-xs font-extrabold text-gray-900">{sortBy === 'ctr' ? val.toFixed(2) + '%' : val.toLocaleString()}</span>
                                                </div>
                                                <div className="ml-6 h-2 bg-gray-100 rounded-full overflow-hidden">
                                                    <div className={`h-full rounded-full ${barColors[idx]} transition-all duration-700`} style={{ width: `${barPct}%` }} />
                                                </div>
                                            </div>
                                        );
                                    })}
                                </div>
                            </div>
                        </div>

                        {/* Slot Grid — Visual */}
                        <div className="bg-white dark:bg-gray-800/50 rounded-2xl border border-gray-100 dark:border-gray-700/50 shadow-sm p-5">
                            <h3 className="text-xs font-bold text-gray-500 dark:text-gray-400 uppercase tracking-wider mb-3 flex items-center gap-2">
                                <Monitor size={14} className="text-indigo-500 dark:text-indigo-400" /> {t('adsPage.allSlotStatus')}
                                <span className="text-[10px] text-gray-400 dark:text-gray-500 font-medium normal-case ml-auto">{t('adsPage.activeSlots', { count: usedSlotCount })}</span>
                            </h3>
                            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-2">
                                {SLOT_OPTIONS.map(slot => {
                                    const slotAd = ads.find(a => a.slot_id === slot.value && a.is_active == 1);
                                    const slotViews = ads.filter(a => a.slot_id === slot.value).reduce((s, a) => s + parseInt(a.view_count || 0), 0);
                                    return (
                                        <div key={slot.value} className={`relative rounded-xl border p-3 transition-all hover:shadow-sm ${slotAd ? 'bg-gradient-to-br from-indigo-500/10 to-violet-500/10 border-indigo-500/30 dark:from-indigo-500/20 dark:to-violet-500/20 dark:border-indigo-400/30' : 'bg-gray-50 dark:bg-gray-700/30 border-gray-200 dark:border-gray-600/40'}`}>
                                            <div className="flex items-center gap-2 mb-1">
                                                <span className={`w-2 h-2 rounded-full ${slotAd ? 'bg-emerald-500 animate-pulse' : 'bg-gray-300 dark:bg-gray-600'}`} />
                                                <span className={`text-[11px] font-bold truncate ${slotAd ? 'text-indigo-700 dark:text-indigo-300' : 'text-gray-400 dark:text-gray-500'}`}>{slot.label.split(' (')[0]}</span>
                                            </div>
                                            {slotAd ? (
                                                <div className="text-[10px] text-gray-500 dark:text-gray-400 pl-4">
                                                    <span className="font-medium">{slotAd.title.substring(0, 12)}{slotAd.title.length > 12 ? '..' : ''}</span>
                                                    <br /><span className="text-indigo-500 dark:text-indigo-400 font-bold">{slotViews.toLocaleString()} views</span>
                                                </div>
                                            ) : (
                                                <p className="text-[10px] text-gray-300 dark:text-gray-600 pl-4">{t('adsPage.empty')}</p>
                                            )}
                                        </div>
                                    );
                                })}
                            </div>
                        </div>

                        {/* Performance Table with visual bars */}
                        <div className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden">
                            <div className="p-5 border-b border-gray-100 flex items-center justify-between">
                                <h3 className="text-sm font-bold text-gray-700 flex items-center gap-2"><TrendingUp size={16} className="text-indigo-500" /> {t('adsPage.adPerformanceRank')}</h3>
                                <div className="flex gap-1">
                                    {[{ key: 'views', label: t('adsPage.sortViews') }, { key: 'clicks', label: t('adsPage.sortClicks') }, { key: 'ctr', label: t('adsPage.sortCTR') }].map(s => (
                                        <button key={s.key} onClick={() => setSortBy(s.key)} className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-colors ${sortBy === s.key ? 'bg-indigo-100 text-indigo-700' : 'bg-gray-50 text-gray-400 hover:bg-gray-100'}`}>{s.label}</button>
                                    ))}
                                </div>
                            </div>
                            {sortedAds.length === 0 ? (
                                <div className="text-center py-12 text-gray-400"><Megaphone size={32} className="mx-auto mb-2 text-gray-300" /><p className="text-sm font-medium">{t('adsPage.noAdsRegistered')}</p></div>
                            ) : (
                                <div className="overflow-x-auto">
                                    <table className="w-full text-sm">
                                        <thead><tr className="bg-gray-50 text-gray-500 text-xs font-bold uppercase">
                                            <th className="text-left px-5 py-3">#</th><th className="text-left px-3 py-3">{t('adsPage.ad')}</th><th className="text-left px-3 py-3">{t('adsPage.slot')}</th>
                                            <th className="text-left px-3 py-3 min-w-[140px]">{t('adsPage.impressions')}</th><th className="text-left px-3 py-3 min-w-[120px]">{t('adsPage.clicks')}</th><th className="text-right px-3 py-3">CTR</th>
                                            <th className="text-center px-3 py-3">{t('adsPage.status')}</th><th className="text-center px-3 py-3">{t('adsPage.action')}</th>
                                        </tr></thead>
                                        <tbody>
                                            {sortedAds.map((ad, idx) => {
                                                const views = parseInt(ad.view_count || 0);
                                                const clicks = parseInt(ad.click_count || 0);
                                                const ctr = views > 0 ? ((clicks / views) * 100).toFixed(2) : '0.00';
                                                const viewPct = Math.max((views / maxViews) * 100, 0);
                                                const clickPct = Math.max((clicks / maxClicks) * 100, 0);
                                                return (
                                                    <tr key={ad.id} className="border-t border-gray-50 hover:bg-gray-50/50 transition-colors">
                                                        <td className="px-5 py-3">
                                                            <span className={`inline-flex items-center justify-center w-6 h-6 rounded-lg text-[10px] font-black ${idx < 3 ? 'bg-gradient-to-br from-amber-400 to-orange-500 text-white' : 'bg-gray-100 text-gray-400'}`}>{idx + 1}</span>
                                                        </td>
                                                        <td className="px-3 py-3"><div className="flex items-center gap-3">{ad.image_url && <img src={ad.image_url} alt="" className="w-10 h-7 object-cover rounded-lg border" />}<span className="font-bold text-gray-900 truncate max-w-[160px]">{ad.title}</span></div></td>
                                                        <td className="px-3 py-3 text-xs text-gray-400">{getSlotLabel(ad.slot_id).split(' (')[0]}</td>
                                                        <td className="px-3 py-3">
                                                            <div className="flex items-center gap-2">
                                                                <span className="text-xs font-bold text-gray-700 w-14 text-right">{views.toLocaleString()}</span>
                                                                <div className="flex-1 h-2 bg-gray-100 rounded-full overflow-hidden"><div className="h-full bg-gradient-to-r from-blue-400 to-indigo-500 rounded-full transition-all duration-500" style={{ width: `${viewPct}%` }} /></div>
                                                            </div>
                                                        </td>
                                                        <td className="px-3 py-3">
                                                            <div className="flex items-center gap-2">
                                                                <span className="text-xs font-bold text-emerald-600 w-10 text-right">{clicks.toLocaleString()}</span>
                                                                <div className="flex-1 h-2 bg-gray-100 rounded-full overflow-hidden"><div className="h-full bg-gradient-to-r from-emerald-400 to-teal-500 rounded-full transition-all duration-500" style={{ width: `${clickPct}%` }} /></div>
                                                            </div>
                                                        </td>
                                                        <td className="px-3 py-3 text-right font-bold text-indigo-600">{ctr}%</td>
                                                        <td className="px-3 py-3 text-center"><span className={`px-2 py-0.5 rounded-full text-[10px] font-bold ${ad.is_active == 1 ? 'bg-emerald-100 text-emerald-700' : 'bg-gray-100 text-gray-500'}`}>{ad.is_active == 1 ? t('adsPage.active') : t('adsPage.inactive')}</span></td>
                                                        <td className="px-3 py-3 text-center"><div className="flex items-center justify-center gap-1">
                                                            <button onClick={() => setReportAd(ad)} className="p-1.5 rounded-lg bg-violet-50 text-violet-600 hover:bg-violet-100" title={t('adsPage.reportTitle')}><BarChart3 size={13} /></button>
                                                            <button onClick={() => handleToggleActive(ad)} className="p-1.5 rounded-lg bg-gray-50 text-gray-500 hover:bg-gray-100" title={ad.is_active == 1 ? t('adsPage.deactivate') : t('adsPage.activate')}>{ad.is_active == 1 ? <EyeOff size={13} /> : <Eye size={13} />}</button>
                                                            <button onClick={() => { setActiveTab('manage'); handleOpenForm(ad); }} className="p-1.5 rounded-lg bg-indigo-50 text-indigo-600 hover:bg-indigo-100" title={t('adsPage.edit')}><Edit3 size={13} /></button>
                                                        </div></td>
                                                    </tr>
                                                );
                                            })}
                                        </tbody>
                                    </table>
                                </div>
                            )}
                        </div>
                    </div>
                );
            })()}

            {/* ===== CAMPAIGNS TAB ===== */}
            {activeTab === 'campaigns' && (() => {
                const statusColors = { active: 'bg-emerald-100 text-emerald-700 dark:bg-emerald-500/20 dark:text-emerald-400', paused: 'bg-amber-100 text-amber-700 dark:bg-amber-500/20 dark:text-amber-400', completed: 'bg-gray-200 text-gray-600 dark:bg-gray-700 dark:text-gray-400' };
                const statusLabels = { active: t('adsPage.statusActive'), paused: t('adsPage.statusPaused'), completed: t('adsPage.statusCompleted') };
                const statusIcons = { active: <Play size={11} />, paused: <Pause size={11} />, completed: <Check size={11} /> };
                const filteredCampaigns = campaigns.filter(c => !campaignSearch || c.name.toLowerCase().includes(campaignSearch.toLowerCase()) || (c.advertiser || '').toLowerCase().includes(campaignSearch.toLowerCase()));

                // Get ads belonging to a campaign
                const getCampaignAds = (cid) => ads.filter(a => a.campaign_id == cid);

                return (
                    <div className="space-y-4">
                        {/* Campaign Header */}
                        <div className="flex items-center gap-3">
                            <div className="relative flex-1">
                                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={16} />
                                <input value={campaignSearch} onChange={e => setCampaignSearch(e.target.value)} placeholder={t('adsPage.searchCampaign')} className="w-full pl-10 pr-4 py-2.5 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl text-sm focus:ring-2 focus:ring-indigo-500 outline-none" />
                            </div>
                            <button onClick={() => { setEditingCampaign(null); setCampaignForm({ name: '', advertiser: '', budget: '', start_date: '', end_date: '', status: 'active', memo: '' }); setShowCampaignForm(true); }}
                                className="flex items-center gap-2 px-4 py-2.5 bg-indigo-600 text-white rounded-xl font-bold text-sm hover:bg-indigo-700 transition-colors whitespace-nowrap">
                                <Plus size={16} /> {t('adsPage.createCampaign')}
                            </button>
                        </div>

                        {/* Campaign Form Modal */}
                        {showCampaignForm && (
                            <div className="bg-white dark:bg-gray-800 rounded-2xl border border-indigo-200 dark:border-indigo-500/30 shadow-lg p-5">
                                <h3 className="text-sm font-extrabold text-gray-900 dark:text-white mb-4">{editingCampaign ? t('adsPage.editCampaign') : t('adsPage.newCampaign')}</h3>
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                                    <div><label className="text-xs font-bold text-gray-500 dark:text-gray-400 block mb-1">{t('adsPage.campaignName')}</label><input value={campaignForm.name} onChange={e => setCampaignForm({ ...campaignForm, name: e.target.value })} className="w-full px-3 py-2 bg-gray-50 dark:bg-gray-700 border border-gray-200 dark:border-gray-600 rounded-lg text-sm" placeholder={t('adsPage.campaignNamePlaceholder')} /></div>
                                    <div><label className="text-xs font-bold text-gray-500 dark:text-gray-400 block mb-1">{t('adsPage.advertiser')}</label><input value={campaignForm.advertiser} onChange={e => setCampaignForm({ ...campaignForm, advertiser: e.target.value })} className="w-full px-3 py-2 bg-gray-50 dark:bg-gray-700 border border-gray-200 dark:border-gray-600 rounded-lg text-sm" placeholder={t('adsPage.advertiserPlaceholder')} /></div>
                                    <div><label className="text-xs font-bold text-gray-500 dark:text-gray-400 block mb-1">{t('adsPage.budget')}</label><input type="number" value={campaignForm.budget} onChange={e => setCampaignForm({ ...campaignForm, budget: e.target.value })} className="w-full px-3 py-2 bg-gray-50 dark:bg-gray-700 border border-gray-200 dark:border-gray-600 rounded-lg text-sm" placeholder={t('adsPage.budgetOptional')} /></div>
                                    <div><label className="text-xs font-bold text-gray-500 dark:text-gray-400 block mb-1">{t('adsPage.campaignStatus')}</label><select value={campaignForm.status} onChange={e => setCampaignForm({ ...campaignForm, status: e.target.value })} className="w-full px-3 py-2 bg-gray-50 dark:bg-gray-700 border border-gray-200 dark:border-gray-600 rounded-lg text-sm"><option value="active">{t('adsPage.statusActive')}</option><option value="paused">{t('adsPage.statusPaused')}</option><option value="completed">{t('adsPage.statusCompleted')}</option></select></div>
                                    <div><label className="text-xs font-bold text-gray-500 dark:text-gray-400 block mb-1">{t('adsPage.startDate')}</label><input type="date" value={campaignForm.start_date} onChange={e => setCampaignForm({ ...campaignForm, start_date: e.target.value })} className="w-full px-3 py-2 bg-gray-50 dark:bg-gray-700 border border-gray-200 dark:border-gray-600 rounded-lg text-sm" /></div>
                                    <div><label className="text-xs font-bold text-gray-500 dark:text-gray-400 block mb-1">{t('adsPage.endDate')}</label><input type="date" value={campaignForm.end_date} onChange={e => setCampaignForm({ ...campaignForm, end_date: e.target.value })} className="w-full px-3 py-2 bg-gray-50 dark:bg-gray-700 border border-gray-200 dark:border-gray-600 rounded-lg text-sm" /></div>
                                    <div className="md:col-span-2"><label className="text-xs font-bold text-gray-500 dark:text-gray-400 block mb-1">{t('adsPage.memo')}</label><textarea value={campaignForm.memo} onChange={e => setCampaignForm({ ...campaignForm, memo: e.target.value })} rows={2} className="w-full px-3 py-2 bg-gray-50 dark:bg-gray-700 border border-gray-200 dark:border-gray-600 rounded-lg text-sm resize-none" /></div>
                                    <div className="md:col-span-2">
                                        <label className="text-xs font-bold text-gray-500 dark:text-gray-400 block mb-1.5">{t('adsPage.targetCountries', '타겟 국가')}</label>
                                        <div className="flex flex-wrap gap-1.5">
                                            <button type="button" onClick={() => setCampaignForm({ ...campaignForm, target_countries: 'all' })} className={`px-2.5 py-1 rounded-lg text-xs font-bold transition-all ${campaignForm.target_countries === 'all' ? 'bg-indigo-600 text-white' : 'bg-gray-100 dark:bg-gray-700 text-gray-500 dark:text-gray-400 hover:bg-gray-200'}`}>🌍 {t('adsPage.allCountriesTarget', '전체')}</button>
                                            {COUNTRY_OPTIONS.map(co => {
                                                const countries = campaignForm.target_countries || 'all';
                                                const arr = countries === 'all' ? [] : countries.split(',');
                                                const isOn = countries === 'all' || arr.includes(co.code);
                                                const toggle = () => {
                                                    if (countries === 'all') {
                                                        setCampaignForm({ ...campaignForm, target_countries: co.code });
                                                    } else if (isOn) {
                                                        const next = arr.filter(c => c !== co.code);
                                                        setCampaignForm({ ...campaignForm, target_countries: next.length ? next.join(',') : 'all' });
                                                    } else {
                                                        setCampaignForm({ ...campaignForm, target_countries: [...arr, co.code].join(',') });
                                                    }
                                                };
                                                return (
                                                    <button key={co.code} type="button" onClick={toggle} className={`px-2.5 py-1 rounded-lg text-xs font-bold transition-all ${countries !== 'all' && isOn ? 'bg-indigo-600 text-white' : 'bg-gray-100 dark:bg-gray-700 text-gray-500 dark:text-gray-400 hover:bg-gray-200'}`}>{co.flag} {co.label}</button>
                                                );
                                            })}
                                        </div>
                                    </div>
                                </div>
                                <div className="flex justify-end gap-2 mt-4">
                                    <button onClick={() => { setShowCampaignForm(false); setEditingCampaign(null); }} className="px-4 py-2 bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300 rounded-lg text-sm font-bold">{t('adsPage.cancel')}</button>
                                    <button onClick={handleCampaignSubmit} className="px-4 py-2 bg-indigo-600 text-white rounded-lg text-sm font-bold hover:bg-indigo-700">{editingCampaign ? t('adsPage.update') : t('adsPage.create')}</button>
                                </div>
                            </div>
                        )}

                        {/* Campaign List */}
                        {filteredCampaigns.length === 0 && (
                            <div className="text-center py-16 bg-white dark:bg-gray-800 rounded-2xl border border-gray-100 dark:border-gray-700">
                                <Layers className="mx-auto text-gray-300 dark:text-gray-600 mb-3" size={40} />
                                <p className="text-sm text-gray-400 font-medium">{t('adsPage.noCampaigns')}</p>
                                <p className="text-xs text-gray-300 dark:text-gray-600 mt-1">{t('adsPage.noCampaignsDesc')}</p>
                            </div>
                        )}

                        {filteredCampaigns.map(c => {
                            const cAds = getCampaignAds(c.id);
                            const isExpanded = expandedCampaign === c.id;
                            const totalViews = parseInt(c.total_views || 0);
                            const totalClicks = parseInt(c.total_clicks || 0);
                            const ctr = totalViews > 0 ? ((totalClicks / totalViews) * 100).toFixed(2) : '0.00';

                            return (
                                <div key={c.id} className="bg-white dark:bg-gray-800 rounded-2xl border border-gray-100 dark:border-gray-700 shadow-sm overflow-hidden transition-all hover:shadow-md">
                                    {/* Campaign Row */}
                                    <div className="px-5 py-4 cursor-pointer" onClick={() => setExpandedCampaign(isExpanded ? null : c.id)}>
                                        <div className="flex items-center gap-3">
                                            <button className="text-gray-400 dark:text-gray-500 transition-transform" style={{ transform: isExpanded ? 'rotate(180deg)' : 'rotate(0deg)' }}>
                                                <ChevronDown size={18} />
                                            </button>
                                            <div className="flex-1 min-w-0">
                                                <div className="flex items-center gap-2">
                                                    <h4 className="text-sm font-extrabold text-gray-900 dark:text-white truncate">{c.name}</h4>
                                                    <span className={`px-2 py-0.5 rounded-full text-[10px] font-bold inline-flex items-center gap-1 ${statusColors[c.status] || ''}`}>{statusIcons[c.status]} {statusLabels[c.status]}</span>
                                                    <span className="text-[10px] text-gray-400 dark:text-gray-500 bg-gray-100 dark:bg-gray-700 px-2 py-0.5 rounded-lg font-bold">{t('adsPage.adsCount', { count: c.ad_count || 0 })}</span>
                                                </div>
                                                <div className="flex items-center gap-3 mt-1">
                                                    {c.advertiser && <span className="text-[11px] text-gray-400 dark:text-gray-500">{c.advertiser}</span>}
                                                    {c.start_date && <span className="text-[10px] text-gray-300 dark:text-gray-600">{c.start_date} ~ {c.end_date || t('adsPage.ongoing')}</span>}
                                                    {c.target_countries && c.target_countries !== 'all' && (
                                                        <span className="flex items-center gap-0.5">
                                                            {c.target_countries.split(',').map(cc => {
                                                                const opt = COUNTRY_OPTIONS.find(o => o.code === cc);
                                                                return opt ? <span key={cc} className="text-[11px] bg-indigo-50 dark:bg-indigo-500/10 text-indigo-600 dark:text-indigo-400 px-1.5 py-0.5 rounded-md font-bold">{opt.flag}</span> : null;
                                                            })}
                                                        </span>
                                                    )}
                                                </div>
                                            </div>
                                            <div className="hidden md:flex items-center gap-5 text-right">
                                                <div><p className="text-sm font-extrabold text-gray-900 dark:text-white">{totalViews.toLocaleString()}</p><p className="text-[10px] text-gray-400 font-medium">{t('adsPage.impressionLabel')}</p></div>
                                                <div><p className="text-sm font-extrabold text-emerald-600 dark:text-emerald-400">{totalClicks.toLocaleString()}</p><p className="text-[10px] text-gray-400 font-medium">{t('adsPage.clickLabel')}</p></div>
                                                <div><p className="text-sm font-extrabold text-indigo-600 dark:text-indigo-400">{ctr}%</p><p className="text-[10px] text-gray-400 font-medium">CTR</p></div>
                                            </div>
                                        </div>
                                    </div>

                                    {/* Expanded Content */}
                                    {isExpanded && (
                                        <div className="border-t border-gray-100 dark:border-gray-700">
                                            {/* Ads in campaign */}
                                            {cAds.length > 0 ? (
                                                <div className="px-5 py-3">
                                                    <div className="space-y-2">
                                                        {cAds.map(a => {
                                                            const av = parseInt(a.view_count || 0);
                                                            const ac = parseInt(a.click_count || 0);
                                                            const aCtr = av > 0 ? ((ac / av) * 100).toFixed(2) : '0.00';
                                                            const slotLabel = SLOT_OPTIONS.find(s => s.value === a.slot_id)?.label?.split(' (')[0] || a.slot_id;
                                                            return (
                                                                <div key={a.id} className="flex items-center gap-3 p-3 rounded-xl bg-gray-50 dark:bg-gray-700/40 hover:bg-gray-100 dark:hover:bg-gray-700/60 transition-colors">
                                                                    {a.image_url && <img src={a.image_url} alt="" className="w-12 h-8 object-cover rounded-lg border border-gray-200 dark:border-gray-600 flex-shrink-0" />}
                                                                    <div className="flex-1 min-w-0">
                                                                        <p className="text-xs font-bold text-gray-800 dark:text-gray-200 truncate">{a.title}</p>
                                                                        <p className="text-[10px] text-gray-400 dark:text-gray-500">{slotLabel}</p>
                                                                    </div>
                                                                    <div className="flex items-center gap-4 text-right">
                                                                        <div><span className="text-xs font-bold text-gray-700 dark:text-gray-300">{av.toLocaleString()}</span><span className="text-[10px] text-gray-400 ml-1">{t('adsPage.impressionLabel')}</span></div>
                                                                        <div><span className="text-xs font-bold text-emerald-600 dark:text-emerald-400">{ac.toLocaleString()}</span><span className="text-[10px] text-gray-400 ml-1">{t('adsPage.clickLabel')}</span></div>
                                                                        <span className="text-xs font-bold text-indigo-600 dark:text-indigo-400 w-14 text-right">{aCtr}%</span>
                                                                    </div>
                                                                    <button onClick={(e) => { e.stopPropagation(); handleUnassignAd(a.id); }} className="p-1 rounded-md text-gray-300 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-500/10" title={t('adsPage.removeFromCampaign')}>
                                                                        <X size={14} />
                                                                    </button>
                                                                </div>
                                                            );
                                                        })}
                                                    </div>

                                                    {/* Campaign Summary Bar */}
                                                    <div className="mt-3 p-3 rounded-xl bg-indigo-50 dark:bg-indigo-500/10 border border-indigo-100 dark:border-indigo-500/20">
                                                        <div className="flex items-center justify-between text-xs">
                                                            <span className="font-bold text-indigo-700 dark:text-indigo-300">{t('adsPage.total')}</span>
                                                            <div className="flex items-center gap-4">
                                                                <span className="text-gray-600 dark:text-gray-300">{t('adsPage.impressionLabel')} <b className="text-indigo-700 dark:text-indigo-300">{totalViews.toLocaleString()}</b></span>
                                                                <span className="text-gray-600 dark:text-gray-300">{t('adsPage.clickLabel')} <b className="text-emerald-600 dark:text-emerald-400">{totalClicks.toLocaleString()}</b></span>
                                                                <span className="text-gray-600 dark:text-gray-300">CTR <b className="text-indigo-700 dark:text-indigo-300">{ctr}%</b></span>
                                                                {c.budget && <span className="text-gray-600 dark:text-gray-300">{t('adsPage.budgetLabel')} <b className="text-amber-600 dark:text-amber-400">₩{Number(c.budget).toLocaleString()}</b></span>}
                                                            </div>
                                                        </div>
                                                    </div>
                                                </div>
                                            ) : (
                                                <div className="px-5 py-6 text-center">
                                                    <FolderOpen className="mx-auto text-gray-300 dark:text-gray-600 mb-2" size={28} />
                                                    <p className="text-xs text-gray-400 dark:text-gray-500">{t('adsPage.noAssignedAds')}</p>
                                                </div>
                                            )}

                                            {/* Action buttons */}
                                            <div className="px-5 py-3 border-t border-gray-50 dark:border-gray-700/50 flex items-center gap-2 flex-wrap">
                                                <button onClick={() => setCampaignReportId(c.id)} className="flex items-center gap-1.5 px-3 py-1.5 bg-violet-50 dark:bg-violet-500/10 text-violet-600 dark:text-violet-400 rounded-lg text-xs font-bold hover:bg-violet-100 dark:hover:bg-violet-500/20"><BarChart3 size={13} /> {t('adsPage.report')}</button>
                                                <button onClick={() => { setAssigningCampaignId(c.id); setAssignSelectedAds(new Set()); }} className="flex items-center gap-1.5 px-3 py-1.5 bg-emerald-50 dark:bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 rounded-lg text-xs font-bold hover:bg-emerald-100 dark:hover:bg-emerald-500/20"><Plus size={13} /> {t('adsPage.assignAds')}</button>
                                                <button onClick={() => { setEditingCampaign(c); setCampaignForm({ name: c.name, advertiser: c.advertiser || '', budget: c.budget || '', start_date: c.start_date || '', end_date: c.end_date || '', status: c.status, memo: c.memo || '', target_countries: c.target_countries || 'all' }); setShowCampaignForm(true); }}
                                                    className="flex items-center gap-1.5 px-3 py-1.5 bg-indigo-50 dark:bg-indigo-500/10 text-indigo-600 dark:text-indigo-400 rounded-lg text-xs font-bold hover:bg-indigo-100 dark:hover:bg-indigo-500/20"><Edit3 size={13} /> {t('adsPage.edit')}</button>
                                                <button onClick={() => handleCampaignDelete(c)} className="flex items-center gap-1.5 px-3 py-1.5 bg-red-50 dark:bg-red-500/10 text-red-500 dark:text-red-400 rounded-lg text-xs font-bold hover:bg-red-100 dark:hover:bg-red-500/20 ml-auto"><Trash2 size={13} /> {t('adsPage.deleteAction')}</button>
                                            </div>

                                            {/* Assign ads modal */}
                                            {assigningCampaignId === c.id && (
                                                <div className="px-5 py-4 border-t border-gray-100 dark:border-gray-700 bg-emerald-50/50 dark:bg-emerald-500/5">
                                                    <div className="flex items-center justify-between mb-3">
                                                        <h4 className="text-xs font-bold text-emerald-700 dark:text-emerald-400">{t('adsPage.selectFromUnassigned')}</h4>
                                                        <div className="flex gap-2">
                                                            <button onClick={() => setAssigningCampaignId(null)} className="px-3 py-1 bg-gray-100 dark:bg-gray-700 text-gray-500 rounded-lg text-xs font-bold">{t('adsPage.cancel')}</button>
                                                            <button onClick={() => handleAssignAds(c.id)} disabled={assignSelectedAds.size === 0} className="px-3 py-1 bg-emerald-600 text-white rounded-lg text-xs font-bold disabled:opacity-50">{t('adsPage.assign', { count: assignSelectedAds.size })}</button>
                                                        </div>
                                                    </div>
                                                    {unassignedAds.length === 0 ? (
                                                        <p className="text-xs text-gray-400 text-center py-4">{t('adsPage.noUnassignedAds')}</p>
                                                    ) : (
                                                        <div className="space-y-1.5 max-h-48 overflow-y-auto">
                                                            {unassignedAds.map(ua => (
                                                                <label key={ua.id} className={`flex items-center gap-3 p-2.5 rounded-lg cursor-pointer transition-colors ${assignSelectedAds.has(ua.id) ? 'bg-emerald-100 dark:bg-emerald-500/15 border border-emerald-300 dark:border-emerald-500/30' : 'bg-white dark:bg-gray-700/40 border border-gray-200 dark:border-gray-600 hover:border-emerald-300'}`}>
                                                                    <input type="checkbox" checked={assignSelectedAds.has(ua.id)} onChange={() => { const n = new Set(assignSelectedAds); n.has(ua.id) ? n.delete(ua.id) : n.add(ua.id); setAssignSelectedAds(n); }} className="accent-emerald-600" />
                                                                    {ua.image_url && <img src={ua.image_url} alt="" className="w-10 h-7 object-cover rounded border" />}
                                                                    <div className="flex-1 min-w-0">
                                                                        <p className="text-xs font-bold text-gray-800 dark:text-gray-200 truncate">{ua.title}</p>
                                                                        <p className="text-[10px] text-gray-400">{SLOT_OPTIONS.find(s => s.value === ua.slot_id)?.label?.split(' (')[0] || ua.slot_id}</p>
                                                                    </div>
                                                                    <span className="text-[10px] text-gray-400">{parseInt(ua.view_count || 0).toLocaleString()} {t('adsPage.impressionLabel')}</span>
                                                                </label>
                                                            ))}
                                                        </div>
                                                    )}
                                                </div>
                                            )}
                                        </div>
                                    )}
                                </div>
                            );
                        })}

                        {/* Unassigned ads section */}
                        {unassignedAds.length > 0 && (
                            <div className="bg-white dark:bg-gray-800 rounded-2xl border border-dashed border-gray-300 dark:border-gray-600 p-5">
                                <h4 className="text-xs font-bold text-gray-400 dark:text-gray-500 uppercase mb-3 flex items-center gap-2">
                                    <FolderOpen size={14} /> {t('adsPage.unassignedAds', { count: unassignedAds.length })}
                                </h4>
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
                                    {unassignedAds.slice(0, 6).map(ua => (
                                        <div key={ua.id} className="flex items-center gap-3 p-2.5 rounded-lg bg-gray-50 dark:bg-gray-700/30">
                                            {ua.image_url && <img src={ua.image_url} alt="" className="w-10 h-7 object-cover rounded border" />}
                                            <div className="flex-1 min-w-0">
                                                <p className="text-xs font-bold text-gray-700 dark:text-gray-300 truncate">{ua.title}</p>
                                                <p className="text-[10px] text-gray-400">{SLOT_OPTIONS.find(s => s.value === ua.slot_id)?.label?.split(' (')[0] || ua.slot_id}</p>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                                {unassignedAds.length > 6 && <p className="text-[10px] text-gray-400 text-center mt-2">{t('adsPage.andMore', { count: unassignedAds.length - 6 })}</p>}
                            </div>
                        )}
                    </div>
                );
            })()}

            {/* ===== MANAGE TAB ===== */}
            {activeTab === 'manage' && (() => {
                const statusFiltered = statusFilter === 'all' ? filteredAds : filteredAds.filter(a => statusFilter === 'active' ? a.is_active == 1 : a.is_active != 1);
                const allSelected = statusFiltered.length > 0 && statusFiltered.every(a => selectedIds.has(a.id));
                const someSelected = selectedIds.size > 0;

                const toggleSelect = (id) => {
                    const next = new Set(selectedIds);
                    next.has(id) ? next.delete(id) : next.add(id);
                    setSelectedIds(next);
                };
                const toggleAll = () => {
                    if (allSelected) { setSelectedIds(new Set()); }
                    else { setSelectedIds(new Set(statusFiltered.map(a => a.id))); }
                };

                const handleBatchToggle = async (activate) => {
                    try {
                        const res = await fetch(`${API_BASE}/batch_update_ads.php`, {
                            method: 'POST', credentials: 'include',
                            headers: { 'Content-Type': 'application/json' },
                            body: JSON.stringify({ ids: [...selectedIds], fields: { is_active: activate ? 1 : 0 } })
                        });
                        const data = await res.json();
                        if (data.success) {
                            showToast(data.message || (activate ? t('adsPage.batchActivated') : t('adsPage.batchDeactivated')));
                            setSelectedIds(new Set());
                            fetchAds();
                        } else {
                            showToast(data.message || t('adsPage.errorOccurred'), 'error');
                        }
                    } catch { showToast(t('adsPage.serverError'), 'error'); }
                };
                const handleBatchDelete = () => {
                    setConfirmModal({
                        title: t('adsPage.batchDeleteTitle'),
                        message: t('adsPage.batchDeleteMsg', { count: selectedIds.size }),
                        onConfirm: async () => {
                            for (const id of selectedIds) {
                                const ad = ads.find(a => a.id === id);
                                if (ad) await handleDelete(ad);
                            }
                            setSelectedIds(new Set());
                            setConfirmModal(null);
                        }
                    });
                };

                return (
                    <div className="space-y-4">
                        {/* Country Filter Tabs */}
                        <div className="flex items-center gap-1.5 flex-wrap">
                            <button onClick={() => { setCountryFilter('all'); setSelectedIds(new Set()); }}
                                className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-all ${countryFilter === 'all' ? 'bg-indigo-600 text-white shadow-md' : 'bg-gray-100 text-gray-500 hover:bg-gray-200 dark:bg-gray-700/50 dark:text-gray-400 dark:hover:bg-gray-700'}`}>
                                🌐 {t('adsPage.allCountries') || '전체'}
                            </button>
                            {COUNTRY_OPTIONS.map(c => (
                                <button key={c.code} onClick={() => { setCountryFilter(c.code); setSelectedIds(new Set()); }}
                                    className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-all ${countryFilter === c.code ? 'bg-indigo-600 text-white shadow-md' : 'bg-gray-100 text-gray-500 hover:bg-gray-200 dark:bg-gray-700/50 dark:text-gray-400 dark:hover:bg-gray-700'}`}>
                                    {c.flag} {c.label}
                                </button>
                            ))}
                        </div>
                        {showAdSenseSettings && (
                            <div className="bg-white dark:bg-gray-800/50 rounded-2xl border border-gray-100 dark:border-gray-700/50 shadow-sm p-6">
                                <div className="flex items-center justify-between mb-4">
                                    <h2 className="text-lg font-bold text-gray-900 dark:text-white flex items-center gap-2"><Settings size={20} className="text-gray-400" /> {t('adsPage.adsenseSettings')}</h2>
                                    <button onClick={() => setShowAdSenseSettings(false)} className="text-gray-400 hover:text-gray-600"><X size={20} /></button>
                                </div>
                                <div className="space-y-3">
                                    <div className="flex items-center gap-3">
                                        <input type="text" value={adsenseForm.client_id} onChange={e => setAdsenseForm({ ...adsenseForm, client_id: e.target.value })} placeholder="ca-pub-XXXXXXXXXX" className="flex-1 px-4 py-2.5 bg-gray-50 dark:bg-gray-700 rounded-xl border border-transparent focus:border-indigo-500 outline-none text-sm font-medium dark:text-white" />
                                        <button onClick={() => setAdsenseForm({ ...adsenseForm, is_enabled: adsenseForm.is_enabled ? 0 : 1 })} className={`px-4 py-2.5 rounded-xl text-sm font-bold ${adsenseForm.is_enabled ? 'bg-emerald-100 text-emerald-700 dark:bg-emerald-500/20 dark:text-emerald-400' : 'bg-gray-100 text-gray-500 dark:bg-gray-700 dark:text-gray-400'}`}>{adsenseForm.is_enabled ? t('adsPage.adsenseEnabled') : t('adsPage.adsenseDisabled')}</button>
                                    </div>
                                    <div className="grid grid-cols-1 md:grid-cols-2 gap-2 max-h-60 overflow-y-auto">
                                        {SLOT_OPTIONS.map(slot => (
                                            <div key={slot.value} className="flex items-center gap-2">
                                                <span className="text-xs text-gray-500 dark:text-gray-400 min-w-[180px] truncate">{slot.label}</span>
                                                <input type="text" value={adsenseForm.slot_configs?.[slot.value] || ''} onChange={e => setAdsenseForm({ ...adsenseForm, slot_configs: { ...adsenseForm.slot_configs, [slot.value]: e.target.value } })} placeholder="Slot ID" className="flex-1 px-3 py-2 bg-gray-50 dark:bg-gray-700 rounded-lg border border-transparent focus:border-indigo-500 outline-none text-xs font-medium dark:text-white" />
                                            </div>
                                        ))}
                                    </div>
                                </div>
                                <button onClick={handleSaveAdsense} className="flex items-center gap-2 px-5 py-2.5 bg-indigo-600 text-white rounded-xl font-bold text-sm hover:bg-indigo-700 transition-colors mt-3"><Save size={16} /> {t('adsPage.save')}</button>
                            </div>
                        )}

                        {/* Search, Filter & Status Pills */}
                        <div className="bg-white dark:bg-gray-800/50 rounded-2xl shadow-sm border border-gray-100 dark:border-gray-700/50 p-4">
                            <div className="flex flex-col md:flex-row gap-3 mb-3">
                                <div className="relative flex-1">
                                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                                    <input type="text" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder={t('adsPage.searchAdTitle')} className="w-full pl-10 pr-4 py-2.5 bg-gray-50 dark:bg-gray-700 rounded-xl border border-transparent focus:border-indigo-500 focus:bg-white dark:focus:bg-gray-600 outline-none font-medium text-sm dark:text-white" />
                                </div>
                                <div className="relative">
                                    <select value={filterSlot} onChange={e => setFilterSlot(e.target.value)} className="w-full md:w-48 px-4 py-2.5 bg-gray-50 dark:bg-gray-700 rounded-xl border border-transparent focus:border-indigo-500 outline-none appearance-none font-medium text-sm dark:text-white">
                                        <option value="">{t('adsPage.allSlots')}</option>
                                        {SLOT_OPTIONS.map(s => (<option key={s.value} value={s.value}>{s.label.split(' (')[0]}</option>))}
                                    </select>
                                    <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 pointer-events-none" size={16} />
                                </div>
                            </div>
                            {/* Status filter pills + View toggle */}
                            <div className="flex items-center justify-between">
                                <div className="flex gap-2">
                                    {[{ key: 'all', label: t('adsPage.all'), count: filteredAds.length },
                                    { key: 'active', label: t('adsPage.active'), count: filteredAds.filter(a => a.is_active == 1).length },
                                    { key: 'inactive', label: t('adsPage.inactive'), count: filteredAds.filter(a => a.is_active != 1).length }
                                    ].map(f => (
                                        <button key={f.key} onClick={() => { setStatusFilter(f.key); setSelectedIds(new Set()); }}
                                            className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-colors flex items-center gap-1.5 ${statusFilter === f.key ? 'bg-indigo-100 text-indigo-700 dark:bg-indigo-500/20 dark:text-indigo-300' : 'bg-gray-50 text-gray-400 hover:bg-gray-100 dark:bg-gray-700/50 dark:text-gray-500 dark:hover:bg-gray-700'}`}>
                                            {f.label} <span className="bg-white/50 dark:bg-gray-600/50 px-1.5 rounded-md">{f.count}</span>
                                        </button>
                                    ))}
                                </div>
                                <div className="flex items-center bg-gray-100 dark:bg-gray-700 rounded-lg p-0.5">
                                    <button onClick={() => setViewMode('list')} className={`p-1.5 rounded-md transition-all ${viewMode === 'list' ? 'bg-white dark:bg-gray-600 text-indigo-600 dark:text-indigo-400 shadow-sm' : 'text-gray-400 hover:text-gray-600 dark:hover:text-gray-300'}`} title={t('adsPage.listView') || '리스트 보기'}>
                                        <List size={16} />
                                    </button>
                                    <button onClick={() => setViewMode('grid')} className={`p-1.5 rounded-md transition-all ${viewMode === 'grid' ? 'bg-white dark:bg-gray-600 text-indigo-600 dark:text-indigo-400 shadow-sm' : 'text-gray-400 hover:text-gray-600 dark:hover:text-gray-300'}`} title={t('adsPage.gridView') || '박스 보기'}>
                                        <LayoutGrid size={16} />
                                    </button>
                                </div>
                            </div>
                        </div>

                        {/* Batch action toolbar */}
                        {someSelected && (
                            <div className="bg-indigo-50 dark:bg-indigo-500/10 border border-indigo-200 dark:border-indigo-500/30 rounded-xl px-4 py-3 flex items-center gap-3 animate-in">
                                <span className="text-sm font-bold text-indigo-700 dark:text-indigo-300">{t('adsPage.batchSelected', { count: selectedIds.size })}</span>
                                <div className="h-5 w-px bg-indigo-200 dark:bg-indigo-500/30" />
                                <button onClick={() => handleBatchToggle(true)} className="px-3 py-1.5 rounded-lg bg-emerald-100 text-emerald-700 dark:bg-emerald-500/20 dark:text-emerald-400 text-xs font-bold hover:bg-emerald-200 dark:hover:bg-emerald-500/30 transition-colors flex items-center gap-1">
                                    <Eye size={13} /> {t('adsPage.batchActivate')}
                                </button>
                                <button onClick={() => handleBatchToggle(false)} className="px-3 py-1.5 rounded-lg bg-gray-100 text-gray-600 dark:bg-gray-700 dark:text-gray-400 text-xs font-bold hover:bg-gray-200 dark:hover:bg-gray-600 transition-colors flex items-center gap-1">
                                    <EyeOff size={13} /> {t('adsPage.batchDeactivate')}
                                </button>
                                <button onClick={handleBatchDelete} className="px-3 py-1.5 rounded-lg bg-red-100 text-red-600 dark:bg-red-500/20 dark:text-red-400 text-xs font-bold hover:bg-red-200 dark:hover:bg-red-500/30 transition-colors flex items-center gap-1">
                                    <Trash2 size={13} /> {t('adsPage.batchDelete')}
                                </button>
                                <button onClick={handleBatchEditOpen} className="px-3 py-1.5 rounded-lg bg-amber-100 text-amber-700 dark:bg-amber-500/20 dark:text-amber-400 text-xs font-bold hover:bg-amber-200 dark:hover:bg-amber-500/30 transition-colors flex items-center gap-1">
                                    <Edit3 size={13} /> {t('adsPage.batchEdit') || '일괄 수정'}
                                </button>
                                <button onClick={() => setSelectedIds(new Set())} className="ml-auto text-xs text-gray-400 hover:text-gray-600 dark:hover:text-gray-300 font-medium">{t('adsPage.deselectAll')}</button>
                            </div>
                        )}

                        {/* Compact table */}
                        {loading ? (
                            <div className="flex items-center justify-center h-64"><div className="animate-spin rounded-full h-8 w-8 border-2 border-indigo-600 border-t-transparent" /></div>
                        ) : statusFiltered.length === 0 ? (
                            <div className="text-center py-20">
                                <Megaphone className="mx-auto text-gray-300 dark:text-gray-600 mb-4" size={48} />
                                <h3 className="text-lg font-bold text-gray-400 dark:text-gray-500">{t('adsPage.noAdsRegistered')}</h3>
                                <button onClick={() => handleOpenForm()} className="mt-4 inline-flex items-center gap-2 px-5 py-2.5 bg-indigo-600 text-white rounded-xl font-bold text-sm hover:bg-indigo-700 transition-colors"><Plus size={16} /> {t('adsPage.newAdRegistration')}</button>
                            </div>
                        ) : viewMode === 'list' ? (
                            <div className="bg-white dark:bg-gray-800/50 rounded-2xl border border-gray-100 dark:border-gray-700/50 shadow-sm overflow-hidden">
                                <div className="overflow-x-auto">
                                    <table className="w-full text-sm">
                                        <thead>
                                            <tr className="bg-gray-50 dark:bg-gray-700/30 text-gray-500 dark:text-gray-400 text-xs font-bold uppercase">
                                                <th className="w-10 px-4 py-3"><input type="checkbox" checked={allSelected} onChange={toggleAll} className="rounded border-gray-300 dark:border-gray-600 text-indigo-600 focus:ring-indigo-500" /></th>
                                                <th className="text-left px-3 py-3">{t('adsPage.adTable')}</th>
                                                <th className="text-left px-3 py-3">{t('adsPage.slot')}</th>
                                                <th className="text-center px-3 py-3">{t('adsPage.status')}</th>
                                                <th className="text-right px-3 py-3">{t('adsPage.impressions')}</th>
                                                <th className="text-right px-3 py-3">{t('adsPage.clicks')}</th>
                                                <th className="text-center px-3 py-3">{t('adsPage.period')}</th>
                                                <th className="text-center px-3 py-3 w-28">{t('adsPage.manage')}</th>
                                            </tr>
                                        </thead>
                                        <tbody className="divide-y divide-gray-50 dark:divide-gray-700/30">
                                            {statusFiltered.map(ad => {
                                                const isSelected = selectedIds.has(ad.id);
                                                return (
                                                    <tr key={ad.id} className={`transition-colors hover:bg-gray-50/50 dark:hover:bg-gray-700/20 ${isSelected ? 'bg-indigo-50/50 dark:bg-indigo-500/5' : ''}`}>
                                                        <td className="px-4 py-3 text-center">
                                                            <input type="checkbox" checked={isSelected} onChange={() => toggleSelect(ad.id)} className="rounded border-gray-300 dark:border-gray-600 text-indigo-600 focus:ring-indigo-500" />
                                                        </td>
                                                        <td className="px-3 py-3">
                                                            <div className="flex items-center gap-3">
                                                                {ad.image_url && <img src={ad.image_url} alt="" className="w-12 h-8 object-cover rounded-lg border dark:border-gray-700 flex-shrink-0" />}
                                                                <div className="min-w-0">
                                                                    <p className="font-bold text-gray-900 dark:text-white truncate max-w-[200px]">{ad.title}</p>
                                                                    {ad.click_url && <p className="text-[10px] text-gray-400 truncate max-w-[200px]">{ad.click_url}</p>}
                                                                </div>
                                                            </div>
                                                        </td>
                                                        <td className="px-3 py-3">
                                                            <span className="text-xs text-gray-500 dark:text-gray-400">{getSlotLabel(ad.slot_id).split(' (')[0]}</span>
                                                        </td>
                                                        <td className="px-3 py-3 text-center">
                                                            <button onClick={() => handleToggleActive(ad)} className={`px-2.5 py-1 rounded-full text-[11px] font-bold cursor-pointer transition-colors ${ad.is_active == 1 ? 'bg-emerald-100 text-emerald-700 hover:bg-emerald-200 dark:bg-emerald-500/20 dark:text-emerald-400 dark:hover:bg-emerald-500/30' : 'bg-gray-100 text-gray-500 hover:bg-gray-200 dark:bg-gray-700 dark:text-gray-400 dark:hover:bg-gray-600'}`}>
                                                                {ad.is_active == 1 ? t('adsPage.active') : t('adsPage.inactive')}
                                                            </button>
                                                        </td>
                                                        <td className="px-3 py-3 text-right font-bold text-gray-700 dark:text-gray-300 tabular-nums">{parseInt(ad.view_count || 0).toLocaleString()}</td>
                                                        <td className="px-3 py-3 text-right font-bold text-emerald-600 dark:text-emerald-400 tabular-nums">{parseInt(ad.click_count || 0).toLocaleString()}</td>
                                                        <td className="px-3 py-3 text-center">
                                                            {(ad.start_date || ad.end_date) ? (
                                                                <span className="text-[11px] text-gray-400">{ad.start_date || '~'} ~ {ad.end_date || ''}</span>
                                                            ) : <span className="text-[11px] text-gray-300 dark:text-gray-600">—</span>}
                                                        </td>
                                                        <td className="px-3 py-3">
                                                            <div className="flex items-center justify-center gap-1">
                                                                <button onClick={() => handleOpenForm(ad)} className="p-1.5 rounded-lg bg-indigo-50 text-indigo-600 hover:bg-indigo-100 dark:bg-indigo-500/10 dark:text-indigo-400 dark:hover:bg-indigo-500/20 transition-colors" title={t('adsPage.edit')}><Edit3 size={13} /></button>
                                                                <button onClick={() => handleCopyAd(ad)} className="p-1.5 rounded-lg bg-amber-50 text-amber-600 hover:bg-amber-100 dark:bg-amber-500/10 dark:text-amber-400 dark:hover:bg-amber-500/20 transition-colors" title={t('adsPage.copy')}><Copy size={13} /></button>
                                                                <button onClick={() => setReportAd(ad)} className="p-1.5 rounded-lg bg-violet-50 text-violet-600 hover:bg-violet-100 dark:bg-violet-500/10 dark:text-violet-400 dark:hover:bg-violet-500/20 transition-colors" title={t('adsPage.reportTitle')}><BarChart3 size={13} /></button>
                                                                <button onClick={() => handleDelete(ad)} className="p-1.5 rounded-lg bg-red-50 text-red-600 hover:bg-red-100 dark:bg-red-500/10 dark:text-red-400 dark:hover:bg-red-500/20 transition-colors" title={t('adsPage.deleteLabel')}><Trash2 size={13} /></button>
                                                            </div>
                                                        </td>
                                                    </tr>
                                                );
                                            })}
                                        </tbody>
                                    </table>
                                </div>
                                {/* Footer summary */}
                                <div className="px-4 py-3 bg-gray-50 dark:bg-gray-700/20 border-t border-gray-100 dark:border-gray-700/30 flex items-center justify-between">
                                    <span className="text-xs text-gray-400">{t('adsPage.totalAdsCount', { count: statusFiltered.length })}</span>
                                    <div className="flex items-center gap-3 text-xs text-gray-400">
                                        <span>{t('adsPage.impressionTotal')} <b className="text-gray-600 dark:text-gray-300">{statusFiltered.reduce((s, a) => s + parseInt(a.view_count || 0), 0).toLocaleString()}</b></span>
                                        <span>{t('adsPage.clickTotal')} <b className="text-emerald-600 dark:text-emerald-400">{statusFiltered.reduce((s, a) => s + parseInt(a.click_count || 0), 0).toLocaleString()}</b></span>
                                    </div>
                                </div>
                            </div>
                        ) : (
                            /* ===== GRID / BOX VIEW ===== */
                            <div>
                                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
                                    {statusFiltered.map(ad => {
                                        const isSelected = selectedIds.has(ad.id);
                                        const views = parseInt(ad.view_count || 0);
                                        const clicks = parseInt(ad.click_count || 0);
                                        const ctr = views > 0 ? ((clicks / views) * 100).toFixed(2) : '0.00';
                                        return (
                                            <div key={ad.id} className={`bg-white dark:bg-gray-800/50 rounded-2xl border shadow-sm overflow-hidden transition-all hover:shadow-lg group ${isSelected ? 'border-indigo-400 dark:border-indigo-500 ring-2 ring-indigo-200 dark:ring-indigo-500/30' : 'border-gray-100 dark:border-gray-700/50'}`}>
                                                {/* Image area */}
                                                <div className="relative aspect-video bg-gray-100 dark:bg-gray-700/50">
                                                    {ad.image_url ? (
                                                        <img src={ad.image_url} alt={ad.title} className="w-full h-full object-cover" />
                                                    ) : (
                                                        <div className="w-full h-full flex items-center justify-center">
                                                            <ImageIcon size={36} className="text-gray-300 dark:text-gray-600" />
                                                        </div>
                                                    )}
                                                    {/* Checkbox overlay */}
                                                    <div className="absolute top-2 left-2">
                                                        <input type="checkbox" checked={isSelected} onChange={() => toggleSelect(ad.id)}
                                                            className="w-4 h-4 rounded border-2 border-white/80 text-indigo-600 focus:ring-indigo-500 shadow-sm" />
                                                    </div>
                                                    {/* Status badge */}
                                                    <div className="absolute top-2 right-2">
                                                        <span className={`px-2 py-0.5 rounded-full text-[10px] font-bold shadow-sm ${ad.is_active == 1 ? 'bg-emerald-500 text-white' : 'bg-gray-500 text-white'}`}>
                                                            {ad.is_active == 1 ? t('adsPage.active') : t('adsPage.inactive')}
                                                        </span>
                                                    </div>
                                                    {/* Click URL indicator */}
                                                    {ad.click_url && (
                                                        <a href={ad.click_url} target="_blank" rel="noreferrer" className="absolute bottom-2 right-2 p-1.5 bg-black/40 hover:bg-black/60 text-white rounded-lg transition-colors" onClick={e => e.stopPropagation()}>
                                                            <ExternalLink size={12} />
                                                        </a>
                                                    )}
                                                </div>
                                                {/* Content */}
                                                <div className="p-4">
                                                    <h3 className="font-bold text-sm text-gray-900 dark:text-white truncate mb-1">{ad.title}</h3>
                                                    <p className="text-[11px] text-gray-400 dark:text-gray-500 mb-3">{getSlotLabel(ad.slot_id).split(' (')[0]}</p>
                                                    {/* Stats row */}
                                                    <div className="flex items-center gap-3 mb-3">
                                                        <div className="flex-1 text-center p-2 bg-gray-50 dark:bg-gray-700/30 rounded-lg">
                                                            <p className="text-xs font-extrabold text-gray-800 dark:text-gray-200">{views.toLocaleString()}</p>
                                                            <p className="text-[9px] text-gray-400 font-medium mt-0.5">{t('adsPage.impressions')}</p>
                                                        </div>
                                                        <div className="flex-1 text-center p-2 bg-gray-50 dark:bg-gray-700/30 rounded-lg">
                                                            <p className="text-xs font-extrabold text-emerald-600 dark:text-emerald-400">{clicks.toLocaleString()}</p>
                                                            <p className="text-[9px] text-gray-400 font-medium mt-0.5">{t('adsPage.clicks')}</p>
                                                        </div>
                                                        <div className="flex-1 text-center p-2 bg-gray-50 dark:bg-gray-700/30 rounded-lg">
                                                            <p className="text-xs font-extrabold text-indigo-600 dark:text-indigo-400">{ctr}%</p>
                                                            <p className="text-[9px] text-gray-400 font-medium mt-0.5">CTR</p>
                                                        </div>
                                                    </div>
                                                    {/* Period */}
                                                    {(ad.start_date || ad.end_date) && (
                                                        <p className="text-[10px] text-gray-400 dark:text-gray-500 flex items-center gap-1 mb-3">
                                                            <Calendar size={10} /> {ad.start_date || '~'} ~ {ad.end_date || ''}
                                                        </p>
                                                    )}
                                                    {/* Action buttons */}
                                                    <div className="flex items-center gap-1.5 pt-3 border-t border-gray-100 dark:border-gray-700/30">
                                                        <button onClick={() => handleToggleActive(ad)} className={`p-1.5 rounded-lg transition-colors ${ad.is_active == 1 ? 'bg-emerald-50 text-emerald-600 hover:bg-emerald-100 dark:bg-emerald-500/10 dark:text-emerald-400' : 'bg-gray-50 text-gray-400 hover:bg-gray-100 dark:bg-gray-700/50 dark:text-gray-500'}`} title={ad.is_active == 1 ? t('adsPage.deactivate') : t('adsPage.activate')}>
                                                            {ad.is_active == 1 ? <EyeOff size={14} /> : <Eye size={14} />}
                                                        </button>
                                                        <button onClick={() => handleOpenForm(ad)} className="p-1.5 rounded-lg bg-indigo-50 text-indigo-600 hover:bg-indigo-100 dark:bg-indigo-500/10 dark:text-indigo-400 dark:hover:bg-indigo-500/20 transition-colors" title={t('adsPage.edit')}><Edit3 size={14} /></button>
                                                        <button onClick={() => handleCopyAd(ad)} className="p-1.5 rounded-lg bg-amber-50 text-amber-600 hover:bg-amber-100 dark:bg-amber-500/10 dark:text-amber-400 dark:hover:bg-amber-500/20 transition-colors" title={t('adsPage.copy')}><Copy size={14} /></button>
                                                        <button onClick={() => setReportAd(ad)} className="p-1.5 rounded-lg bg-violet-50 text-violet-600 hover:bg-violet-100 dark:bg-violet-500/10 dark:text-violet-400 dark:hover:bg-violet-500/20 transition-colors" title={t('adsPage.reportTitle')}><BarChart3 size={14} /></button>
                                                        <button onClick={() => handleDelete(ad)} className="p-1.5 rounded-lg bg-red-50 text-red-600 hover:bg-red-100 dark:bg-red-500/10 dark:text-red-400 dark:hover:bg-red-500/20 transition-colors ml-auto" title={t('adsPage.deleteLabel')}><Trash2 size={14} /></button>
                                                    </div>
                                                </div>
                                            </div>
                                        );
                                    })}
                                </div>
                                {/* Footer summary */}
                                <div className="mt-4 px-4 py-3 bg-white dark:bg-gray-800/50 rounded-2xl border border-gray-100 dark:border-gray-700/50 flex items-center justify-between">
                                    <span className="text-xs text-gray-400">{t('adsPage.totalAdsCount', { count: statusFiltered.length })}</span>
                                    <div className="flex items-center gap-3 text-xs text-gray-400">
                                        <span>{t('adsPage.impressionTotal')} <b className="text-gray-600 dark:text-gray-300">{statusFiltered.reduce((s, a) => s + parseInt(a.view_count || 0), 0).toLocaleString()}</b></span>
                                        <span>{t('adsPage.clickTotal')} <b className="text-emerald-600 dark:text-emerald-400">{statusFiltered.reduce((s, a) => s + parseInt(a.click_count || 0), 0).toLocaleString()}</b></span>
                                    </div>
                                </div>
                            </div>
                        )}
                    </div>
                );
            })()}

            {/* Create/Edit Modal */}
            {showForm && (
                <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center p-4" onClick={() => { setShowForm(false); resetForm(); }}>
                    <div className="bg-white rounded-3xl shadow-2xl w-full max-w-lg overflow-hidden max-h-[90vh] overflow-y-auto" onClick={e => e.stopPropagation()}>
                        <div className="bg-gradient-to-r from-amber-500 to-orange-600 p-5 text-white flex items-center justify-between">
                            <h2 className="font-extrabold text-lg flex items-center gap-2"><Megaphone size={20} />{editingAd ? t('adsPage.editAd') : t('adsPage.createAd')}</h2>
                            <button onClick={() => { setShowForm(false); resetForm(); }} className="text-white/80 hover:text-white"><X size={22} /></button>
                        </div>
                        <form onSubmit={handleSubmit} className="p-6 space-y-4">
                            <div>
                                <label className="block text-xs font-bold text-gray-500 uppercase mb-1.5">{t('adsPage.adSlot')}</label>
                                <select value={form.slot_id} onChange={e => setForm({ ...form, slot_id: e.target.value })} className="w-full px-4 py-2.5 bg-gray-50 rounded-xl border border-gray-200 focus:border-indigo-500 outline-none text-sm font-medium">
                                    {SLOT_OPTIONS.map(s => (<option key={s.value} value={s.value}>{s.label}</option>))}
                                </select>
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-gray-500 uppercase mb-1.5">{t('adsPage.adTitle')}</label>
                                <input type="text" value={form.title} onChange={e => setForm({ ...form, title: e.target.value })} placeholder={t('adsPage.adTitlePlaceholder')} className="w-full px-4 py-2.5 bg-gray-50 rounded-xl border border-gray-200 focus:border-indigo-500 outline-none text-sm font-medium" required />
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-gray-500 uppercase mb-1.5">{t('adsPage.adImage')} {editingAd ? t('adsPage.adImageOptional') : ''}</label>
                                {(() => { const guide = SLOT_SIZE_GUIDE[form.slot_id]; if (!guide) return null; const fl = guide.format === 'banner' ? t('adsPage.bannerType') : guide.format === 'card' ? t('adsPage.cardType') : t('adsPage.nativeType'); return (<p className="text-[11px] text-indigo-400 font-medium mb-1.5 flex items-center gap-1">{t('adsPage.recommendedSize', { size: guide.size, ratio: guide.ratio, format: fl })}</p>); })()}
                                {imagePreview && (<div className="relative mb-2 rounded-xl overflow-hidden border border-gray-200"><img src={imagePreview} alt={t('adsPage.preview')} className="w-full h-32 object-cover" /><button type="button" onClick={() => { setImageFile(null); setImagePreview(editingAd?.image_url || null); }} className="absolute top-2 right-2 p-1 bg-black/50 rounded-lg text-white hover:bg-black/70"><X size={14} /></button></div>)}
                                <label className="flex items-center gap-2 px-4 py-3 bg-gray-50 rounded-xl border-2 border-dashed border-gray-300 cursor-pointer hover:border-indigo-400 hover:bg-indigo-50/30 transition-colors">
                                    <ImageIcon size={18} className="text-gray-400" /><span className="text-sm text-gray-500 font-medium">{t('adsPage.selectImage')}</span>
                                    <input type="file" accept="image/*" onChange={handleImageChange} className="hidden" />
                                </label>
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-gray-500 uppercase mb-1.5">{t('adsPage.clickUrl')}</label>
                                <div className="relative"><Link2 className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={16} /><input type="url" value={form.click_url} onChange={e => setForm({ ...form, click_url: e.target.value })} placeholder="https://example.com" className="w-full pl-10 pr-4 py-2.5 bg-gray-50 rounded-xl border border-gray-200 focus:border-indigo-500 outline-none text-sm font-medium" /></div>
                            </div>
                            <div className="grid grid-cols-2 gap-3">
                                <div><label className="block text-xs font-bold text-gray-500 uppercase mb-1.5">{t('adsPage.startDate')}</label><input type="date" value={form.start_date} onChange={e => setForm({ ...form, start_date: e.target.value })} className="w-full px-4 py-2.5 bg-gray-50 rounded-xl border border-gray-200 focus:border-indigo-500 outline-none text-sm font-medium" /></div>
                                <div><label className="block text-xs font-bold text-gray-500 uppercase mb-1.5">{t('adsPage.endDate')}</label><input type="date" value={form.end_date} onChange={e => setForm({ ...form, end_date: e.target.value })} className="w-full px-4 py-2.5 bg-gray-50 rounded-xl border border-gray-200 focus:border-indigo-500 outline-none text-sm font-medium" /></div>
                            </div>
                            <div className="flex flex-wrap gap-2">
                                <span className="text-xs font-bold text-gray-400 self-center mr-1">{t('adsPage.quickSetup')}</span>
                                {[{ label: t('adsPage.days7'), days: 7 }, { label: t('adsPage.days15'), days: 15 }, { label: t('adsPage.days30'), days: 30 }, { label: t('adsPage.months2'), days: 60 }, { label: t('adsPage.months3'), days: 90 }].map(opt => (
                                    <button key={opt.days} type="button" onClick={() => handleDateShortcut(opt.days)} className="px-3 py-1.5 bg-indigo-50 text-indigo-600 rounded-lg text-xs font-bold hover:bg-indigo-100 transition-colors">{opt.label}</button>
                                ))}
                            </div>
                            <div className="grid grid-cols-2 gap-3">
                                <div><label className="block text-xs font-bold text-gray-500 uppercase mb-1.5">{t('adsPage.priority')}</label><input type="number" min="0" max="100" value={form.priority} onChange={e => setForm({ ...form, priority: parseInt(e.target.value) || 0 })} className="w-full px-4 py-2.5 bg-gray-50 rounded-xl border border-gray-200 focus:border-indigo-500 outline-none text-sm font-medium" /></div>
                                <div><label className="block text-xs font-bold text-gray-500 uppercase mb-1.5">{t('adsPage.statusLabel')}</label><button type="button" onClick={() => setForm({ ...form, is_active: form.is_active ? 0 : 1 })} className={`w-full px-4 py-2.5 rounded-xl text-sm font-bold transition-colors ${form.is_active ? 'bg-emerald-100 text-emerald-700' : 'bg-gray-100 text-gray-500'}`}>{form.is_active ? t('adsPage.activeStatus') : t('adsPage.inactiveStatus')}</button></div>
                            </div>
                            {/* Target Countries */}
                            <div>
                                <label className="block text-xs font-bold text-gray-500 uppercase mb-1.5">{t('adsPage.targetCountries') || '대상 국가'}</label>
                                <div className="flex flex-wrap gap-2">
                                    <button type="button" onClick={() => setForm({ ...form, target_countries: 'all' })}
                                        className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-colors ${form.target_countries === 'all' ? 'bg-indigo-600 text-white' : 'bg-gray-100 text-gray-500 hover:bg-gray-200'}`}>
                                        🌐 {t('adsPage.allCountries') || '전체'}
                                    </button>
                                    {COUNTRY_OPTIONS.map(c => {
                                        const selected = form.target_countries !== 'all' && form.target_countries.split(',').includes(c.code);
                                        return (
                                            <button key={c.code} type="button" onClick={() => {
                                                if (form.target_countries === 'all') {
                                                    setForm({ ...form, target_countries: c.code });
                                                } else {
                                                    const codes = form.target_countries.split(',').filter(Boolean);
                                                    if (selected) {
                                                        const next = codes.filter(x => x !== c.code);
                                                        setForm({ ...form, target_countries: next.length ? next.join(',') : 'all' });
                                                    } else {
                                                        setForm({ ...form, target_countries: [...codes, c.code].join(',') });
                                                    }
                                                }
                                            }}
                                                className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-colors ${selected ? 'bg-indigo-600 text-white' : 'bg-gray-100 text-gray-500 hover:bg-gray-200'}`}>
                                                {c.flag} {c.label}
                                            </button>
                                        );
                                    })}
                                </div>
                                {form.target_countries !== 'all' && (
                                    <p className="text-[10px] text-indigo-400 mt-1.5">{t('adsPage.selectedCountries') || '선택된 국가'}: {form.target_countries.split(',').map(c => COUNTRY_OPTIONS.find(o => o.code === c)?.flag || c).join(' ')}</p>
                                )}
                            </div>
                            <div className="flex gap-3 pt-2">
                                <button type="submit" disabled={submitting} className="flex-1 py-3 bg-indigo-600 text-white rounded-xl font-bold text-sm hover:bg-indigo-700 transition-colors disabled:opacity-50">{submitting ? t('adsPage.submitting') : (editingAd ? t('adsPage.submitEdit') : t('adsPage.submitCreate'))}</button>
                                <button type="button" onClick={() => { setShowForm(false); resetForm(); }} className="px-5 py-3 bg-gray-100 text-gray-600 rounded-xl font-bold text-sm hover:bg-gray-200 transition-colors">{t('adsPage.cancel')}</button>
                            </div>
                        </form>
                    </div>
                </div>
            )}

            {/* Batch Edit Modal */}
            {showBatchEdit && (
                <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center p-4" onClick={() => setShowBatchEdit(false)}>
                    <div className="bg-white dark:bg-gray-800 rounded-3xl shadow-2xl w-full max-w-lg overflow-hidden max-h-[90vh] overflow-y-auto" onClick={e => e.stopPropagation()}>
                        <div className="bg-gradient-to-r from-amber-500 to-orange-500 p-5 text-white flex items-center justify-between">
                            <h2 className="font-extrabold text-lg flex items-center gap-2"><Edit3 size={20} />{t('adsPage.batchEdit') || '일괄 수정'} ({selectedIds.size}{t('adsPage.batchCount') || '개'})</h2>
                            <button onClick={() => setShowBatchEdit(false)} className="text-white/80 hover:text-white"><X size={22} /></button>
                        </div>
                        <div className="p-6 space-y-4">
                            <p className="text-xs text-gray-400">{t('adsPage.batchEditDesc') || '수정할 항목을 체크한 후 값을 설정하세요. 체크된 항목만 일괄 적용됩니다.'}</p>

                            {/* Target Countries */}
                            <div className={`rounded-xl border p-3 transition-colors ${batchEditForm.target_countries.enabled ? 'border-indigo-300 bg-indigo-50/50 dark:border-indigo-500/30 dark:bg-indigo-500/10' : 'border-gray-200 dark:border-gray-700'}`}>
                                <label className="flex items-center gap-2 cursor-pointer mb-2">
                                    <input type="checkbox" checked={batchEditForm.target_countries.enabled} onChange={e => setBatchEditForm({ ...batchEditForm, target_countries: { ...batchEditForm.target_countries, enabled: e.target.checked } })} className="w-4 h-4 rounded accent-indigo-600" />
                                    <span className="text-xs font-bold text-gray-600 dark:text-gray-300 uppercase">{t('adsPage.targetCountries') || '대상 국가'}</span>
                                </label>
                                {batchEditForm.target_countries.enabled && (
                                    <div className="flex flex-wrap gap-1.5 mt-1">
                                        <button type="button" onClick={() => setBatchEditForm({ ...batchEditForm, target_countries: { ...batchEditForm.target_countries, value: 'all' } })}
                                            className={`px-2.5 py-1 rounded-md text-xs font-bold transition-colors ${batchEditForm.target_countries.value === 'all' ? 'bg-indigo-600 text-white' : 'bg-gray-100 text-gray-500 hover:bg-gray-200 dark:bg-gray-700 dark:text-gray-400'}`}>
                                            🌐 {t('adsPage.allCountries') || '전체'}
                                        </button>
                                        {COUNTRY_OPTIONS.map(c => {
                                            const sel = batchEditForm.target_countries.value !== 'all' && batchEditForm.target_countries.value.split(',').includes(c.code);
                                            return (
                                                <button key={c.code} type="button" onClick={() => {
                                                    const cur = batchEditForm.target_countries.value;
                                                    if (cur === 'all') {
                                                        setBatchEditForm({ ...batchEditForm, target_countries: { ...batchEditForm.target_countries, value: c.code } });
                                                    } else {
                                                        const codes = cur.split(',').filter(Boolean);
                                                        const next = sel ? codes.filter(x => x !== c.code) : [...codes, c.code];
                                                        setBatchEditForm({ ...batchEditForm, target_countries: { ...batchEditForm.target_countries, value: next.length ? next.join(',') : 'all' } });
                                                    }
                                                }}
                                                    className={`px-2.5 py-1 rounded-md text-xs font-bold transition-colors ${sel ? 'bg-indigo-600 text-white' : 'bg-gray-100 text-gray-500 hover:bg-gray-200 dark:bg-gray-700 dark:text-gray-400'}`}>
                                                    {c.flag} {c.label}
                                                </button>
                                            );
                                        })}
                                    </div>
                                )}
                            </div>

                            {/* Slot */}
                            <div className={`rounded-xl border p-3 transition-colors ${batchEditForm.slot_id.enabled ? 'border-indigo-300 bg-indigo-50/50 dark:border-indigo-500/30 dark:bg-indigo-500/10' : 'border-gray-200 dark:border-gray-700'}`}>
                                <label className="flex items-center gap-2 cursor-pointer">
                                    <input type="checkbox" checked={batchEditForm.slot_id.enabled} onChange={e => setBatchEditForm({ ...batchEditForm, slot_id: { ...batchEditForm.slot_id, enabled: e.target.checked } })} className="w-4 h-4 rounded accent-indigo-600" />
                                    <span className="text-xs font-bold text-gray-600 dark:text-gray-300 uppercase">{t('adsPage.adSlot')}</span>
                                </label>
                                {batchEditForm.slot_id.enabled && (
                                    <select value={batchEditForm.slot_id.value} onChange={e => setBatchEditForm({ ...batchEditForm, slot_id: { ...batchEditForm.slot_id, value: e.target.value } })} className="w-full mt-2 px-3 py-2 bg-white dark:bg-gray-700 rounded-lg border border-gray-200 dark:border-gray-600 text-sm font-medium dark:text-white outline-none">
                                        {SLOT_OPTIONS.map(s => (<option key={s.value} value={s.value}>{s.label}</option>))}
                                    </select>
                                )}
                            </div>

                            {/* Priority & Status */}
                            <div className="grid grid-cols-2 gap-3">
                                <div className={`rounded-xl border p-3 transition-colors ${batchEditForm.priority.enabled ? 'border-indigo-300 bg-indigo-50/50 dark:border-indigo-500/30 dark:bg-indigo-500/10' : 'border-gray-200 dark:border-gray-700'}`}>
                                    <label className="flex items-center gap-2 cursor-pointer">
                                        <input type="checkbox" checked={batchEditForm.priority.enabled} onChange={e => setBatchEditForm({ ...batchEditForm, priority: { ...batchEditForm.priority, enabled: e.target.checked } })} className="w-4 h-4 rounded accent-indigo-600" />
                                        <span className="text-xs font-bold text-gray-600 dark:text-gray-300 uppercase">{t('adsPage.priority')}</span>
                                    </label>
                                    {batchEditForm.priority.enabled && (
                                        <input type="number" min="0" max="100" value={batchEditForm.priority.value} onChange={e => setBatchEditForm({ ...batchEditForm, priority: { ...batchEditForm.priority, value: parseInt(e.target.value) || 0 } })} className="w-full mt-2 px-3 py-2 bg-white dark:bg-gray-700 rounded-lg border border-gray-200 dark:border-gray-600 text-sm font-medium dark:text-white outline-none" />
                                    )}
                                </div>
                                <div className={`rounded-xl border p-3 transition-colors ${batchEditForm.is_active.enabled ? 'border-indigo-300 bg-indigo-50/50 dark:border-indigo-500/30 dark:bg-indigo-500/10' : 'border-gray-200 dark:border-gray-700'}`}>
                                    <label className="flex items-center gap-2 cursor-pointer">
                                        <input type="checkbox" checked={batchEditForm.is_active.enabled} onChange={e => setBatchEditForm({ ...batchEditForm, is_active: { ...batchEditForm.is_active, enabled: e.target.checked } })} className="w-4 h-4 rounded accent-indigo-600" />
                                        <span className="text-xs font-bold text-gray-600 dark:text-gray-300 uppercase">{t('adsPage.statusLabel')}</span>
                                    </label>
                                    {batchEditForm.is_active.enabled && (
                                        <button type="button" onClick={() => setBatchEditForm({ ...batchEditForm, is_active: { ...batchEditForm.is_active, value: batchEditForm.is_active.value ? 0 : 1 } })} className={`w-full mt-2 px-3 py-2 rounded-lg text-sm font-bold transition-colors ${batchEditForm.is_active.value ? 'bg-emerald-100 text-emerald-700 dark:bg-emerald-500/20 dark:text-emerald-400' : 'bg-gray-100 text-gray-500 dark:bg-gray-700 dark:text-gray-400'}`}>
                                            {batchEditForm.is_active.value ? t('adsPage.activeStatus') : t('adsPage.inactiveStatus')}
                                        </button>
                                    )}
                                </div>
                            </div>

                            {/* Dates */}
                            <div className={`rounded-xl border p-3 transition-colors ${batchEditForm.start_date.enabled || batchEditForm.end_date.enabled ? 'border-indigo-300 bg-indigo-50/50 dark:border-indigo-500/30 dark:bg-indigo-500/10' : 'border-gray-200 dark:border-gray-700'}`}>
                                <div className="grid grid-cols-2 gap-3">
                                    <div>
                                        <label className="flex items-center gap-2 cursor-pointer mb-1.5">
                                            <input type="checkbox" checked={batchEditForm.start_date.enabled} onChange={e => setBatchEditForm({ ...batchEditForm, start_date: { ...batchEditForm.start_date, enabled: e.target.checked } })} className="w-4 h-4 rounded accent-indigo-600" />
                                            <span className="text-xs font-bold text-gray-600 dark:text-gray-300 uppercase">{t('adsPage.startDate')}</span>
                                        </label>
                                        {batchEditForm.start_date.enabled && (
                                            <input type="date" value={batchEditForm.start_date.value} onChange={e => setBatchEditForm({ ...batchEditForm, start_date: { ...batchEditForm.start_date, value: e.target.value } })} className="w-full px-3 py-2 bg-white dark:bg-gray-700 rounded-lg border border-gray-200 dark:border-gray-600 text-sm font-medium dark:text-white outline-none" />
                                        )}
                                    </div>
                                    <div>
                                        <label className="flex items-center gap-2 cursor-pointer mb-1.5">
                                            <input type="checkbox" checked={batchEditForm.end_date.enabled} onChange={e => setBatchEditForm({ ...batchEditForm, end_date: { ...batchEditForm.end_date, enabled: e.target.checked } })} className="w-4 h-4 rounded accent-indigo-600" />
                                            <span className="text-xs font-bold text-gray-600 dark:text-gray-300 uppercase">{t('adsPage.endDate')}</span>
                                        </label>
                                        {batchEditForm.end_date.enabled && (
                                            <input type="date" value={batchEditForm.end_date.value} onChange={e => setBatchEditForm({ ...batchEditForm, end_date: { ...batchEditForm.end_date, value: e.target.value } })} className="w-full px-3 py-2 bg-white dark:bg-gray-700 rounded-lg border border-gray-200 dark:border-gray-600 text-sm font-medium dark:text-white outline-none" />
                                        )}
                                    </div>
                                </div>
                            </div>

                            <div className="flex gap-3 pt-2">
                                <button onClick={handleBatchEditSubmit} className="flex-1 py-3 bg-amber-500 text-white rounded-xl font-bold text-sm hover:bg-amber-600 transition-colors">{t('adsPage.applyBatchEdit') || '일괄 적용'}</button>
                                <button onClick={() => setShowBatchEdit(false)} className="px-5 py-3 bg-gray-100 text-gray-600 dark:bg-gray-700 dark:text-gray-400 rounded-xl font-bold text-sm hover:bg-gray-200 dark:hover:bg-gray-600 transition-colors">{t('adsPage.cancel')}</button>
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {reportAd && <AdminAdDashboard ad={reportAd} onClose={() => setReportAd(null)} />}
            {campaignReportId && <CampaignReportModal campaignId={campaignReportId} onClose={() => setCampaignReportId(null)} />}
            <ConfirmModal modal={confirmModal} onClose={() => setConfirmModal(null)} />
            <Toast toast={toast} onClose={() => setToast(null)} />
        </div>
    );
};

export default AdminAds;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { useTranslation } from 'react-i18next';
import { useAuth } from '../../context/AuthContext';
import { AlertTriangle, CheckCircle, XCircle, Clock, Search, User, MapPin, Store, ChevronDown, ChevronUp, MessageSquare, Shield, ArrowRight, FileText, X } from 'lucide-react';
import ConfirmModal from '../../components/ConfirmModal';
import Toast from '../../components/Toast';

const API_BASE = '/api';

const AdminCancellations = () => {
    const { t } = useTranslation('admin');
    const { user } = useAuth();
    const [requests, setRequests] = useState([]);
    const [loading, setLoading] = useState(true);
    const [activeTab, setActiveTab] = useState('pending');
    const [searchTerm, setSearchTerm] = useState('');
    const [expandedId, setExpandedId] = useState(null);
    const [processing, setProcessing] = useState(null);
    const [decisionNote, setDecisionNote] = useState('');
    const [confirmModal, setConfirmModal] = useState(null);
    const [toast, setToast] = useState(null);

    const showToast = useCallback((message, type = 'success') => {
        setToast({ message, type });
    }, []);

    useEffect(() => { fetchRequests(); }, []);

    const fetchRequests = async () => {
        setLoading(true);
        try {
            const res = await fetch(`${API_BASE}/applications/get_cancellation_requests.php`, { credentials: 'include' });
            const data = await res.json();
            if (data.success) setRequests(data.requests || []);
        } catch (err) {
            console.error(t('cancellationsPage.loadFailed'), err);
        } finally {
            setLoading(false);
        }
    };

    const handleAction = async (requestId, action) => {
        const actionLabel = action === 'approved' ? t('cancellationsPage.approve') : t('cancellationsPage.reject');
        setConfirmModal({
            title: action === 'approved' ? t('cancellationsPage.approveTitle') : t('cancellationsPage.rejectTitle'),
            message: action === 'approved' ? t('cancellationsPage.approveConfirm') : t('cancellationsPage.rejectConfirm'),
            type: action === 'approved' ? 'success' : 'danger',
            confirmLabel: actionLabel,
            onConfirm: async () => {
                setConfirmModal(null);
                setProcessing(requestId);
                try {
                    const res = await fetch(`${API_BASE}/applications/handle_cancellation.php`, {
                        method: 'POST', credentials: 'include',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({ request_id: requestId, action, decision_note: decisionNote })
                    });
                    const data = await res.json();
                    if (data.success) { showToast(data.message, 'success'); setDecisionNote(''); setExpandedId(null); fetchRequests(); }
                    else { showToast(data.message || t('cancellationsPage.processFailed'), 'error'); }
                } catch { showToast(t('cancellationsPage.errorOccurred'), 'error'); }
                finally { setProcessing(null); }
            }
        });
    };

    const stats = useMemo(() => ({
        total: requests.length,
        pending: requests.filter(r => r.status === 'pending').length,
        approved: requests.filter(r => r.status === 'approved').length,
        rejected: requests.filter(r => r.status === 'rejected').length,
    }), [requests]);

    const filteredRequests = useMemo(() => {
        let filtered = requests;
        if (activeTab !== 'all') filtered = filtered.filter(r => r.status === activeTab);
        if (searchTerm) {
            const term = searchTerm.toLowerCase();
            filtered = filtered.filter(r =>
                (r.seller_name || '').toLowerCase().includes(term) ||
                (r.venue_title || '').toLowerCase().includes(term) ||
                (r.reason || '').toLowerCase().includes(term)
            );
        }
        return filtered;
    }, [requests, activeTab, searchTerm]);

    const formatDate = (str) => {
        if (!str) return '-';
        return new Date(str).toLocaleString('ko-KR', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' });
    };

    const relativeTime = (str) => {
        if (!str) return '';
        const diff = Math.floor((new Date() - new Date(str)) / 1000);
        if (diff < 60) return t('cancellationsPage.justNow');
        if (diff < 3600) return t('cancellationsPage.minutesAgo', { count: Math.floor(diff / 60) });
        if (diff < 86400) return t('cancellationsPage.hoursAgo', { count: Math.floor(diff / 3600) });
        if (diff < 604800) return t('cancellationsPage.daysAgo', { count: Math.floor(diff / 86400) });
        return formatDate(str);
    };

    const isAdmin = user?.role === 'admin' || user?.role === 'superadmin';

    const tabConfig = [
        { id: 'pending', label: t('cancellationsPage.tabPending'), count: stats.pending, icon: <Clock size={14} />, activeColor: 'bg-amber-500 text-white', dotColor: 'bg-amber-500' },
        { id: 'approved', label: t('cancellationsPage.tabApproved'), count: stats.approved, icon: <CheckCircle size={14} />, activeColor: 'bg-emerald-500 text-white', dotColor: 'bg-emerald-500' },
        { id: 'rejected', label: t('cancellationsPage.tabRejected'), count: stats.rejected, icon: <XCircle size={14} />, activeColor: 'bg-red-500 text-white', dotColor: 'bg-red-500' },
        { id: 'all', label: t('cancellationsPage.tabAll'), count: stats.total, icon: <FileText size={14} />, activeColor: 'bg-gray-800 text-white', dotColor: 'bg-gray-500' },
    ];

    return (
        <div className="pb-20">
            {/* Header */}
            <div className="mb-8">
                <div className="flex items-start gap-4 mb-1">
                    <div className="w-11 h-11 bg-gradient-to-br from-amber-400 to-orange-500 rounded-2xl flex items-center justify-center text-white shadow-lg shadow-amber-200/40 flex-shrink-0">
                        {isAdmin ? <Shield size={20} /> : <AlertTriangle size={20} />}
                    </div>
                    <div>
                        <p className="text-amber-600 font-bold text-xs tracking-widest uppercase mb-0.5">Cancellation Requests</p>
                        <h1 className="text-2xl md:text-3xl font-extrabold text-gray-900 tracking-tight">
                            {isAdmin ? t('cancellationsPage.titleMonitoring') : t('cancellationsPage.title')}
                        </h1>
                        <p className="text-gray-500 text-sm font-medium mt-1">
                            {isAdmin ? t('cancellationsPage.subtitleAdmin') : t('cancellationsPage.subtitleVendor')}
                        </p>
                    </div>
                </div>
            </div>

            {/* Stats Cards */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-3 mb-8">
                {[
                    { label: t('cancellationsPage.statsTotal'), value: stats.total, icon: <MessageSquare size={16} />, gradient: 'from-slate-600 to-slate-800', light: 'bg-slate-50 border-slate-100' },
                    { label: t('cancellationsPage.statsPending'), value: stats.pending, icon: <Clock size={16} />, gradient: 'from-amber-500 to-orange-500', light: 'bg-amber-50 border-amber-100', pulse: stats.pending > 0 },
                    { label: t('cancellationsPage.statsApproved'), value: stats.approved, icon: <CheckCircle size={16} />, gradient: 'from-emerald-500 to-green-600', light: 'bg-emerald-50 border-emerald-100' },
                    { label: t('cancellationsPage.statsRejected'), value: stats.rejected, icon: <XCircle size={16} />, gradient: 'from-red-500 to-rose-600', light: 'bg-red-50 border-red-100' },
                ].map((stat, i) => (
                    <div key={i} className={`relative overflow-hidden ${stat.light} border rounded-2xl p-4 group hover:shadow-md transition-all`}>
                        <div className={`absolute top-0 left-0 right-0 h-1 bg-gradient-to-r ${stat.gradient}`}></div>
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-[11px] font-bold text-gray-400 uppercase tracking-wider">{stat.label}</p>
                                <div className="flex items-baseline gap-1 mt-1">
                                    <p className="text-2xl font-extrabold text-gray-900">{stat.value}</p>
                                    {stat.pulse && <span className="relative flex h-2 w-2"><span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-amber-400 opacity-75"></span><span className="relative inline-flex rounded-full h-2 w-2 bg-amber-500"></span></span>}
                                </div>
                            </div>
                            <div className={`w-9 h-9 rounded-xl bg-gradient-to-br ${stat.gradient} text-white flex items-center justify-center opacity-80`}>{stat.icon}</div>
                        </div>
                    </div>
                ))}
            </div>

            {/* Toolbar */}
            <div className="flex flex-col md:flex-row gap-3 mb-6">
                <div className="relative flex-1">
                    <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 text-gray-400" size={16} />
                    <input
                        type="text" placeholder={t('cancellationsPage.searchPlaceholder')}
                        value={searchTerm} onChange={e => setSearchTerm(e.target.value)}
                        className="w-full pl-10 pr-4 py-2.5 bg-white border border-gray-200 rounded-xl text-sm font-medium focus:outline-none focus:ring-2 focus:ring-amber-200 focus:border-amber-300 transition-all"
                    />
                </div>
                <div className="flex gap-1.5 p-1 bg-gray-100/80 rounded-xl overflow-x-auto">
                    {tabConfig.map(tab => (
                        <button key={tab.id} onClick={() => setActiveTab(tab.id)}
                            className={`flex items-center gap-1.5 px-3.5 py-2 rounded-lg text-xs font-bold transition-all whitespace-nowrap
                                ${activeTab === tab.id ? tab.activeColor + ' shadow-sm' : 'text-gray-500 hover:text-gray-700 hover:bg-white/50'}`}
                        >
                            {tab.icon} {tab.label}
                            <span className={`px-1.5 py-0.5 rounded-full text-[10px] ${activeTab === tab.id ? 'bg-white/25' : 'bg-gray-200/60'}`}>
                                {tab.count}
                            </span>
                        </button>
                    ))}
                </div>
            </div>

            {/* Request List */}
            {loading ? (
                <div className="flex flex-col items-center justify-center py-24 gap-3">
                    <div className="animate-spin rounded-full h-10 w-10 border-[3px] border-amber-500 border-t-transparent"></div>
                    <p className="text-sm text-gray-400 font-medium">{t('cancellationsPage.loadingRequests')}</p>
                </div>
            ) : filteredRequests.length === 0 ? (
                <div className="text-center py-20">
                    <div className="w-20 h-20 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-4">
                        <AlertTriangle size={32} className="text-gray-300" />
                    </div>
                    <h3 className="text-lg font-bold text-gray-900 mb-1">{t('cancellationsPage.noRequests')}</h3>
                    <p className="text-gray-500 text-sm">
                        {activeTab !== 'all' ? t('cancellationsPage.noRequestsOtherTab') : t('cancellationsPage.noRequestsAll')}
                    </p>
                </div>
            ) : (
                <div className="space-y-3">
                    {filteredRequests.map(req => {
                        const isExpanded = expandedId === req.id;
                        const isPending = req.status === 'pending';

                        return (
                            <div key={req.id}
                                className={`bg-white rounded-2xl border overflow-hidden transition-all duration-300
                                    ${isPending ? 'border-amber-200/80 shadow-sm hover:shadow-md' : 'border-gray-100 hover:border-gray-200'}
                                    ${isExpanded ? 'shadow-lg ring-1 ring-gray-100' : ''}`}
                            >
                                {/* Main Row */}
                                <div
                                    className="p-4 md:p-5 flex items-center gap-4 cursor-pointer hover:bg-gray-50/50 transition-colors select-none"
                                    onClick={() => { setExpandedId(isExpanded ? null : req.id); setDecisionNote(''); }}
                                >
                                    {/* Status Indicator */}
                                    <div className="flex-shrink-0">
                                        <div className={`w-10 h-10 rounded-xl flex items-center justify-center
                                            ${isPending ? 'bg-amber-100 text-amber-600' :
                                                req.status === 'approved' ? 'bg-emerald-100 text-emerald-600' :
                                                    'bg-red-100 text-red-500'}`}
                                        >
                                            {isPending && <Clock size={18} />}
                                            {req.status === 'approved' && <CheckCircle size={18} />}
                                            {req.status === 'rejected' && <XCircle size={18} />}
                                        </div>
                                    </div>

                                    {/* Info */}
                                    <div className="flex-1 min-w-0">
                                        <div className="flex flex-wrap items-center gap-1.5 mb-0.5">
                                            <span className="text-sm font-bold text-gray-900">{req.seller_name || ''}</span>
                                            <ArrowRight size={12} className="text-gray-300" />
                                            <span className="text-sm font-medium text-gray-600 truncate">{req.venue_title || req.venue_name}</span>
                                        </div>
                                        <div className="flex items-center gap-2">
                                            <span className={`inline-flex items-center gap-1 text-[10px] font-bold px-1.5 py-0.5 rounded
                                                ${isPending ? 'bg-amber-50 text-amber-600' :
                                                    req.status === 'approved' ? 'bg-emerald-50 text-emerald-600' :
                                                        'bg-red-50 text-red-500'}`}
                                            >
                                                {isPending ? t('cancellationsPage.statusPending') : req.status === 'approved' ? t('cancellationsPage.statusApproved') : t('cancellationsPage.statusRejected')}
                                            </span>
                                            <span className="text-[11px] text-gray-400">{relativeTime(req.created_at)}</span>
                                        </div>
                                    </div>

                                    {/* Reason Preview (desktop) */}
                                    <p className="hidden lg:block text-xs text-gray-400 truncate max-w-[180px] flex-shrink-0 italic">
                                        "{(req.reason || '').substring(0, 40)}{(req.reason || '').length > 40 ? '...' : ''}"
                                    </p>

                                    {/* Expand */}
                                    <div className={`flex-shrink-0 w-7 h-7 rounded-lg flex items-center justify-center transition-all ${isExpanded ? 'bg-gray-100 text-gray-600' : 'text-gray-300'}`}>
                                        {isExpanded ? <ChevronUp size={16} /> : <ChevronDown size={16} />}
                                    </div>
                                </div>

                                {/* Expanded Panel */}
                                {isExpanded && (
                                    <div className="border-t border-gray-100 bg-gray-50/50">
                                        <div className="p-4 md:p-5 space-y-4">
                                            {/* Reason */}
                                            <div>
                                                <label className="text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1.5 block">{t('cancellationsPage.cancelReason')}</label>
                                                <div className="bg-white rounded-xl p-4 text-sm text-gray-700 leading-relaxed border border-gray-100 shadow-sm">
                                                    {req.reason}
                                                </div>
                                            </div>

                                            {/* Meta Info */}
                                            <div className="flex flex-wrap gap-x-4 gap-y-2">
                                                {req.venue_location && (
                                                    <span className="flex items-center gap-1.5 text-xs text-gray-500">
                                                        <MapPin size={12} className="text-gray-400" /> {req.venue_location}
                                                    </span>
                                                )}
                                                {req.seller_email && (
                                                    <span className="flex items-center gap-1.5 text-xs text-gray-500">
                                                        <User size={12} className="text-gray-400" /> {req.seller_email}
                                                    </span>
                                                )}
                                                {req.host_name && (
                                                    <span className="flex items-center gap-1.5 text-xs text-gray-500">
                                                        <Store size={12} className="text-gray-400" /> {req.host_name}
                                                    </span>
                                                )}
                                                <span className="flex items-center gap-1.5 text-xs text-gray-500">
                                                    <Clock size={12} className="text-gray-400" /> {formatDate(req.created_at)}
                                                </span>
                                            </div>

                                            {/* Decision Result */}
                                            {req.status !== 'pending' && (
                                                <div className={`rounded-xl p-4 border ${req.status === 'approved'
                                                    ? 'bg-emerald-50 border-emerald-100 text-emerald-800'
                                                    : 'bg-red-50 border-red-100 text-red-800'}`}
                                                >
                                                    <div className="flex items-center gap-2 mb-1">
                                                        {req.status === 'approved' ? <CheckCircle size={14} /> : <XCircle size={14} />}
                                                        <span className="text-sm font-bold">
                                                            {req.status === 'approved' ? t('cancellationsPage.approvedResult') : t('cancellationsPage.rejectedResult')}
                                                        </span>
                                                        {req.decided_by_name && (
                                                            <span className="text-xs opacity-60">by {req.decided_by_name}</span>
                                                        )}
                                                    </div>
                                                    {req.decision_note && <p className="text-sm mt-1 opacity-80">{req.decision_note}</p>}
                                                    {req.decided_at && <p className="text-[11px] opacity-50 mt-2">{formatDate(req.decided_at)}</p>}
                                                </div>
                                            )}

                                            {/* Action Area */}
                                            {isPending && (
                                                <div className="pt-2 space-y-3">
                                                    <div>
                                                        <label className="text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1.5 block">{t('cancellationsPage.decisionNote')}</label>
                                                        <textarea
                                                            value={decisionNote}
                                                            onChange={e => setDecisionNote(e.target.value)}
                                                            placeholder={t('cancellationsPage.decisionPlaceholder')}
                                                            rows={2}
                                                            className="w-full border border-gray-200 rounded-xl p-3 text-sm bg-white focus:outline-none focus:ring-2 focus:ring-amber-200 focus:border-amber-300 resize-none transition-all"
                                                        />
                                                    </div>
                                                    <div className="flex gap-3">
                                                        <button
                                                            onClick={() => handleAction(req.id, 'approved')}
                                                            disabled={processing === req.id}
                                                            className="flex-1 py-3 bg-gradient-to-r from-emerald-500 to-green-600 text-white rounded-xl text-sm font-bold hover:from-emerald-600 hover:to-green-700 shadow-lg shadow-emerald-200/50 transition-all disabled:opacity-50 disabled:shadow-none flex items-center justify-center gap-2"
                                                        >
                                                            <CheckCircle size={16} />
                                                            {processing === req.id ? t('cancellationsPage.processing') : t('cancellationsPage.approveCancel')}
                                                        </button>
                                                        <button
                                                            onClick={() => handleAction(req.id, 'rejected')}
                                                            disabled={processing === req.id}
                                                            className="flex-1 py-3 bg-white text-red-600 border-2 border-red-200 rounded-xl text-sm font-bold hover:bg-red-50 hover:border-red-300 transition-all disabled:opacity-50 flex items-center justify-center gap-2"
                                                        >
                                                            <XCircle size={16} />
                                                            {processing === req.id ? t('cancellationsPage.processing') : t('cancellationsPage.rejectCancel')}
                                                        </button>
                                                    </div>
                                                </div>
                                            )}
                                        </div>
                                    </div>
                                )}
                            </div>
                        );
                    })}
                </div>
            )}

            <ConfirmModal modal={confirmModal} onClose={() => setConfirmModal(null)} />
            <Toast toast={toast} onClose={() => setToast(null)} />
        </div>
    );
};

export default AdminCancellations;

import React, { useState, useEffect, useCallback } from 'react';
import { useTranslation } from 'react-i18next';
import {
    Eye, EyeOff, Globe, MapPin, User, Save, Search,
    Home, ClipboardList, Building, Flame, TrendingUp, BarChart3,
    ShoppingBag, Store, AlertTriangle, MessageSquare, UserCircle,
    CreditCard, LayoutDashboard, Users, Settings, X,
    RefreshCw, Trash2, Megaphone, Inbox, Package, Wallet, Send, Truck
} from 'lucide-react';

const API_BASE = '/api/admin/menu_visibility.php';

// Menu definitions matching Layout.jsx
const SELLER_MENUS = [
    { key: '/seller', label: 'sidebar.home', icon: Home, group: 'main' },
    { key: '/seller/applications', label: 'sidebar.applicationStatus', icon: ClipboardList, group: 'main' },
    { key: '/seller/hosts', label: 'sidebar.hostDirectory', icon: Building, group: 'main' },
    { key: '/seller/popular', label: 'sidebar.popularSpaces', icon: Flame, group: 'main' },
    { key: '/seller/proposals', label: 'sidebar.distributionProposals', icon: Inbox, group: 'main' },
    { key: '/seller/shipments', label: 'sidebar.shippingManagement', icon: Package, group: 'main' },
    { key: '/seller/settlements', label: 'sidebar.settlements', icon: Wallet, group: 'main' },
    { key: '/seller/stats', label: 'sidebar.salesManagement', icon: TrendingUp, group: 'main' },
    { key: '/seller/analytics', label: 'sidebar.analytics', icon: BarChart3, group: 'main' },
    { key: '/seller/marketing', label: 'sidebar.marketing', icon: Megaphone, group: 'main' },
    { key: '/seller/community', label: 'sidebar.sellerCommunity', icon: ShoppingBag, group: 'community' },
    { key: '/seller/community/general', label: 'sidebar.integratedCommunity', icon: Users, group: 'community' },
    { key: '/seller/profile', label: 'sidebar.myProfile', icon: UserCircle, group: 'bottom' },
    { key: '/seller/payments', label: 'sidebar.servicePayment', icon: CreditCard, group: 'bottom' },
];

const VENDOR_MENUS = [
    { key: '/host', label: 'sidebar.home', icon: Home, group: 'main' },
    { key: '/host/dashboard', label: 'sidebar.dashboard', icon: LayoutDashboard, group: 'main' },
    { key: '/host/sellers', label: 'sidebar.sellerDirectory', icon: ShoppingBag, group: 'main' },
    { key: '/host/analytics', label: 'sidebar.analytics', icon: BarChart3, group: 'main' },
    { key: '/host/report', label: 'sidebar.analyticsReport', icon: TrendingUp, group: 'main' },
    { key: '/host/venues', label: 'sidebar.spaceManagement', icon: Store, group: 'management' },
    { key: '/host/applications', label: 'sidebar.applicationManagement', icon: ClipboardList, group: 'management' },
    { key: '/host/cancellations', label: 'sidebar.cancellationRequests', icon: AlertTriangle, group: 'management' },
    { key: '/host/marketing', label: 'sidebar.marketing', icon: Megaphone, group: 'main' },
    { key: '/host/community', label: 'sidebar.hostCommunity', icon: Store, group: 'community' },
    { key: '/host/community/general', label: 'sidebar.integratedCommunity', icon: Users, group: 'community' },
    { key: '/host/profile', label: 'sidebar.myProfile', icon: UserCircle, group: 'bottom' },
    { key: '/host/payments', label: 'sidebar.servicePayment', icon: CreditCard, group: 'bottom' },
];

// Vendor role menus (separate from host)
const VENDOR_ROLE_MENUS = [
    { key: '/vendor', label: 'sidebar.home', icon: Home, group: 'main' },
    { key: '/vendor/sellers', label: 'sidebar.sellerDirectory', icon: ShoppingBag, group: 'main' },
    { key: '/vendor/proposals', label: 'sidebar.distributionProposals', icon: Send, group: 'main' },
    { key: '/vendor/shipments', label: 'sidebar.shippingManagement', icon: Package, group: 'main' },
    { key: '/vendor/settlements', label: 'sidebar.settlements', icon: Wallet, group: 'main' },
    { key: '/vendor/profile', label: 'sidebar.myProfile', icon: UserCircle, group: 'bottom' },
];

const COUNTRY_FLAGS = {
    KR: '🇰🇷', US: '🇺🇸', GB: '🇬🇧', CA: '🇨🇦', JP: '🇯🇵',
    VN: '🇻🇳', TH: '🇹🇭', KH: '🇰🇭', RU: '🇷🇺', UA: '🇺🇦',
    // Lowercase DB aliases
    ko: '🇰🇷', ja: '🇯🇵', vi: '🇻🇳', th: '🇹🇭',
    km: '🇰🇭', ru: '🇷🇺', uk: '🇺🇦',
};

const AdminMenuVisibility = () => {
    const { t } = useTranslation('common');
    const [activeRole, setActiveRole] = useState('seller');
    const [activeTab, setActiveTab] = useState('global');
    const [rules, setRules] = useState([]);
    const [countries, setCountries] = useState([]);
    const [users, setUsers] = useState([]);
    const [loading, setLoading] = useState(false);
    const [saving, setSaving] = useState(false);
    const [toast, setToast] = useState(null);
    const [selectedCountry, setSelectedCountry] = useState('');
    const [selectedUser, setSelectedUser] = useState(null);
    const [userSearch, setUserSearch] = useState('');
    // Track local visibility state directly
    const [localVisibility, setLocalVisibility] = useState({});
    const [isDirty, setIsDirty] = useState(false);

    const menus = activeRole === 'seller' ? SELLER_MENUS : activeRole === 'vendor' ? VENDOR_ROLE_MENUS : VENDOR_MENUS;

    const groupLabels = {
        main: t('menuVis.mainMenu'),
        management: t('menuVis.managementMenu'),
        community: t('menuVis.communityMenu'),
        bottom: t('menuVis.otherMenu'),
    };

    const showToast = (message, type = 'success') => {
        setToast({ message, type });
        setTimeout(() => setToast(null), 3000);
    };

    // Fetch rules from server
    const fetchRules = useCallback(async (opts = {}) => {
        setLoading(true);
        try {
            let url = `${API_BASE}?role=${activeRole}&fetch_users=1&user_role=${activeRole}`;
            const search = opts.search ?? userSearch;
            if (search.trim()) url += `&user_search=${encodeURIComponent(search)}`;
            const res = await fetch(url, { credentials: 'include' });
            const data = await res.json();
            if (data.success) {
                setRules(data.rules || []);
                setCountries(data.countries || []);
                setUsers(data.users || []);
                // Build local visibility map based on current scope
                buildLocalVisibility(data.rules || []);
            }
        } catch {
            showToast(t('menuVis.loadFailed'), 'error');
        } finally {
            setLoading(false);
        }
    }, [activeRole, activeTab, userSearch]);

    // Build local visibility from rules for current scope
    const buildLocalVisibility = useCallback((rulesData, country, user) => {
        const cs = country ?? selectedCountry;
        const us = user ?? selectedUser;
        const vis = {};

        menus.forEach(m => {
            // Default: visible
            vis[m.key] = 1;

            if (activeTab === 'global') {
                const rule = rulesData.find(r => r.menu_key === m.key && r.scope === 'global');
                if (rule) vis[m.key] = parseInt(rule.is_visible);
            } else if (activeTab === 'country' && cs) {
                // Start from global, then overlay country
                const globalRule = rulesData.find(r => r.menu_key === m.key && r.scope === 'global');
                if (globalRule) vis[m.key] = parseInt(globalRule.is_visible);
                const countryRule = rulesData.find(r => r.menu_key === m.key && r.scope === 'country' && r.scope_value === cs);
                if (countryRule) vis[m.key] = parseInt(countryRule.is_visible);
            } else if (activeTab === 'user' && us) {
                // global → country → user
                const globalRule = rulesData.find(r => r.menu_key === m.key && r.scope === 'global');
                if (globalRule) vis[m.key] = parseInt(globalRule.is_visible);
                if (us.country) {
                    const countryRule = rulesData.find(r => r.menu_key === m.key && r.scope === 'country' && r.scope_value === us.country);
                    if (countryRule) vis[m.key] = parseInt(countryRule.is_visible);
                }
                const userRule = rulesData.find(r => r.menu_key === m.key && r.scope === 'user' && r.scope_value == us.id);
                if (userRule) vis[m.key] = parseInt(userRule.is_visible);
            }
        });

        setLocalVisibility(vis);
        setIsDirty(false);
    }, [menus, activeTab, selectedCountry, selectedUser]);

    // Refetch on role/tab change
    useEffect(() => {
        setSelectedCountry('');
        setSelectedUser(null);
        setUserSearch('');
        setIsDirty(false);
        fetchRules({ search: '' });
    }, [activeRole, activeTab]);

    // Rebuild local state when country/user selection changes
    useEffect(() => {
        if (rules.length > 0) {
            buildLocalVisibility(rules);
        }
    }, [selectedCountry, selectedUser]);

    // Debounced user search
    useEffect(() => {
        if (activeTab !== 'user') return;
        const timer = setTimeout(() => fetchRules(), 300);
        return () => clearTimeout(timer);
    }, [userSearch]);

    const toggleVisibility = (menuKey) => {
        setLocalVisibility(prev => ({
            ...prev,
            [menuKey]: prev[menuKey] === 1 ? 0 : 1
        }));
        setIsDirty(true);
    };

    const handleSave = async () => {
        setSaving(true);
        try {
            let rulesToSave = [];

            if (activeTab === 'country' && selectedCountry === '__ALL__') {
                // Save the same settings for ALL countries
                countries.forEach(c => {
                    menus.forEach(m => {
                        rulesToSave.push({
                            role: activeRole,
                            menu_key: m.key,
                            scope: 'country',
                            scope_value: c,
                            is_visible: localVisibility[m.key] ?? 1
                        });
                    });
                });
            } else {
                const scopeValue = activeTab === 'country' ? selectedCountry : activeTab === 'user' ? String(selectedUser?.id) : '';
                rulesToSave = menus.map(m => ({
                    role: activeRole,
                    menu_key: m.key,
                    scope: activeTab,
                    scope_value: scopeValue,
                    is_visible: localVisibility[m.key] ?? 1
                }));
            }

            const res = await fetch(API_BASE, {
                method: 'POST',
                credentials: 'include',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ rules: rulesToSave })
            });
            const data = await res.json();
            if (data.success) {
                showToast(selectedCountry === '__ALL__' ? (t('menuVis.allCountriesSaved') || '전체 국가에 저장되었습니다') : t('menuVis.saved'));
                setIsDirty(false);
                fetchRules();
            } else {
                showToast(data.message || t('menuVis.saveFailed'), 'error');
            }
        } catch {
            showToast(t('menuVis.serverError'), 'error');
        } finally {
            setSaving(false);
        }
    };

    const handleDeleteOverride = async () => {
        if (activeTab === 'global') return;
        const scopeValue = activeTab === 'country' ? selectedCountry : String(selectedUser?.id);
        if (!scopeValue) return;

        try {
            const res = await fetch(API_BASE, {
                method: 'DELETE',
                credentials: 'include',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ role: activeRole, scope: activeTab, scope_value: scopeValue })
            });
            const data = await res.json();
            if (data.success) {
                showToast(t('menuVis.overrideDeleted'));
                setIsDirty(false);
                fetchRules();
            }
        } catch {
            showToast(t('menuVis.serverError'), 'error');
        }
    };

    // Group menus for display
    const groupedMenus = {};
    menus.forEach(m => {
        if (!groupedMenus[m.group]) groupedMenus[m.group] = [];
        groupedMenus[m.group].push(m);
    });

    const canEdit = activeTab === 'global' || (activeTab === 'country' && selectedCountry) || (activeTab === 'user' && selectedUser);

    // Check if scope has overrides
    const scopeHasOverrides = () => {
        if (activeTab === 'country' && selectedCountry)
            return rules.some(r => r.scope === 'country' && r.scope_value === selectedCountry);
        if (activeTab === 'user' && selectedUser)
            return rules.some(r => r.scope === 'user' && r.scope_value == selectedUser.id);
        return false;
    };

    return (
        <div className="max-w-5xl mx-auto space-y-6">
            {/* Header */}
            <div className="bg-gradient-to-r from-slate-700 to-slate-900 rounded-2xl p-6 text-white relative overflow-hidden">
                <div className="absolute inset-0 opacity-10">
                    <div className="absolute -right-10 -top-10 w-40 h-40 bg-white rounded-full" />
                    <div className="absolute -left-5 -bottom-5 w-24 h-24 bg-white rounded-full" />
                </div>
                <div className="relative z-10">
                    <div className="flex items-center gap-3 mb-1">
                        <Settings size={28} />
                        <h1 className="text-2xl md:text-3xl font-extrabold">{t('menuVis.title')}</h1>
                    </div>
                    <p className="text-white/70 text-sm">{t('menuVis.subtitle')}</p>
                </div>
            </div>

            {/* Role Selector + Scope Tabs */}
            <div className="bg-white dark:bg-gray-800/50 rounded-2xl border border-gray-100 dark:border-gray-700/50 shadow-sm p-4 space-y-4">
                <div className="flex gap-2 flex-wrap">
                    {[{ key: 'seller', label: t('menuVis.seller'), icon: ShoppingBag },
                    { key: 'host', label: t('menuVis.vendor'), icon: Store },
                    { key: 'vendor', label: t('menuVis.vendorRole', 'Vendor'), icon: Truck }].map(r => (
                        <button key={r.key} onClick={() => setActiveRole(r.key)}
                            className={`flex items-center gap-2 px-5 py-2.5 rounded-xl text-sm font-bold transition-all ${activeRole === r.key
                                ? 'bg-violet-100 text-violet-700 dark:bg-violet-500/20 dark:text-violet-400 ring-2 ring-violet-300'
                                : 'bg-gray-50 text-gray-500 hover:bg-gray-100 dark:bg-gray-700/50 dark:text-gray-400'}`}>
                            <r.icon size={16} />
                            {r.label}
                            <span className="text-xs opacity-60">({t('menuVis.menuCount', { count: (r.key === 'seller' ? SELLER_MENUS : r.key === 'vendor' ? VENDOR_ROLE_MENUS : VENDOR_MENUS).length })})</span>
                        </button>
                    ))}
                </div>

                <div className="flex gap-2">
                    {[{ key: 'global', label: t('menuVis.globalTab'), icon: Globe, desc: t('menuVis.globalDesc') },
                    { key: 'country', label: t('menuVis.countryTab'), icon: MapPin, desc: t('menuVis.countryDesc') },
                    { key: 'user', label: t('menuVis.userTab'), icon: User, desc: t('menuVis.userDesc') }].map(tab => (
                        <button key={tab.key} onClick={() => setActiveTab(tab.key)}
                            className={`flex-1 flex items-center gap-2 px-4 py-3 rounded-xl text-sm font-bold transition-all ${activeTab === tab.key
                                ? 'bg-indigo-100 text-indigo-700 dark:bg-indigo-500/20 dark:text-indigo-400 ring-2 ring-indigo-300'
                                : 'bg-gray-50 text-gray-500 hover:bg-gray-100 dark:bg-gray-700/50 dark:text-gray-400'}`}>
                            <tab.icon size={16} />
                            <div className="text-left">
                                <div>{tab.label}</div>
                                <div className="text-[10px] font-normal opacity-60">{tab.desc}</div>
                            </div>
                        </button>
                    ))}
                </div>
            </div>

            {/* Country Selector */}
            {activeTab === 'country' && (
                <div className="bg-white dark:bg-gray-800/50 rounded-2xl border border-gray-100 dark:border-gray-700/50 shadow-sm p-4">
                    <h3 className="text-sm font-bold text-gray-700 dark:text-gray-300 mb-3 flex items-center gap-2">
                        <MapPin size={16} className="text-indigo-500" />
                        {t('menuVis.selectCountry')}
                    </h3>
                    <div className="flex flex-wrap gap-2">
                        {/* Select All Countries button */}
                        <button onClick={() => setSelectedCountry('__ALL__')}
                            className={`flex items-center gap-1.5 px-4 py-2 rounded-xl text-sm font-bold transition-all ${selectedCountry === '__ALL__'
                                ? 'bg-violet-100 text-violet-700 ring-2 ring-violet-300 dark:bg-violet-500/20 dark:text-violet-400'
                                : 'bg-violet-50 text-violet-600 hover:bg-violet-100 dark:bg-violet-700/30 dark:text-violet-400'}`}>
                            <Globe size={14} />
                            {t('menuVis.allCountries') || '전체 국가'}
                        </button>
                        {countries.length > 0 ? countries.map(c => {
                            const hasOvr = rules.some(r => r.scope === 'country' && r.scope_value === c);
                            return (
                                <button key={c} onClick={() => setSelectedCountry(c)}
                                    className={`flex items-center gap-1.5 px-4 py-2 rounded-xl text-sm font-bold transition-all ${selectedCountry === c
                                        ? 'bg-indigo-100 text-indigo-700 ring-2 ring-indigo-300 dark:bg-indigo-500/20 dark:text-indigo-400'
                                        : 'bg-gray-50 text-gray-600 hover:bg-gray-100 dark:bg-gray-700/50 dark:text-gray-400'}`}>
                                    <span>{COUNTRY_FLAGS[c] || '🏳️'}</span>
                                    {t(`menuVis.countries.${c}`) || c}
                                    {hasOvr && <span className="w-2 h-2 bg-amber-400 rounded-full" title={t('menuVis.hasOverride')} />}
                                </button>
                            );
                        }) : (
                            <p className="text-sm text-gray-400">{t('menuVis.noCountries')}</p>
                        )}
                    </div>
                </div>
            )}

            {/* User Selector */}
            {activeTab === 'user' && (
                <div className="bg-white dark:bg-gray-800/50 rounded-2xl border border-gray-100 dark:border-gray-700/50 shadow-sm p-4">
                    <h3 className="text-sm font-bold text-gray-700 dark:text-gray-300 mb-3 flex items-center gap-2">
                        <User size={16} className="text-indigo-500" />
                        {t('menuVis.searchUser')}
                        <span className="text-xs font-normal text-gray-400">— {t('menuVis.allUsers')}: {users.length}</span>
                    </h3>
                    <div className="relative mb-3">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={16} />
                        <input type="text" value={userSearch} onChange={e => setUserSearch(e.target.value)}
                            placeholder={t('menuVis.searchPlaceholder')}
                            className="w-full pl-10 pr-4 py-2.5 bg-gray-50 dark:bg-gray-700 rounded-xl border border-transparent focus:border-indigo-500 outline-none font-medium text-sm dark:text-white" />
                        {userSearch && (
                            <button onClick={() => setUserSearch('')} className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600">
                                <X size={14} />
                            </button>
                        )}
                    </div>
                    {users.length > 0 && (
                        <div className="max-h-60 overflow-y-auto space-y-1 border border-gray-100 dark:border-gray-700 rounded-xl p-2">
                            {users.map(u => {
                                const hasOvr = rules.some(r => r.scope === 'user' && r.scope_value == u.id);
                                return (
                                    <button key={u.id} onClick={() => setSelectedUser(u)}
                                        className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-lg text-sm transition-all text-left ${selectedUser?.id === u.id
                                            ? 'bg-indigo-100 dark:bg-indigo-500/20 ring-1 ring-indigo-300'
                                            : 'hover:bg-gray-50 dark:hover:bg-gray-700/50'}`}>
                                        <div className="w-9 h-9 rounded-full bg-gradient-to-br from-indigo-400 to-violet-500 flex items-center justify-center text-white text-xs font-bold flex-shrink-0">
                                            {u.name?.[0] || '?'}
                                        </div>
                                        <div className="flex-1 min-w-0">
                                            <div className="font-bold text-gray-800 dark:text-gray-200 truncate">{u.name}</div>
                                            <div className="text-xs text-gray-400 truncate">{u.email} · ID: {u.id}</div>
                                        </div>
                                        {u.country && <span className="text-sm flex-shrink-0">{COUNTRY_FLAGS[u.country] || u.country}</span>}
                                        {hasOvr && <span className="w-2 h-2 bg-amber-400 rounded-full flex-shrink-0" title={t('menuVis.hasOverride')} />}
                                    </button>
                                );
                            })}
                        </div>
                    )}
                </div>
            )}

            {/* Menu Toggle Grid */}
            {canEdit && !loading && (
                <div className="bg-white dark:bg-gray-800/50 rounded-2xl border border-gray-100 dark:border-gray-700/50 shadow-sm overflow-hidden">
                    {/* Title bar */}
                    <div className="px-6 py-4 border-b border-gray-100 dark:border-gray-700/50 flex items-center justify-between flex-wrap gap-2">
                        <div>
                            <h3 className="font-bold text-gray-800 dark:text-white flex items-center gap-2 flex-wrap">
                                <Eye size={18} className="text-indigo-500" />
                                {activeRole === 'seller' ? t('menuVis.seller') : t('menuVis.vendor')} {t('menuVis.menuSettings')}
                                {activeTab === 'country' && selectedCountry && (
                                    <span className="text-sm font-normal text-gray-400">
                                        — {selectedCountry === '__ALL__' ? `🌐 ${t('menuVis.allCountries')}` : `${COUNTRY_FLAGS[selectedCountry] || ''} ${t(`menuVis.countries.${selectedCountry}`) || selectedCountry}`}
                                    </span>
                                )}
                                {activeTab === 'user' && selectedUser && (
                                    <span className="text-sm font-normal text-gray-400">
                                        — {selectedUser.name} ({selectedUser.email})
                                    </span>
                                )}
                            </h3>
                            <p className="text-xs text-gray-400 mt-0.5">
                                {activeTab === 'global' && t('menuVis.globalNote')}
                                {activeTab === 'country' && t('menuVis.countryNote')}
                                {activeTab === 'user' && t('menuVis.userNote')}
                            </p>
                        </div>
                        <div className="flex items-center gap-2">
                            {activeTab !== 'global' && scopeHasOverrides() && (
                                <button onClick={handleDeleteOverride}
                                    className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-red-50 text-red-600 dark:bg-red-500/10 dark:text-red-400 text-xs font-bold hover:bg-red-100 transition-colors">
                                    <Trash2 size={13} />
                                    {t('menuVis.deleteOverride')}
                                </button>
                            )}
                            <button onClick={handleSave} disabled={saving}
                                className={`flex items-center gap-1.5 px-4 py-2 rounded-xl text-sm font-bold transition-colors disabled:opacity-50 ${isDirty
                                    ? 'bg-indigo-600 text-white hover:bg-indigo-700 shadow-lg shadow-indigo-500/30'
                                    : 'bg-gray-200 text-gray-500 dark:bg-gray-700 dark:text-gray-400'}`}>
                                {saving ? <RefreshCw size={14} className="animate-spin" /> : <Save size={14} />}
                                {t('menuVis.save')}
                            </button>
                        </div>
                    </div>

                    {/* Menu items by group */}
                    <div className="divide-y divide-gray-50 dark:divide-gray-700/30">
                        {Object.entries(groupedMenus).map(([group, items]) => (
                            <div key={group}>
                                <div className="px-6 py-2 bg-gray-50/50 dark:bg-gray-700/20">
                                    <span className="text-xs font-bold text-gray-400 uppercase tracking-wider">{groupLabels[group] || group}</span>
                                </div>
                                {items.map(menu => {
                                    const visible = localVisibility[menu.key] ?? 1;
                                    const Icon = menu.icon;

                                    return (
                                        <div key={menu.key}
                                            className="flex items-center justify-between px-6 py-3 hover:bg-gray-50/50 dark:hover:bg-gray-700/20 transition-colors">
                                            <div className="flex items-center gap-3">
                                                <div className={`w-9 h-9 rounded-lg flex items-center justify-center transition-colors ${visible ? 'bg-indigo-100 dark:bg-indigo-500/20' : 'bg-gray-100 dark:bg-gray-700'}`}>
                                                    <Icon size={16} className={visible ? 'text-indigo-600 dark:text-indigo-400' : 'text-gray-400'} />
                                                </div>
                                                <div>
                                                    <div className={`text-sm font-bold transition-colors ${visible ? 'text-gray-800 dark:text-gray-200' : 'text-gray-400'}`}>
                                                        {t(menu.label)}
                                                    </div>
                                                    <div className="text-[10px] text-gray-400 font-mono">{menu.key}</div>
                                                </div>
                                            </div>
                                            <button onClick={() => toggleVisibility(menu.key)}
                                                className={`relative w-12 h-7 rounded-full transition-all duration-300 flex-shrink-0 ${visible
                                                    ? 'bg-indigo-500 shadow-inner shadow-indigo-600'
                                                    : 'bg-gray-300 dark:bg-gray-600 shadow-inner'}`}>
                                                <div className={`absolute top-0.5 w-6 h-6 bg-white rounded-full shadow-md transition-all duration-300 flex items-center justify-center ${visible ? 'left-[22px]' : 'left-0.5'}`}>
                                                    {visible ? <Eye size={12} className="text-indigo-500" /> : <EyeOff size={12} className="text-gray-400" />}
                                                </div>
                                            </button>
                                        </div>
                                    );
                                })}
                            </div>
                        ))}
                    </div>
                </div>
            )}

            {/* No selection message */}
            {!canEdit && (activeTab === 'country' || activeTab === 'user') && !loading && (
                <div className="bg-white dark:bg-gray-800/50 rounded-2xl border border-gray-100 dark:border-gray-700/50 shadow-sm p-12 text-center">
                    <div className="w-16 h-16 bg-gray-100 dark:bg-gray-700 rounded-2xl flex items-center justify-center mx-auto mb-4">
                        {activeTab === 'country' ? <MapPin size={28} className="text-gray-300" /> : <User size={28} className="text-gray-300" />}
                    </div>
                    <h3 className="text-lg font-bold text-gray-400 dark:text-gray-500">
                        {activeTab === 'country' ? t('menuVis.selectCountryPrompt') : t('menuVis.selectUserPrompt')}
                    </h3>
                    <p className="text-sm text-gray-300 mt-1">
                        {activeTab === 'country' ? t('menuVis.selectCountryDesc') : t('menuVis.selectUserDesc')}
                    </p>
                </div>
            )}

            {/* Loading */}
            {loading && (
                <div className="flex items-center justify-center py-8">
                    <div className="animate-spin rounded-full h-8 w-8 border-2 border-indigo-600 border-t-transparent" />
                </div>
            )}

            {/* Toast */}
            {toast && (
                <div className={`fixed bottom-6 left-1/2 -translate-x-1/2 z-50 px-6 py-3 rounded-xl text-sm font-bold shadow-lg transition-all ${toast.type === 'error' ? 'bg-red-600 text-white' : 'bg-emerald-600 text-white'}`}>
                    {toast.message}
                </div>
            )}
        </div>
    );
};

export default AdminMenuVisibility;

import React, { useState, useEffect, useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import {
    CreditCard, Settings, History, Save, ToggleLeft, ToggleRight,
    CheckCircle, XCircle, Clock, Search, Filter, ChevronDown, ChevronUp,
    Copy, AlertTriangle, Banknote, Eye, X, Send, Plus, Edit2,
    Trash2, GripVertical, Package, List, Star, ArrowUp, ArrowDown,
    Tag, Layers, ShoppingBag, Zap, Crown, Globe, Languages, RefreshCw
} from 'lucide-react';
import NumberInput from '../../components/NumberInput';

const API_BASE = '/api/payments';

const STATUS_MAP_KEYS = {
    pending: { labelKey: 'paymentsPage.statusPending', color: 'text-gray-500', bg: 'bg-gray-50 border-gray-200', dot: 'bg-gray-400', icon: Clock },
    submitted: { labelKey: 'paymentsPage.statusSubmitted', color: 'text-blue-600', bg: 'bg-blue-50 border-blue-200', dot: 'bg-blue-500', icon: Send },
    confirmed: { labelKey: 'paymentsPage.statusConfirmed', color: 'text-emerald-600', bg: 'bg-emerald-50 border-emerald-200', dot: 'bg-emerald-500', icon: CheckCircle },
    rejected: { labelKey: 'paymentsPage.statusRejected', color: 'text-red-600', bg: 'bg-red-50 border-red-200', dot: 'bg-red-500', icon: XCircle }
};

const PERIOD_MAP_KEYS = { monthly: 'paymentsPage.periodMonthly', yearly: 'paymentsPage.periodYearly', once: 'paymentsPage.periodOnce' };
const ROLE_MAP_KEYS = { all: 'paymentsPage.roleAll', host: 'paymentsPage.roleHost', seller: 'paymentsPage.roleSeller' };

const LANG_OPTIONS = [
    { code: 'en', label: 'English', flag: '🇺🇸' },
    { code: 'vi', label: 'Việt Nam', flag: '🇻🇳' },
    { code: 'ja', label: '日本語', flag: '🇯🇵' },
    { code: 'th', label: 'ไทย', flag: '🇹🇭' },
    { code: 'km', label: 'ខ្មែរ', flag: '🇰🇭' },
    { code: 'ru', label: 'Русский', flag: '🇷🇺' },
    { code: 'uk', label: 'Українська', flag: '🇺🇦' },
];

const CATEGORY_KEY_OPTIONS = ['categoryListing', 'categoryMarketing', 'categoryPremium', 'categoryOther'];
const CATEGORY_META_KEYS = {
    categoryListing: { icon: ShoppingBag, color: 'text-indigo-600', bg: 'bg-indigo-50', border: 'border-indigo-200' },
    categoryMarketing: { icon: Zap, color: 'text-emerald-600', bg: 'bg-emerald-50', border: 'border-emerald-200' },
    categoryPremium: { icon: Crown, color: 'text-amber-600', bg: 'bg-amber-50', border: 'border-amber-200' },
};
const DEFAULT_CAT_META = { icon: Layers, color: 'text-purple-600', bg: 'bg-purple-50', border: 'border-purple-200' };

const AdminPayments = () => {
    const { t } = useTranslation('admin');
    const [activeTab, setActiveTab] = useState('plans');
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);
    const [toast, setToast] = useState(null);

    // Settings state
    const [settings, setSettings] = useState({
        is_payment_enabled: 0,
        bank_name: '',
        account_number: '',
        account_holder: '',
        payment_notice: '',
        platform_fee_amount: 0,
        platform_fee_period: 'monthly'
    });

    // Plans state
    const [plans, setPlans] = useState([]);
    const [planModal, setPlanModal] = useState(null); // null | 'new' | plan object
    const [planForm, setPlanForm] = useState({ name: '', description: '', amount: 0, period: 'monthly', features: [], target_role: 'all', category: '', plan_type: 'single', is_active: 1, sort_order: 0 });
    const [customCategory, setCustomCategory] = useState('');
    const [featureInput, setFeatureInput] = useState('');
    const [planSaving, setPlanSaving] = useState(false);
    const [deleteConfirm, setDeleteConfirm] = useState(null);
    // Translation state
    const [transLang, setTransLang] = useState('en');
    const [translating, setTranslating] = useState(false);

    // Payments state
    const [payments, setPayments] = useState([]);
    const [statusFilter, setStatusFilter] = useState('all');
    const [typeFilter, setTypeFilter] = useState('all');
    const [searchQuery, setSearchQuery] = useState('');

    // Confirm modal
    const [confirmModal, setConfirmModal] = useState(null);
    const [adminNote, setAdminNote] = useState('');
    const [processing, setProcessing] = useState(false);

    // Detail modal
    const [detailModal, setDetailModal] = useState(null);

    const showToast = (message, type = 'success') => {
        setToast({ message, type });
        setTimeout(() => setToast(null), 3000);
    };

    useEffect(() => {
        fetchSettings();
        fetchPlans();
        fetchPayments();
    }, []);

    const fetchSettings = async () => {
        try {
            const res = await fetch(`${API_BASE}/get_settings.php`, { credentials: 'include' });
            const data = await res.json();
            if (data.success) setSettings(data.settings);
        } catch (err) { console.error(err); }
        finally { setLoading(false); }
    };

    const fetchPlans = async () => {
        try {
            const res = await fetch(`${API_BASE}/manage_plans.php`, {
                method: 'POST', credentials: 'include',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ action: 'list' })
            });
            const data = await res.json();
            if (data.success) setPlans(data.plans);
        } catch (err) { console.error(err); }
    };

    const fetchPayments = async () => {
        try {
            const res = await fetch(`${API_BASE}/get_payments.php`, { credentials: 'include' });
            const data = await res.json();
            if (data.success) setPayments(data.payments);
        } catch (err) { console.error(err); }
    };

    const handleSaveSettings = async () => {
        setSaving(true);
        try {
            const res = await fetch(`${API_BASE}/update_settings.php`, {
                method: 'POST', credentials: 'include',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(settings)
            });
            const data = await res.json();
            showToast(data.success ? t('paymentsPage.settingsSaved') : (data.message || t('paymentsPage.saveFailed')), data.success ? 'success' : 'error');
        } catch (err) { showToast(t('paymentsPage.errorOccurred'), 'error'); }
        finally { setSaving(false); }
    };

    // ─── Plan CRUD ───
    const openPlanModal = (plan = null) => {
        if (plan) {
            const cat = plan.category || '';
            const isCustom = cat && !CATEGORY_OPTIONS.includes(cat);
            setPlanForm({
                name: plan.name || '', description: plan.description || '', amount: plan.amount || 0,
                period: plan.period || 'monthly', features: plan.features || [], target_role: plan.target_role || 'all',
                category: isCustom ? '__custom__' : cat, plan_type: plan.plan_type || 'single',
                is_active: plan.is_active ?? 1, sort_order: plan.sort_order || 0,
                translations: plan.translations || {}
            });
            setCustomCategory(isCustom ? cat : '');
            setPlanModal(plan);
        } else {
            setPlanForm({ name: '', description: '', amount: 0, period: 'monthly', features: [], target_role: 'all', category: '', plan_type: 'single', is_active: 1, sort_order: plans.length, translations: {} });
            setCustomCategory('');
            setPlanModal('new');
        }
        setFeatureInput('');
        setTransLang('en');
    };

    // ─── Translation helpers ───
    const updateTranslation = (lang, field, value) => {
        setPlanForm(f => ({
            ...f,
            translations: {
                ...f.translations,
                [lang]: { ...(f.translations?.[lang] || {}), [field]: value }
            }
        }));
    };

    const updateTransFeature = (lang, idx, value) => {
        setPlanForm(f => {
            const current = f.translations?.[lang]?.features || [];
            const updated = [...current];
            updated[idx] = value;
            return {
                ...f,
                translations: {
                    ...f.translations,
                    [lang]: { ...(f.translations?.[lang] || {}), features: updated }
                }
            };
        });
    };

    const autoTranslateAll = async () => {
        if (!planForm.name.trim()) {
            showToast(t('paymentsPage.enterServiceName'), 'error');
            return;
        }
        setTranslating(true);
        try {
            const myMemoryLangMap = { en: 'en', vi: 'vi', ja: 'ja', th: 'th', km: 'km', ru: 'ru', uk: 'uk' };
            const newTranslations = { ...planForm.translations };

            for (const lang of LANG_OPTIONS) {
                const targetLang = myMemoryLangMap[lang.code] || lang.code;
                const translateOne = async (text) => {
                    if (!text || !text.trim()) return '';
                    try {
                        const response = await fetch(`https://api.mymemory.translated.net/get?q=${encodeURIComponent(text)}&langpair=ko|${targetLang}`);
                        const data = await response.json();
                        if (data.responseStatus === 200 && data.responseData?.translatedText) {
                            return data.responseData.translatedText;
                        }
                        return text;
                    } catch {
                        return text;
                    }
                };

                const translatedName = await translateOne(planForm.name);
                const translatedDesc = await translateOne(planForm.description);
                const translatedFeatures = [];
                for (const f of planForm.features) {
                    translatedFeatures.push(await translateOne(f));
                }

                newTranslations[lang.code] = {
                    name: translatedName,
                    description: translatedDesc,
                    features: translatedFeatures
                };
            }

            setPlanForm(f => ({ ...f, translations: newTranslations }));
            showToast(t('paymentsPage.autoTranslateSuccess', '자동 번역이 완료되었습니다!'));
        } catch (err) {
            console.error('Auto-translate error:', err);
            showToast(t('paymentsPage.autoTranslateFailed', '자동 번역에 실패했습니다.'), 'error');
        } finally {
            setTranslating(false);
        }
    };

    const addFeature = () => {
        if (featureInput.trim()) {
            setPlanForm(f => ({ ...f, features: [...f.features, featureInput.trim()] }));
            setFeatureInput('');
        }
    };

    const removeFeature = (idx) => {
        setPlanForm(f => ({ ...f, features: f.features.filter((_, i) => i !== idx) }));
    };

    const handleSavePlan = async () => {
        if (!planForm.name.trim()) { showToast(t('paymentsPage.enterServiceName'), 'error'); return; }
        if (planForm.amount <= 0) { showToast(t('paymentsPage.enterAmount'), 'error'); return; }
        setPlanSaving(true);
        try {
            const isEdit = planModal !== 'new';
            const finalCategory = planForm.category === '__custom__' ? customCategory.trim() : planForm.category;
            const res = await fetch(`${API_BASE}/manage_plans.php`, {
                method: 'POST', credentials: 'include',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    action: isEdit ? 'update' : 'create',
                    ...(isEdit ? { id: planModal.id } : {}),
                    ...planForm,
                    category: finalCategory,
                    translations: planForm.translations || {}
                })
            });
            const data = await res.json();
            if (data.success) {
                showToast(data.message);
                setPlanModal(null);
                fetchPlans();
            } else {
                const debugInfo = data.debug_role !== undefined ? ` (role: ${data.debug_role || 'empty'})` : '';
                showToast((data.message || t('paymentsPage.saveFailed')) + debugInfo, 'error');
            }
        } catch (err) { showToast(t('paymentsPage.errorOccurred') + ': ' + err.message, 'error'); }
        finally { setPlanSaving(false); }
    };

    const handleDeletePlan = async (id) => {
        try {
            const res = await fetch(`${API_BASE}/manage_plans.php`, {
                method: 'POST', credentials: 'include',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ action: 'delete', id })
            });
            const data = await res.json();
            if (data.success) { showToast(data.message); fetchPlans(); }
            else showToast(data.message || t('paymentsPage.deleteFailed'), 'error');
        } catch (err) { showToast(t('paymentsPage.errorOccurred'), 'error'); }
        setDeleteConfirm(null);
    };

    const handleTogglePlan = async (id) => {
        try {
            const res = await fetch(`${API_BASE}/manage_plans.php`, {
                method: 'POST', credentials: 'include',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ action: 'toggle', id })
            });
            const data = await res.json();
            if (data.success) fetchPlans();
        } catch (err) { console.error(err); }
    };

    const handleMovePlan = async (index, direction) => {
        const newPlans = [...plans];
        const targetIndex = direction === 'up' ? index - 1 : index + 1;
        if (targetIndex < 0 || targetIndex >= newPlans.length) return;
        [newPlans[index], newPlans[targetIndex]] = [newPlans[targetIndex], newPlans[index]];
        setPlans(newPlans);
        try {
            const res = await fetch(`${API_BASE}/manage_plans.php`, {
                method: 'POST', credentials: 'include',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ action: 'reorder', ordered_ids: newPlans.map(p => p.id) })
            });
            const data = await res.json();
            if (data.success) showToast(t('paymentsPage.orderChanged'));
            else { showToast(data.message || t('paymentsPage.orderFailed'), 'error'); fetchPlans(); }
        } catch (err) { showToast(t('paymentsPage.errorOccurred'), 'error'); fetchPlans(); }
    };

    // ─── Payment Actions ───
    const handleConfirmAction = async (action) => {
        if (!confirmModal) return;
        setProcessing(true);
        try {
            const res = await fetch(`${API_BASE}/confirm_payment.php`, {
                method: 'POST', credentials: 'include',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ payment_id: confirmModal.id, action, admin_note: adminNote })
            });
            const data = await res.json();
            if (data.success) { showToast(data.message); setConfirmModal(null); setAdminNote(''); fetchPayments(); }
            else showToast(data.message || t('paymentsPage.processFailed'), 'error');
        } catch (err) { showToast(t('paymentsPage.errorOccurred'), 'error'); }
        finally { setProcessing(false); }
    };

    const filteredPayments = useMemo(() => {
        let result = payments;
        if (statusFilter !== 'all') result = result.filter(p => p.status === statusFilter);
        if (typeFilter !== 'all') result = result.filter(p => p.payment_type === typeFilter);
        if (searchQuery.trim()) {
            const q = searchQuery.toLowerCase();
            result = result.filter(p =>
                (p.user_name || '').toLowerCase().includes(q) ||
                (p.depositor_name || '').toLowerCase().includes(q) ||
                (p.reference_label || '').toLowerCase().includes(q)
            );
        }
        return result;
    }, [payments, statusFilter, typeFilter, searchQuery]);

    // Group plans by category for display
    const groupedPlans = useMemo(() => {
        const catKeyMap = {
            '입점 서비스': 'categoryListing', '마케팅 서비스': 'categoryMarketing',
            '프리미엄 서비스': 'categoryPremium'
        };
        const groups = {};
        plans.forEach(plan => {
            const rawCat = plan.category?.trim() || '';
            const catKey = catKeyMap[rawCat] || rawCat || 'categoryOther';
            if (!groups[catKey]) groups[catKey] = [];
            groups[catKey].push(plan);
        });
        const order = ['categoryListing', 'categoryMarketing', 'categoryPremium'];
        const result = [];
        order.forEach(cat => {
            if (groups[cat]) { result.push({ category: cat, plans: groups[cat] }); delete groups[cat]; }
        });
        Object.entries(groups).forEach(([cat, ps]) => result.push({ category: cat, plans: ps }));
        return result;
    }, [plans]);

    const stats = useMemo(() => ({
        total: payments.length,
        pending: payments.filter(p => p.status === 'pending').length,
        submitted: payments.filter(p => p.status === 'submitted').length,
        confirmed: payments.filter(p => p.status === 'confirmed').length,
        totalConfirmed: payments.filter(p => p.status === 'confirmed').reduce((s, p) => s + parseInt(p.amount || 0), 0),
    }), [payments]);

    if (loading) {
        return (
            <div className="flex items-center justify-center py-20">
                <div className="animate-spin w-8 h-8 border-4 border-indigo-200 border-t-indigo-600 rounded-full" />
            </div>
        );
    }

    return (
        <div className="space-y-6 pb-20">
            {/* Toast */}
            {toast && (
                <div className={`fixed top-6 right-6 z-50 px-5 py-3 rounded-xl shadow-xl text-sm font-bold text-white transition-all ${toast.type === 'error' ? 'bg-red-500' : 'bg-emerald-500'}`}
                    style={{ animation: 'popupScale 0.3s ease' }}>
                    {toast.message}
                </div>
            )}

            {/* Header */}
            <div className="flex flex-col gap-4 md:flex-row md:items-end justify-between">
                <div>
                    <h1 className="text-2xl md:text-3xl lg:text-4xl font-extrabold text-gray-900 flex items-center gap-3">
                        <div className="w-10 h-10 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-2xl flex items-center justify-center text-white shadow-lg">
                            <CreditCard size={20} />
                        </div>
                        {t('paymentsPage.title')}
                    </h1>
                    <p className="text-gray-500 font-medium mt-2">{t('paymentsPage.subtitle')}</p>
                </div>

                {/* Tab Switcher */}
                <div className="flex p-1 bg-gray-100/80 rounded-xl">
                    {[
                        { id: 'plans', icon: Package, label: t('paymentsPage.tabPlans') },
                        { id: 'settings', icon: Settings, label: t('paymentsPage.tabSettings') },
                        { id: 'history', icon: History, label: t('paymentsPage.tabHistory'), badge: stats.submitted },
                    ].map(tab => (
                        <button key={tab.id}
                            onClick={() => setActiveTab(tab.id)}
                            className={`flex items-center gap-2 px-4 py-2.5 rounded-lg text-sm font-bold transition-all ${activeTab === tab.id ? 'bg-white text-gray-900 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
                        >
                            <tab.icon size={16} /> {tab.label}
                            {tab.badge > 0 && <span className="ml-1 px-2 py-0.5 bg-red-100 text-red-600 rounded-full text-xs font-bold">{tab.badge}</span>}
                        </button>
                    ))}
                </div>
            </div>

            {/* ═══════════════════════════════════════════ */}
            {/* ═══ Plans Tab ═══ */}
            {/* ═══════════════════════════════════════════ */}
            {activeTab === 'plans' && (
                <div className="space-y-6">
                    <div className="flex items-center justify-between">
                        <p className="text-sm text-gray-500">
                            {t('paymentsPage.planDesc', { count: plans.length })}
                        </p>
                        <button onClick={() => openPlanModal()} className="flex items-center gap-2 px-5 py-2.5 bg-indigo-600 text-white rounded-xl text-sm font-bold hover:bg-indigo-700 transition-colors shadow-lg shadow-indigo-200">
                            <Plus size={16} /> {t('paymentsPage.addService')}
                        </button>
                    </div>

                    {/* Plans — Category Grouped */}
                    {groupedPlans.length > 0 ? (
                        <div className="space-y-8">
                            {groupedPlans.map(group => {
                                const catMeta = CATEGORY_META_KEYS[group.category] || DEFAULT_CAT_META;
                                const CatIcon = catMeta.icon;
                                return (
                                    <div key={group.category}>
                                        {/* Category Header */}
                                        <div className="flex items-center gap-3 mb-4">
                                            <div className={`w-8 h-8 rounded-lg flex items-center justify-center ${catMeta.bg} ${catMeta.color}`}>
                                                <CatIcon size={16} />
                                            </div>
                                            <div>
                                                <h3 className="text-base font-extrabold text-gray-900">{t(`paymentsPage.${group.category}`)}</h3>
                                                <p className="text-xs text-gray-400">{t('paymentsPage.serviceCount', { count: group.plans.length })}</p>
                                            </div>
                                        </div>

                                        {/* Plans Grid */}
                                        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-5">
                                            {group.plans.map((plan, index) => {
                                                const globalIndex = plans.indexOf(plan);
                                                const isPackage = plan.plan_type === 'package';
                                                return (
                                                    <div key={plan.id}
                                                        className={`bg-white rounded-2xl border shadow-sm p-5 relative transition-all hover:shadow-lg ${plan.is_active == 1 ? 'border-gray-100' : 'border-gray-200 opacity-60'} ${isPackage ? 'ring-2 ring-amber-200/50' : ''}`}>
                                                        {/* Top Bar: Reorder + Actions */}
                                                        <div className="flex items-center justify-between mb-3">
                                                            <div className="flex items-center gap-1">
                                                                <button onClick={() => handleMovePlan(globalIndex, 'up')} disabled={globalIndex === 0}
                                                                    className={`p-1 rounded-md transition-colors ${globalIndex === 0 ? 'text-gray-200 cursor-not-allowed' : 'text-gray-400 hover:text-indigo-600 hover:bg-indigo-50'}`}
                                                                    title={t('paymentsPage.moveForward')}>
                                                                    <ArrowUp size={14} />
                                                                </button>
                                                                <span className="text-xs font-bold text-gray-300 min-w-[18px] text-center">{globalIndex + 1}</span>
                                                                <button onClick={() => handleMovePlan(globalIndex, 'down')} disabled={globalIndex === plans.length - 1}
                                                                    className={`p-1 rounded-md transition-colors ${globalIndex === plans.length - 1 ? 'text-gray-200 cursor-not-allowed' : 'text-gray-400 hover:text-indigo-600 hover:bg-indigo-50'}`}
                                                                    title={t('paymentsPage.moveBack')}>
                                                                    <ArrowDown size={14} />
                                                                </button>
                                                            </div>
                                                            <div className="flex gap-1">
                                                                <button onClick={() => handleTogglePlan(plan.id)}
                                                                    className={`p-1.5 rounded-lg transition-colors ${plan.is_active == 1 ? 'text-emerald-600 hover:bg-emerald-50' : 'text-gray-400 hover:bg-gray-100'}`}
                                                                    title={plan.is_active == 1 ? t('paymentsPage.deactivate') : t('paymentsPage.activate')}>
                                                                    {plan.is_active == 1 ? <ToggleRight size={18} /> : <ToggleLeft size={18} />}
                                                                </button>
                                                                <button onClick={() => openPlanModal(plan)}
                                                                    className="p-1.5 text-gray-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors" title={t('paymentsPage.edit')}>
                                                                    <Edit2 size={16} />
                                                                </button>
                                                                <button onClick={() => setDeleteConfirm(plan)}
                                                                    className="p-1.5 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors" title={t('paymentsPage.delete')}>
                                                                    <Trash2 size={16} />
                                                                </button>
                                                            </div>
                                                        </div>

                                                        {/* Name + Badges */}
                                                        <h4 className="font-bold text-gray-900 text-lg">{plan.name}</h4>
                                                        <div className="mt-1 mb-3 flex flex-wrap gap-1">
                                                            <span className={`inline-flex px-2 py-0.5 rounded-full text-xs font-bold ${plan.is_active == 1 ? 'bg-emerald-100 text-emerald-700' : 'bg-gray-100 text-gray-500'}`}>
                                                                {plan.is_active == 1 ? t('paymentsPage.active') : t('paymentsPage.inactive')}
                                                            </span>
                                                            <span className="inline-flex px-2 py-0.5 rounded-full text-xs font-bold bg-indigo-100 text-indigo-700">
                                                                {t(ROLE_MAP_KEYS[plan.target_role] || 'paymentsPage.roleAll')}
                                                            </span>
                                                            {isPackage && (
                                                                <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-bold bg-amber-100 text-amber-700 border border-amber-200">
                                                                    <Layers size={10} /> {t('paymentsPage.package')}
                                                                </span>
                                                            )}
                                                        </div>

                                                        {/* Price */}
                                                        <p className="text-2xl font-extrabold text-gray-900 mb-2">
                                                            ₩{parseInt(plan.amount || 0).toLocaleString()}
                                                            <span className="text-sm text-gray-400 font-medium ml-1">/ {t(PERIOD_MAP_KEYS[plan.period] || 'paymentsPage.periodMonthly')}</span>
                                                        </p>

                                                        {/* Description */}
                                                        {plan.description && (
                                                            <p className="text-sm text-gray-500 mb-3 line-clamp-2">{plan.description}</p>
                                                        )}

                                                        {/* Features */}
                                                        {plan.features && plan.features.length > 0 && (
                                                            <div className="space-y-1.5 pt-3 border-t border-gray-100">
                                                                {plan.features.map((f, i) => (
                                                                    <div key={i} className="flex items-center gap-2 text-sm text-gray-600">
                                                                        <CheckCircle size={14} className={`${isPackage ? 'text-amber-500' : 'text-emerald-500'} flex-shrink-0`} />
                                                                        <span>{f}</span>
                                                                    </div>
                                                                ))}
                                                            </div>
                                                        )}
                                                    </div>
                                                );
                                            })}
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    ) : (
                        <div className="py-16 text-center bg-gray-50 rounded-2xl border border-dashed border-gray-200">
                            <div className="w-16 h-16 bg-white rounded-full flex items-center justify-center mx-auto mb-4 shadow-sm text-gray-300">
                                <Package size={24} />
                            </div>
                            <p className="font-bold text-gray-400 mb-1">{t('paymentsPage.noServicesTitle')}</p>
                            <p className="text-sm text-gray-300 mb-4">{t('paymentsPage.noServicesDesc')}</p>
                            <button onClick={() => openPlanModal()} className="px-5 py-2.5 bg-indigo-600 text-white rounded-xl text-sm font-bold hover:bg-indigo-700 transition-colors">
                                <Plus size={14} className="inline mr-1" /> {t('paymentsPage.addFirstService')}
                            </button>
                        </div>
                    )}
                </div>
            )}

            {/* ═══════════════════════════════════════════ */}
            {/* ═══ Settings Tab ═══ */}
            {/* ═══════════════════════════════════════════ */}
            {activeTab === 'settings' && (
                <div className="space-y-6">
                    {/* Payment Toggle */}
                    <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-6">
                        <div className="flex items-center justify-between">
                            <div>
                                <h3 className="text-lg font-bold text-gray-900">{t('paymentsPage.paymentFeature')}</h3>
                                <p className="text-sm text-gray-500 mt-1">{t('paymentsPage.paymentFeatureDesc')}</p>
                            </div>
                            <button
                                onClick={() => setSettings(s => ({ ...s, is_payment_enabled: s.is_payment_enabled ? 0 : 1 }))}
                                className={`flex items-center gap-2 px-5 py-3 rounded-xl font-bold text-sm transition-all ${settings.is_payment_enabled
                                    ? 'bg-emerald-500 text-white hover:bg-emerald-600 shadow-lg shadow-emerald-200'
                                    : 'bg-gray-200 text-gray-600 hover:bg-gray-300'}`}
                            >
                                {settings.is_payment_enabled ? <ToggleRight size={20} /> : <ToggleLeft size={20} />}
                                {settings.is_payment_enabled ? t('paymentsPage.paymentOn') : t('paymentsPage.paymentOff')}
                            </button>
                        </div>
                        {!settings.is_payment_enabled && (
                            <div className="mt-4 bg-amber-50 border border-amber-200 rounded-xl p-4 flex items-start gap-3">
                                <AlertTriangle size={18} className="text-amber-500 flex-shrink-0 mt-0.5" />
                                <div className="text-sm text-amber-800">
                                    <p className="font-bold">{t('paymentsPage.paymentDisabledTitle')}</p>
                                    <p>{t('paymentsPage.paymentDisabledDesc')}</p>
                                </div>
                            </div>
                        )}
                    </div>

                    {/* Bank Account */}
                    <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-6">
                        <h3 className="text-lg font-bold text-gray-900 mb-5 flex items-center gap-2">
                            <Banknote size={20} className="text-indigo-500" /> {t('paymentsPage.bankInfo')}
                        </h3>
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                            {[
                                { key: 'bank_name', label: t('paymentsPage.bankName'), placeholder: t('paymentsPage.bankNamePlaceholder') },
                                { key: 'account_number', label: t('paymentsPage.accountNumber'), placeholder: t('paymentsPage.accountNumberPlaceholder') },
                                { key: 'account_holder', label: t('paymentsPage.accountHolder'), placeholder: t('paymentsPage.accountHolderPlaceholder') }
                            ].map(field => (
                                <div key={field.key}>
                                    <label className="block text-sm font-bold text-gray-700 mb-2">{field.label}</label>
                                    <input type="text" value={settings[field.key]} onChange={e => setSettings(s => ({ ...s, [field.key]: e.target.value }))}
                                        placeholder={field.placeholder} className="w-full border border-gray-200 rounded-xl px-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-200 focus:border-indigo-400" />
                                </div>
                            ))}
                        </div>
                    </div>

                    {/* Notice */}
                    <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-6">
                        <h3 className="text-lg font-bold text-gray-900 mb-5">{t('paymentsPage.paymentNotice')}</h3>
                        <textarea value={settings.payment_notice} onChange={e => setSettings(s => ({ ...s, payment_notice: e.target.value }))}
                            placeholder={t('paymentsPage.paymentNoticePlaceholder')} rows={4}
                            className="w-full border border-gray-200 rounded-xl px-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-200 focus:border-indigo-400 resize-none" />
                    </div>

                    <div className="flex justify-end">
                        <button onClick={handleSaveSettings} disabled={saving}
                            className="flex items-center gap-2 px-8 py-3.5 bg-indigo-600 text-white rounded-xl font-bold text-sm hover:bg-indigo-700 transition-colors disabled:opacity-50 shadow-lg shadow-indigo-200">
                            <Save size={18} /> {saving ? t('paymentsPage.saving') : t('paymentsPage.saveSettings')}
                        </button>
                    </div>
                </div>
            )}

            {/* ═══════════════════════════════════════════ */}
            {/* ═══ History Tab ═══ */}
            {/* ═══════════════════════════════════════════ */}
            {activeTab === 'history' && (
                <div className="space-y-6">
                    {/* Stats */}
                    <div className="grid grid-cols-2 md:grid-cols-5 gap-3">
                        {[
                            { label: t('paymentsPage.statsAll'), value: stats.total, color: 'text-gray-900', bg: 'bg-gray-50' },
                            { label: t('paymentsPage.statsAwaitPayment'), value: stats.pending, color: 'text-gray-600', bg: 'bg-gray-50' },
                            { label: t('paymentsPage.statsAwaitConfirm'), value: stats.submitted, color: 'text-blue-600', bg: 'bg-blue-50' },
                            { label: t('paymentsPage.statsConfirmed'), value: stats.confirmed, color: 'text-emerald-600', bg: 'bg-emerald-50' },
                            { label: t('paymentsPage.statsTotalAmount'), value: `₩${stats.totalConfirmed.toLocaleString()}`, color: 'text-indigo-600', bg: 'bg-indigo-50' }
                        ].map((s, i) => (
                            <div key={i} className={`${s.bg} rounded-2xl p-4 border border-gray-100`}>
                                <p className="text-xs font-bold text-gray-500 mb-1">{s.label}</p>
                                <p className={`text-xl font-extrabold ${s.color}`}>{s.value}</p>
                            </div>
                        ))}
                    </div>

                    {/* Filters */}
                    <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-4">
                        <div className="flex flex-wrap gap-3 items-center">
                            <div className="relative flex-1 min-w-[200px]">
                                <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
                                <input type="text" value={searchQuery} onChange={e => setSearchQuery(e.target.value)}
                                    placeholder={t('paymentsPage.searchPlaceholder')} className="w-full pl-9 pr-4 py-2.5 border border-gray-200 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-indigo-200" />
                            </div>
                            <select value={statusFilter} onChange={e => setStatusFilter(e.target.value)}
                                className="border border-gray-200 rounded-xl px-4 py-2.5 text-sm font-medium focus:outline-none focus:ring-2 focus:ring-indigo-200">
                                <option value="all">{t('paymentsPage.allStatus')}</option>
                                <option value="pending">{t('paymentsPage.statusPending')}</option>
                                <option value="submitted">{t('paymentsPage.statusSubmitted')}</option>
                                <option value="confirmed">{t('paymentsPage.statusConfirmed')}</option>
                                <option value="rejected">{t('paymentsPage.statusRejected')}</option>
                            </select>
                        </div>
                    </div>

                    {/* Table */}
                    <div className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden">
                        {filteredPayments.length > 0 ? (
                            <div className="overflow-x-auto">
                                <table className="w-full text-sm">
                                    <thead>
                                        <tr className="bg-gray-50 border-b border-gray-100">
                                            {[t('paymentsPage.colNo'), t('paymentsPage.colUser'), t('paymentsPage.colService'), t('paymentsPage.colAmount'), t('paymentsPage.colDepositor'), t('paymentsPage.colStatus'), t('paymentsPage.colDate'), t('paymentsPage.colManage')].map((h, hi) => (
                                                <th key={h} className={`${hi === 3 ? 'text-right' : hi === 7 ? 'text-center' : 'text-left'} px-5 py-3.5 font-bold text-gray-500 text-xs`}>{h}</th>
                                            ))}
                                        </tr>
                                    </thead>
                                    <tbody>
                                        {filteredPayments.map((p, idx) => {
                                            const si = STATUS_MAP_KEYS[p.status] || STATUS_MAP_KEYS.pending;
                                            return (
                                                <tr key={p.id} className="border-b border-gray-50 hover:bg-gray-50/50 transition-colors">
                                                    <td className="px-5 py-4 text-gray-400 font-medium">{filteredPayments.length - idx}</td>
                                                    <td className="px-5 py-4">
                                                        <div className="font-bold text-gray-900">{p.user_name || '—'}</div>
                                                        <div className="text-xs text-gray-400">{p.user_role === 'host' ? t('paymentsPage.host') : t('paymentsPage.seller')}</div>
                                                    </td>
                                                    <td className="px-5 py-4 text-gray-700 font-medium">{p.reference_label || p.payment_type}</td>
                                                    <td className="px-5 py-4 text-right font-bold text-gray-900">₩{parseInt(p.amount || 0).toLocaleString()}</td>
                                                    <td className="px-5 py-4 text-gray-700 font-medium">{p.depositor_name || '—'}</td>
                                                    <td className="px-5 py-4">
                                                        <span className={`inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-bold border ${si.bg}`}>
                                                            <div className={`w-2 h-2 rounded-full ${si.dot}`} />
                                                            {t(si.labelKey)}
                                                        </span>
                                                    </td>
                                                    <td className="px-5 py-4 text-gray-500 text-xs">{new Date(p.created_at).toLocaleDateString()}</td>
                                                    <td className="px-5 py-4 text-center">
                                                        <div className="flex items-center justify-center gap-1.5">
                                                            <button onClick={() => setDetailModal(p)} className="p-2 text-gray-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors"><Eye size={16} /></button>
                                                            {p.status === 'submitted' && (
                                                                <>
                                                                    <button onClick={() => { setConfirmModal(p); setAdminNote(''); }}
                                                                        className="px-3 py-1.5 bg-emerald-500 text-white rounded-lg text-xs font-bold hover:bg-emerald-600 transition-colors">{t('paymentsPage.confirm')}</button>
                                                                    <button onClick={() => { setConfirmModal({ ...p, _rejectMode: true }); setAdminNote(''); }}
                                                                        className="px-3 py-1.5 bg-red-50 text-red-600 border border-red-200 rounded-lg text-xs font-bold hover:bg-red-100 transition-colors">{t('paymentsPage.reject')}</button>
                                                                </>
                                                            )}
                                                        </div>
                                                    </td>
                                                </tr>
                                            );
                                        })}
                                    </tbody>
                                </table>
                            </div>
                        ) : (
                            <div className="py-16 text-center">
                                <div className="w-16 h-16 bg-gray-100 rounded-2xl flex items-center justify-center mx-auto mb-4 text-gray-300"><CreditCard size={24} /></div>
                                <p className="font-bold text-gray-400 mb-1">{t('paymentsPage.noPaymentsTitle')}</p>
                                <p className="text-sm text-gray-300">{t('paymentsPage.noPaymentsDesc')}</p>
                            </div>
                        )}
                    </div>
                </div>
            )}

            {/* ═══ Plan Add/Edit Modal ═══ */}
            {planModal && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4" onClick={() => setPlanModal(null)}>
                    <div className="absolute inset-0 bg-black/50 backdrop-blur-sm" />
                    <div className="relative bg-white rounded-2xl max-w-lg w-full p-6 shadow-2xl max-h-[90vh] overflow-y-auto" onClick={e => e.stopPropagation()}>
                        <button onClick={() => setPlanModal(null)} className="absolute top-4 right-4 text-gray-400 hover:text-gray-600"><X size={20} /></button>

                        <div className="flex items-center gap-3 mb-6">
                            <div className="w-10 h-10 bg-indigo-100 rounded-xl flex items-center justify-center text-indigo-600">
                                <Package size={20} />
                            </div>
                            <h3 className="text-lg font-bold text-gray-900">
                                {planModal === 'new' ? t('paymentsPage.newService') : t('paymentsPage.editService')}
                            </h3>
                        </div>

                        <div className="space-y-4">
                            <div>
                                <label className="block text-sm font-bold text-gray-700 mb-1.5">{t('paymentsPage.serviceName')} <span className="text-red-500">*</span></label>
                                <input type="text" value={planForm.name} onChange={e => setPlanForm(f => ({ ...f, name: e.target.value }))}
                                    placeholder={t('paymentsPage.serviceNamePlaceholder')} className="w-full border border-gray-200 rounded-xl px-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-200" />
                            </div>

                            <div>
                                <label className="block text-sm font-bold text-gray-700 mb-1.5">{t('paymentsPage.description')}</label>
                                <textarea value={planForm.description} onChange={e => setPlanForm(f => ({ ...f, description: e.target.value }))}
                                    placeholder={t('paymentsPage.descriptionPlaceholder')} rows={3}
                                    className="w-full border border-gray-200 rounded-xl px-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-200 resize-none" />
                            </div>

                            <div className="grid grid-cols-2 gap-3">
                                <div>
                                    <label className="block text-sm font-bold text-gray-700 mb-1.5">{t('paymentsPage.amountLabel')} <span className="text-red-500">*</span></label>
                                    <NumberInput value={planForm.amount} onChange={val => setPlanForm(f => ({ ...f, amount: parseInt(val) || 0 }))} className="w-full border border-gray-200 rounded-xl px-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-200" />
                                </div>
                                <div>
                                    <label className="block text-sm font-bold text-gray-700 mb-1.5">{t('paymentsPage.paymentCycle')}</label>
                                    <select value={planForm.period} onChange={e => setPlanForm(f => ({ ...f, period: e.target.value }))}
                                        className="w-full border border-gray-200 rounded-xl px-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-200">
                                        <option value="monthly">{t('paymentsPage.monthlyLabel')}</option>
                                        <option value="yearly">{t('paymentsPage.yearlyLabel')}</option>
                                        <option value="once">{t('paymentsPage.onceLabel')}</option>
                                    </select>
                                </div>
                            </div>

                            <div>
                                <label className="block text-sm font-bold text-gray-700 mb-1.5">{t('paymentsPage.target')}</label>
                                <select value={planForm.target_role} onChange={e => setPlanForm(f => ({ ...f, target_role: e.target.value }))}
                                    className="w-full border border-gray-200 rounded-xl px-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-200">
                                    <option value="all">{t('paymentsPage.targetAll')}</option>
                                    <option value="host">{t('paymentsPage.targetVendor')}</option>
                                    <option value="seller">{t('paymentsPage.targetSeller')}</option>
                                </select>
                            </div>

                            <div className="grid grid-cols-2 gap-3">
                                <div>
                                    <label className="block text-sm font-bold text-gray-700 mb-1.5">{t('paymentsPage.category')}</label>
                                    <select value={planForm.category} onChange={e => { setPlanForm(f => ({ ...f, category: e.target.value })); if (e.target.value !== '__custom__') setCustomCategory(''); }}
                                        className="w-full border border-gray-200 rounded-xl px-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-200">
                                        <option value="">{t('paymentsPage.noSelection')}</option>
                                        {CATEGORY_KEY_OPTIONS.map(c => <option key={c} value={t(`paymentsPage.${c}`)}>{t(`paymentsPage.${c}`)}</option>)}
                                        <option value="__custom__">{t('paymentsPage.customInput')}</option>
                                    </select>
                                    {planForm.category === '__custom__' && (
                                        <input type="text" value={customCategory} onChange={e => setCustomCategory(e.target.value)}
                                            placeholder={t('paymentsPage.categoryPlaceholder')} className="w-full border border-gray-200 rounded-xl px-4 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-200 mt-2" />
                                    )}
                                </div>
                                <div>
                                    <label className="block text-sm font-bold text-gray-700 mb-1.5">{t('paymentsPage.serviceType')}</label>
                                    <select value={planForm.plan_type} onChange={e => setPlanForm(f => ({ ...f, plan_type: e.target.value }))}
                                        className="w-full border border-gray-200 rounded-xl px-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-200">
                                        <option value="single">{t('paymentsPage.singleService')}</option>
                                        <option value="package">{t('paymentsPage.packageService')}</option>
                                    </select>
                                </div>
                            </div>

                            {/* Features */}
                            <div>
                                <label className="block text-sm font-bold text-gray-700 mb-1.5">{t('paymentsPage.includedFeatures')}</label>
                                <div className="flex gap-2 mb-2">
                                    <input type="text" value={featureInput}
                                        onChange={e => setFeatureInput(e.target.value)}
                                        onKeyDown={e => { if (e.key === 'Enter') { e.preventDefault(); addFeature(); } }}
                                        placeholder={t('paymentsPage.featurePlaceholder')}
                                        className="flex-1 border border-gray-200 rounded-xl px-4 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-200" />
                                    <button onClick={addFeature} className="px-4 py-2.5 bg-gray-100 text-gray-700 rounded-xl text-sm font-bold hover:bg-gray-200 transition-colors">{t('paymentsPage.add')}</button>
                                </div>
                                {planForm.features.length > 0 && (
                                    <div className="space-y-1.5 bg-gray-50 rounded-xl p-3">
                                        {planForm.features.map((f, i) => (
                                            <div key={i} className="flex items-center justify-between bg-white rounded-lg px-3 py-2 border border-gray-100">
                                                <span className="text-sm text-gray-700 flex items-center gap-2">
                                                    <CheckCircle size={14} className="text-emerald-500" /> {f}
                                                </span>
                                                <button onClick={() => removeFeature(i)} className="text-gray-400 hover:text-red-500"><X size={14} /></button>
                                            </div>
                                        ))}
                                    </div>
                                )}
                            </div>

                            {/* ═══ Translations Section ═══ */}
                            <div className="border-t border-gray-200 pt-4">
                                <div className="flex items-center justify-between mb-3">
                                    <label className="text-sm font-bold text-gray-700 flex items-center gap-2">
                                        <Languages size={16} className="text-indigo-500" />
                                        {t('paymentsPage.translations', '다국어 번역')}
                                    </label>
                                    <button type="button" onClick={autoTranslateAll} disabled={translating}
                                        className="flex items-center gap-1.5 px-3 py-1.5 bg-indigo-100 text-indigo-700 rounded-lg text-xs font-bold hover:bg-indigo-200 transition-colors disabled:opacity-50">
                                        <RefreshCw size={12} className={translating ? 'animate-spin' : ''} />
                                        {translating ? t('paymentsPage.translating', '번역 중...') : t('paymentsPage.autoTranslate', '자동 번역')}
                                    </button>
                                </div>

                                {/* Language tabs */}
                                <div className="flex flex-wrap gap-1.5 mb-3">
                                    {LANG_OPTIONS.map(lang => {
                                        const hasTrans = planForm.translations?.[lang.code]?.name;
                                        return (
                                            <button key={lang.code} type="button" onClick={() => setTransLang(lang.code)}
                                                className={`flex items-center gap-1 px-2.5 py-1.5 rounded-lg text-xs font-bold border transition-all ${transLang === lang.code
                                                    ? 'bg-indigo-500 text-white border-indigo-500'
                                                    : hasTrans
                                                        ? 'bg-emerald-50 text-emerald-700 border-emerald-200 hover:border-emerald-400'
                                                        : 'bg-white text-gray-600 border-gray-200 hover:border-indigo-300'
                                                    }`}>
                                                {lang.flag} {lang.label}
                                                {hasTrans && transLang !== lang.code && <CheckCircle size={10} className="text-emerald-500" />}
                                            </button>
                                        );
                                    })}
                                </div>

                                {/* Translation inputs for selected language */}
                                <div className="bg-gray-50 rounded-xl p-3 space-y-3">
                                    <p className="text-[10px] text-gray-400 font-medium">
                                        {LANG_OPTIONS.find(l => l.code === transLang)?.flag} {LANG_OPTIONS.find(l => l.code === transLang)?.label} {t('paymentsPage.translationLabel', '번역')}
                                    </p>
                                    <div>
                                        <label className="block text-xs font-bold text-gray-500 mb-1">{t('paymentsPage.serviceName')}</label>
                                        <input type="text"
                                            value={planForm.translations?.[transLang]?.name || ''}
                                            onChange={e => updateTranslation(transLang, 'name', e.target.value)}
                                            placeholder={planForm.name || t('paymentsPage.serviceNamePlaceholder')}
                                            className="w-full border border-gray-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-200" />
                                    </div>
                                    <div>
                                        <label className="block text-xs font-bold text-gray-500 mb-1">{t('paymentsPage.description')}</label>
                                        <textarea
                                            value={planForm.translations?.[transLang]?.description || ''}
                                            onChange={e => updateTranslation(transLang, 'description', e.target.value)}
                                            placeholder={planForm.description || t('paymentsPage.descriptionPlaceholder')}
                                            rows={2}
                                            className="w-full border border-gray-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-200 resize-none" />
                                    </div>
                                    {planForm.features.length > 0 && (
                                        <div>
                                            <label className="block text-xs font-bold text-gray-500 mb-1">{t('paymentsPage.includedFeatures')}</label>
                                            <div className="space-y-1.5">
                                                {planForm.features.map((origFeature, idx) => (
                                                    <div key={idx} className="flex items-center gap-2">
                                                        <span className="text-[10px] text-gray-400 w-4 flex-shrink-0">{idx + 1}.</span>
                                                        <input type="text"
                                                            value={planForm.translations?.[transLang]?.features?.[idx] || ''}
                                                            onChange={e => updateTransFeature(transLang, idx, e.target.value)}
                                                            placeholder={origFeature}
                                                            className="flex-1 border border-gray-200 rounded-lg px-2.5 py-1.5 text-xs focus:outline-none focus:ring-2 focus:ring-indigo-200" />
                                                    </div>
                                                ))}
                                            </div>
                                        </div>
                                    )}
                                </div>
                            </div>

                            <div>
                                <label className="block text-sm font-bold text-gray-700 mb-1.5">{t('paymentsPage.sortOrder')}</label>
                                <NumberInput value={planForm.sort_order} onChange={val => setPlanForm(f => ({ ...f, sort_order: parseInt(val) || 0 }))} className="w-full border border-gray-200 rounded-xl px-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-200" />
                            </div>
                        </div>

                        <div className="flex gap-3 mt-6">
                            <button onClick={() => setPlanModal(null)} className="flex-1 py-3 border border-gray-200 rounded-xl text-sm font-bold text-gray-600 hover:bg-gray-50 transition-colors">{t('paymentsPage.cancel')}</button>
                            <button onClick={handleSavePlan} disabled={planSaving}
                                className="flex-1 py-3 bg-indigo-600 text-white rounded-xl text-sm font-bold hover:bg-indigo-700 transition-colors disabled:opacity-50">
                                {planSaving ? t('paymentsPage.savingPlan') : (planModal === 'new' ? t('paymentsPage.addPlan') : t('paymentsPage.editPlan'))}
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* ═══ Delete Confirm Modal ═══ */}
            {deleteConfirm && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4" onClick={() => setDeleteConfirm(null)}>
                    <div className="absolute inset-0 bg-black/50 backdrop-blur-sm" />
                    <div className="relative bg-white rounded-2xl max-w-sm w-full p-6 shadow-2xl" onClick={e => e.stopPropagation()}>
                        <div className="text-center mb-5">
                            <div className="w-12 h-12 bg-red-100 rounded-xl flex items-center justify-center mx-auto mb-3 text-red-600"><Trash2 size={24} /></div>
                            <h3 className="text-lg font-bold text-gray-900">{t('paymentsPage.deleteService')}</h3>
                            <p className="text-sm text-gray-500 mt-1">{t('paymentsPage.deleteConfirm', { name: deleteConfirm.name })}</p>
                        </div>
                        <div className="flex gap-3">
                            <button onClick={() => setDeleteConfirm(null)} className="flex-1 py-3 border border-gray-200 rounded-xl text-sm font-bold text-gray-600 hover:bg-gray-50">{t('paymentsPage.cancel')}</button>
                            <button onClick={() => handleDeletePlan(deleteConfirm.id)} className="flex-1 py-3 bg-red-500 text-white rounded-xl text-sm font-bold hover:bg-red-600">{t('paymentsPage.delete')}</button>
                        </div>
                    </div>
                </div>
            )}

            {/* ═══ Detail Modal ═══ */}
            {detailModal && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4" onClick={() => setDetailModal(null)}>
                    <div className="absolute inset-0 bg-black/50 backdrop-blur-sm" />
                    <div className="relative bg-white rounded-2xl max-w-lg w-full p-6 shadow-2xl" onClick={e => e.stopPropagation()}>
                        <button onClick={() => setDetailModal(null)} className="absolute top-4 right-4 text-gray-400 hover:text-gray-600"><X size={20} /></button>
                        <h3 className="text-lg font-bold text-gray-900 mb-5 flex items-center gap-2"><CreditCard size={20} className="text-indigo-500" /> {t('paymentsPage.paymentDetail')}</h3>
                        <div className="space-y-3 text-sm">
                            {[
                                [t('paymentsPage.detailUser'), `${detailModal.user_name} (${detailModal.user_role === 'host' ? t('paymentsPage.host') : t('paymentsPage.seller')})`],
                                [t('paymentsPage.detailService'), detailModal.reference_label || detailModal.payment_type],
                                [t('paymentsPage.detailAmount'), `₩${parseInt(detailModal.amount || 0).toLocaleString()}`],
                                [t('paymentsPage.detailDepositor'), detailModal.depositor_name || '—'],
                                [t('paymentsPage.detailStatus'), t((STATUS_MAP_KEYS[detailModal.status] || {}).labelKey || 'paymentsPage.statusPending')],
                                [t('paymentsPage.detailAdminNote'), detailModal.admin_note || '—'],
                                [t('paymentsPage.detailCreatedAt'), new Date(detailModal.created_at).toLocaleString()],
                                [t('paymentsPage.detailSubmittedAt'), detailModal.submitted_at ? new Date(detailModal.submitted_at).toLocaleString() : '—'],
                                [t('paymentsPage.detailConfirmedAt'), detailModal.confirmed_at ? new Date(detailModal.confirmed_at).toLocaleString() : '—'],
                            ].map(([l, v], i) => (
                                <div key={i} className="flex justify-between py-2 border-b border-gray-50">
                                    <span className="text-gray-500 font-medium">{l}</span>
                                    <span className="text-gray-900 font-bold text-right max-w-[60%]">{v}</span>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            )}

            {/* ═══ Confirm/Reject Modal ═══ */}
            {confirmModal && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4" onClick={() => setConfirmModal(null)}>
                    <div className="absolute inset-0 bg-black/50 backdrop-blur-sm" />
                    <div className="relative bg-white rounded-2xl max-w-md w-full p-6 shadow-2xl" onClick={e => e.stopPropagation()}>
                        <button onClick={() => setConfirmModal(null)} className="absolute top-4 right-4 text-gray-400 hover:text-gray-600"><X size={20} /></button>
                        <div className="flex items-center gap-3 mb-5">
                            <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${confirmModal._rejectMode ? 'bg-red-100 text-red-600' : 'bg-emerald-100 text-emerald-600'}`}>
                                {confirmModal._rejectMode ? <XCircle size={20} /> : <CheckCircle size={20} />}
                            </div>
                            <div>
                                <h3 className="text-lg font-bold text-gray-900">{confirmModal._rejectMode ? t('paymentsPage.rejectDeposit') : t('paymentsPage.confirmDeposit')}</h3>
                                <p className="text-sm text-gray-500">{confirmModal.user_name} — ₩{parseInt(confirmModal.amount || 0).toLocaleString()}</p>
                            </div>
                        </div>
                        <div className="bg-gray-50 rounded-xl p-4 mb-4 text-sm space-y-1">
                            <div className="flex justify-between"><span className="text-gray-500">{t('paymentsPage.depositorNameLabel')}</span><span className="font-bold">{confirmModal.depositor_name || '—'}</span></div>
                            <div className="flex justify-between"><span className="text-gray-500">{t('paymentsPage.submittedAtLabel')}</span><span className="font-medium">{confirmModal.submitted_at ? new Date(confirmModal.submitted_at).toLocaleString() : '—'}</span></div>
                        </div>
                        <label className="block text-sm font-bold text-gray-700 mb-2">{t('paymentsPage.adminNoteLabel')}</label>
                        <textarea value={adminNote} onChange={e => setAdminNote(e.target.value)} placeholder={t('paymentsPage.adminNotePlaceholder')} rows={3}
                            className="w-full border border-gray-200 rounded-xl p-3 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-200 resize-none" />
                        <div className="flex gap-3 mt-5">
                            <button onClick={() => setConfirmModal(null)} className="flex-1 py-3 border border-gray-200 rounded-xl text-sm font-bold text-gray-600 hover:bg-gray-50 transition-colors">{t('paymentsPage.close')}</button>
                            <button onClick={() => handleConfirmAction(confirmModal._rejectMode ? 'reject' : 'confirm')} disabled={processing}
                                className={`flex-1 py-3 rounded-xl text-sm font-bold text-white transition-colors disabled:opacity-50 ${confirmModal._rejectMode ? 'bg-red-500 hover:bg-red-600' : 'bg-emerald-500 hover:bg-emerald-600'}`}>
                                {processing ? t('paymentsPage.processing') : (confirmModal._rejectMode ? t('paymentsPage.rejectProcess') : t('paymentsPage.confirmProcess'))}
                            </button>
                        </div>
                    </div>
                </div>
            )}

            <style>{`
                @keyframes popupScale {
                    from { transform: scale(0.9) translateY(10px); opacity: 0; }
                    to { transform: scale(1) translateY(0); opacity: 1; }
                }
            `}</style>
        </div>
    );
};

export default AdminPayments;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { useTranslation } from 'react-i18next';
import {
    Flame, TrendingUp, Search, Plus, X, Calendar, Store,
    MapPin, Trash2, Edit3, ArrowUpDown, Clock, CheckCircle,
    AlertCircle, Eye, ChevronDown, Sparkles, AlertTriangle, XCircle
} from 'lucide-react';
import ConfirmModal from '../../components/ConfirmModal';
import Toast from '../../components/Toast';

const API_BASE = '/api';

const TIER_CONFIG_KEYS = {
    hot_top: { labelKey: 'promotionsPage.tierHotTop', color: 'bg-gradient-to-r from-orange-500 to-red-500', textColor: 'text-orange-600', bgLight: 'bg-orange-50 border-orange-200' },
    hot_mid: { labelKey: 'promotionsPage.tierHotMid', color: 'bg-gradient-to-r from-violet-500 to-purple-600', textColor: 'text-violet-600', bgLight: 'bg-violet-50 border-violet-200' },
    category_featured: { labelKey: 'promotionsPage.tierCategoryFeatured', color: 'bg-gradient-to-r from-teal-500 to-cyan-600', textColor: 'text-teal-600', bgLight: 'bg-teal-50 border-teal-200' },
};

const TYPE_LABEL_KEYS = {
    popup: 'promotionsPage.typePopup', gallery: 'promotionsPage.typeGallery', cafe: 'promotionsPage.typeCafe',
    showroom: 'promotionsPage.typeShowroom', fleamarket: 'promotionsPage.typeFleamarket', store: 'promotionsPage.typeStore'
};

const AdminPromotions = () => {
    const { t } = useTranslation('admin');
    const [promotions, setPromotions] = useState([]);
    const [allVenues, setAllVenues] = useState([]);
    const [loading, setLoading] = useState(true);
    const [showModal, setShowModal] = useState(false);
    const [editTarget, setEditTarget] = useState(null);
    const [searchVenue, setSearchVenue] = useState('');
    const [filterTier, setFilterTier] = useState('');
    const [confirmModal, setConfirmModal] = useState(null);
    const [toast, setToast] = useState(null);

    const showToast = useCallback((message, type = 'success') => {
        setToast({ message, type });
    }, []);

    // Form state
    const [form, setForm] = useState({
        venue_id: '',
        tier: 'hot_top',
        featured_category: '',
        start_date: new Date().toISOString().slice(0, 10),
        end_date: '',
        admin_note: '',
        display_order: 0,
    });

    useEffect(() => { fetchData(); }, []);

    const fetchData = async () => {
        try {
            const res = await fetch(`${API_BASE}/promotions/get_admin_promotions.php`, { credentials: 'include' });
            const json = await res.json();
            if (json.success) {
                setPromotions(json.promotions || []);
                setAllVenues(json.venues || []);
            }
        } catch (err) {
            console.error(t('promotionsPage.loadFailed'), err);
        } finally {
            setLoading(false);
        }
    };

    const handleOpenAdd = () => {
        setEditTarget(null);
        setForm({
            venue_id: '',
            tier: 'hot_top',
            featured_category: '',
            start_date: new Date().toISOString().slice(0, 10),
            end_date: '',
            admin_note: '',
            display_order: 0,
        });
        setSearchVenue('');
        setShowModal(true);
    };

    const handleOpenEdit = (promo) => {
        setEditTarget(promo);
        setForm({
            venue_id: promo.venue_id,
            tier: promo.tier,
            featured_category: promo.featured_category || '',
            start_date: promo.start_date,
            end_date: promo.end_date,
            admin_note: promo.admin_note || '',
            display_order: promo.display_order || 0,
        });
        setShowModal(true);
    };

    const handleQuickDate = (days) => {
        const start = new Date(form.start_date || new Date());
        const end = new Date(start);
        end.setDate(end.getDate() + days);
        setForm(prev => ({ ...prev, end_date: end.toISOString().slice(0, 10) }));
    };

    const handleSubmit = async () => {
        if (!form.venue_id || !form.start_date || !form.end_date) {
            showToast(t('promotionsPage.requiredFields'), 'error');
            return;
        }
        try {
            const res = await fetch(`${API_BASE}/promotions/set_promotion.php`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                credentials: 'include',
                body: JSON.stringify(form),
            });
            const json = await res.json();
            if (json.success) {
                setShowModal(false);
                fetchData();
                showToast(t('promotionsPage.promotionRegistered'), 'success');
            } else {
                showToast(json.message || t('promotionsPage.errorOccurred'), 'error');
            }
        } catch (err) {
            showToast(t('promotionsPage.serverError'), 'error');
        }
    };

    const handleRemove = async (promotionId) => {
        setConfirmModal({
            title: t('promotionsPage.deletePromotion'),
            message: t('promotionsPage.deleteConfirm'),
            type: 'danger',
            confirmLabel: t('promotionsPage.deleteLabel'),
            onConfirm: async () => {
                setConfirmModal(null);
                try {
                    const res = await fetch(`${API_BASE}/promotions/remove_promotion.php`, {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        credentials: 'include',
                        body: JSON.stringify({ promotion_id: promotionId }),
                    });
                    const json = await res.json();
                    if (json.success) {
                        fetchData();
                        showToast(t('promotionsPage.promotionDeleted'), 'success');
                    }
                } catch (err) {
                    showToast(t('promotionsPage.serverError'), 'error');
                }
            }
        });
    };

    // Filter venues not already promoted (for the venue selector)
    const promotedVenueIds = useMemo(() => new Set(promotions.map(p => parseInt(p.venue_id))), [promotions]);

    const availableVenues = useMemo(() => {
        return allVenues.filter(v => {
            // When editing, include the currently edited venue
            if (editTarget && parseInt(v.id) === parseInt(editTarget.venue_id)) return true;
            if (promotedVenueIds.has(parseInt(v.id))) return false;
            if (searchVenue) {
                const term = searchVenue.toLowerCase();
                return v.name?.toLowerCase().includes(term) || v.location?.toLowerCase().includes(term);
            }
            return true;
        });
    }, [allVenues, promotedVenueIds, searchVenue, editTarget]);

    const filteredPromotions = useMemo(() => {
        if (!filterTier) return promotions;
        return promotions.filter(p => p.tier === filterTier);
    }, [promotions, filterTier]);

    const activeCount = promotions.filter(p => p.promo_status === 'active').length;
    const expiredCount = promotions.filter(p => p.promo_status === 'expired').length;

    if (loading) {
        return (
            <div className="flex items-center justify-center h-64">
                <div className="w-8 h-8 border-4 border-indigo-200 border-t-indigo-600 rounded-full animate-spin" />
            </div>
        );
    }

    return (
        <div className="p-4 md:p-6 max-w-6xl">
            {/* Header */}
            <div className="flex flex-col md:flex-row md:items-center gap-4 mb-6">
                <div className="flex-1">
                    <h1 className="text-2xl font-black text-gray-900 flex items-center gap-2">
                        <Flame size={24} className="text-orange-500" />
                        {t('promotionsPage.title')}</h1>
                    <p className="text-sm text-gray-500 mt-1">{t('promotionsPage.subtitle')}</p>
                </div>
                <button
                    onClick={handleOpenAdd}
                    className="flex items-center gap-2 px-5 py-2.5 bg-indigo-600 text-white rounded-xl font-bold text-sm hover:bg-indigo-700 transition-colors shadow-lg shadow-indigo-200"
                >
                    <Plus size={18} />
                    {t('promotionsPage.addPromotion')}
                </button>
            </div>

            {/* Stats */}
            <div className="grid grid-cols-3 gap-3 mb-6">
                <div className="bg-white rounded-xl p-4 border border-gray-100 text-center">
                    <p className="text-2xl font-black text-gray-900">{promotions.length}</p>
                    <p className="text-xs text-gray-500 font-medium">{t('promotionsPage.totalPromotions')}</p>
                </div>
                <div className="bg-emerald-50 rounded-xl p-4 border border-emerald-100 text-center">
                    <p className="text-2xl font-black text-emerald-600">{activeCount}</p>
                    <p className="text-xs text-emerald-600 font-medium">{t('promotionsPage.active')}</p>
                </div>
                <div className="bg-gray-50 rounded-xl p-4 border border-gray-100 text-center">
                    <p className="text-2xl font-black text-gray-400">{expiredCount}</p>
                    <p className="text-xs text-gray-400 font-medium">{t('promotionsPage.expired')}</p>
                </div>
            </div>

            {/* Filter Tabs */}
            <div className="flex items-center gap-2 mb-4 overflow-x-auto pb-1">
                {[
                    { value: '', label: t('promotionsPage.filterAll') },
                    { value: 'hot_top', label: t('promotionsPage.filterHot') },
                    { value: 'hot_mid', label: t('promotionsPage.filterCurated') },
                    { value: 'category_featured', label: t('promotionsPage.filterCategoryFeatured') },
                ].map(tab => (
                    <button
                        key={tab.value}
                        onClick={() => setFilterTier(tab.value)}
                        className={`px-4 py-2 rounded-xl text-sm font-bold whitespace-nowrap transition-colors ${filterTier === tab.value
                            ? 'bg-indigo-600 text-white shadow'
                            : 'bg-white text-gray-600 border border-gray-200 hover:bg-gray-50'
                            }`}
                    >
                        {tab.label}
                    </button>
                ))}
            </div>

            {/* Promotions List */}
            <div className="space-y-3">
                {filteredPromotions.length === 0 ? (
                    <div className="bg-white rounded-2xl p-12 text-center border border-gray-100">
                        <Store size={40} className="mx-auto text-gray-300 mb-3" />
                        <p className="text-gray-400 font-medium">{t('promotionsPage.noPromotions')}</p>
                        <button onClick={handleOpenAdd} className="text-indigo-600 font-bold text-sm mt-2 hover:underline">
                            {t('promotionsPage.addNewPromotion')}
                        </button>
                    </div>
                ) : (
                    filteredPromotions.map(promo => {
                        const isExpired = promo.promo_status === 'expired';
                        const tierConf = TIER_CONFIG_KEYS[promo.tier];
                        const daysLeft = Math.ceil((new Date(promo.end_date) - new Date()) / (1000 * 60 * 60 * 24));
                        return (
                            <div key={promo.id}
                                className={`bg-white rounded-2xl p-4 md:p-5 border transition-all ${isExpired ? 'border-gray-100 opacity-60' : 'border-gray-100 hover:shadow-md'
                                    }`}
                            >
                                <div className="flex flex-col md:flex-row md:items-center gap-3">
                                    {/* Venue Info */}
                                    <div className="flex items-center gap-3 flex-1 min-w-0">
                                        <div className="w-14 h-14 md:w-12 md:h-12 rounded-xl bg-gray-100 overflow-hidden flex-shrink-0">
                                            {promo.venue_images?.[0] ? (() => {
                                                const img = promo.venue_images[0];
                                                const src = img.startsWith('/') ? img : `/${img}`;
                                                return <img src={src} alt="" className="w-full h-full object-cover" />;
                                            })() : (
                                                <div className="w-full h-full flex items-center justify-center"><Store size={20} className="text-gray-400" /></div>
                                            )}
                                        </div>
                                        <div className="min-w-0">
                                            <div className="flex items-center gap-2 flex-wrap">
                                                <h3 className="font-bold text-gray-900 truncate">{promo.venue_name}</h3>
                                                <span className={`px-2 py-0.5 ${tierConf.color} text-white rounded-md text-xs font-bold`}>
                                                    {t(tierConf.labelKey)}
                                                </span>
                                                {promo.tier === 'category_featured' && promo.featured_category && (
                                                    <span className="px-2 py-0.5 bg-teal-100 text-teal-700 rounded-md text-xs font-bold">
                                                        {t(TYPE_LABEL_KEYS[promo.featured_category]) || promo.featured_category}
                                                    </span>
                                                )}
                                                {isExpired && (
                                                    <span className="px-2 py-0.5 bg-gray-200 text-gray-500 rounded-md text-xs font-bold">{t('promotionsPage.expired')}</span>
                                                )}
                                            </div>
                                            <p className="text-xs text-gray-400 truncate mt-0.5">
                                                {promo.venue_location} · {t(TYPE_LABEL_KEYS[promo.venue_type]) || promo.venue_type}
                                            </p>
                                            {promo.admin_note && (
                                                <p className="text-xs text-orange-600 font-medium mt-1 truncate flex items-center gap-1">
                                                    <Sparkles size={10} />{promo.admin_note}
                                                </p>
                                            )}
                                        </div>
                                    </div>

                                    {/* Date & Actions */}
                                    <div className="flex items-center gap-2 md:gap-4 flex-shrink-0">
                                        <div className="text-right">
                                            <p className="text-xs text-gray-500 flex items-center gap-1">
                                                <Calendar size={11} />
                                                {promo.start_date} ~ {promo.end_date}
                                            </p>
                                            {!isExpired && (
                                                <p className={`text-xs font-bold mt-0.5 ${daysLeft <= 3 ? 'text-red-500' : daysLeft <= 7 ? 'text-orange-500' : 'text-emerald-600'}`}>
                                                    {daysLeft <= 0 ? t('promotionsPage.expiresToday') : t('promotionsPage.daysLeft', { days: daysLeft })}
                                                </p>
                                            )}
                                        </div>
                                        <div className="flex items-center gap-1">
                                            <button
                                                onClick={() => handleOpenEdit(promo)}
                                                className="p-2 text-gray-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors"
                                                title={t('promotionsPage.editTitle')}
                                            >
                                                <Edit3 size={16} />
                                            </button>
                                            <button
                                                onClick={() => handleRemove(promo.id)}
                                                className="p-2 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                                                title={t('promotionsPage.deleteTitle')}
                                            >
                                                <Trash2 size={16} />
                                            </button>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        );
                    })
                )}
            </div>

            {/* ??' Add/Edit Modal '????? */}
            {showModal && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
                    <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => setShowModal(false)} />
                    <div className="relative bg-white rounded-3xl max-w-md w-full shadow-2xl max-h-[90vh] overflow-y-auto">
                        <div className="p-6">
                            <div className="flex items-center justify-between mb-6">
                                <h2 className="text-xl font-black text-gray-900">
                                    {editTarget ? t('promotionsPage.editPromotion') : t('promotionsPage.addPromotionTitle')}
                                </h2>
                                <button onClick={() => setShowModal(false)} className="w-8 h-8 flex items-center justify-center rounded-lg hover:bg-gray-100 transition-colors">
                                    <X size={18} />
                                </button>
                            </div>

                            {/* Venue Select */}
                            <div className="mb-5">
                                <label className="text-sm font-bold text-gray-700 mb-2 block">{t('promotionsPage.selectVenue')}</label>
                                {!editTarget && (
                                    <div className="relative mb-2">
                                        <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
                                        <input
                                            type="text"
                                            placeholder={t('promotionsPage.searchVenue')}
                                            value={searchVenue}
                                            onChange={e => setSearchVenue(e.target.value)}
                                            className="w-full pl-9 pr-4 py-2 bg-gray-50 border border-gray-200 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-indigo-200"
                                        />
                                    </div>
                                )}
                                <div className="max-h-40 overflow-y-auto border border-gray-200 rounded-xl">
                                    {availableVenues.length === 0 ? (
                                        <p className="text-center py-4 text-sm text-gray-400">{t('promotionsPage.noAvailableVenues')}</p>
                                    ) : (
                                        availableVenues.map(v => (
                                            <button
                                                key={v.id}
                                                onClick={() => setForm(prev => ({ ...prev, venue_id: v.id }))}
                                                className={`w-full text-left px-4 py-2.5 text-sm hover:bg-indigo-50 transition-colors flex items-center gap-2 border-b border-gray-50 last:border-0 ${parseInt(form.venue_id) === parseInt(v.id) ? 'bg-indigo-50 text-indigo-700 font-bold' : 'text-gray-700'
                                                    }`}
                                            >
                                                <Store size={14} className="text-gray-400 flex-shrink-0" />
                                                <span className="truncate">{v.name}</span>
                                                <span className="text-xs text-gray-400 ml-auto flex-shrink-0">{v.location?.split(' ').slice(0, 2).join(' ')}</span>
                                            </button>
                                        ))
                                    )}
                                </div>
                            </div>

                            {/* Tier Select */}
                            <div className="mb-5">
                                <label className="text-sm font-bold text-gray-700 mb-2 block">{t('promotionsPage.exposureTier')}</label>
                                <div className="grid grid-cols-3 gap-2">
                                    {Object.entries(TIER_CONFIG_KEYS).map(([key, conf]) => (
                                        <button
                                            key={key}
                                            onClick={() => setForm(prev => ({ ...prev, tier: key, featured_category: key === 'category_featured' ? prev.featured_category : '' }))}
                                            className={`p-3 rounded-xl border-2 text-xs font-bold text-center transition-all ${form.tier === key
                                                ? `${conf.bgLight} ${conf.textColor}`
                                                : 'border-gray-200 text-gray-500 hover:border-gray-300'
                                                }`}
                                        >
                                            {t(conf.labelKey)}
                                        </button>
                                    ))}
                                </div>
                                {form.tier === 'category_featured' && (
                                    <div className="mt-3">
                                        <label className="text-xs font-bold text-teal-700 mb-1.5 block">{t('promotionsPage.selectCategory')}</label>
                                        <div className="grid grid-cols-3 gap-2">
                                            {Object.entries(TYPE_LABEL_KEYS).map(([key, labelKey]) => (
                                                <button
                                                    key={key}
                                                    onClick={() => setForm(prev => ({ ...prev, featured_category: key }))}
                                                    className={`px-3 py-2 rounded-lg border text-xs font-bold text-center transition-all ${form.featured_category === key
                                                        ? 'bg-teal-50 border-teal-300 text-teal-700'
                                                        : 'border-gray-200 text-gray-500 hover:border-gray-300'
                                                        }`}
                                                >
                                                    {t(labelKey)}
                                                </button>
                                            ))}
                                        </div>
                                    </div>
                                )}
                            </div>

                            {/* Date Range */}
                            <div className="mb-5">
                                <label className="text-sm font-bold text-gray-700 mb-2 block">{t('promotionsPage.exposurePeriod')}</label>
                                <div className="grid grid-cols-2 gap-3 mb-2">
                                    <div>
                                        <label className="text-xs text-gray-400 mb-1 block">{t('promotionsPage.startDate')}</label>
                                        <input
                                            type="date"
                                            value={form.start_date}
                                            onChange={e => setForm(prev => ({ ...prev, start_date: e.target.value }))}
                                            className="w-full px-3 py-2 border border-gray-200 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-indigo-200"
                                        />
                                    </div>
                                    <div>
                                        <label className="text-xs text-gray-400 mb-1 block">{t('promotionsPage.endDate')}</label>
                                        <input
                                            type="date"
                                            value={form.end_date}
                                            onChange={e => setForm(prev => ({ ...prev, end_date: e.target.value }))}
                                            className="w-full px-3 py-2 border border-gray-200 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-indigo-200"
                                        />
                                    </div>
                                </div>
                                <div className="flex gap-2">
                                    {[
                                        { days: 7, label: '7' },
                                        { days: 14, label: '14' },
                                        { days: 30, label: '30' },
                                        { days: 60, label: '60' },
                                    ].map(opt => (
                                        <button
                                            key={opt.days}
                                            onClick={() => handleQuickDate(opt.days)}
                                            className="flex-1 py-1.5 text-xs font-bold text-indigo-600 bg-indigo-50 rounded-lg hover:bg-indigo-100 transition-colors"
                                        >
                                            {opt.label}
                                        </button>
                                    ))}
                                </div>
                            </div>

                            {/* Admin Note */}
                            <div className="mb-5">
                                <label className="text-sm font-bold text-gray-700 mb-2 block">{t('promotionsPage.adminNote')}</label>
                                <input
                                    type="text"
                                    value={form.admin_note}
                                    onChange={e => setForm(prev => ({ ...prev, admin_note: e.target.value }))}
                                    placeholder={t('promotionsPage.adminNotePlaceholder')}
                                    className="w-full px-4 py-2.5 border border-gray-200 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-indigo-200"
                                    maxLength={100}
                                />
                                <p className="text-xs text-gray-400 mt-1">{t('promotionsPage.adminNotePublic')}</p>
                            </div>

                            {/* Display Order */}
                            <div className="mb-6">
                                <label className="text-sm font-bold text-gray-700 mb-2 block">{t('promotionsPage.sortOrder')}</label>
                                <input
                                    type="number"
                                    value={form.display_order}
                                    onChange={e => setForm(prev => ({ ...prev, display_order: parseInt(e.target.value) || 0 }))}
                                    className="w-full px-4 py-2.5 border border-gray-200 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-indigo-200"
                                    min={0}
                                />
                                <p className="text-xs text-gray-400 mt-1">{t('promotionsPage.sortOrderDesc')}</p>
                            </div>

                            {/* Actions */}
                            <div className="flex gap-3">
                                <button
                                    onClick={handleSubmit}
                                    className="flex-1 py-3 bg-indigo-600 text-white rounded-xl font-bold text-sm hover:bg-indigo-700 transition-colors"
                                >
                                    {editTarget ? t('promotionsPage.editComplete') : t('promotionsPage.registerPromotion')}
                                </button>
                                <button
                                    onClick={() => setShowModal(false)}
                                    className="px-5 py-3 border border-gray-200 text-gray-600 rounded-xl font-bold text-sm hover:bg-gray-50 transition-colors"
                                >
                                    {t('promotionsPage.cancel')}
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            )}

            <ConfirmModal modal={confirmModal} onClose={() => setConfirmModal(null)} />
            <Toast toast={toast} onClose={() => setToast(null)} />
        </div>
    );
};

export default AdminPromotions;

import React, { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { Shield, ShieldCheck, ShieldOff, Loader2, Save, RefreshCw, AlertTriangle, Lock, Unlock, Users, Clock, Globe, Zap, Code2, Search, CheckCircle2, XCircle, AlertCircle, Wrench, Activity } from 'lucide-react';

const API_BASE = '/api';

const SETTINGS_META = {
    maintenance_mode: {
        labelKey: 'maintenanceMode',
        descKey: 'maintenanceModeDesc',
        icon: AlertTriangle,
        type: 'toggle',
        danger: true,
    },
    force_https: {
        labelKey: 'forceHttps',
        descKey: 'forceHttpsDesc',
        icon: Lock,
        type: 'toggle',
    },
    block_suspicious_ips: {
        labelKey: 'blockSuspiciousIps',
        descKey: 'blockSuspiciousIpsDesc',
        icon: Shield,
        type: 'toggle',
    },
    allow_registration: {
        labelKey: 'allowRegistration',
        descKey: 'allowRegistrationDesc',
        icon: Users,
        type: 'toggle',
    },
    enable_api_rate_limit: {
        labelKey: 'apiRateLimit',
        descKey: 'apiRateLimitDesc',
        icon: Zap,
        type: 'toggle',
    },
    max_login_attempts: {
        labelKey: 'maxLoginAttempts',
        descKey: 'maxLoginAttemptsDesc',
        icon: Lock,
        type: 'number',
        min: 1,
        max: 20,
    },
    session_timeout_minutes: {
        labelKey: 'sessionTimeout',
        descKey: 'sessionTimeoutDesc',
        icon: Clock,
        type: 'number',
        min: 5,
        max: 1440,
    },
    disable_devtools_block: {
        labelKey: 'disableDevtoolsBlock',
        descKey: 'disableDevtoolsBlockDesc',
        icon: Code2,
        type: 'toggle',
    },
};

const SEVERITY_CONFIG = {
    critical: { color: 'red', label: '심각', bg: 'bg-red-50', border: 'border-red-200', text: 'text-red-700', badge: 'bg-red-100 text-red-700' },
    high: { color: 'orange', label: '높음', bg: 'bg-orange-50', border: 'border-orange-200', text: 'text-orange-700', badge: 'bg-orange-100 text-orange-700' },
    medium: { color: 'yellow', label: '보통', bg: 'bg-yellow-50', border: 'border-yellow-200', text: 'text-yellow-700', badge: 'bg-amber-100 text-amber-700' },
    low: { color: 'blue', label: '낮음', bg: 'bg-blue-50', border: 'border-blue-200', text: 'text-blue-700', badge: 'bg-blue-100 text-blue-700' },
};

const GRADE_CONFIG = {
    A: { color: 'text-emerald-500', bg: 'bg-emerald-50', label: '매우 안전' },
    B: { color: 'text-blue-500', bg: 'bg-blue-50', label: '양호' },
    C: { color: 'text-yellow-500', bg: 'bg-yellow-50', label: '주의 필요' },
    D: { color: 'text-orange-500', bg: 'bg-orange-50', label: '위험' },
    F: { color: 'text-red-500', bg: 'bg-red-50', label: '매우 위험' },
};

const AdminSecurity = () => {
    const { t } = useTranslation('admin');
    const [activeTab, setActiveTab] = useState('settings');
    const [settings, setSettings] = useState({});
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);
    const [dirty, setDirty] = useState(false);
    const [lastSaved, setLastSaved] = useState(null);

    // Audit state
    const [auditData, setAuditData] = useState(null);
    const [auditLoading, setAuditLoading] = useState(false);
    const [fixingItems, setFixingItems] = useState({});

    const fetchSettings = async () => {
        setLoading(true);
        try {
            const res = await fetch(`${API_BASE}/admin/security_settings.php`, { credentials: 'include' });
            const data = await res.json();
            if (data.success) {
                setSettings(data.settings);
                setDirty(false);
            }
        } catch (err) {
            console.error(t('securityPage.settingsLoadFailed'), err);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => { fetchSettings(); }, []);

    const handleToggle = (key) => {
        setSettings(prev => ({ ...prev, [key]: prev[key] === '1' ? '0' : '1' }));
        setDirty(true);
    };

    const handleNumber = (key, value) => {
        const meta = SETTINGS_META[key];
        const num = Math.max(meta.min || 1, Math.min(meta.max || 9999, parseInt(value) || 0));
        setSettings(prev => ({ ...prev, [key]: String(num) }));
        setDirty(true);
    };

    const saveSettings = async () => {
        setSaving(true);
        try {
            const res = await fetch(`${API_BASE}/admin/security_settings.php`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                credentials: 'include',
                body: JSON.stringify({ settings }),
            });
            const data = await res.json();
            if (data.success) {
                setDirty(false);
                setLastSaved(new Date());
            } else {
                alert(t('securityPage.saveFailed') + (data.message || t('securityPage.unknownError')));
            }
        } catch (err) {
            alert(t('securityPage.saveError') + err.message);
        } finally {
            setSaving(false);
        }
    };

    // ─── Audit Functions ───
    const runAudit = async () => {
        setAuditLoading(true);
        try {
            const res = await fetch(`${API_BASE}/admin/security_audit.php`, { credentials: 'include' });
            const data = await res.json();
            if (data.success) {
                setAuditData(data.audit);
            }
        } catch (err) {
            console.error('Security audit failed:', err);
        } finally {
            setAuditLoading(false);
        }
    };

    const applyFix = async (fixId) => {
        setFixingItems(prev => ({ ...prev, [fixId]: true }));
        try {
            const res = await fetch(`${API_BASE}/admin/security_audit.php`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                credentials: 'include',
                body: JSON.stringify({ fix_id: fixId }),
            });
            const data = await res.json();
            if (data.success && data.results?.[0]?.success) {
                // Re-run audit after fix
                await runAudit();
            } else {
                alert('수정 실패: ' + (data.results?.[0]?.message || '알 수 없는 오류'));
            }
        } catch (err) {
            alert('수정 중 오류: ' + err.message);
        } finally {
            setFixingItems(prev => ({ ...prev, [fixId]: false }));
        }
    };

    const fixAll = async () => {
        if (!auditData) return;
        const fixableChecks = auditData.checks.filter(c => c.fixable && c.status !== 'pass');
        for (const check of fixableChecks) {
            await applyFix(check.fix_id);
        }
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center py-32">
                <Loader2 className="animate-spin text-indigo-500" size={32} />
            </div>
        );
    }

    const StatusIcon = ({ status }) => {
        if (status === 'pass') return <CheckCircle2 size={18} className="text-emerald-500" />;
        if (status === 'fail') return <XCircle size={18} className="text-red-500" />;
        return <AlertCircle size={18} className="text-amber-500" />;
    };

    const fixableFailCount = auditData?.checks?.filter(c => c.fixable && c.status !== 'pass').length || 0;

    return (
        <div className="space-y-8 pb-20">
            {/* Header */}
            <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
                <div>
                    <h1 className="text-2xl md:text-3xl font-extrabold text-gray-900 flex items-center gap-3">
                        <div className="w-10 h-10 bg-gradient-to-br from-emerald-500 to-teal-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-emerald-200">
                            <ShieldCheck size={20} />
                        </div>
                        {t('securityPage.title')}
                    </h1>
                    <p className="text-gray-500 mt-1 text-sm">{t('securityPage.subtitle')}</p>
                </div>
                <div className="flex items-center gap-3">
                    {activeTab === 'settings' && (
                        <>
                            <button
                                onClick={fetchSettings}
                                className="flex items-center gap-2 px-4 py-2.5 bg-gray-100 hover:bg-gray-200 rounded-xl text-sm font-bold text-gray-600 transition-colors"
                            >
                                <RefreshCw size={14} />
                                {t('securityPage.refresh')}
                            </button>
                            <button
                                onClick={saveSettings}
                                disabled={!dirty || saving}
                                className={`flex items-center gap-2 px-5 py-2.5 rounded-xl text-sm font-bold transition-all duration-300 ${dirty
                                    ? 'bg-indigo-600 text-white hover:bg-indigo-700 shadow-lg shadow-indigo-200'
                                    : 'bg-gray-100 text-gray-400 cursor-not-allowed'
                                    }`}
                            >
                                {saving ? <Loader2 size={14} className="animate-spin" /> : <Save size={14} />}
                                {saving ? t('securityPage.saving') : t('securityPage.saveChanges')}
                            </button>
                        </>
                    )}
                    {activeTab === 'audit' && (
                        <>
                            <button
                                onClick={runAudit}
                                disabled={auditLoading}
                                className="flex items-center gap-2 px-4 py-2.5 bg-indigo-600 hover:bg-indigo-700 rounded-xl text-sm font-bold text-white transition-colors shadow-lg shadow-indigo-200"
                            >
                                {auditLoading ? <Loader2 size={14} className="animate-spin" /> : <Search size={14} />}
                                {auditLoading ? '점검 중...' : '보안 점검 실행'}
                            </button>
                            {fixableFailCount > 0 && (
                                <button
                                    onClick={fixAll}
                                    className="flex items-center gap-2 px-4 py-2.5 bg-emerald-600 hover:bg-emerald-700 rounded-xl text-sm font-bold text-white transition-colors shadow-lg shadow-emerald-200"
                                >
                                    <Wrench size={14} />
                                    전체 자동 수정 ({fixableFailCount})
                                </button>
                            )}
                        </>
                    )}
                </div>
            </div>

            {lastSaved && activeTab === 'settings' && (
                <div className="bg-emerald-50 border border-emerald-200 rounded-xl px-4 py-2.5 text-sm text-emerald-700 font-medium flex items-center gap-2">
                    <ShieldCheck size={14} />
                    {t('securityPage.lastSaved')} {lastSaved.toLocaleTimeString()}
                </div>
            )}

            {/* Tab Switcher */}
            <div className="flex gap-2 bg-gray-100 p-1 rounded-xl w-fit">
                <button
                    onClick={() => setActiveTab('settings')}
                    className={`px-5 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'settings'
                        ? 'bg-white text-gray-900 shadow-sm'
                        : 'text-gray-500 hover:text-gray-700'
                        }`}
                >
                    <div className="flex items-center gap-2">
                        <Shield size={14} />
                        보안 설정
                    </div>
                </button>
                <button
                    onClick={() => { setActiveTab('audit'); if (!auditData) runAudit(); }}
                    className={`px-5 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'audit'
                        ? 'bg-white text-gray-900 shadow-sm'
                        : 'text-gray-500 hover:text-gray-700'
                        }`}
                >
                    <div className="flex items-center gap-2">
                        <Activity size={14} />
                        서버 보안 점검
                        {auditData && (
                            <span className={`text-[10px] px-1.5 py-0.5 rounded-full font-bold ${auditData.summary.failed > 0 ? 'bg-red-100 text-red-600' : 'bg-emerald-100 text-emerald-600'}`}>
                                {auditData.summary.grade}
                            </span>
                        )}
                    </div>
                </button>
            </div>

            {/* ═══ TAB: Settings ═══ */}
            {activeTab === 'settings' && (
                <>
                    <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
                        {Object.entries(SETTINGS_META).map(([key, meta]) => {
                            const Icon = meta.icon;
                            const isOn = settings[key] === '1';
                            const isDanger = meta.danger;

                            return (
                                <div
                                    key={key}
                                    className={`bg-white rounded-2xl border p-5 transition-all duration-300 ${isDanger && isOn
                                        ? 'border-red-200 bg-red-50/30 shadow-sm shadow-red-100'
                                        : 'border-gray-100 hover:border-gray-200 hover:shadow-sm'
                                        }`}
                                >
                                    <div className="flex items-start justify-between gap-4">
                                        <div className="flex items-start gap-3.5 flex-1">
                                            <div className={`w-10 h-10 rounded-xl flex items-center justify-center flex-shrink-0 ${isDanger && isOn
                                                ? 'bg-red-100 text-red-600'
                                                : isOn
                                                    ? 'bg-emerald-100 text-emerald-600'
                                                    : 'bg-gray-100 text-gray-400'
                                                }`}>
                                                <Icon size={18} />
                                            </div>
                                            <div>
                                                <h3 className="font-bold text-gray-900 text-sm flex items-center gap-2">
                                                    {t(`securityPage.${meta.labelKey}`)}
                                                    {isDanger && isOn && (
                                                        <span className="text-[10px] font-bold bg-red-100 text-red-600 px-1.5 py-0.5 rounded-full">{t('securityPage.danger')}</span>
                                                    )}
                                                </h3>
                                                <p className="text-xs text-gray-400 mt-0.5 leading-relaxed">{t(`securityPage.${meta.descKey}`)}</p>
                                            </div>
                                        </div>

                                        {meta.type === 'toggle' ? (
                                            <button
                                                onClick={() => handleToggle(key)}
                                                className={`relative w-12 h-6 rounded-full transition-all duration-300 flex-shrink-0 ${isOn
                                                    ? isDanger
                                                        ? 'bg-red-500'
                                                        : 'bg-emerald-500'
                                                    : 'bg-gray-300'
                                                    }`}
                                            >
                                                <div className={`absolute top-0.5 w-5 h-5 bg-white rounded-full shadow-sm transition-all duration-300 ${isOn ? 'left-[26px]' : 'left-0.5'
                                                    }`} />
                                            </button>
                                        ) : (
                                            <input
                                                type="number"
                                                value={settings[key] || ''}
                                                onChange={(e) => handleNumber(key, e.target.value)}
                                                min={meta.min}
                                                max={meta.max}
                                                className="w-20 px-3 py-1.5 text-sm font-bold text-center bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500"
                                            />
                                        )}
                                    </div>
                                </div>
                            );
                        })}
                    </div>

                    {/* Security Status */}
                    <div className="bg-gradient-to-br from-gray-900 to-gray-800 rounded-2xl p-6 text-white">
                        <h3 className="font-bold text-lg mb-4 flex items-center gap-2">
                            <Shield size={18} />
                            {t('securityPage.securitySummary')}
                        </h3>
                        <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
                            {[
                                { label: 'HTTPS', active: settings.force_https === '1' },
                                { label: t('securityPage.ipBlock'), active: settings.block_suspicious_ips === '1' },
                                { label: t('securityPage.apiLimit'), active: settings.enable_api_rate_limit === '1' },
                                { label: t('securityPage.maintenanceLabel'), active: settings.maintenance_mode === '1', warn: true },
                                { label: t('securityPage.devtoolsLabel'), active: settings.disable_devtools_block === '1', warn: true },
                            ].map((item, i) => (
                                <div key={i} className={`flex items-center gap-2 px-3 py-2 rounded-xl text-sm font-medium ${item.active
                                    ? item.warn
                                        ? 'bg-red-500/20 text-red-300'
                                        : 'bg-emerald-500/20 text-emerald-300'
                                    : 'bg-white/10 text-gray-400'
                                    }`}>
                                    {item.active
                                        ? item.warn ? <ShieldOff size={14} /> : <ShieldCheck size={14} />
                                        : <ShieldOff size={14} />
                                    }
                                    {item.label}
                                </div>
                            ))}
                        </div>
                    </div>
                </>
            )}

            {/* ═══ TAB: Audit ═══ */}
            {activeTab === 'audit' && (
                <>
                    {auditLoading && !auditData && (
                        <div className="flex flex-col items-center justify-center py-20 gap-4">
                            <Loader2 size={32} className="animate-spin text-indigo-500" />
                            <p className="text-gray-500 font-medium">서버 보안 점검 중...</p>
                        </div>
                    )}

                    {auditData && (
                        <>
                            {/* Score Card */}
                            <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                                <div className={`col-span-1 md:col-span-1 rounded-2xl border p-6 flex flex-col items-center justify-center gap-2 ${GRADE_CONFIG[auditData.summary.grade]?.bg || 'bg-gray-50'}`}>
                                    <span className={`text-6xl font-black ${GRADE_CONFIG[auditData.summary.grade]?.color || 'text-gray-500'}`}>
                                        {auditData.summary.grade}
                                    </span>
                                    <span className="text-sm font-bold text-gray-600">{GRADE_CONFIG[auditData.summary.grade]?.label}</span>
                                    <span className="text-2xl font-extrabold text-gray-900">{auditData.summary.score}점</span>
                                </div>
                                <div className="col-span-1 md:col-span-3 grid grid-cols-3 gap-4">
                                    <div className="bg-white rounded-2xl border border-gray-100 p-5 flex flex-col items-center gap-1">
                                        <CheckCircle2 size={24} className="text-emerald-500" />
                                        <span className="text-3xl font-black text-emerald-600">{auditData.summary.passed}</span>
                                        <span className="text-xs font-medium text-gray-400">통과</span>
                                    </div>
                                    <div className="bg-white rounded-2xl border border-gray-100 p-5 flex flex-col items-center gap-1">
                                        <XCircle size={24} className="text-red-500" />
                                        <span className="text-3xl font-black text-red-600">{auditData.summary.failed}</span>
                                        <span className="text-xs font-medium text-gray-400">실패</span>
                                    </div>
                                    <div className="bg-white rounded-2xl border border-gray-100 p-5 flex flex-col items-center gap-1">
                                        <AlertCircle size={24} className="text-amber-500" />
                                        <span className="text-3xl font-black text-amber-600">{auditData.summary.warned}</span>
                                        <span className="text-xs font-medium text-gray-400">경고</span>
                                    </div>
                                </div>
                            </div>

                            {/* Audit Items */}
                            <div className="space-y-3">
                                <h3 className="font-bold text-lg text-gray-900 flex items-center gap-2">
                                    <Search size={18} />
                                    점검 항목 ({auditData.checks.length}개)
                                </h3>
                                {auditData.checks.map((check, idx) => {
                                    const sev = SEVERITY_CONFIG[check.severity] || SEVERITY_CONFIG.medium;
                                    return (
                                        <div
                                            key={idx}
                                            className={`bg-white rounded-2xl border p-5 transition-all ${check.status === 'fail' ? 'border-red-200 shadow-sm shadow-red-50' : check.status === 'warn' ? 'border-amber-200' : 'border-gray-100'}`}
                                        >
                                            <div className="flex items-start justify-between gap-4">
                                                <div className="flex items-start gap-3 flex-1">
                                                    <div className="mt-0.5">
                                                        <StatusIcon status={check.status} />
                                                    </div>
                                                    <div className="flex-1">
                                                        <div className="flex items-center gap-2 flex-wrap">
                                                            <h4 className="font-bold text-gray-900 text-sm">{check.title}</h4>
                                                            <span className={`text-[10px] font-bold px-1.5 py-0.5 rounded-full ${sev.badge}`}>
                                                                {sev.label}
                                                            </span>
                                                            <span className={`text-[10px] font-bold px-1.5 py-0.5 rounded-full ${check.status === 'pass' ? 'bg-emerald-100 text-emerald-700' : check.status === 'fail' ? 'bg-red-100 text-red-700' : 'bg-amber-100 text-amber-700'}`}>
                                                                {check.status === 'pass' ? '통과' : check.status === 'fail' ? '실패' : '경고'}
                                                            </span>
                                                        </div>
                                                        <p className="text-xs text-gray-400 mt-0.5">{check.description}</p>
                                                        <p className={`text-xs mt-1.5 font-medium ${check.status === 'pass' ? 'text-emerald-600' : check.status === 'fail' ? 'text-red-600' : 'text-amber-600'}`}>
                                                            {check.detail}
                                                        </p>
                                                    </div>
                                                </div>
                                                {check.fixable && check.status !== 'pass' && (
                                                    <button
                                                        onClick={() => applyFix(check.fix_id)}
                                                        disabled={fixingItems[check.fix_id]}
                                                        className="flex items-center gap-1.5 px-4 py-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl text-xs font-bold transition-colors shadow-sm flex-shrink-0 disabled:opacity-50"
                                                    >
                                                        {fixingItems[check.fix_id] ? (
                                                            <Loader2 size={12} className="animate-spin" />
                                                        ) : (
                                                            <Wrench size={12} />
                                                        )}
                                                        {fixingItems[check.fix_id] ? '수정 중...' : '자동 수정'}
                                                    </button>
                                                )}
                                            </div>
                                        </div>
                                    );
                                })}
                            </div>

                            {/* Audit timestamp */}
                            <div className="text-center text-xs text-gray-400 mt-4">
                                마지막 점검: {auditData.timestamp}
                            </div>
                        </>
                    )}

                    {!auditLoading && !auditData && (
                        <div className="flex flex-col items-center justify-center py-20 gap-4">
                            <div className="w-16 h-16 bg-indigo-100 rounded-2xl flex items-center justify-center">
                                <Shield size={32} className="text-indigo-500" />
                            </div>
                            <h3 className="font-bold text-lg text-gray-900">서버 보안 점검</h3>
                            <p className="text-sm text-gray-500 text-center max-w-md">
                                서버의 보안 상태를 자동으로 점검합니다.<br />
                                .htaccess 보호, 파일 업로드 보안, SQL Injection 방어 등을 확인합니다.
                            </p>
                            <button
                                onClick={runAudit}
                                className="flex items-center gap-2 px-6 py-3 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl text-sm font-bold transition-colors shadow-lg shadow-indigo-200 mt-2"
                            >
                                <Search size={16} />
                                보안 점검 시작
                            </button>
                        </div>
                    )}
                </>
            )}
        </div>
    );
};

export default AdminSecurity;

import React, { useState, useEffect, useCallback } from 'react';
import { useTranslation } from 'react-i18next';
import {
    Trash2, RotateCcw, XCircle, Search, ChevronDown,
    AlertTriangle, CheckCircle, RefreshCw, Package
} from 'lucide-react';
import ConfirmModal from '../../components/ConfirmModal';
import Toast from '../../components/Toast';

const TABLE_LABEL_KEYS = {
    ads: 'ads',
    venues: 'venues',
    community_posts: 'communityPosts',
    seller_photos: 'sellerPhotos',
    applications: 'applications',
    users: 'users',
    popups: 'popups',
};

const AdminTrash = () => {
    const { t } = useTranslation('admin');
    const [items, setItems] = useState([]);
    const [loading, setLoading] = useState(true);
    const [tables, setTables] = useState([]);
    const [filterTable, setFilterTable] = useState('');
    const [searchTerm, setSearchTerm] = useState('');
    const [page, setPage] = useState(1);
    const [total, setTotal] = useState(0);
    const [selectedIds, setSelectedIds] = useState(new Set());
    const [confirmModal, setConfirmModal] = useState(null);
    const [toast, setToast] = useState(null);

    const perPage = 20;
    const showToast = useCallback((message, type = 'success') => setToast({ message, type }), []);

    const fetchTrash = useCallback(async () => {
        try {
            const params = new URLSearchParams({ page });
            if (filterTable) params.append('table_name', filterTable);
            if (searchTerm) params.append('search', searchTerm);
            const res = await fetch(`/api/trash/list_trash.php?${params}`, { credentials: 'include' });
            const data = await res.json();
            if (data.success) {
                setItems(data.items || []);
                setTotal(data.total || 0);
                setTables(data.tables || []);
            }
        } catch { showToast(t('trashPage.loadFailed'), 'error'); }
        finally { setLoading(false); }
    }, [filterTable, searchTerm, page, showToast]);

    useEffect(() => { fetchTrash(); }, [fetchTrash]);

    const handleRestore = async (id) => {
        try {
            const res = await fetch('/api/trash/restore.php', {
                method: 'POST', headers: { 'Content-Type': 'application/json' }, credentials: 'include',
                body: JSON.stringify({ id })
            });
            const data = await res.json();
            showToast(data.message, data.success ? 'success' : 'error');
            if (data.success) fetchTrash();
        } catch { showToast(t('trashPage.restoreFailed'), 'error'); }
    };

    const handlePermanentDelete = async (id) => {
        setConfirmModal({
            title: t('trashPage.confirmDelete'),
            message: t('trashPage.confirmDeleteMsg', { title: '' }),
            onConfirm: async () => {
                try {
                    const res = await fetch('/api/trash/permanent_delete.php', {
                        method: 'POST', headers: { 'Content-Type': 'application/json' }, credentials: 'include',
                        body: JSON.stringify({ id })
                    });
                    const data = await res.json();
                    showToast(data.message, data.success ? 'success' : 'error');
                    if (data.success) fetchTrash();
                } catch { showToast(t('trashPage.deleteFailed'), 'error'); }
                setConfirmModal(null);
            }
        });
    };

    const handleBatchRestore = async () => {
        for (const id of selectedIds) { await handleRestore(id); }
        setSelectedIds(new Set());
    };

    const handleBatchPermanentDelete = () => {
        setConfirmModal({
            title: t('trashPage.batchDelete'),
            message: t('trashPage.batchDeleteMsg', { count: selectedIds.size }),
            onConfirm: async () => {
                try {
                    const res = await fetch('/api/trash/permanent_delete.php', {
                        method: 'POST', headers: { 'Content-Type': 'application/json' }, credentials: 'include',
                        body: JSON.stringify({ ids: [...selectedIds] })
                    });
                    const data = await res.json();
                    showToast(data.message, data.success ? 'success' : 'error');
                    if (data.success) { setSelectedIds(new Set()); fetchTrash(); }
                } catch { showToast(t('trashPage.deleteFailed'), 'error'); }
                setConfirmModal(null);
            }
        });
    };

    const toggleSelect = (id) => {
        const next = new Set(selectedIds);
        next.has(id) ? next.delete(id) : next.add(id);
        setSelectedIds(next);
    };
    const toggleAll = () => {
        if (items.every(i => selectedIds.has(i.id))) setSelectedIds(new Set());
        else setSelectedIds(new Set(items.map(i => i.id)));
    };

    const totalPages = Math.ceil(total / perPage);
    const allSelected = items.length > 0 && items.every(i => selectedIds.has(i.id));

    const formatDate = (d) => {
        if (!d) return '';
        const date = new Date(d);
        const now = new Date();
        const diff = now - date;
        if (diff < 60000) return t('trashPage.justNow');
        if (diff < 3600000) return t('trashPage.minutesAgo', { count: Math.floor(diff / 60000) });
        if (diff < 86400000) return t('trashPage.hoursAgo', { count: Math.floor(diff / 3600000) });
        if (diff < 604800000) return t('trashPage.daysAgo', { count: Math.floor(diff / 86400000) });
        return date.toLocaleDateString();
    };

    return (
        <div className="max-w-6xl mx-auto">
            {/* Header */}
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
                <div className="flex items-center gap-3">
                    <div className="w-10 h-10 bg-gradient-to-br from-gray-500 to-gray-700 rounded-xl flex items-center justify-center">
                        <Trash2 className="text-white" size={22} />
                    </div>
                    <div>
                        <h1 className="text-2xl md:text-3xl font-extrabold text-gray-900 dark:text-white">{t('trashPage.title')}</h1>
                        <p className="text-sm text-gray-500 dark:text-gray-400">{t('trashPage.subtitle')}</p>
                    </div>
                </div>
                <button onClick={fetchTrash} className="flex items-center gap-2 px-4 py-2.5 bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-300 rounded-xl font-bold text-sm hover:bg-gray-200 dark:hover:bg-gray-600 transition-colors">
                    <RefreshCw size={16} /> {t('trashPage.refresh')}
                </button>
            </div>

            {/* Search & Filter */}
            <div className="bg-white dark:bg-gray-800/50 rounded-2xl shadow-sm border border-gray-100 dark:border-gray-700/50 p-4 mb-4">
                <div className="flex flex-col md:flex-row gap-3 mb-3">
                    <div className="relative flex-1">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                        <input type="text" value={searchTerm} onChange={e => { setSearchTerm(e.target.value); setPage(1); }} placeholder={t('trashPage.searchPlaceholder')} className="w-full pl-10 pr-4 py-2.5 bg-gray-50 dark:bg-gray-700 rounded-xl border border-transparent focus:border-indigo-500 outline-none font-medium text-sm dark:text-white" />
                    </div>
                    <div className="relative">
                        <select value={filterTable} onChange={e => { setFilterTable(e.target.value); setPage(1); }} className="w-full md:w-48 px-4 py-2.5 bg-gray-50 dark:bg-gray-700 rounded-xl border border-transparent focus:border-indigo-500 outline-none appearance-none font-medium text-sm dark:text-white">
                            <option value="">{t('trashPage.allTables')}</option>
                            {tables.map(tbl => (<option key={tbl} value={tbl}>{t(`trashPage.table_${TABLE_LABEL_KEYS[tbl]}`, tbl)}</option>))}
                        </select>
                        <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 pointer-events-none" size={16} />
                    </div>
                </div>
                <p className="text-xs text-gray-400">{t('trashPage.totalItems', { count: total })}</p>
            </div>

            {/* Batch action toolbar */}
            {selectedIds.size > 0 && (
                <div className="bg-indigo-50 dark:bg-indigo-500/10 border border-indigo-200 dark:border-indigo-500/30 rounded-xl px-4 py-3 flex items-center gap-3 mb-4">
                    <span className="text-sm font-bold text-indigo-700 dark:text-indigo-300">{t('trashPage.selectedCount', { count: selectedIds.size })}</span>
                    <div className="h-5 w-px bg-indigo-200 dark:bg-indigo-500/30" />
                    <button onClick={handleBatchRestore} className="px-3 py-1.5 rounded-lg bg-emerald-100 text-emerald-700 dark:bg-emerald-500/20 dark:text-emerald-400 text-xs font-bold hover:bg-emerald-200 transition-colors flex items-center gap-1">
                        <RotateCcw size={13} /> {t('trashPage.batchRestore')}
                    </button>
                    <button onClick={handleBatchPermanentDelete} className="px-3 py-1.5 rounded-lg bg-red-100 text-red-600 dark:bg-red-500/20 dark:text-red-400 text-xs font-bold hover:bg-red-200 transition-colors flex items-center gap-1">
                        <XCircle size={13} /> {t('trashPage.batchDeleteBtn')}
                    </button>
                    <button onClick={() => setSelectedIds(new Set())} className="ml-auto text-xs text-gray-400 hover:text-gray-600 dark:hover:text-gray-300 font-medium">{t('trashPage.deselectAll')}</button>
                </div>
            )}

            {/* Table */}
            {loading ? (
                <div className="flex items-center justify-center h-64"><div className="animate-spin rounded-full h-8 w-8 border-2 border-indigo-600 border-t-transparent" /></div>
            ) : items.length === 0 ? (
                <div className="text-center py-20">
                    <Trash2 className="mx-auto text-gray-300 dark:text-gray-600 mb-4" size={48} />
                    <h3 className="text-lg font-bold text-gray-400 dark:text-gray-500">{t('trashPage.noItems')}</h3>
                    <p className="text-sm text-gray-300 dark:text-gray-600 mt-1">{t('trashPage.noItemsDesc')}</p>
                </div>
            ) : (
                <div className="bg-white dark:bg-gray-800/50 rounded-2xl border border-gray-100 dark:border-gray-700/50 shadow-sm overflow-hidden">
                    <div className="overflow-x-auto">
                        <table className="w-full text-sm">
                            <thead>
                                <tr className="bg-gray-50 dark:bg-gray-700/30 text-gray-500 dark:text-gray-400 text-xs font-bold uppercase">
                                    <th className="w-10 px-4 py-3"><input type="checkbox" checked={allSelected} onChange={toggleAll} className="rounded border-gray-300 dark:border-gray-600 text-indigo-600 focus:ring-indigo-500" /></th>
                                    <th className="text-left px-3 py-3">{t('trashPage.title_col')}</th>
                                    <th className="text-left px-3 py-3">{t('trashPage.sourceTable')}</th>
                                    <th className="text-left px-3 py-3">{t('trashPage.deletedBy')}</th>
                                    <th className="text-left px-3 py-3">{t('trashPage.deletedAt')}</th>
                                    <th className="text-center px-3 py-3 w-28">{t('trashPage.action')}</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-50 dark:divide-gray-700/30">
                                {items.map(item => {
                                    const isSelected = selectedIds.has(item.id);
                                    return (
                                        <tr key={item.id} className={`transition-colors hover:bg-gray-50/50 dark:hover:bg-gray-700/20 ${isSelected ? 'bg-indigo-50/50 dark:bg-indigo-500/5' : ''}`}>
                                            <td className="px-4 py-3 text-center">
                                                <input type="checkbox" checked={isSelected} onChange={() => toggleSelect(item.id)} className="rounded border-gray-300 dark:border-gray-600 text-indigo-600 focus:ring-indigo-500" />
                                            </td>
                                            <td className="px-3 py-3">
                                                <div className="flex items-center gap-2">
                                                    <Package size={14} className="text-gray-400 flex-shrink-0" />
                                                    <span className="font-bold text-gray-900 dark:text-white truncate max-w-[250px]">{item.item_label || `#${item.record_id}`}</span>
                                                </div>
                                            </td>
                                            <td className="px-3 py-3">
                                                <span className="px-2 py-0.5 bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-400 rounded-lg text-[11px] font-bold">
                                                    {t(`trashPage.table_${TABLE_LABEL_KEYS[item.table_name]}`, item.table_name)}
                                                </span>
                                            </td>
                                            <td className="px-3 py-3 text-xs text-gray-500 dark:text-gray-400">{item.deleted_by_name || '-'}</td>
                                            <td className="px-3 py-3 text-xs text-gray-400" title={item.deleted_at}>{formatDate(item.deleted_at)}</td>
                                            <td className="px-3 py-3">
                                                <div className="flex items-center justify-center gap-1">
                                                    <button onClick={() => handleRestore(item.id)} className="p-1.5 rounded-lg bg-emerald-50 text-emerald-600 hover:bg-emerald-100 dark:bg-emerald-500/10 dark:text-emerald-400 dark:hover:bg-emerald-500/20 transition-colors" title={t('trashPage.restore')}>
                                                        <RotateCcw size={13} />
                                                    </button>
                                                    <button onClick={() => handlePermanentDelete(item.id)} className="p-1.5 rounded-lg bg-red-50 text-red-600 hover:bg-red-100 dark:bg-red-500/10 dark:text-red-400 dark:hover:bg-red-500/20 transition-colors" title={t('trashPage.permanentDelete')}>
                                                        <XCircle size={13} />
                                                    </button>
                                                </div>
                                            </td>
                                        </tr>
                                    );
                                })}
                            </tbody>
                        </table>
                    </div>
                    {/* Pagination */}
                    {totalPages > 1 && (
                        <div className="px-4 py-3 bg-gray-50 dark:bg-gray-700/20 border-t border-gray-100 dark:border-gray-700/30 flex items-center justify-center gap-1">
                            {Array.from({ length: totalPages }, (_, i) => i + 1).map(p => (
                                <button key={p} onClick={() => setPage(p)} className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-colors ${page === p ? 'bg-indigo-600 text-white' : 'bg-white dark:bg-gray-700 text-gray-500 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-600'}`}>{p}</button>
                            ))}
                        </div>
                    )}
                </div>
            )}

            {/* Modals */}
            {confirmModal && <ConfirmModal modal={{ ...confirmModal, type: 'danger', confirmLabel: confirmModal.title }} onClose={() => setConfirmModal(null)} />}
            {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
        </div>
    );
};

