        setNewPhotos(prev => [...prev, ...toAdd]);

        toAdd.forEach(file => {
            const reader = new FileReader();
            reader.onload = (ev) => {
                setPhotoPreviewUrls(prev => [...prev, ev.target.result]);
            };
            reader.readAsDataURL(file);
        });
        e.target.value = '';
