        const newIdx = direction === 'left' ? index - 1 : index + 1;
        if (newIdx < 0 || newIdx >= newPhotos.length) return;
        setNewPhotos(prev => {
            const arr = [...prev];
            [arr[index], arr[newIdx]] = [arr[newIdx], arr[index]];
            return arr;
        });
        setPhotoPreviewUrls(prev => {
