                if (data.post.is_notice > 0) {
                    setNotices(prev => [data.post, ...prev]);
                } else {
                    setPosts(prev => [data.post, ...prev]);
                }
                setNewPost({ title: '', content: '', label: '', keywords: '', is_notice: 0 });
                setNewPhotos([]);
                setPhotoPreviewUrls([]);
                setShowWriteForm(false);
                setNewPollOptions(['', '']);
                setShowPollForm(false);
