                        showToast(t('commentDeleteFailed'), 'error');
                    }
                } catch (err) {
                    showToast(t('commentDeleteError'), 'error');
                }
            }
        });
    };

    // Like toggle (optimistic)
    const handleToggleLike = async (e, postId) => {
        e.stopPropagation();
        if (isDemoUser) { demoAlert('좋아요'); return; }
        // Optimistic update
        setPosts(prev => prev.map(p => p.id === postId ? { ...p, is_liked: !p.is_liked, like_count: p.is_liked ? p.like_count - 1 : p.like_count + 1 } : p));
        setPopularPosts(prev => prev.map(p => p.id === postId ? { ...p, is_liked: !p.is_liked, like_count: p.is_liked ? p.like_count - 1 : p.like_count + 1 } : p));
        try {
            const res = await fetch(`${API_BASE}/community_likes.php`, {
                method: 'POST', credentials: 'include',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ post_id: postId })
            });
            const data = await res.json();
            if (data.success) {
                setPosts(prev => prev.map(p => p.id === postId ? { ...p, is_liked: data.liked, like_count: data.like_count } : p));
            }
        } catch (err) { console.error('Like toggle failed:', err); }
    };

    // Comment like toggle (optimistic)
    const handleToggleCommentLike = async (e, postId, commentId) => {
        e.stopPropagation();
        // Optimistic update in commentsMap
        setCommentsMap(prev => {
            const updated = { ...prev };
            if (!updated[postId]) return updated;
            updated[postId] = updated[postId].map(c => {
                if (c.id === commentId) {
                    return { ...c, is_liked: !c.is_liked, like_count: c.is_liked ? (c.like_count || 1) - 1 : (c.like_count || 0) + 1 };
                }
                if (c.replies) {
                    return { ...c, replies: c.replies.map(r => r.id === commentId ? { ...r, is_liked: !r.is_liked, like_count: r.is_liked ? (r.like_count || 1) - 1 : (r.like_count || 0) + 1 } : r) };
                }
                return c;
            });
            return updated;
        });
        try {
            const res = await fetch(`${API_BASE}/community_comment_likes.php`, {
                method: 'POST', credentials: 'include',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ comment_id: commentId })
            });
            const data = await res.json();
            if (data.success) {
                setCommentsMap(prev => {
                    const updated = { ...prev };
                    if (!updated[postId]) return updated;
                    updated[postId] = updated[postId].map(c => {
                        if (c.id === commentId) return { ...c, is_liked: data.liked, like_count: data.like_count };
                        if (c.replies) return { ...c, replies: c.replies.map(r => r.id === commentId ? { ...r, is_liked: data.liked, like_count: data.like_count } : r) };
                        return c;
                    });
                    return updated;
                });
            }
        } catch (err) { console.error('Comment like toggle failed:', err); }
    };

    // View count increment
    const incrementViewCount = async (postId) => {
        try {
            await fetch(`${API_BASE}/community_likes.php`, {
                method: 'PUT', credentials: 'include',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ post_id: postId })
            });
            setPosts(prev => prev.map(p => p.id === postId ? { ...p, view_count: (p.view_count || 0) + 1 } : p));
        } catch (err) { /* silent */ }
    };

    // Load comments when a post is expanded
    const handleTogglePost = (postId) => {
        const isExpanding = expandedPost !== postId;
        setExpandedPost(isExpanding ? postId : null);
        setReplyingTo(null);
        setReplyInput('');
        setCommentInput('');
        if (isExpanding) {
            if (!commentsMap[postId]) fetchComments(postId);
            incrementViewCount(postId);
        }
    };

    // Navigate to a popular post
    const goToPopularPost = (postId) => {
        // If on page 1 and post exists, just expand; otherwise navigate
        const found = posts.find(p => p.id === postId);
        if (found) {
            setExpandedPost(postId);
            if (!commentsMap[postId]) fetchComments(postId);
            incrementViewCount(postId);
            setTimeout(() => {
                document.getElementById(`post-${postId}`)?.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }, 100);
        } else {
            setFilterLabel('');
            setPage(1);
            setHighlightedPostId(postId);
            setExpandedPost(postId);
        }
    };

    // Fetch public profile for popup
    const openUserProfile = async (e, userId) => {
        e.stopPropagation();
        setProfilePopup(userId);
        setProfileData(null);
        setProfileLoading(true);
        try {
            const [profileRes, activityRes] = await Promise.all([
                fetch(`/api/users/get_public_profile.php?id=${userId}`, { credentials: 'include' }),
                fetch(`${API_BASE}/community_activity.php?user_id=${userId}`, { credentials: 'include' })
            ]);
            const profileJson = await profileRes.json();
            const activityJson = await activityRes.json();
            if (profileJson.success) {
                setProfileData({
                    ...profileJson,
                    activity: activityJson.success ? activityJson.activity : null
                });
            }
        } catch (err) {
            console.error(err);
        } finally {
            setProfileLoading(false);
        }
    };

    // Double-tap like handler
    const handleDoubleTap = (e, postId) => {
        const now = Date.now();
        const lastTap = lastTapRef.current[postId] || 0;
        if (now - lastTap < 350) {
            // Double tap detected
            const post = posts.find(p => p.id === postId);
            if (post && !post.is_liked) {
                handleToggleLike(e, postId);
            }
            setDoubleTapHeart(postId);
            setTimeout(() => setDoubleTapHeart(null), 900);
            lastTapRef.current[postId] = 0;
        } else {
            lastTapRef.current[postId] = now;
        }
    };

    // Check if post is new (within 24h) or hot (5+ likes)
    const getPostBadge = (post) => {
        const created = new Date(post.created_at);
        const hoursDiff = (Date.now() - created.getTime()) / (1000 * 60 * 60);
        if ((post.like_count || 0) >= 5) return 'hot';
        if (hoursDiff < 24) return 'new';
        return null;
    };

    return (
        <div className="max-w-4xl mx-auto pb-20 space-y-6">
            {/* Community Header Banner */}
            <div className={`bg-gradient-to-r ${config.gradient} rounded-2xl p-6 text-white relative overflow-hidden`}>
                <div className="absolute inset-0 opacity-10">
                    <div className="absolute -right-10 -top-10 w-40 h-40 bg-white rounded-full"></div>
                    <div className="absolute -left-5 -bottom-5 w-24 h-24 bg-white rounded-full"></div>
                </div>
                <div className="relative z-10 flex items-center justify-between">
                    <div>
                        <div className="flex items-center gap-3 mb-1">
                            <MessageSquare size={28} />
                            <h1 className="text-2xl md:text-3xl font-extrabold">{t(config.titleKey)}</h1>
                        </div>
                        <p className="text-white/80 text-sm">{t(config.subtitleKey)}</p>
                    </div>
                    <button
                        onClick={() => { if (isDemoUser) { demoAlert('글 작성'); return; } setShowWriteForm(!showWriteForm); }}
                        className="flex items-center gap-2 px-5 py-2.5 bg-white/20 backdrop-blur rounded-xl font-bold text-sm hover:bg-white/30 transition-colors"
                    >
                        <PenLine size={16} />
                        {t('writePost')}
                    </button>
                </div>
                {/* Real-time Activity Indicator */}
                <div className="flex items-center gap-3 mt-2">
                    <div className="flex items-center gap-1.5 px-3 py-1 bg-white/15 backdrop-blur rounded-full">
                        <span className="w-2 h-2 bg-green-400 rounded-full animate-pulse"></span>
                        <span className="text-white/90 text-xs font-medium" dangerouslySetInnerHTML={{ __html: t('currentViewers', { count: Math.max(3, Math.floor((posts.reduce((s, p) => s + (p.view_count || 0), 0) / Math.max(1, posts.length)) * 0.08 + popularPosts.length * 2)) }) }} />
                    </div>
                    <span className="text-white/60 text-xs">{t('todayPosts', { count: posts.filter(p => { const d = new Date(p.created_at); const now = new Date(); return d.toDateString() === now.toDateString(); }).length })}</span>
                </div>
            </div>

            {/* Mode Tabs + Sort */}
            <div className="flex items-center gap-2">
                <div className="flex-1 overflow-x-auto scrollbar-hide">
                    <div className="flex items-center gap-1 bg-gray-50 rounded-xl p-1 min-w-max">
                        {[
                            { key: 'all', label: t('feedAll'), icon: <BarChart3 size={13} /> },
                            { key: 'best', label: t('feedBest'), icon: <Crown size={13} /> },
                            { key: 'bookmarks', label: t('myBookmarks'), icon: <Bookmark size={13} /> },
                        ].map(tab => (
                            <button
                                key={tab.key}
                                onClick={() => { setFeedMode(tab.key); setPage(1); }}
                                className={`flex items-center gap-1 px-3 py-2 rounded-lg text-xs font-bold transition-all whitespace-nowrap ${feedMode === tab.key
                                    ? 'bg-white text-gray-900 shadow-sm'
                                    : 'text-gray-500 hover:text-gray-700'
                                    }`}
                            >
                                {tab.icon}
                                {tab.label}
                                {tab.key === 'best' && <span className="text-[9px] text-amber-500 font-extrabold">🏅</span>}
                            </button>
                        ))}
                        {/* 국가 설정 버튼 - 내 북마크 옆 */}
                        <button
                            onClick={() => setShowCountryDropdown(!showCountryDropdown)}
                            className={`flex items-center gap-1 px-3 py-2 rounded-lg text-xs font-bold transition-all whitespace-nowrap ${showCountryDropdown || countryFilter !== 'all'
                                ? 'bg-white text-gray-900 shadow-sm'
                                : 'text-gray-500 hover:text-gray-700'
                                }`}
                        >
                            <Globe size={13} />
                            {countryFilter !== 'all'
                                ? (() => { const info = COUNTRY_FLAGS[countryFilter]; return info ? `${info.flag} ${i18n.language === 'ko' ? info.name : info.nameEn}` : t('countrySetting', '국가 설정'); })()
                                : t('countrySetting', '국가 설정')
                            }
                            <ChevronDown size={11} className={`transition-transform duration-200 ${showCountryDropdown ? 'rotate-180' : ''}`} />
                        </button>
                    </div>
                </div>
                {/* Sort Dropdown */}
                <div className="flex items-center gap-1 flex-shrink-0 bg-gray-50 rounded-xl px-2.5 py-2">
                    <ArrowUpDown size={12} className="text-gray-400" />
                    <select
                        value={sortBy}
                        onChange={(e) => { setSortBy(e.target.value); setPage(1); }}
                        className="text-xs font-bold text-gray-600 bg-transparent border-none outline-none cursor-pointer"
                    >
                        <option value="latest">{t('sortBy.latest')}</option>
                        <option value="likes">{t('sortBy.likes')}</option>
                        <option value="comments">{t('sortBy.comments')}</option>
                        <option value="views">{t('sortBy.views')}</option>
                    </select>
                </div>
            </div>

            {/* 🔥 Trending Hashtags */}
            {trendingTags.length > 0 && (
                <div className="overflow-x-auto -mx-1 px-1 scrollbar-hide">
                    <div className="flex items-center gap-1.5 py-1 min-w-max">
                        <Flame size={14} className="text-orange-400 flex-shrink-0" />
                        <span className="text-[10px] font-bold text-gray-400 mr-1">{t('trendingTags')}</span>
                        {trendingTags.map(tag => (
                            <button
                                key={tag}
                                onClick={() => {
                                    if (searchQuery === tag) {
                                        setSearchQuery('');
                                    } else {
                                        setSearchQuery(tag);
                                    }
                                    setPage(1);
                                }}
                                className={`px-2.5 py-1 rounded-full text-[11px] font-bold transition-all whitespace-nowrap ${searchQuery === tag
                                    ? 'bg-gradient-to-r from-orange-400 to-red-400 text-white shadow-sm'
                                    : 'bg-orange-50 text-orange-600 border border-orange-200 hover:bg-orange-100'
                                    }`}
                            >
                                #{translateTag(tag)}
                            </button>
                        ))}
                    </div>
                </div>
            )}

            {/* 🌍 Country Filter Dropdown (toggled by 국가 설정 button) */}
            {showCountryDropdown && (
                <div className="overflow-x-auto -mx-1 px-1 scrollbar-hide animate-in slide-in-from-top-1">
                    <div className="flex items-center gap-1.5 py-1.5 min-w-max bg-gray-50/80 rounded-xl px-2">
                        <Globe size={14} className="text-gray-400 flex-shrink-0" />
                        <button
                            onClick={() => { setCountryFilter('all'); setPage(1); setShowCountryDropdown(false); }}
                            className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-bold border transition-all whitespace-nowrap ${countryFilter === 'all'
                                ? 'bg-gradient-to-r from-indigo-500 to-purple-500 text-white border-transparent shadow-sm'
                                : 'bg-white text-gray-600 border-gray-200 hover:border-gray-300 hover:bg-gray-50'
                                }`}
                        >
                            🌍 {t('allCountries')}
                        </button>
                        {Object.entries(COUNTRY_FLAGS).map(([code, info]) => (
                            <button
                                key={code}
                                onClick={() => { setCountryFilter(code); setPage(1); setShowCountryDropdown(false); }}
                                className={`flex items-center gap-1 px-3 py-1.5 rounded-full text-xs font-bold border transition-all whitespace-nowrap ${countryFilter === code
                                    ? 'bg-gradient-to-r from-indigo-500 to-purple-500 text-white border-transparent shadow-sm'
                                    : code === user?.country
                                        ? 'bg-indigo-50 text-indigo-700 border-indigo-200 hover:bg-indigo-100'
                                        : 'bg-white text-gray-600 border-gray-200 hover:border-gray-300 hover:bg-gray-50'
                                    }`}
                            >
                                <span>{info.flag}</span>
                                <span>{i18n.language === 'ko' ? info.name : info.nameEn}</span>
                                {code === user?.country && countryFilter !== code && (
                                    <span className="w-1.5 h-1.5 bg-indigo-400 rounded-full"></span>
                                )}
                            </button>
                        ))}
                    </div>
                </div>
            )}

            {/* Search Bar */}
            <div className="relative">
                <Search size={16} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-gray-400" />
                <input
                    type="text"
                    value={searchQuery}
                    onChange={(e) => { setSearchQuery(e.target.value); setPage(1); }}
                    placeholder={t('searchPlaceholder')}
                    className="w-full pl-10 pr-4 py-2.5 border border-gray-200 rounded-xl text-sm focus:ring-2 focus:ring-indigo-500/30 focus:border-indigo-400 outline-none bg-white"
                />
            </div>

            {/* Label Filter */}
            {
                availableLabels.length > 0 && (
                    <div className="overflow-x-auto scrollbar-hide">
                        <div className="flex items-center gap-2 min-w-max py-0.5">
                            <Filter size={14} className="text-gray-400" />
                            <button
                                onClick={() => { setFilterLabel(''); setPage(1); }}
                                className={`px-3 py-1.5 rounded-lg text-xs font-bold border transition-colors ${filterLabel === '' ? config.labelActiveColor : config.labelColor}`}
                            >
                                {t('all')}
                            </button>
                            {availableLabels.map(lbl => (
                                <button
                                    key={lbl}
                                    onClick={() => { setFilterLabel(lbl); setPage(1); }}
                                    className={`px-3 py-1.5 rounded-lg text-xs font-bold border transition-colors ${filterLabel === lbl ? config.labelActiveColor : config.labelColor}`}
                                >
                                    {translateLabel(lbl)}
                                </button>
                            ))}
                        </div>
                    </div>
                )
            }

            {/* 🔥 Trending Hashtags */}
            {
                trendingTags.length > 0 && (
                    <div className="relative overflow-hidden bg-gradient-to-r from-orange-50 via-amber-50 to-yellow-50 dark:from-orange-950/40 dark:via-amber-950/30 dark:to-yellow-950/20 rounded-2xl border border-orange-100 dark:border-orange-800/40 p-4">
                        <div className="absolute inset-0 opacity-5">
                            <div className="absolute -right-8 -top-8 w-32 h-32 bg-orange-400 rounded-full blur-2xl"></div>
                            <div className="absolute -left-4 -bottom-4 w-20 h-20 bg-yellow-400 rounded-full blur-xl"></div>
                        </div>
                        <div className="relative z-10">
                            <div className="flex items-center gap-2 mb-3">
                                <div className="w-6 h-6 bg-gradient-to-br from-orange-500 to-red-500 rounded-lg flex items-center justify-center">
                                    <TrendingUp size={13} className="text-white" />
                                </div>
                                <span className="text-sm font-extrabold text-gray-800 dark:text-gray-100">{t('trending')}</span>
                                <span className="text-[10px] text-orange-500 dark:text-orange-400 font-bold bg-orange-100 dark:bg-orange-900/50 px-2 py-0.5 rounded-full">LIVE</span>
                            </div>
                            <div className="flex flex-wrap gap-2">
                                {trendingTags.map((tag, i) => (
                                    <button
                                        key={tag}
                                        onClick={() => { setSearchQuery(tag); setPage(1); }}
                                        className="group flex items-center gap-1 px-3 py-1.5 bg-white/80 dark:bg-white/10 backdrop-blur border border-orange-100 dark:border-orange-800/40 rounded-full text-xs font-bold text-gray-700 dark:text-gray-200 hover:bg-gradient-to-r hover:from-orange-500 hover:to-red-500 hover:text-white hover:border-transparent transition-all duration-200 shadow-sm hover:shadow-md hover:scale-105"
                                    >
                                        <Hash size={11} className="text-orange-400 group-hover:text-white/80" />
                                        {translateTag(tag)}
                                        {i === 0 && <Flame size={11} className="text-orange-500 group-hover:text-yellow-200 ml-0.5" />}
                                    </button>
                                ))}
                            </div>
                        </div>
                    </div>
                )
            }

            {/* Popular Posts Section */}
            {
                popularPosts.length > 0 && (
                    <div className="bg-white dark:bg-gray-900 rounded-2xl border border-gray-100 dark:border-gray-800 shadow-sm overflow-hidden">
                        <div className="px-5 py-3 border-b border-gray-50 dark:border-gray-800 flex items-center gap-2">
                            <div className="w-7 h-7 bg-gradient-to-br from-amber-400 to-orange-500 rounded-lg flex items-center justify-center">
                                <Flame size={15} className="text-white" />
                            </div>
                            <h2 className="font-extrabold text-gray-900 dark:text-gray-100 text-sm">{t('popularRanking')}</h2>
                            <span className="text-[10px] text-gray-400 dark:text-gray-500 font-medium ml-auto">{t('last7days')}</span>
                        </div>
                        <div className="relative group">
                            {/* Left Arrow */}
                            <button
                                onClick={() => { const el = popularScrollRef.current; if (el) el.scrollBy({ left: -280, behavior: 'smooth' }); }}
                                className="absolute left-2 top-1/2 -translate-y-1/2 z-10 w-8 h-8 bg-black/40 hover:bg-black/60 text-white rounded-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity shadow-lg backdrop-blur-sm"
                            >
                                <ChevronLeft size={18} />
                            </button>
                            {/* Right Arrow */}
                            <button
                                onClick={() => { const el = popularScrollRef.current; if (el) el.scrollBy({ left: 280, behavior: 'smooth' }); }}
                                className="absolute right-2 top-1/2 -translate-y-1/2 z-10 w-8 h-8 bg-black/40 hover:bg-black/60 text-white rounded-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity shadow-lg backdrop-blur-sm"
                            >
                                <ChevronRight size={18} />
                            </button>
                            <div
                                ref={popularScrollRef}
                                className="flex gap-3 overflow-x-auto p-4 scroll-smooth cursor-grab active:cursor-grabbing select-none"
                                style={{ scrollbarWidth: 'none', msOverflowStyle: 'none', WebkitOverflowScrolling: 'touch' }}
                                onMouseDown={(e) => {
                                    setIsDragging(true);
                                    hasDraggedRef.current = false;
                                    setDragStartX(e.clientX);
                                    setScrollStartX(popularScrollRef.current?.scrollLeft || 0);
                                }}
                                onMouseMove={(e) => {
                                    if (!isDragging) return;
                                    e.preventDefault();
                                    const dx = e.clientX - dragStartX;
                                    if (Math.abs(dx) > 5) hasDraggedRef.current = true;
                                    if (popularScrollRef.current) {
                                        popularScrollRef.current.scrollLeft = scrollStartX - dx;
                                    }
                                }}
                                onMouseUp={() => setIsDragging(false)}
                                onMouseLeave={() => setIsDragging(false)}
                            >
                                {popularPosts.map((pp, idx) => {
                                    const rankColors = [
                                        'border-amber-300 dark:border-amber-700 bg-gradient-to-br from-amber-50 to-yellow-50 dark:from-amber-950/50 dark:to-yellow-950/30 shadow-amber-100 dark:shadow-none',
                                        'border-gray-300 dark:border-gray-600 bg-gradient-to-br from-gray-50 to-slate-50 dark:from-gray-800/80 dark:to-slate-800/60 shadow-gray-100 dark:shadow-none',
                                        'border-orange-200 dark:border-orange-800 bg-gradient-to-br from-orange-50 to-amber-50 dark:from-orange-950/40 dark:to-amber-950/30 shadow-orange-100 dark:shadow-none',
                                    ];
                                    const medals = ['🏆', '🥈', '🥉'];
                                    const rankStyle = idx < 3 ? rankColors[idx] : 'border-gray-100 dark:border-gray-700 bg-white dark:bg-gray-800';
                                    const engagementScore = (pp.like_count || 0) * 3 + (pp.comment_count || 0) * 2 + (pp.view_count || 0);
                                    return (
                                        <div
                                            key={pp.id}
                                            onClick={() => { if (!hasDraggedRef.current) goToPopularPost(pp.id); }}
                                            className={`flex-shrink-0 w-60 sm:w-72 rounded-xl border-2 p-4 cursor-pointer hover:shadow-lg transition-all duration-200 group/card hover:-translate-y-0.5 ${rankStyle}`}
                                        >
                                            <div className="flex items-center justify-between mb-2.5">
                                                <div className="flex items-center gap-2">
                                                    <span className="text-lg">{medals[idx] || `#${idx + 1}`}</span>
                                                    {idx < 3 && <span className="text-[10px] font-extrabold text-amber-600 bg-amber-100 px-1.5 py-0.5 rounded">{idx === 0 ? t('rank1') : idx === 1 ? t('rank2') : t('rank3')}</span>}
                                                </div>
                                                {pp.label && (
                                                    <span className={`text-[10px] font-bold px-1.5 py-0.5 rounded border ${config.labelColor}`}>{pp.label}</span>
                                                )}
                                            </div>
                                            <h4 className="text-sm font-bold text-gray-800 dark:text-gray-100 line-clamp-2 group-hover/card:text-indigo-600 dark:group-hover/card:text-indigo-400 transition-colors leading-tight mb-2">{pp.title}</h4>
                                            <div className="flex items-center justify-between text-[10px] text-gray-400 dark:text-gray-500">
                                                <span className="truncate font-medium">{getDisplayName(pp, countryToLang(user?.country))}</span>
                                                <div className="flex items-center gap-2.5">
                                                    <span className="flex items-center gap-0.5">
                                                        <Heart size={10} className={pp.is_liked ? 'text-red-500 fill-red-500' : ''} />
                                                        {pp.like_count}
                                                    </span>
                                                    <span className="flex items-center gap-0.5">
                                                        <MessageCircle size={10} />
                                                        {pp.comment_count || 0}
                                                    </span>
                                                    <span className="flex items-center gap-0.5">
                                                        <Eye size={10} />
                                                        {pp.view_count}
                                                    </span>
                                                </div>
                                            </div>
                                            {/* Engagement bar */}
                                            <div className="mt-2.5 flex items-center gap-2">
                                                <div className="flex-1 h-1 bg-gray-100 dark:bg-gray-700 rounded-full overflow-hidden">
                                                    <div className={`h-full rounded-full ${idx === 0 ? 'bg-gradient-to-r from-amber-400 to-orange-500' : idx === 1 ? 'bg-gradient-to-r from-gray-400 to-gray-500' : idx === 2 ? 'bg-gradient-to-r from-orange-300 to-amber-400' : 'bg-gray-300'}`}
                                                        style={{ width: `${Math.min(100, (engagementScore / Math.max(1, ((popularPosts[0]?.like_count || 0) * 3 + (popularPosts[0]?.comment_count || 0) * 2 + (popularPosts[0]?.view_count || 0)))) * 100)}%` }}
                                                    ></div>
                                                </div>
                                                <span className="text-[9px] font-bold text-gray-400 flex items-center gap-0.5"><Zap size={8} />{engagementScore}</span>
                                            </div>
                                        </div>
                                    );
                                })}
                            </div>
                        </div>
                    </div>
                )
            }

            {/* Write Form Modal */}
            {
                showWriteForm && (
                    <div className="fixed inset-0 z-[9999] flex items-center justify-center p-4"
                        onClick={(e) => { if (e.target === e.currentTarget) { setShowWriteForm(false); setNewPhotos([]); setPhotoPreviewUrls([]); } }}>
                        {/* Backdrop */}
                        <div className="absolute inset-0 bg-black/50 backdrop-blur-sm" />
                        {/* Modal Content */}
                        <div className={`relative w-full max-w-2xl max-h-[90vh] overflow-y-auto bg-white rounded-2xl shadow-2xl border ${config.accentBorder}`}
                            style={{ scrollbarWidth: 'thin' }}>
                            {/* Modal Header */}
                            <div className={`sticky top-0 z-10 flex justify-between items-center px-6 py-4 border-b border-gray-100 bg-gradient-to-r ${config.gradient} text-white rounded-t-2xl`}>
                                <h3 className="font-bold flex items-center gap-2 text-lg">
                                    <PenLine size={20} />
                                    {t('writePost')}
                                </h3>
                                <button onClick={() => { setShowWriteForm(false); setNewPhotos([]); setPhotoPreviewUrls([]); }}
                                    className="p-1.5 hover:bg-white/20 rounded-lg transition-colors">
                                    <X size={20} />
                                </button>
                            </div>
                            {/* Modal Body */}
                            <div className="p-6">
                                <form onSubmit={handleSubmitPost} className="space-y-4">
                                    {/* Admin Notice Type Selector */}
                                    {isAdmin && (
                                        <div className="mb-1">
                                            <label className="block text-xs font-bold text-gray-500 mb-2 flex items-center gap-1">
                                                <Megaphone size={12} />
                                                {t('noticeType')}
                                            </label>
                                            <div className="flex gap-2">
                                                {[{ v: 0, l: t('noticeNormal'), icon: null, color: 'bg-white text-gray-600 border-gray-200' },
                                                { v: 1, l: t('noticeGeneral'), icon: <Megaphone size={11} />, color: 'bg-blue-50 text-blue-700 border-blue-200' },
                                                { v: 2, l: t('noticeRequired'), icon: <Pin size={11} />, color: 'bg-red-50 text-red-700 border-red-200' }
                                                ].map(opt => (
                                                    <button
                                                        key={opt.v}
                                                        type="button"
                                                        onClick={() => setNewPost(p => ({ ...p, is_notice: opt.v }))}
                                                        className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-bold border transition-all ${newPost.is_notice === opt.v
                                                            ? (opt.v === 2 ? 'bg-red-500 text-white border-red-500 shadow-sm' : opt.v === 1 ? 'bg-blue-500 text-white border-blue-500 shadow-sm' : 'bg-gray-800 text-white border-gray-800 shadow-sm')
                                                            : opt.color + ' hover:border-gray-300'
                                                            }`}
                                                    >
                                                        {opt.icon}
                                                        {opt.l}
                                                    </button>
                                                ))}
                                            </div>
                                        </div>
                                    )}

                                    {/* Label Selection */}
                                    <div>
                                        <label className="block text-xs font-bold text-gray-500 mb-2 flex items-center gap-1">
                                            <Tag size={12} />
                                            {t('selectLabel')}
                                        </label>
                                        <div className="flex flex-wrap gap-2">
                                            {DEFAULT_LABELS.map(lbl => (
                                                <button
                                                    key={lbl}
                                                    type="button"
                                                    onClick={() => setNewPost(p => ({ ...p, label: p.label === lbl ? '' : lbl }))}
                                                    className={`px-3 py-1.5 rounded-lg text-xs font-bold border transition-all ${newPost.label === lbl
                                                        ? config.labelActiveColor + ' shadow-sm scale-105'
                                                        : 'bg-white text-gray-600 border-gray-200 hover:border-gray-300'
                                                        }`}
                                                >
                                                    {lbl}
                                                </button>
                                            ))}
                                        </div>
                                    </div>
                                    <input
                                        type="text"
                                        placeholder={t('titlePlaceholder')}
                                        value={newPost.title}
                                        onChange={e => setNewPost(p => ({ ...p, title: e.target.value }))}
                                        className="w-full px-4 py-3 bg-white border border-gray-200 rounded-xl focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 outline-none font-bold text-sm"
                                    />
                                    {/* Content */}
                                    <div className="relative">
                                        <textarea
                                            ref={contentTextareaRef}
                                            placeholder={t('contentPlaceholder')}
                                            value={newPost.content}
                                            onChange={e => {
                                                const val = e.target.value;
                                                setNewPost(p => ({ ...p, content: val }));
                                                // @mention detection
                                                const cursorPos = e.target.selectionStart;
                                                const textBefore = val.substring(0, cursorPos);
                                                const mentionMatch = textBefore.match(/@([\w\uAC00-\uD7A3]*)$/);
                                                if (mentionMatch) {
                                                    const q = mentionMatch[1];
                                                    setMentionQuery(q);
                                                    if (q.length >= 1) {
                                                        fetch(`/api/users/search_users.php?q=${encodeURIComponent(q)}`, { credentials: 'include' })
                                                            .then(r => r.json())
                                                            .then(data => {
                                                                setMentionResults(data.users || []);
                                                                setShowMentionDropdown((data.users || []).length > 0);
                                                            });
                                                    }
                                                } else {
                                                    setShowMentionDropdown(false);
                                                }
                                            }}
                                            rows={6}
                                            className="w-full px-4 py-3 bg-white border border-gray-200 rounded-xl focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 outline-none font-medium resize-none"
                                        />
                                        {/* @Mention Dropdown */}
                                        {
                                            showMentionDropdown && mentionResults.length > 0 && (
                                                <div className="absolute left-0 right-0 bottom-full mb-1 bg-white border border-gray-200 rounded-xl shadow-xl z-50 max-h-48 overflow-y-auto">
                                                    {mentionResults.map(mu => (
                                                        <button
                                                            key={mu.id}
                                                            type="button"
                                                            className="w-full flex items-center gap-3 px-4 py-2.5 hover:bg-indigo-50 transition-colors text-left"
                                                            onClick={() => {
                                                                const content = newPost.content;
                                                                const before = content.substring(0, mentionCursorPos);
                                                                const after = content.substring(mentionCursorPos);
                                                                const mentionStart = before.lastIndexOf('@');
                                                                const newContent = before.substring(0, mentionStart) + `@${mu.name} ` + after;
                                                                setNewPost(p => ({ ...p, content: newContent }));
                                                                setShowMentionDropdown(false);
                                                                setMentionResults([]);
                                                                setTimeout(() => contentTextareaRef.current?.focus(), 50);
                                                            }}
                                                        >
                                                            <div className="w-7 h-7 bg-gradient-to-br from-gray-200 to-gray-300 rounded-lg flex items-center justify-center flex-shrink-0 overflow-hidden">
                                                                {mu.profile_image ? (
                                                                    <img src={mu.profile_image} alt="" className="w-full h-full object-cover" />
                                                                ) : (
                                                                    <User size={14} className="text-gray-500" />
                                                                )}
                                                            </div>
                                                            <div>
                                                                <span className="text-sm font-bold text-gray-900">{mu.name}</span>
                                                                <span className="ml-2 text-[10px] text-gray-400 font-medium">{mu.role === 'seller' ? '' : mu.role === 'host' ? 'Host' : mu.role}</span>
                                                            </div>
                                                        </button>
                                                    ))}
                                                </div>
                                            )
                                        }
                                    </div>

                                    {/* Keywords Input */}
                                    <div>
                                        <label className="block text-xs font-bold text-gray-500 mb-2 flex items-center gap-1">
                                            <Hash size={12} />
                                            {t('keywordsLabel')}
                                        </label>
                                        <input
                                            type="text"
                                            placeholder={t('keywordsPlaceholder')}
                                            value={newPost.keywords}
                                            onChange={e => setNewPost(p => ({ ...p, keywords: e.target.value }))}
                                            className="w-full px-4 py-2.5 bg-white border border-gray-200 rounded-xl focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 outline-none text-sm"
                                        />
                                        <p className="text-[10px] text-gray-400 mt-1">{t('keywordsHint')}</p>
                                    </div>

                                    {/* Poll Options (shown when '투표' label is selected) */}
                                    {(newPost.label === t('labels.poll') || showPollForm) && (
                                        <div className="bg-gradient-to-br from-indigo-50 to-violet-50 rounded-xl p-4 border border-indigo-100">
                                            <label className="block text-xs font-bold text-indigo-600 mb-3 flex items-center gap-1">
                                                <BarChart2 size={12} />
                                                {t('pollTitle')}
                                            </label>
                                            <div className="space-y-2">
                                                {newPollOptions.map((opt, idx) => (
                                                    <div key={idx} className="flex items-center gap-2">
                                                        <span className="text-xs font-bold text-indigo-400 w-5">{idx + 1}</span>
                                                        <input
                                                            type="text"
                                                            placeholder={t('pollOptionPlaceholder', { index: idx + 1 })}
                                                            value={opt}
                                                            onChange={(e) => {
                                                                const updated = [...newPollOptions];
                                                                updated[idx] = e.target.value;
                                                                setNewPollOptions(updated);
                                                            }}
                                                            className="flex-1 px-3 py-2 bg-white border border-indigo-200 rounded-lg focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 outline-none text-sm"
                                                        />
                                                        {newPollOptions.length > 2 && (
                                                            <button
                                                                type="button"
                                                                onClick={() => setNewPollOptions(prev => prev.filter((_, i) => i !== idx))}
                                                                className="p-1.5 text-red-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                                                            >
                                                                <X size={14} />
                                                            </button>
                                                        )}
                                                    </div>
                                                ))}
                                            </div>
                                            {newPollOptions.length < 6 && (
                                                <button
                                                    type="button"
                                                    onClick={() => setNewPollOptions(prev => [...prev, ''])}
                                                    className="mt-2 text-xs font-bold text-indigo-500 hover:text-indigo-700 flex items-center gap-1 transition-colors"
                                                >
                                                    + {t('pollAddOption')}
                                                </button>
                                            )}
                                            <div className="mt-3 flex items-center gap-2">
                                                <label className="text-xs font-bold text-gray-500">{t('pollEndDate')}:</label>
                                                <input
                                                    type="datetime-local"
                                                    value={pollEndDate}
                                                    onChange={(e) => setPollEndDate(e.target.value)}
                                                    className="px-2 py-1 text-xs border border-gray-200 rounded-lg focus:ring-2 focus:ring-indigo-500/20 outline-none"
                                                />
                                            </div>
                                        </div>
                                    )}

                                    {/* Photo Upload */}
                                    <div>
                                        <label className="block text-xs font-bold text-gray-500 mb-2 flex items-center gap-1">
                                            <ImagePlus size={12} />
                                            {t('maxImages', { count: 10 })}
                                        </label>
                                        <div className="grid grid-cols-5 gap-2">
                                            {photoPreviewUrls.map((url, idx) => (
                                                <div key={idx} className="relative aspect-square rounded-xl overflow-hidden border border-gray-200 group">
                                                    <img src={url} alt="" className="w-full h-full object-cover" />
                                                    {/* Order badge */}
                                                    <span className="absolute top-1 left-1 w-5 h-5 bg-black/60 text-white text-[10px] font-bold rounded-md flex items-center justify-center">
                                                        {idx + 1}
                                                    </span>
                                                    {/* Delete button */}
                                                    <button
                                                        type="button"
                                                        onClick={() => removePhoto(idx)}
                                                        className="absolute top-1 right-1 p-1 bg-red-500 text-white rounded-lg opacity-0 group-hover:opacity-100 transition-opacity shadow"
                                                    >
                                                        <X size={10} />
                                                    </button>
                                                    {/* Reorder buttons */}
                                                    {newPhotos.length > 1 && (
                                                        <div className="absolute bottom-1 left-1/2 -translate-x-1/2 flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                                            {idx > 0 && (
                                                                <button
                                                                    type="button"
                                                                    onClick={() => movePhoto(idx, 'left')}
                                                                    className="p-1 bg-black/60 text-white rounded-md hover:bg-black/80 transition-colors"
                                                                >
                                                                    <ArrowLeft size={10} />
                                                                </button>
                                                            )}
                                                            {idx < newPhotos.length - 1 && (
                                                                <button
                                                                    type="button"
                                                                    onClick={() => movePhoto(idx, 'right')}
                                                                    className="p-1 bg-black/60 text-white rounded-md hover:bg-black/80 transition-colors"
                                                                >
                                                                    <ArrowRight size={10} />
                                                                </button>
                                                            )}
                                                        </div>
                                                    )}
                                                </div>
                                            ))}
                                            {newPhotos.length < 10 && (
                                                <button
                                                    type="button"
                                                    onClick={() => photoInputRef.current?.click()}
                                                    className="aspect-square rounded-xl border-2 border-dashed border-gray-300 flex flex-col items-center justify-center text-gray-400 hover:border-indigo-400 hover:text-indigo-500 transition-colors"
                                                >
                                                    <ImagePlus size={20} />
                                                    <span className="text-[10px] mt-1 font-medium">{newPhotos.length}/10</span>
                                                </button>
                                            )}
                                        </div>
                                        <input
                                            type="file"
                                            ref={photoInputRef}
                                            onChange={handlePhotoSelect}
                                            className="hidden"
                                            accept="image/*"
                                            multiple
                                        />
                                    </div>

                                    {/* Action Buttons - sticky at bottom */}
                                    <div className="flex justify-end gap-3 pt-2">
                                        <button
                                            type="button"
                                            onClick={() => { setShowWriteForm(false); setNewPhotos([]); setPhotoPreviewUrls([]); }}
                                            className="px-5 py-2.5 text-gray-600 bg-white border border-gray-200 rounded-xl hover:bg-gray-50 font-medium text-sm transition-colors"
                                        >
                                            {t('cancel')}
                                        </button>
                                        <button
                                            type="submit"
                                            disabled={submitting}
                                            className={`px-6 py-2.5 ${config.buttonBg} text-white rounded-xl font-bold text-sm shadow-lg transition-all flex items-center gap-2 disabled:opacity-50`}
                                        >
                                            <Send size={14} />
                                            {submitting ? t('submitting') : t('publish')}
                                        </button>
                                    </div>
                                </form>
                            </div>
                        </div>
                    </div>
                )
            }

            {/* Ad Section - Community Top */}
            <div className="mb-4">
                <div className="flex items-center gap-3 mb-3">
                    <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">{t('sponsor')}</span>
                    <div className="flex-1 h-px bg-gray-200" />
                </div>
                <AdSlot slotId={`${type}_community_top`} format="banner" />
            </div>

            {/* Access Denied */}
            {
                accessDenied ? (
                    <div className="bg-white rounded-2xl border border-red-100 p-12 text-center shadow-sm">
                        <div className="w-16 h-16 bg-red-50 rounded-2xl flex items-center justify-center mx-auto mb-5">
                            <ShieldAlert size={32} className="text-red-400" />
                        </div>
                        <h3 className="text-lg font-bold text-gray-900 mb-2">{t('accessDenied')}</h3>
                        <p className="text-gray-500 text-sm mb-6">{accessDenied.message}</p>
                        <button
                            onClick={() => navigate(-1)}
                            className="px-6 py-2.5 bg-gray-900 text-white rounded-xl font-bold text-sm hover:bg-gray-800 transition-colors inline-flex items-center gap-2"
                        >
                            <ChevronLeft size={16} />
                            {t('goBack')}
                        </button>
                    </div>
                ) : loading ? (
                    <div className="flex justify-center py-16">
                        <div className="w-8 h-8 border-3 border-indigo-200 border-t-indigo-600 rounded-full animate-spin"></div>
                    </div>
                ) : posts.length === 0 ? (
                    <div className="bg-white rounded-2xl border border-gray-100 p-16 text-center">
                        {feedMode === 'bookmarks' ? (
                            <>
                                <Bookmark className="mx-auto text-amber-300 mb-4" size={48} />
                                <p className="text-gray-500 font-medium">{t('noBookmarks')}</p>
                                <p className="text-gray-400 text-sm mt-1">{t('noBookmarksDesc')}</p>
                            </>
                        ) : (
                            <>
                                <MessageSquare className="mx-auto text-gray-300 mb-4" size={48} />
                                <p className="text-gray-500 font-medium">{t('noPostsYet')}</p>
                                <p className="text-gray-400 text-sm mt-1">{t('writeFirstPost')}</p>
                            </>
                        )}
                    </div>
                ) : (
                    <div className="space-y-3">
                        {/* Notice Strip */}
                        {notices.length > 0 && (
                            <div className="bg-white rounded-xl border border-gray-100 overflow-hidden shadow-sm">
                                {notices.filter(n => n.is_notice === 2).map(n => (
                                    <div key={n.id}
                                        onClick={() => { setExpandedPost(n.id); const el = document.getElementById(`post-${n.id}`); if (el) el.scrollIntoView({ behavior: 'smooth', block: 'center' }); else goToPopularPost(n.id); }}
                                        className="flex items-center gap-2 px-3 py-2 border-b border-gray-50 last:border-b-0 cursor-pointer hover:bg-red-50/50 transition-colors"
                                    >
                                        <Pin size={12} className="text-red-500 flex-shrink-0" />
                                        <span className="text-[10px] font-extrabold text-red-600 bg-red-50 px-1.5 py-0.5 rounded flex-shrink-0">{t('requiredNotice')}</span>
                                        <span className="text-xs font-bold text-gray-800 truncate">{n.title}</span>
                                        <span className="text-[10px] text-gray-400 ml-auto flex-shrink-0">{new Date(n.created_at).toLocaleDateString('ko-KR')}</span>
                                    </div>
                                ))}
                                {notices.filter(n => n.is_notice === 1).length > 0 && (
                                    <>
                                        {(noticesExpanded ? notices.filter(n => n.is_notice === 1) : notices.filter(n => n.is_notice === 1).slice(0, 2)).map(n => (
                                            <div key={n.id}
                                                onClick={() => { setExpandedPost(n.id); const el = document.getElementById(`post-${n.id}`); if (el) el.scrollIntoView({ behavior: 'smooth', block: 'center' }); else goToPopularPost(n.id); }}
                                                className="flex items-center gap-2 px-3 py-2 border-b border-gray-50 last:border-b-0 cursor-pointer hover:bg-blue-50/50 transition-colors"
                                            >
                                                <Megaphone size={12} className="text-blue-500 flex-shrink-0" />
                                                <span className="text-[10px] font-bold text-blue-600 bg-blue-50 px-1.5 py-0.5 rounded flex-shrink-0">{t('notice')}</span>
                                                <span className="text-xs text-gray-700 truncate">{n.title}</span>
                                                <span className="text-[10px] text-gray-400 ml-auto flex-shrink-0">{new Date(n.created_at).toLocaleDateString('ko-KR')}</span>
                                            </div>
                                        ))}
                                        {notices.filter(n => n.is_notice === 1).length > 2 && (
                                            <button
                                                onClick={() => setNoticesExpanded(!noticesExpanded)}
                                                className="w-full flex items-center justify-center gap-1 py-1.5 text-[10px] font-bold text-gray-400 hover:text-gray-600 hover:bg-gray-50 transition-colors"
                                            >
                                                <ChevronDown size={12} className={`transition-transform ${noticesExpanded ? 'rotate-180' : ''}`} />
                                                {noticesExpanded ? t('foldNotices') : t('moreNotices', { count: notices.filter(n => n.is_notice === 1).length - 2 })}
                                            </button>
                                        )}
                                    </>
                                )}
                            </div>
                        )}
                        {posts.map((post, postIdx) => {
                            const roleBadge = getRoleBadge(post.user_role);
                            const isExpanded = expandedPost === post.id;
                            const hasPhotos = post.photos && post.photos.length > 0;
                            const postBadge = getPostBadge(post);

                            const isHighlighted = highlightedPostId === post.id;

                            return (
                                <React.Fragment key={post.id}>
                                    {/* Repeating feed ad: first at index 2, then every 5 posts */}
                                    {(postIdx === 2 || (postIdx > 2 && (postIdx - 2) % 5 === 0)) && (
                                        <AdSlot slotId={`${type}_community_feed`} format="native" className="my-3" />
                                    )}
                                    <div
                                        id={`post-${post.id}`}
                                        ref={isHighlighted ? highlightRef : undefined}
                                        className={`bg-white rounded-2xl border shadow-sm hover:shadow-md transition-all ${isHighlighted
                                            ? 'border-amber-400 ring-2 ring-amber-300 animate-pulse shadow-amber-100 shadow-lg'
                                            : 'border-gray-100'
                                            }`}
                                    >
                                        <div
                                            className="p-5 cursor-pointer relative"
                                            onClick={(e) => { handleDoubleTap(e, post.id); handleTogglePost(post.id); }}
                                        >
                                            {/* Double-tap heart animation */}
                                            {doubleTapHeart === post.id && (
                                                <div className="absolute inset-0 flex items-center justify-center z-20 pointer-events-none">
                                                    <Heart size={64} className="text-red-500 fill-red-500" style={{ animation: 'heartBurst 0.8s ease-out forwards' }} />
                                                </div>
                                            )}
                                            {/* NEW / HOT Badge */}
                                            {postBadge && (
                                                <div className="absolute top-3 right-3 z-10">
                                                    {postBadge === 'hot' ? (
                                                        <span className="inline-flex items-center gap-1 px-2 py-0.5 bg-gradient-to-r from-red-500 to-orange-500 text-white text-[10px] font-extrabold rounded-full shadow-sm">
                                                            <Flame size={10} /> HOT
                                                        </span>
                                                    ) : (
                                                        <span className="inline-flex items-center gap-1 px-2 py-0.5 bg-gradient-to-r from-emerald-500 to-teal-500 text-white text-[10px] font-extrabold rounded-full shadow-sm">
                                                            <Zap size={10} /> NEW
                                                        </span>
                                                    )}
                                                </div>
                                            )}
                                            <div className="flex items-start gap-3">
                                                <div
                                                    className="w-10 h-10 bg-gradient-to-br from-gray-200 to-gray-300 rounded-xl flex items-center justify-center text-white font-bold text-sm flex-shrink-0 overflow-hidden cursor-pointer hover:ring-2 hover:ring-indigo-300 transition-all"
                                                    onClick={(e) => openUserProfile(e, post.user_id)}
                                                >
                                                    {post.profile_image ? (
                                                        <img src={post.profile_image} alt="" className="w-full h-full object-cover" />
                                                    ) : (
                                                        <User size={18} className="text-gray-500" />
                                                    )}
                                                </div>
                                                <div className="flex-1 min-w-0">
                                                    <div className="flex items-center gap-2 mb-1 flex-wrap">
                                                        <span
                                                            className="font-bold text-gray-900 text-sm cursor-pointer hover:text-indigo-600 transition-colors"
                                                            onClick={(e) => openUserProfile(e, post.user_id)}
                                                        >{getDisplayName(post, countryToLang(user?.country))}</span>
                                                        {type === 'general' && (() => {
                                                            const RoleBadgeIcon = roleBadge.icon;
                                                            return (
                                                                <span className={`text-[10px] font-bold px-1.5 py-0.5 rounded inline-flex items-center gap-0.5 ${roleBadge.color}`}>
                                                                    {RoleBadgeIcon && <RoleBadgeIcon size={9} />}
                                                                    {roleBadge.label}
                                                                </span>
                                                            );
                                                        })()}
                                                        {/* Activity Level Badge */}
                                                        {(() => {
                                                            const actBadge = getActivityBadge(post.activity_level || 1);
                                                            return (
                                                                <span className={`text-[10px] font-bold ${actBadge.color}`} title={t('activityLevel', { level: actBadge.label })}>
                                                                    {actBadge.emoji}{actBadge.label}
                                                                </span>
                                                            );
                                                        })()}
                                                        {post.label && (
                                                            <span className={`text-[10px] font-bold px-1.5 py-0.5 rounded border ${config.labelColor}`}>
                                                                {translateLabel(post.label)}
                                                            </span>
                                                        )}
                                                        <span className="text-xs text-gray-400 flex items-center gap-1">
                                                            <Clock size={10} />
                                                            {formatDate(post.created_at)}
                                                        </span>
                                                        {hasPhotos && (
                                                            <span className="text-xs text-gray-400 flex items-center gap-1">
                                                                <ImagePlus size={10} />
                                                                {post.photos.length}
                                                            </span>
                                                        )}
                                                    </div>
                                                    <h3 className="font-bold text-gray-900 truncate">
                                                        <TranslatedText text={post.title} sourceLang={post.original_lang} showBadge={false} />
                                                        {commentCounts[post.id] > 0 && (
                                                            <span className="ml-2 text-xs font-medium text-gray-400 inline-flex items-center gap-0.5">
                                                                <MessageCircle size={11} />
                                                                {commentCounts[post.id]}
                                                            </span>
                                                        )}
                                                    </h3>
                                                    {/* Cover Image for non-expanded cards */}
                                                    {!isExpanded && hasPhotos && (
                                                        <div className="mt-2 rounded-xl overflow-hidden h-36 bg-gray-100">
                                                            <img src={post.photos[0].image_url} alt="" className="w-full h-full object-cover hover:scale-105 transition-transform duration-300" />
                                                        </div>
                                                    )}
                                                    {!isExpanded && (
                                                        <p className="text-sm text-gray-500 mt-2 line-clamp-2"><TranslatedText text={post.content} sourceLang={post.original_lang} showBadge={false} /></p>
                                                    )}
                                                    {/* Keyword Chips */}
                                                    {post.keywords && post.keywords.length > 0 && (
                                                        <div className="flex flex-wrap gap-1 mt-2">
                                                            {post.keywords.map((kw, ki) => (
                                                                <button
                                                                    key={ki}
                                                                    onClick={(e) => { e.stopPropagation(); setSearchQuery(kw); setPage(1); }}
                                                                    className="text-[10px] font-bold px-2 py-0.5 rounded-full bg-indigo-50 text-indigo-600 border border-indigo-100 hover:bg-indigo-100 transition-colors cursor-pointer"
                                                                >
                                                                    #{kw}
                                                                </button>
                                                            ))}
                                                        </div>
                                                    )}
                                                    {/* Like / View count / Share / Bookmark bar */}
                                                    <div className="flex items-center gap-3 mt-3">
                                                        <button
                                                            onClick={(e) => handleToggleLike(e, post.id)}
                                                            className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full text-sm font-medium transition-all duration-200 ${post.is_liked ? 'text-red-500 bg-red-50 scale-105' : 'text-gray-400 hover:text-red-400 hover:bg-red-50/50'}`}
                                                        >
                                                            <Heart size={18} className={`transition-transform ${post.is_liked ? 'fill-red-500 scale-110' : ''}`} />
                                                            <span className="tabular-nums">{post.like_count || 0}</span>
                                                        </button>
                                                        <span className="flex items-center gap-1.5 text-sm text-gray-400">
                                                            <MessageCircle size={16} />
                                                            <span className="tabular-nums">{commentCounts[post.id] || 0}</span>
                                                        </span>
                                                        <span className="flex items-center gap-1.5 text-sm text-gray-400">
                                                            <Eye size={16} />
                                                            <span className="tabular-nums">{post.view_count || 0}</span>
                                                        </span>
                                                        <div className="relative" ref={shareMenuPostId === post.id ? shareMenuRef : undefined}>
                                                            <button
                                                                onClick={(e) => {
                                                                    e.stopPropagation();
                                                                    const shareUrl = `${window.location.origin}/api/community/share_preview.php?post=${post.id}&type=${type}`;
                                                                    if (navigator.share && /Android|iPhone|iPad/i.test(navigator.userAgent)) {
                                                                        const shareText = `[SpaceMatch ${config.title}] ${post.title}`;
                                                                        navigator.share({ title: shareText, text: `${shareText}\n${post.content?.substring(0, 100)}...`, url: shareUrl }).catch(() => { });
                                                                        // Increment share count
                                                                        fetch(`${API_BASE}/community_posts.php?type=${type}&increment_share=${post.id}`, { credentials: 'include' }).catch(() => { });
                                                                    } else {
                                                                        setShareMenuPostId(shareMenuPostId === post.id ? null : post.id);
                                                                    }
                                                                }}
                                                                className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full text-sm font-medium transition-all ${shareMenuPostId === post.id ? 'text-indigo-500 bg-indigo-50' : 'text-gray-400 hover:text-indigo-500 hover:bg-indigo-50/50'}`}
                                                                title={t('shareTitle')}
                                                            >
                                                                <Share2 size={16} />
                                                                <span>{t('share')}{post.share_count > 0 ? ` ${post.share_count}` : ''}</span>
                                                            </button>

                                                            {/* Share Dropdown */}
                                                            {shareMenuPostId === post.id && (
                                                                <div
                                                                    className="absolute top-full left-0 mt-2 w-56 bg-white rounded-xl shadow-xl border border-gray-100 overflow-hidden z-50"
                                                                    style={{ animation: 'fadeInUp 0.2s ease-out' }}
                                                                    onClick={(e) => e.stopPropagation()}
                                                                >
                                                                    <div className="px-4 py-3 bg-gray-50 border-b border-gray-100">
                                                                        <p className="text-xs font-bold text-gray-700">{t('shareTitle')}</p>
                                                                    </div>
                                                                    <div className="p-1.5">
                                                                        {/* Copy Link */}
                                                                        <button
                                                                            onClick={async () => {
                                                                                const shareUrl = `${window.location.origin}/api/community/share_preview.php?post=${post.id}&type=${type}`;
                                                                                try {
                                                                                    await navigator.clipboard.writeText(shareUrl);
                                                                                } catch {
                                                                                    const ta = document.createElement('textarea');
                                                                                    ta.value = shareUrl;
                                                                                    document.body.appendChild(ta);
                                                                                    ta.select();
                                                                                    document.execCommand('copy');
                                                                                    document.body.removeChild(ta);
                                                                                }
                                                                                setCopiedPostId(post.id);
                                                                                setTimeout(() => setCopiedPostId(null), 2000);
                                                                                setTimeout(() => setShareMenuPostId(null), 1500);
                                                                                // Increment share count
                                                                                fetch(`${API_BASE}/community_posts.php?type=${type}&increment_share=${post.id}`, { credentials: 'include' }).catch(() => { });
                                                                            }}
                                                                            className="w-full flex items-center gap-3 px-3 py-2.5 rounded-lg hover:bg-indigo-50 transition-colors group"
                                                                        >
                                                                            {copiedPostId === post.id ? (
                                                                                <div className="w-8 h-8 flex items-center justify-center bg-emerald-100 rounded-lg">
                                                                                    <Check size={16} className="text-emerald-600" />
                                                                                </div>
                                                                            ) : (
                                                                                <div className="w-8 h-8 flex items-center justify-center bg-gray-100 group-hover:bg-indigo-100 rounded-lg transition-colors">
                                                                                    <Link2 size={16} className="text-gray-500 group-hover:text-indigo-600" />
                                                                                </div>
                                                                            )}
                                                                            <div className="text-left">
                                                                                <p className={`text-sm font-bold ${copiedPostId === post.id ? 'text-emerald-600' : 'text-gray-700'}`}>
                                                                                    {copiedPostId === post.id ? t('linkCopied') : t('copyLink')}
                                                                                </p>
                                                                                <p className="text-[10px] text-gray-400">{t('copyLinkDesc')}</p>
                                                                            </div>
                                                                        </button>

                                                                        {/* KakaoTalk */}
                                                                        <button
                                                                            onClick={() => {
                                                                                const shareUrl = `${window.location.origin}/api/community/share_preview.php?post=${post.id}&type=${type}`;
                                                                                const text = `[SpaceMatch ${t(config.titleKey)}] ${post.title}`;
                                                                                const kakaoUrl = `https://sharer.kakao.com/talk/friends/picker/link?url=${encodeURIComponent(shareUrl)}&text=${encodeURIComponent(text)}`;
                                                                                window.open(kakaoUrl, '_blank', 'width=500,height=600');
                                                                                setShareMenuPostId(null);
                                                                                // Increment share count
                                                                                fetch(`${API_BASE}/community_posts.php?type=${type}&increment_share=${post.id}`, { credentials: 'include' }).catch(() => { });
                                                                            }}
                                                                            className="w-full flex items-center gap-3 px-3 py-2.5 rounded-lg hover:bg-yellow-50 transition-colors group"
                                                                        >
                                                                            <div className="w-8 h-8 flex items-center justify-center bg-yellow-100 rounded-lg">
                                                                                <svg viewBox="0 0 24 24" width="16" height="16" fill="#3C1E1E">
                                                                                    <path d="M12 3C6.48 3 2 6.36 2 10.5c0 2.69 1.76 5.04 4.4 6.38l-1.12 4.12c-.1.36.3.65.6.44L10.5 18.5c.49.06 1 .1 1.5.1 5.52 0 10-3.36 10-7.5S17.52 3 12 3z" />
                                                                                </svg>
                                                                            </div>
                                                                            <div className="text-left">
                                                                                <p className="text-sm font-bold text-gray-700">{t('kakaoTalk')}</p>
                                                                                <p className="text-[10px] text-gray-400">{t('kakaoTalkDesc')}</p>
                                                                            </div>
                                                                        </button>

                                                                        {/* X (Twitter) Share */}
                                                                        <button
                                                                            onClick={() => {
                                                                                const shareUrl = `${window.location.origin}/api/community/share_preview.php?post=${post.id}&type=${type}`;
                                                                                const text = `${post.title} - SpaceMatch ${t(config.titleKey)}`;
                                                                                const hashtags = (post.keywords || []).slice(0, 3).join(',');
                                                                                const twitterUrl = `https://twitter.com/intent/tweet?text=${encodeURIComponent(text)}&url=${encodeURIComponent(shareUrl)}${hashtags ? `&hashtags=${encodeURIComponent(hashtags)}` : ''}`;
                                                                                window.open(twitterUrl, '_blank', 'width=550,height=420');
                                                                                setShareMenuPostId(null);
                                                                                fetch(`${API_BASE}/community_posts.php?type=${type}&increment_share=${post.id}`, { credentials: 'include' }).catch(() => { });
                                                                            }}
                                                                            className="w-full flex items-center gap-3 px-3 py-2.5 rounded-lg hover:bg-gray-100 transition-colors group"
                                                                        >
                                                                            <div className="w-8 h-8 flex items-center justify-center bg-gray-900 rounded-lg">
                                                                                <svg viewBox="0 0 24 24" width="14" height="14" fill="white">
                                                                                    <path d="M18.244 2.25h3.308l-7.227 8.26 8.502 11.24H16.17l-5.214-6.817L4.99 21.75H1.68l7.73-8.835L1.254 2.25H8.08l4.713 6.231zm-1.161 17.52h1.833L7.084 4.126H5.117z" />
                                                                                </svg>
                                                                            </div>
                                                                            <div className="text-left">
                                                                                <p className="text-sm font-bold text-gray-700">{t('xTwitter')}</p>
                                                                                <p className="text-[10px] text-gray-400">{t('xTwitterDesc')}</p>
                                                                            </div>
                                                                        </button>

                                                                        {/* Native Share (only if supported) */}
                                                                        {navigator.share && (
                                                                            <button
                                                                                onClick={async () => {
                                                                                    const shareUrl = `${window.location.origin}${window.location.pathname}?post=${post.id}`;
                                                                                    const shareText = `[SpaceMatch ${t(config.titleKey)}] ${post.title}`;
                                                                                    try {
                                                                                        await navigator.share({ title: shareText, text: `${shareText}\n${post.content?.substring(0, 100)}...`, url: shareUrl });
                                                                                    } catch (e) { }
                                                                                    setShareMenuPostId(null);
                                                                                }}
                                                                                className="w-full flex items-center gap-3 px-3 py-2.5 rounded-lg hover:bg-blue-50 transition-colors group"
                                                                            >
                                                                                <div className="w-8 h-8 flex items-center justify-center bg-blue-100 rounded-lg">
                                                                                    <ExternalLink size={16} className="text-blue-600" />
                                                                                </div>
                                                                                <div className="text-left">
                                                                                    <p className="text-sm font-bold text-gray-700">{t('shareOther')}</p>
                                                                                    <p className="text-[10px] text-gray-400">{t('shareOtherDesc')}</p>
                                                                                </div>
                                                                            </button>
                                                                        )}
                                                                    </div>
                                                                </div>
                                                            )}
                                                        </div>
                                                        {/* Bookmark button */}
                                                        <button
                                                            onClick={(e) => handleToggleBookmark(e, post.id)}
                                                            className={`ml-auto flex items-center gap-1 px-2 py-1.5 rounded-full text-sm font-medium transition-all duration-200 ${bookmarkedPosts.has(post.id) ? 'text-amber-500 bg-amber-50' : 'text-gray-400 hover:text-amber-500 hover:bg-amber-50/50'}`}
                                                            title={t('bookmark')}
                                                        >
                                                            {bookmarkedPosts.has(post.id) ? <BookmarkCheck size={16} className="fill-amber-500" /> : <Bookmark size={16} />}
                                                        </button>
                                                    </div>
                                                </div>
                                            </div>
                                        </div>

                                        {isExpanded && (
                                            <div className="px-5 pb-5 border-t border-gray-50">
                                                <div className="pt-4">
                                                    {editingPost === post.id ? (
                                                        <div className="space-y-3">
                                                            <div className="flex flex-wrap gap-2 mb-2">
                                                                {DEFAULT_LABELS.map(lbl => (
                                                                    <button
                                                                        key={lbl}
                                                                        type="button"
                                                                        onClick={(e) => { e.stopPropagation(); setEditData(d => ({ ...d, label: d.label === lbl ? '' : lbl })); }}
                                                                        className={`px-2 py-1 rounded-lg text-[10px] font-bold border transition-all ${editData.label === lbl ? config.labelActiveColor : 'bg-white text-gray-500 border-gray-200'
                                                                            }`}
                                                                    >
                                                                        {lbl}
                                                                    </button>
                                                                ))}
                                                            </div>
                                                            <input
                                                                type="text"
                                                                value={editData.title}
                                                                onChange={e => setEditData(d => ({ ...d, title: e.target.value }))}
                                                                className="w-full px-3 py-2 bg-white border border-gray-200 rounded-lg text-sm font-bold outline-none focus:border-indigo-400"
                                                                onClick={e => e.stopPropagation()}
                                                            />
                                                            <textarea
                                                                value={editData.content}
                                                                onChange={e => setEditData(d => ({ ...d, content: e.target.value }))}
                                                                rows={4}
                                                                className="w-full px-3 py-2 bg-white border border-gray-200 rounded-lg text-sm outline-none focus:border-indigo-400 resize-none"
                                                                onClick={e => e.stopPropagation()}
                                                            />
                                                        </div>
                                                    ) : (
                                                        <div className="text-gray-700 whitespace-pre-wrap leading-relaxed text-sm">
                                                            <TranslatedText text={post.content} sourceLang={post.original_lang} as="p" />
                                                        </div>
                                                    )}

                                                    {/* Post Photos */}
                                                    {hasPhotos && (
                                                        <div className={`grid gap-2 mt-4 ${post.photos.length === 1 ? 'grid-cols-1' : post.photos.length === 2 ? 'grid-cols-2' : 'grid-cols-3'}`}>
                                                            {post.photos.map((photo, idx) => (
                                                                <div
                                                                    key={photo.id || idx}
                                                                    className="aspect-square rounded-xl overflow-hidden border border-gray-200 bg-gray-50 cursor-pointer hover:opacity-90 transition-opacity"
                                                                    onClick={(e) => { e.stopPropagation(); openPhotoViewer(post.photos, idx); }}
                                                                >
                                                                    <img src={photo.image_url} alt="" className="w-full h-full object-cover" />
                                                                </div>
                                                            ))}
                                                        </div>
                                                    )}
                                                </div>

                                                {/* Poll UI (if post has poll data) */}
                                                {(() => {
                                                    const poll = pollData[post.id];
                                                    if (!poll) {
                                                        // Fetch poll data on expand if label matches
                                                        if (isExpanded && (post.label === '투표' || post.label === 'Poll' || post.label === '投票' || post.label === 'Bình chọn' || post.label === 'โหวต' || post.label === 'ការបោះឆ្នោត' || post.label === 'Опрос' || post.label === 'Опитування')) {
                                                            if (!pollData[post.id] && !pollData[`loading_${post.id}`]) {
                                                                setPollData(prev => ({ ...prev, [`loading_${post.id}`]: true }));
                                                                fetchPollData(post.id);
                                                            }
                                                        }
                                                        return null;
                                                    }

                                                    const hasVoted = poll.user_voted !== null;
                                                    const showResults = hasVoted || poll.is_ended;

                                                    return (
                                                        <div className="mt-4 bg-gradient-to-br from-indigo-50 to-violet-50 rounded-xl p-4 border border-indigo-100">
                                                            <div className="flex items-center justify-between mb-3">
                                                                <h5 className="text-sm font-bold text-indigo-700 flex items-center gap-1.5">
                                                                    <BarChart2 size={14} />
                                                                    {t('pollTitle')}
                                                                </h5>
                                                                <span className="text-xs text-gray-400">
                                                                    {t('pollTotalVotes', { count: poll.total_votes })}
                                                                </span>
                                                            </div>
                                                            <div className="space-y-2">
                                                                {poll.options.map(opt => {
                                                                    const pct = poll.total_votes > 0 ? Math.round((opt.vote_count / poll.total_votes) * 100) : 0;
                                                                    const isSelected = poll.user_voted === opt.id;

                                                                    return showResults ? (
                                                                        <div key={opt.id} className="relative">
                                                                            <div className={`relative overflow-hidden rounded-lg px-3 py-2.5 border ${isSelected ? 'border-indigo-400 bg-white' : 'border-gray-200 bg-white'}`}>
                                                                                <div
                                                                                    className={`absolute left-0 top-0 bottom-0 transition-all duration-500 ${isSelected ? 'bg-indigo-100' : 'bg-gray-100'}`}
                                                                                    style={{ width: `${pct}%` }}
                                                                                />
                                                                                <div className="relative flex items-center justify-between">
                                                                                    <span className={`text-sm font-medium ${isSelected ? 'text-indigo-700' : 'text-gray-700'}`}>
                                                                                        {isSelected && <CheckCircle size={12} className="inline mr-1" />}
                                                                                        {opt.option_text}
                                                                                    </span>
                                                                                    <span className={`text-xs font-bold ${isSelected ? 'text-indigo-600' : 'text-gray-500'}`}>
                                                                                        {pct}%
                                                                                    </span>
                                                                                </div>
                                                                            </div>
                                                                        </div>
                                                                    ) : (
                                                                        <button
                                                                            key={opt.id}
                                                                            onClick={(e) => { e.stopPropagation(); handlePollVote(poll.id, opt.id, post.id); }}
                                                                            className="w-full text-left px-3 py-2.5 rounded-lg border border-indigo-200 bg-white hover:bg-indigo-50 hover:border-indigo-400 transition-all text-sm font-medium text-gray-700"
                                                                        >
                                                                            {opt.option_text}
                                                                        </button>
                                                                    );
                                                                })}
                                                            </div>
                                                            {poll.end_date && (
                                                                <p className="text-[10px] text-gray-400 mt-2 flex items-center gap-1">
                                                                    <CalendarClock size={10} />
                                                                    {t('pollEndDate')}: {new Date(poll.end_date).toLocaleString()}
                                                                </p>
                                                            )}
                                                            {poll.is_ended && (
                                                                <p className="text-xs text-red-400 font-bold mt-1">{t('pollEnded')}</p>
                                                            )}
                                                        </div>
                                                    );
                                                })()}
                                                {post.can_manage && (
                                                    <div className="mt-4 flex justify-end gap-3">
                                                        {editingPost === post.id ? (
                                                            <>
                                                                <button
                                                                    onClick={(e) => { e.stopPropagation(); setEditingPost(null); }}
                                                                    className="text-xs text-gray-400 hover:text-gray-600 flex items-center gap-1 transition-colors"
                                                                >
                                                                    <X size={12} />
                                                                    {t('cancel')}
                                                                </button>
                                                                <button
                                                                    onClick={(e) => { e.stopPropagation(); handleEditPost(post.id); }}
                                                                    className="text-xs text-green-500 hover:text-green-700 flex items-center gap-1 transition-colors font-bold"
                                                                >
                                                                    <Check size={12} />
                                                                    {t('editDone')}
                                                                </button>
                                                            </>
                                                        ) : (
                                                            <>
                                                                <button
                                                                    onClick={(e) => { e.stopPropagation(); startEditing(post); }}
                                                                    className="text-xs text-blue-400 hover:text-blue-600 flex items-center gap-1 transition-colors"
                                                                >
                                                                    <Edit3 size={12} />
                                                                    {t('edit')}
                                                                </button>
                                                                <button
                                                                    onClick={(e) => { e.stopPropagation(); handleDeletePost(post.id); }}
                                                                    className="text-xs text-red-400 hover:text-red-600 flex items-center gap-1 transition-colors"
                                                                >
                                                                    <Trash2 size={12} />
                                                                    {t('delete')}
                                                                </button>
                                                            </>
                                                        )}
                                                    </div>
                                                )}

                                                {/* Report button (not for own posts) */}
                                                {!post.is_mine && (
                                                    <div className={`${post.can_manage ? '' : 'mt-4'} flex justify-end`}>
                                                        <button
                                                            onClick={(e) => { e.stopPropagation(); setReportModal({ postId: post.id }); setReportReason(''); setReportDetail(''); }}
                                                            className="text-xs text-gray-400 hover:text-red-500 flex items-center gap-1 transition-colors"
                                                        >
                                                            <Flag size={12} />
                                                            {t('reportPost')}
                                                        </button>
                                                    </div>
                                                )}

                                                {/* ===== COMMENTS SECTION ===== */}
                                                <div className="mt-6 pt-5 border-t border-gray-100">
                                                    <h4 className="text-sm font-bold text-gray-700 flex items-center gap-2 mb-4">
                                                        <MessageCircle size={16} />
                                                        {t('comment')} {commentCounts[post.id] > 0 && <span className="text-xs bg-gray-100 text-gray-500 px-1.5 py-0.5 rounded-full">{commentCounts[post.id]}</span>}
                                                    </h4>

                                                    {/* Comment Input */}
                                                    <div className="flex gap-2 mb-4">
                                                        <div className="w-8 h-8 bg-gradient-to-br from-gray-200 to-gray-300 rounded-lg flex items-center justify-center text-white flex-shrink-0 overflow-hidden">
                                                            {user?.profile_image ? (
                                                                <img src={user.profile_image} alt="" className="w-full h-full object-cover" />
                                                            ) : (
                                                                <User size={14} className="text-gray-500" />
                                                            )}
                                                        </div>
                                                        <div className="flex-1 flex gap-2">
                                                            <input
                                                                type="text"
                                                                value={commentInput}
                                                                onChange={e => setCommentInput(e.target.value)}
                                                                onKeyDown={e => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSubmitComment(post.id); } }}
                                                                placeholder={t('writeComment')}
                                                                className="flex-1 px-3 py-2 bg-gray-50 border border-gray-200 rounded-xl text-sm outline-none focus:border-indigo-400 focus:bg-white transition-colors"
                                                                onClick={e => e.stopPropagation()}
                                                            />
                                                            <button
                                                                onClick={(e) => { e.stopPropagation(); handleSubmitComment(post.id); }}
                                                                disabled={submittingComment || !commentInput.trim()}
                                                                className={`px-3 py-2 ${config.buttonBg} text-white rounded-xl text-sm font-bold transition-all disabled:opacity-40 flex-shrink-0`}
                                                            >
                                                                <Send size={14} />
                                                            </button>
                                                        </div>
                                                    </div>

                                                    {/* Comments List */}
                                                    {commentsMap[post.id] && commentsMap[post.id].length > 0 ? (
                                                        <div className="space-y-3">
                                                            {commentsMap[post.id].map(comment => {
                                                                const cBadge = getRoleBadge(comment.user_role);
                                                                return (
                                                                    <div key={comment.id} className="group/comment">
                                                                        {/* Top-level comment */}
                                                                        <div className="flex gap-2.5">
                                                                            <div className="w-7 h-7 bg-gradient-to-br from-gray-200 to-gray-300 rounded-lg flex items-center justify-center text-white flex-shrink-0 overflow-hidden mt-0.5">
                                                                                {comment.profile_image ? (
                                                                                    <img src={comment.profile_image} alt="" className="w-full h-full object-cover" />
                                                                                ) : (
                                                                                    <User size={12} className="text-gray-500" />
                                                                                )}
                                                                            </div>
                                                                            <div className="flex-1 min-w-0">
                                                                                <div className="flex items-center gap-1.5 flex-wrap">
                                                                                    <span className="text-xs font-bold text-gray-800">{getDisplayName(comment, countryToLang(user?.country))}</span>
                                                                                    <span className={`text-[9px] font-bold px-1 py-0.5 rounded ${cBadge.color}`}>{cBadge.label}</span>
                                                                                    <span className="text-[10px] text-gray-400">{formatDate(comment.created_at)}</span>
                                                                                </div>
                                                                                <p className="text-sm text-gray-700 mt-0.5 whitespace-pre-wrap"><TranslatedText text={comment.content} sourceLang={comment.original_lang} /></p>
                                                                                {comment.country && <CountryBadge country={comment.country} size="xs" className="mt-1" />}
                                                                                <div className="flex items-center gap-3 mt-1">
                                                                                    <button
                                                                                        onClick={(e) => handleToggleCommentLike(e, post.id, comment.id)}
                                                                                        className={`flex items-center gap-1 px-2 py-0.5 rounded-full text-[11px] font-medium transition-all ${comment.is_liked ? 'text-red-500 bg-red-50' : 'text-gray-400 hover:text-red-400 hover:bg-red-50/50'}`}
                                                                                    >
                                                                                        <Heart size={12} className={comment.is_liked ? 'fill-red-500' : ''} />
                                                                                        {comment.like_count > 0 && comment.like_count}
                                                                                    </button>
                                                                                    <button
                                                                                        onClick={(e) => { e.stopPropagation(); setReplyingTo(replyingTo?.commentId === comment.id ? null : { commentId: comment.id, userName: getDisplayName(comment, countryToLang(user?.country)) }); setReplyInput(''); }}
                                                                                        className="text-[11px] text-gray-400 hover:text-indigo-500 font-medium flex items-center gap-1 transition-colors"
                                                                                    >
                                                                                        <CornerDownRight size={10} />
                                                                                        {t('reply')}</button>
                                                                                    {comment.can_delete && (
                                                                                        <button
                                                                                            onClick={(e) => { e.stopPropagation(); handleDeleteComment(post.id, comment.id); }}
                                                                                            className="text-[11px] text-gray-400 hover:text-red-500 font-medium flex items-center gap-1 transition-colors opacity-0 group-hover/comment:opacity-100"
                                                                                        >
                                                                                            <Trash2 size={10} />
                                                                                            {t('delete')}
                                                                                        </button>
                                                                                    )}
                                                                                </div>
                                                                            </div>
                                                                        </div>

                                                                        {/* Reply Input */}
                                                                        {replyingTo?.commentId === comment.id && (
                                                                            <div className="ml-9 mt-2 flex gap-2">
                                                                                <input
                                                                                    type="text"
                                                                                    value={replyInput}
                                                                                    onChange={e => setReplyInput(e.target.value)}
                                                                                    onKeyDown={e => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSubmitReply(post.id, comment.id); } }}
                                                                                    placeholder={t('replyPlaceholder', { name: replyingTo.userName })}
                                                                                    className="flex-1 px-3 py-1.5 bg-gray-50 border border-gray-200 rounded-lg text-xs outline-none focus:border-indigo-400 focus:bg-white transition-colors"
                                                                                    onClick={e => e.stopPropagation()}
                                                                                    autoFocus
                                                                                />
                                                                                <button
                                                                                    onClick={(e) => { e.stopPropagation(); handleSubmitReply(post.id, comment.id); }}
                                                                                    disabled={submittingComment || !replyInput.trim()}
                                                                                    className={`px-2.5 py-1.5 ${config.buttonBg} text-white rounded-lg text-xs font-bold transition-all disabled:opacity-40`}
                                                                                >
                                                                                    <Send size={12} />
                                                                                </button>
                                                                                <button
                                                                                    onClick={(e) => { e.stopPropagation(); setReplyingTo(null); setReplyInput(''); }}
                                                                                    className="px-2 py-1.5 text-gray-400 hover:text-gray-600 text-xs"
                                                                                >
                                                                                    <X size={12} />
                                                                                </button>
                                                                            </div>
                                                                        )}

                                                                        {/* Replies */}
                                                                        {comment.replies && comment.replies.length > 0 && (
                                                                            <div className="ml-9 mt-2 space-y-2 pl-3 border-l-2 border-gray-100">
                                                                                {comment.replies.map(reply => {
                                                                                    const rBadge = getRoleBadge(reply.user_role);
                                                                                    return (
                                                                                        <div key={reply.id} className="flex gap-2 group/reply">
                                                                                            <div className="w-6 h-6 bg-gradient-to-br from-gray-200 to-gray-300 rounded-md flex items-center justify-center text-white flex-shrink-0 overflow-hidden mt-0.5">
                                                                                                {reply.profile_image ? (
                                                                                                    <img src={reply.profile_image} alt="" className="w-full h-full object-cover" />
                                                                                                ) : (
                                                                                                    <User size={10} className="text-gray-500" />
                                                                                                )}
                                                                                            </div>
                                                                                            <div className="flex-1 min-w-0">
                                                                                                <div className="flex items-center gap-1.5 flex-wrap">
                                                                                                    <span className="text-[11px] font-bold text-gray-800">{getDisplayName(reply, countryToLang(user?.country))}</span>
                                                                                                    <span className={`text-[8px] font-bold px-1 py-0.5 rounded ${rBadge.color}`}>{rBadge.label}</span>
                                                                                                    <span className="text-[10px] text-gray-400">{formatDate(reply.created_at)}</span>
                                                                                                </div>
                                                                                                <p className="text-xs text-gray-700 mt-0.5 whitespace-pre-wrap">{reply.content}</p>
                                                                                                <div className="flex items-center gap-2 mt-0.5">
                                                                                                    <button
                                                                                                        onClick={(e) => handleToggleCommentLike(e, post.id, reply.id)}
                                                                                                        className={`flex items-center gap-0.5 px-1.5 py-0.5 rounded-full text-[10px] font-medium transition-all ${reply.is_liked ? 'text-red-500 bg-red-50' : 'text-gray-400 hover:text-red-400 hover:bg-red-50/50'}`}
                                                                                                    >
                                                                                                        <Heart size={10} className={reply.is_liked ? 'fill-red-500' : ''} />
                                                                                                        {reply.like_count > 0 && reply.like_count}
                                                                                                    </button>
                                                                                                    {reply.can_delete && (
                                                                                                        <button
                                                                                                            onClick={(e) => { e.stopPropagation(); handleDeleteComment(post.id, reply.id); }}
                                                                                                            className="text-[10px] text-gray-400 hover:text-red-500 font-medium flex items-center gap-1 transition-colors opacity-0 group-hover/reply:opacity-100"
                                                                                                        >
                                                                                                            <Trash2 size={9} />
                                                                                                            {t('delete')}</button>
                                                                                                    )}
                                                                                                </div>
                                                                                            </div>
                                                                                        </div>
                                                                                    );
                                                                                })}
                                                                            </div>
                                                                        )}
                                                                    </div>
                                                                );
                                                            })}
                                                        </div>
                                                    ) : commentsMap[post.id] ? (
                                                        <p className="text-xs text-gray-400 text-center py-2">{t('noComments')}</p>
                                                    ) : (
                                                        <div className="flex justify-center py-3">
                                                            <div className="w-5 h-5 border-2 border-gray-200 border-t-gray-400 rounded-full animate-spin"></div>
                                                        </div>
                                                    )}
                                                </div>
                                            </div>
                                        )}
                                    </div>
                                </React.Fragment>
                            );
                        })}
                    </div>
                )
            }

            {/* Pagination */}
            {
                totalPages > 1 && (
                    <div className="flex justify-center items-center gap-2 pt-4">
                        <button
                            onClick={() => setPage(p => Math.max(1, p - 1))}
                            disabled={page === 1}
                            className="p-2 rounded-xl bg-white border border-gray-200 text-gray-600 hover:bg-gray-50 disabled:opacity-30 transition-colors"
                        >
                            <ChevronLeft size={18} />
                        </button>
                        <span className="text-sm font-medium text-gray-600 px-3">
                            {page} / {totalPages}
                        </span>
                        <button
                            onClick={() => setPage(p => Math.min(totalPages, p + 1))}
                            disabled={page === totalPages}
                            className="p-2 rounded-xl bg-white border border-gray-200 text-gray-600 hover:bg-gray-50 disabled:opacity-30 transition-colors"
                        >
                            <ChevronRight size={18} />
                        </button>
                    </div>
                )
            }

            {/* Photo Viewer Modal */}
            {
                photoViewerImages.length > 0 && (
                    <div className="fixed inset-0 bg-black/90 z-[60] flex items-center justify-center" onClick={closePhotoViewer}>
                        <button className="absolute top-4 right-4 text-white/80 hover:text-white p-2" onClick={closePhotoViewer}>
                            <X size={28} />
                        </button>
                        <div className="flex items-center gap-4 max-w-4xl w-full px-4" onClick={e => e.stopPropagation()}>
                            {photoViewerImages.length > 1 && (
                                <button
                                    className="text-white/60 hover:text-white p-2 flex-shrink-0"
                                    onClick={() => setPhotoViewerIndex(i => (i - 1 + photoViewerImages.length) % photoViewerImages.length)}
                                >
                                    <ChevronLeft size={32} />
                                </button>
                            )}
                            <div className="flex-1 flex items-center justify-center">
                                <img
                                    src={photoViewerImages[photoViewerIndex]?.image_url}
                                    alt=""
                                    className="max-h-[80vh] max-w-full object-contain rounded-lg"
                                />
                            </div>
                            {photoViewerImages.length > 1 && (
                                <button
                                    className="text-white/60 hover:text-white p-2 flex-shrink-0"
                                    onClick={() => setPhotoViewerIndex(i => (i + 1) % photoViewerImages.length)}
                                >
                                    <ChevronRight size={32} />
                                </button>
                            )}
                        </div>
                        {photoViewerImages.length > 1 && (
                            <div className="absolute bottom-6 text-white/60 text-sm font-medium">
                                {photoViewerIndex + 1} / {photoViewerImages.length}
                            </div>
                        )}
                    </div>
                )
            }
            {/* User Profile Popup Modal */}
            {
                profilePopup && (
                    <div
                        className="fixed inset-0 z-[999] flex items-center justify-center bg-black/50 backdrop-blur-sm p-4"
                        onClick={() => { setProfilePopup(null); setProfileData(null); }}
                    >
                        <div
                            className="bg-white rounded-2xl shadow-2xl max-w-lg w-full max-h-[85vh] overflow-y-auto"
                            onClick={e => e.stopPropagation()}
                            style={{ animation: 'fadeInUp 0.25s ease-out' }}
                        >
                            {profileLoading ? (
                                <div className="flex justify-center items-center py-20">
                                    <div className="w-8 h-8 border-3 border-indigo-200 border-t-indigo-600 rounded-full animate-spin"></div>
                                </div>
                            ) : profileData ? (
                                <>
                                    {/* Header */}
                                    <div className="relative p-6 pb-4 border-b border-gray-100">
                                        <button
                                            onClick={() => { setProfilePopup(null); setProfileData(null); }}
                                            className="absolute top-4 right-4 p-1.5 text-gray-400 hover:text-gray-600 hover:bg-gray-100 rounded-lg transition-colors"
                                        >
                                            <X size={18} />
                                        </button>
                                        <div className="flex items-center gap-4">
                                            <div className="w-16 h-16 bg-gradient-to-br from-gray-200 to-gray-300 rounded-2xl flex items-center justify-center overflow-hidden flex-shrink-0 shadow-md">
                                                {profileData.user.profile_image ? (
                                                    <img src={profileData.user.profile_image} alt="" className="w-full h-full object-cover" />
                                                ) : (
                                                    <User size={28} className="text-gray-400" />
                                                )}
                                            </div>
                                            <div>
                                                <div className="flex items-center gap-2 flex-wrap">
                                                    <h3 className="text-xl font-extrabold text-gray-900">{profileData.user.name}</h3>
                                                    <span className={`px-2.5 py-0.5 rounded-full text-[10px] font-bold border ${profileData.user.role === 'host' ? 'bg-blue-50 text-blue-700 border-blue-100' :
                                                        profileData.user.role === 'seller' ? 'bg-green-50 text-green-700 border-green-100' :
                                                            'bg-purple-50 text-purple-700 border-purple-100'
                                                        }`}>
                                                        {profileData.user.role === 'host' ? t('roleHost') : profileData.user.role === 'seller' ? t('roleSeller') : profileData.user.role === 'superadmin' ? t('roleSuperAdmin') : t('roleAdmin')}
                                                    </span>
                                                </div>
                                                <div className="flex items-center gap-3 mt-1.5 text-xs text-gray-400">
                                                    <span className="flex items-center gap-1">
                                                        <Calendar size={11} />
                                                        {t('joinDate')}: {new Date(profileData.user.created_at).toLocaleDateString()}
                                                    </span>
                                                    {(profileData.user.product_category || profileData.user.category) && (
                                                        <span className="flex items-center gap-1">
                                                            <Tag size={11} />
                                                            {profileData.user.product_category || profileData.user.category}
                                                        </span>
                                                    )}
                                                </div>
                                            </div>
                                        </div>
                                    </div>

                                    {/* Activity Stats */}
                                    <div className="grid grid-cols-3 gap-0 border-b border-gray-100">
                                        <div className="text-center py-4 border-r border-gray-50">
                                            <p className="text-lg font-extrabold text-gray-900">{profileData.community_stats?.post_count || 0}</p>
                                            <p className="text-[10px] text-gray-400 font-medium">{t('profilePosts')}</p>
                                        </div>
                                        <div className="text-center py-4 border-r border-gray-50">
                                            <p className="text-lg font-extrabold text-gray-900">{profileData.community_stats?.comment_count || 0}</p>
                                            <p className="text-[10px] text-gray-400 font-medium">{t('profileComments')}</p>
                                        </div>
                                        <div className="text-center py-4">
                                            <p className="text-lg font-extrabold text-gray-900">
                                                {profileData.user.role === 'host' ? (profileData.stats?.total_venues || 0) : (profileData.stats?.total_applications || 0)}
                                            </p>
                                            <p className="text-[10px] text-gray-400 font-medium">
                                                {profileData.user.role === 'host' ? t('registeredVenues') : t('applicationActivity')}
                                            </p>
                                        </div>
                                    </div>

                                    {/* Activity Level Card */}
                                    {profileData.activity && (
                                        <div className="px-5 py-4 border-b border-gray-100">
                                            <div className="flex items-center justify-between">
                                                <div className="flex items-center gap-2">
                                                    <span className="text-2xl">{profileData.activity.level_emoji}</span>
                                                    <div>
                                                        <p className="text-sm font-bold text-gray-900">
                                                            {t('activityLevel', { level: `Lv.${profileData.activity.level}` })}
                                                        </p>
                                                        <p className="text-[10px] text-gray-400">
                                                            {t('activityScore')}: {profileData.activity.total_activity}
                                                        </p>
                                                    </div>
                                                </div>
                                                <div className="flex items-center gap-3 text-[10px] text-gray-400">
                                                    <span>📝 {profileData.activity.post_count}</span>
                                                    <span>💬 {profileData.activity.comment_count}</span>
                                                    <span>❤️ {profileData.activity.received_likes}</span>
                                                </div>
                                            </div>
                                            {/* Level progress bar */}
                                            <div className="mt-2 h-1.5 bg-gray-100 rounded-full overflow-hidden">
                                                <div
                                                    className="h-full bg-gradient-to-r from-green-400 via-amber-400 to-red-400 rounded-full transition-all"
                                                    style={{ width: `${Math.min(100, (profileData.activity.total_activity / 100) * 100)}%` }}
                                                />
                                            </div>
                                        </div>
                                    )}

                                    {/* Seller Product Photos */}
                                    {profileData.seller_photos && profileData.seller_photos.length > 0 && (
                                        <div className="p-5 border-b border-gray-100">
                                            <h4 className="text-sm font-bold text-gray-900 mb-3 flex items-center gap-1.5">
                                                <ImagePlus size={14} className="text-indigo-500" />
                                                {t('sellerProducts')}
                                            </h4>
                                            <div className="grid grid-cols-4 gap-2">
                                                {profileData.seller_photos.map(photo => (
                                                    <div key={photo.id} className="aspect-square rounded-xl overflow-hidden border border-gray-200 bg-gray-50">
                                                        <img src={photo.image_url} alt={photo.caption || ''} className="w-full h-full object-cover" />
                                                    </div>
                                                ))}
                                            </div>
                                        </div>
                                    )}

                                    {/* Vendor Venues */}
                                    {profileData.user.role === 'host' && profileData.venues && profileData.venues.length > 0 && (
                                        <div className="p-5 border-b border-gray-100">
                                            <h4 className="text-sm font-bold text-gray-900 mb-3 flex items-center gap-1.5">
                                                <Store size={14} className="text-blue-500" />
                                                {t('registeredVenuesList')}
                                            </h4>
                                            <div className="space-y-2">
                                                {profileData.venues.map(venue => (
                                                    <div key={venue.id} className="flex items-center gap-3 p-3 bg-gray-50 rounded-xl">
                                                        <div className="w-12 h-12 rounded-lg overflow-hidden bg-gray-200 flex-shrink-0">
                                                            {venue.images && venue.images[0] ? (
                                                                <img src={venue.images[0]} alt="" className="w-full h-full object-cover" />
                                                            ) : (
                                                                <div className="w-full h-full flex items-center justify-center"><Store size={16} className="text-gray-400" /></div>
                                                            )}
                                                        </div>
                                                        <div className="flex-1 min-w-0">
                                                            <p className="text-sm font-bold text-gray-900 truncate">{venue.name}</p>
                                                            <p className="text-[10px] text-gray-400 truncate flex items-center gap-1">
                                                                <MapPin size={9} />
                                                                {venue.location}
                                                            </p>
                                                        </div>
                                                        <span className="text-[10px] font-bold text-gray-400 bg-gray-200 px-2 py-0.5 rounded">{venue.type}</span>
                                                    </div>
                                                ))}
                                            </div>
                                        </div>
                                    )}

                                    {/* Seller Applications (Activity) */}
                                    {profileData.user.role === 'seller' && profileData.applications && profileData.applications.length > 0 && (
                                        <div className="p-5">
                                            <h4 className="text-sm font-bold text-gray-900 mb-3 flex items-center gap-1.5">
                                                <ClipboardList size={14} className="text-green-500" />
                                                {t('activityArea')}
                                            </h4>
                                            <div className="space-y-2">
                                                {profileData.applications.map(app => (
                                                    <div key={app.id} className="flex items-center justify-between p-3 bg-gray-50 rounded-xl">
                                                        <div className="min-w-0">
                                                            <p className="text-sm font-bold text-gray-900 truncate">{app.venue_name}</p>
                                                            <p className="text-[10px] text-gray-400 truncate flex items-center gap-1">
                                                                <MapPin size={9} />
                                                                {app.venue_location}
                                                            </p>
                                                        </div>
                                                        <span className="text-[10px] font-bold text-gray-400 flex-shrink-0">{app.venue_type}</span>
                                                    </div>
                                                ))}
                                            </div>
                                        </div>
                                    )}

                                    {/* No activity fallback */}
                                    {((!profileData.venues || profileData.venues.length === 0) &&
                                        (!profileData.applications || profileData.applications.length === 0) &&
                                        (!profileData.seller_photos || profileData.seller_photos.length === 0)) && (
                                            <div className="p-8 text-center text-gray-400 text-sm">
                                                {t('noActivityArea')}
                                            </div>
                                        )}
                                </>
                            ) : (
                                <div className="p-8 text-center text-gray-400 text-sm">
                                    {t('profileLoadError')}
                                </div>
                            )}
                        </div>
                    </div>
                )
            }
            {/* Confirm Modal */}
            {
                confirmModal && (
                    <div className="fixed inset-0 z-[9999] flex items-center justify-center p-4" style={{ backgroundColor: 'rgba(0,0,0,0.5)' }}>
                        <div className="bg-white rounded-2xl shadow-2xl max-w-sm w-full overflow-hidden" onClick={(e) => e.stopPropagation()}>
                            <div className={`p-5 flex items-center gap-3 ${confirmModal.type === 'danger' ? 'bg-red-50' : 'bg-amber-50'}`}>
                                <div className={`w-10 h-10 rounded-full flex items-center justify-center flex-shrink-0 ${confirmModal.type === 'danger' ? 'bg-red-100' : 'bg-amber-100'}`}>
                                    <AlertTriangle size={20} className={confirmModal.type === 'danger' ? 'text-red-500' : 'text-amber-500'} />
                                </div>
                                <h3 className="text-base font-bold text-gray-900">{confirmModal.title}</h3>
                            </div>
                            <div className="p-5">
                                <p className="text-sm text-gray-600 leading-relaxed whitespace-pre-line">{confirmModal.message}</p>
                            </div>
                            <div className="px-5 pb-5 flex gap-3">
                                <button onClick={() => setConfirmModal(null)} className="flex-1 py-3 bg-gray-100 text-gray-700 rounded-xl text-sm font-bold hover:bg-gray-200 transition-colors">
                                    {t('cancel')}
                                </button>
                                <button onClick={confirmModal.onConfirm} className={`flex-1 py-3 rounded-xl text-sm font-bold transition-colors text-white ${confirmModal.type === 'danger' ? 'bg-red-500 hover:bg-red-600' : 'bg-amber-500 hover:bg-amber-600'}`}>
                                    {confirmModal.confirmLabel || t('confirm')}
                                </button>
                            </div>
                        </div>
                    </div>
                )
            }

            {/* Toast Notification */}
            {
                toast && (
                    <div className="fixed top-6 left-1/2 -translate-x-1/2 z-[9999]">
                        <div className={`flex items-center gap-3 px-5 py-3.5 rounded-2xl shadow-2xl border backdrop-blur-sm ${toast.type === 'success' ? 'bg-emerald-50 border-emerald-200 text-emerald-800' : 'bg-red-50 border-red-200 text-red-800'
                            }`}>
                            {toast.type === 'success' ? <CheckCircle size={18} className="text-emerald-500 flex-shrink-0" /> : <X size={18} className="text-red-500 flex-shrink-0" />}
                            <span className="text-sm font-bold">{toast.message}</span>
                            <button onClick={() => setToast(null)} className="ml-2 p-0.5 hover:bg-black/5 rounded-full transition-colors"><X size={14} className="text-gray-400" /></button>
                        </div>
                    </div>
                )
            }

            {/* Floating Action Button (Write) */}
            {
                !showWriteForm && user && (
                    <button
                        onClick={() => setShowWriteForm(true)}
                        className={`fixed bottom-[6rem] right-6 lg:bottom-[7.5rem] lg:right-10 w-14 h-14 lg:w-16 lg:h-16 ${config.buttonBg} text-white rounded-full shadow-lg hover:shadow-xl transition-all duration-200 flex items-center justify-center z-50 hover:scale-110 active:scale-95`}
                        title={t('writePost')}
                    >
                        <PenLine size={22} />
                    </button>
                )
            }

            {/* Report Modal */}
            {reportModal && (
                <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-[60] flex items-center justify-center p-4"
                    onClick={() => setReportModal(null)}>
                    <div className="bg-white rounded-2xl shadow-xl max-w-sm w-full p-6" onClick={e => e.stopPropagation()}>
                        <div className="flex items-center justify-between mb-4">
                            <h3 className="text-lg font-bold text-gray-900 flex items-center gap-2">
                                <Flag size={18} className="text-red-500" />
                                {t('reportPost')}
                            </h3>
                            <button onClick={() => setReportModal(null)} className="p-1 hover:bg-gray-100 rounded-lg transition-colors">
                                <X size={18} className="text-gray-400" />
                            </button>
                        </div>
                        <p className="text-sm text-gray-500 mb-4">{t('reportDesc')}</p>
                        <div className="space-y-2 mb-4">
                            {[
                                { key: 'spam', label: t('reportSpam') },
                                { key: 'inappropriate', label: t('reportInappropriate') },
                                { key: 'advertising', label: t('reportAdvertising') },
                                { key: 'other', label: t('reportOther') },
                            ].map(r => (
                                <label key={r.key}
                                    className={`flex items-center gap-3 p-3 rounded-xl border cursor-pointer transition-all ${reportReason === r.key ? 'border-red-400 bg-red-50' : 'border-gray-200 hover:border-gray-300'}`}>
                                    <input type="radio" name="report_reason" value={r.key}
                                        checked={reportReason === r.key}
                                        onChange={() => setReportReason(r.key)}
                                        className="accent-red-500" />
                                    <span className="text-sm font-medium text-gray-700">{r.label}</span>
                                </label>
                            ))}
                        </div>
                        {reportReason === 'other' && (
                            <textarea
                                placeholder={t('reportDetailPlaceholder')}
                                value={reportDetail}
                                onChange={e => setReportDetail(e.target.value)}
                                className="w-full px-3 py-2 border border-gray-200 rounded-xl text-sm focus:ring-2 focus:ring-red-500/20 focus:border-red-500 outline-none resize-none mb-4"
                                rows={3}
                            />
                        )}
                        <button
                            onClick={handleSubmitReport}
                            disabled={!reportReason || reportSubmitting}
                            className="w-full py-2.5 bg-red-500 text-white rounded-xl font-bold text-sm hover:bg-red-600 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                        >
                            {reportSubmitting ? '...' : t('submitReport')}
                        </button>
                    </div>
                </div>
            )}

            {/* Heart burst animation CSS */}
            <style>{`
                @keyframes heartBurst {
                    0% { transform: scale(0); opacity: 1; }
                    50% { transform: scale(1.3); opacity: 0.8; }
                    100% { transform: scale(1.5); opacity: 0; }
                }
            `}</style>
        </div >
    );
};

export default CommunityPage;

import React, { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { useAuth } from '../../context/AuthContext';
import {
    BarChart3, TrendingUp, Eye, Users, Store, CheckCircle, Clock, XCircle,
    Zap, ArrowUpRight, ArrowDownRight, Trophy, PieChart, Activity, Calendar,
    RefreshCw, Lock, Download, ArrowRight, Minus
} from 'lucide-react';

const API_BASE = '/api';

// CATEGORY_LABELS moved into component

const HostAnalyticsReport = () => {
    const { t } = useTranslation('host');
    const { user } = useAuth();
    const [data, setData] = useState(null);
    const [loading, setLoading] = useState(true);
    const [activeTab, setActiveTab] = useState('overview');
    const [hasAccess, setHasAccess] = useState(null);

    const fetchReport = async () => {
        try {
            setLoading(true);
            const res = await fetch(`${API_BASE}/venues/host_report.php`, { credentials: 'include' });
            const json = await res.json();
            if (json.success) setData(json.data);
        } catch (err) {
            console.error('리포트 로드 실패:', err);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetch(`${API_BASE}/users/check_service.php?service=analytics_report`, { credentials: 'include' })
            .then(res => res.json())
            .then(data => {
                setHasAccess(data.hasAccess ?? false);
                if (data.hasAccess) fetchReport();
                else setLoading(false);
            })
            .catch(() => { setHasAccess(false); setLoading(false); });
    }, []);

    const getCatLabel = (cat) => CATEGORY_LABELS[cat] || cat || '기타';

    // CSV export helper
    const exportCSV = () => {
        if (!data?.venues) return;
        const headers = ['공간명', '위치', '상태', '가격', '조회수', '신청수', '승인수', '거절수', '대기수', '전환율(%)'];
        const rows = data.venues.map(v => [
            v.name, v.location, v.status === 'approved' ? '운영 중' : v.status,
            v.price, v.view_count, v.app_count, v.approved_count, v.rejected_count, v.pending_count, v.conversion_rate
        ]);
        const csv = '\uFEFF' + [headers, ...rows].map(r => r.map(c => `"${String(c ?? '').replace(/"/g, '""')}"`).join(',')).join('\n');
        const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.download = `공간분석_${new Date().toISOString().slice(0, 10)}.csv`;
        link.click();
        URL.revokeObjectURL(url);
    };

    if (loading || hasAccess === null) {
        return (
            <div className="flex items-center justify-center py-32">
                <div className="w-8 h-8 border-3 border-indigo-200 dark:border-indigo-800 border-t-indigo-600 dark:border-t-indigo-400 rounded-full animate-spin" />
            </div>
        );
    }

    if (hasAccess === false) {
        return (
            <div className="flex items-center justify-center py-20">
                <div className="text-center max-w-md">
                    <div className="w-20 h-20 bg-gradient-to-br from-violet-100 to-purple-100 dark:from-violet-900/50 dark:to-purple-900/50 rounded-3xl flex items-center justify-center mx-auto mb-6">
                        <Lock size={32} className="text-violet-500 dark:text-violet-400" />
                    </div>
                    <h2 className="text-2xl font-extrabold text-gray-900 dark:text-white mb-2">분석 리포트 서비스</h2>
                    <p className="text-gray-500 dark:text-gray-400 mb-6 leading-relaxed">
                        이 서비스는 유료 구독 후 이용할 수 있습니다.<br />
                        관리자에게 문의하여 서비스를 활성화하세요.
                    </p>
                    <div className="bg-violet-50 dark:bg-violet-950/50 rounded-2xl p-4 border border-violet-100 dark:border-violet-800">
                        <p className="text-xs font-bold text-violet-600 dark:text-violet-400 mb-2">📊 포함된 기능</p>
                        <ul className="text-xs text-gray-600 dark:text-gray-400 space-y-1 text-left">
                            <li>• 공간별 조회수/신청수/전환율 분석</li>
                            <li>• vs Last Month 성과 비교 및 증감률</li>
                            <li>• 전환 퍼널 및 요일별 히트맵</li>
                            <li>• CSV 데이터 내보내기</li>
                        </ul>
                    </div>
                </div>
            </div>
        );
    }

    if (!data) {
        return (
            <div className="text-center py-20">
                <BarChart3 className="mx-auto text-gray-300 dark:text-gray-600 mb-4" size={48} />
                <h3 className="text-lg font-bold text-gray-400 dark:text-gray-500">Unable to load report</h3>
            </div>
        );
    }

    const { summary, venues, monthlyTrend, appsByCategory, recentApps, venueRanking, previousPeriod, weekdayStats } = data;

    // Growth indicator helper
    const GrowthBadge = ({ value }) => {
        if (value === 0 || value === undefined) return <span className="flex items-center gap-0.5 text-xs font-bold text-gray-400"><Minus size={12} /> 0%</span>;
        const isPositive = value > 0;
        return (
            <span className={`flex items-center gap-0.5 text-xs font-bold ${isPositive ? 'text-emerald-600 dark:text-emerald-400' : 'text-red-500 dark:text-red-400'}`}>
                {isPositive ? <ArrowUpRight size={12} /> : <ArrowDownRight size={12} />}
                {isPositive ? '+' : ''}{value}%
            </span>
        );
    };

    // Bar component with dark mode
    const Bar = ({ value, max, color = 'bg-indigo-500' }) => (
        <div className="w-full bg-gray-100 dark:bg-gray-700 rounded-full h-2.5 overflow-hidden">
            <div className={`h-full rounded-full ${color} transition-all duration-500`}
                style={{ width: `${max > 0 ? Math.min(value / max * 100, 100) : 0}%` }} />
        </div>
    );

    const tabs = [
        { id: 'overview', label: '개요', icon: PieChart },
        { id: 'venues', label: '공간별 분석', icon: Store },
        { id: 'trends', label: '트렌드', icon: Activity },
    ];

    return (
        <div className="space-y-6 animate-fadeIn pb-24">
            {/* Header */}
            <div className="flex flex-col md:flex-row md:items-end justify-between gap-4">
                <div>
                    <h1 className="text-3xl font-extrabold text-gray-900 dark:text-white tracking-tight">📊 분석 리포트</h1>
                    <p className="text-gray-500 dark:text-gray-400 mt-2 font-medium">내 공간의 성과를 한눈에 확인하세요</p>
                </div>
                <div className="flex items-center gap-2">
                    <button onClick={exportCSV} className="flex items-center gap-2 px-4 py-2.5 bg-emerald-50 dark:bg-emerald-950/50 text-emerald-600 dark:text-emerald-400 rounded-xl text-sm font-bold hover:bg-emerald-100 dark:hover:bg-emerald-900/50 transition-colors border border-emerald-200 dark:border-emerald-800">
                        <Download size={16} /> CSV 내보내기
                    </button>
                    <button onClick={fetchReport} className="flex items-center gap-2 px-4 py-2.5 bg-indigo-50 dark:bg-indigo-950/50 text-indigo-600 dark:text-indigo-400 rounded-xl text-sm font-bold hover:bg-indigo-100 dark:hover:bg-indigo-900/50 transition-colors border border-indigo-200 dark:border-indigo-800">
                        <RefreshCw size={16} /> 새로고침
                    </button>
                </div>
            </div>

            {/* KPI Cards */}
            <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-3">
                {[
                    { label: '등록 공간', value: summary.totalVenues, icon: Store, color: 'text-indigo-600 dark:text-indigo-400', bg: 'bg-indigo-50 dark:bg-indigo-950/40', borderColor: 'border-indigo-100 dark:border-indigo-800' },
                    { label: '운영 중', value: summary.activeVenues, icon: CheckCircle, color: 'text-emerald-600 dark:text-emerald-400', bg: 'bg-emerald-50 dark:bg-emerald-950/40', borderColor: 'border-emerald-100 dark:border-emerald-800' },
                    { label: '총 조회수', value: summary.totalViews?.toLocaleString(), icon: Eye, color: 'text-sky-600 dark:text-sky-400', bg: 'bg-sky-50 dark:bg-sky-950/40', borderColor: 'border-sky-100 dark:border-sky-800' },
                    { label: 'Total Applications수', value: summary.totalApps, icon: Users, color: 'text-violet-600 dark:text-violet-400', bg: 'bg-violet-50 dark:bg-violet-950/40', borderColor: 'border-violet-100 dark:border-violet-800' },
                    { label: '승인 수', value: summary.totalApproved, icon: CheckCircle, color: 'text-emerald-600 dark:text-emerald-400', bg: 'bg-green-50 dark:bg-green-950/40', borderColor: 'border-green-100 dark:border-green-800' },
                    { label: '전환율', value: `${summary.conversionRate}%`, icon: TrendingUp, color: 'text-amber-600 dark:text-amber-400', bg: 'bg-amber-50 dark:bg-amber-950/40', borderColor: 'border-amber-100 dark:border-amber-800' },
                ].map((kpi, i) => (
                    <div key={i} className={`${kpi.bg} rounded-2xl p-4 border ${kpi.borderColor}`}>
                        <div className="flex items-center gap-2 mb-2">
                            <kpi.icon size={16} className={kpi.color} />
                            <span className="text-xs font-bold text-gray-500 dark:text-gray-400 uppercase">{kpi.label}</span>
                        </div>
                        <p className="text-2xl font-extrabold text-gray-900 dark:text-white">{kpi.value}</p>
                    </div>
                ))}
            </div>

            {/* Tabs */}
            <div className="flex p-1 bg-gray-100/80 dark:bg-gray-800/80 rounded-xl overflow-x-auto">
                {tabs.map(tab => (
                    <button key={tab.id} onClick={() => setActiveTab(tab.id)}
                        className={`flex items-center gap-1.5 px-4 py-2 rounded-lg text-sm font-bold transition-all whitespace-nowrap
                            ${activeTab === tab.id ? 'bg-white dark:bg-gray-700 text-gray-900 dark:text-white shadow-sm' : 'text-gray-500 dark:text-gray-400'}`}>
                        <tab.icon size={14} /> {tab.label}
                    </button>
                ))}
            </div>

            {/* Overview Tab */}
            {activeTab === 'overview' && (
                <div className="space-y-6">
                    {/* Period Comparison */}
                    {previousPeriod && (
                        <div className="bg-white dark:bg-gray-900 rounded-2xl border border-gray-200 dark:border-gray-700 p-6">
                            <h3 className="text-sm font-bold text-gray-500 dark:text-gray-400 uppercase tracking-wider mb-4 flex items-center gap-2">
                                <Calendar size={14} /> vs Last Month 성과 비교
                            </h3>
                            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                                {[
                                    { label: '신청수', current: previousPeriod.currentApps, prev: previousPeriod.prevApps, growth: previousPeriod.appsGrowth, color: 'indigo' },
                                    { label: '승인수', current: previousPeriod.currentApproved, prev: previousPeriod.prevApproved, growth: previousPeriod.approvedGrowth, color: 'emerald' },
                                    { label: '전환율', current: `${previousPeriod.currentConversion}%`, prev: `${previousPeriod.prevConversion}%`, growth: previousPeriod.prevConversion > 0 ? parseFloat(((previousPeriod.currentConversion - previousPeriod.prevConversion) / previousPeriod.prevConversion * 100).toFixed(1)) : 0, color: 'amber' },
                                ].map((item, i) => (
                                    <div key={i} className="bg-gray-50 dark:bg-gray-800 rounded-xl p-4">
                                        <div className="flex items-center justify-between mb-3">
                                            <span className="text-xs font-bold text-gray-500 dark:text-gray-400 uppercase">{item.label}</span>
                                            <GrowthBadge value={item.growth} />
                                        </div>
                                        <div className="flex items-end gap-3">
                                            <div>
                                                <p className="text-xs text-gray-400 dark:text-gray-500">이번 달</p>
                                                <p className={`text-2xl font-extrabold text-${item.color}-600 dark:text-${item.color}-400`}>{item.current}</p>
                                            </div>
                                            <ArrowRight size={16} className="text-gray-300 dark:text-gray-600 mb-1.5" />
                                            <div>
                                                <p className="text-xs text-gray-400 dark:text-gray-500">지난 달</p>
                                                <p className="text-lg font-bold text-gray-400 dark:text-gray-500">{item.prev}</p>
                                            </div>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>
                    )}

                    {/* Conversion Funnel */}
                    <div className="bg-white dark:bg-gray-900 rounded-2xl border border-gray-200 dark:border-gray-700 p-6">
                        <h3 className="text-sm font-bold text-gray-500 dark:text-gray-400 uppercase tracking-wider mb-4 flex items-center gap-2">
                            <Activity size={14} /> 전환 퍼널
                        </h3>
                        <div className="flex items-center justify-center gap-0">
                            {[
                                { label: '조회', value: summary.totalViews, color: 'bg-sky-500', width: '100%' },
                                { label: '신청', value: summary.totalApps, color: 'bg-violet-500', width: summary.totalViews > 0 ? `${Math.max(Math.round(summary.totalApps / summary.totalViews * 100), 30)}%` : '60%' },
                                { label: '승인', value: summary.totalApproved, color: 'bg-emerald-500', width: summary.totalViews > 0 ? `${Math.max(Math.round(summary.totalApproved / summary.totalViews * 100), 20)}%` : '30%' },
                            ].map((step, i, arr) => {
                                const convRate = i > 0 && arr[i - 1].value > 0
                                    ? (step.value / arr[i - 1].value * 100).toFixed(1)
                                    : null;
                                return (
                                    <React.Fragment key={i}>
                                        <div className="flex-1 flex flex-col items-center">
                                            <span className="text-xs font-bold text-gray-500 dark:text-gray-400 mb-2">{step.label}</span>
                                            <div
                                                className={`${step.color} rounded-xl flex items-center justify-center transition-all duration-500`}
                                                style={{ width: step.width, height: '64px', minWidth: '80px' }}
                                            >
                                                <span className="text-white font-extrabold text-lg">{typeof step.value === 'number' ? step.value.toLocaleString() : step.value}</span>
                                            </div>
                                        </div>
                                        {i < arr.length - 1 && (
                                            <div className="flex flex-col items-center mx-1 flex-shrink-0">
                                                <ArrowRight size={20} className="text-gray-300 dark:text-gray-600" />
                                                {convRate && (
                                                    <span className="text-[10px] font-bold text-gray-400 dark:text-gray-500 mt-1">{convRate}%</span>
                                                )}
                                            </div>
                                        )}
                                    </React.Fragment>
                                );
                            })}
                        </div>
                    </div>

                    <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                        {/* Monthly Trend */}
                        <div className="bg-white dark:bg-gray-900 rounded-2xl border border-gray-200 dark:border-gray-700 p-6">
                            <h3 className="text-sm font-bold text-gray-500 dark:text-gray-400 uppercase tracking-wider mb-4 flex items-center gap-2">
                                <Calendar size={14} /> Monthly Application Trend
                            </h3>
                            {monthlyTrend.length > 0 ? (
                                <div className="space-y-3">
                                    {monthlyTrend.map((m, i) => (
                                        <div key={i} className="flex items-center gap-3">
                                            <span className="text-xs font-bold text-gray-500 dark:text-gray-400 w-16 flex-shrink-0">{m.month}</span>
                                            <div className="flex-1">
                                                <Bar value={m.count} max={Math.max(...monthlyTrend.map(t => t.count))} color="bg-indigo-500" />
                                            </div>
                                            <div className="flex items-center gap-2 flex-shrink-0">
                                                <span className="text-sm font-bold text-gray-700 dark:text-gray-300">{m.count} applications</span>
                                                <span className="text-xs text-emerald-600 dark:text-emerald-400 font-bold">{m.approved || 0} 승인</span>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            ) : (
                                <p className="text-gray-400 dark:text-gray-500 text-sm text-center py-8">데이터가 없습니다</p>
                            )}
                        </div>

                        {/* Category Distribution */}
                        <div className="bg-white dark:bg-gray-900 rounded-2xl border border-gray-200 dark:border-gray-700 p-6">
                            <h3 className="text-sm font-bold text-gray-500 dark:text-gray-400 uppercase tracking-wider mb-4 flex items-center gap-2">
                                <PieChart size={14} /> 신청자 카테고리 분포
                            </h3>
                            {appsByCategory.length > 0 ? (
                                <div className="space-y-3">
                                    {appsByCategory.map((cat, i) => (
                                        <div key={i} className="flex items-center gap-3">
                                            <span className="text-xs font-bold text-gray-600 dark:text-gray-400 w-24 flex-shrink-0 truncate">{getCatLabel(cat.category)}</span>
                                            <div className="flex-1">
                                                <Bar value={cat.count} max={appsByCategory[0]?.count || 1} color="bg-violet-500" />
                                            </div>
                                            <span className="text-sm font-bold text-gray-700 dark:text-gray-300 flex-shrink-0">{cat.count} applications</span>
                                        </div>
                                    ))}
                                </div>
                            ) : (
                                <p className="text-gray-400 dark:text-gray-500 text-sm text-center py-8">데이터가 없습니다</p>
                            )}
                        </div>

                        {/* Recent Applications */}
                        <div className="bg-white dark:bg-gray-900 rounded-2xl border border-gray-200 dark:border-gray-700 p-6 lg:col-span-2">
                            <h3 className="text-sm font-bold text-gray-500 dark:text-gray-400 uppercase tracking-wider mb-4 flex items-center gap-2">
                                <Clock size={14} /> 최근 신청 내역
                            </h3>
                            {recentApps.length > 0 ? (
                                <div className="space-y-2">
                                    {recentApps.map((app, i) => (
                                        <div key={i} className={`flex items-center justify-between p-3 rounded-xl ${app.is_priority == 1 ? 'bg-amber-50 dark:bg-amber-950/30 border border-amber-100 dark:border-amber-800' : 'bg-gray-50 dark:bg-gray-800'}`}>
                                            <div className="flex items-center gap-3 min-w-0">
                                                <div className={`w-2 h-2 rounded-full flex-shrink-0 ${app.status === 'approved' ? 'bg-emerald-500' : app.status === 'rejected' ? 'bg-red-500' : 'bg-yellow-500'}`} />
                                                <div className="min-w-0">
                                                    <div className="flex items-center gap-1.5">
                                                        {app.is_priority == 1 && <Zap size={11} className="text-amber-500" fill="currentColor" />}
                                                        <span className="text-sm font-bold text-gray-900 dark:text-white truncate">{app.seller_name}</span>
                                                    </div>
                                                    <span className="text-xs text-gray-500 dark:text-gray-400 truncate block">{app.venue_name} · {getCatLabel(app.seller_category)}</span>
                                                </div>
                                            </div>
                                            <div className="flex items-center gap-2 flex-shrink-0 ml-3">
                                                <span className={`px-2 py-0.5 rounded-full text-[10px] font-bold
                                                    ${app.status === 'approved' ? 'bg-emerald-100 dark:bg-emerald-900/50 text-emerald-700 dark:text-emerald-400' :
                                                        app.status === 'rejected' ? 'bg-red-100 dark:bg-red-900/50 text-red-700 dark:text-red-400' : 'bg-yellow-100 dark:bg-yellow-900/50 text-yellow-700 dark:text-yellow-400'}`}>
                                                    {app.status === 'approved' ? '승인' : app.status === 'rejected' ? '거절' : '대기'}
                                                </span>
                                                <span className="text-xs text-gray-400 dark:text-gray-500">{new Date(app.created_at).toLocaleDateString('ko-KR')}</span>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            ) : (
                                <p className="text-gray-400 dark:text-gray-500 text-sm text-center py-8">신청 내역이 없습니다</p>
                            )}
                        </div>
                    </div>
                </div>
            )}

            {/* Venues Tab */}
            {activeTab === 'venues' && (
                <div className="space-y-4">
                    {venues.length > 0 ? venues.map((v, i) => {
                        return (
                            <div key={v.id} className="bg-white dark:bg-gray-900 rounded-2xl border border-gray-200 dark:border-gray-700 p-5 hover:shadow-md dark:hover:shadow-gray-900/50 transition-shadow">
                                <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                                    <div className="min-w-0">
                                        <div className="flex items-center gap-2 mb-1">
                                            <h4 className="text-lg font-bold text-gray-900 dark:text-white truncate">{v.name}</h4>
                                            <span className={`px-2 py-0.5 rounded-full text-[10px] font-bold ${v.status === 'approved' ? 'bg-emerald-100 dark:bg-emerald-900/50 text-emerald-700 dark:text-emerald-400' : 'bg-gray-100 dark:bg-gray-800 text-gray-500 dark:text-gray-400'}`}>
                                                {v.status === 'approved' ? '운영 중' : v.status}
                                            </span>
                                        </div>
                                        <p className="text-xs text-gray-500 dark:text-gray-400">{v.location} · {v.type} · ₩{parseInt(v.price || 0).toLocaleString()}/{v.pricing_unit || '일'}</p>
                                    </div>
                                    <div className="flex items-center gap-4 flex-shrink-0">
                                        <div className="text-center">
                                            <p className="text-lg font-extrabold text-sky-600 dark:text-sky-400">{v.view_count}</p>
                                            <p className="text-[10px] text-gray-400 dark:text-gray-500 font-bold">조회</p>
                                        </div>
                                        <div className="text-center">
                                            <p className="text-lg font-extrabold text-violet-600 dark:text-violet-400">{v.app_count}</p>
                                            <p className="text-[10px] text-gray-400 dark:text-gray-500 font-bold">신청</p>
                                        </div>
                                        <div className="text-center">
                                            <p className="text-lg font-extrabold text-emerald-600 dark:text-emerald-400">{v.approved_count}</p>
                                            <p className="text-[10px] text-gray-400 dark:text-gray-500 font-bold">승인</p>
                                        </div>
                                        <div className="text-center">
                                            <p className={`text-lg font-extrabold ${v.conversion_rate >= 50 ? 'text-emerald-600 dark:text-emerald-400' : v.conversion_rate >= 20 ? 'text-amber-600 dark:text-amber-400' : 'text-gray-400 dark:text-gray-500'}`}>
                                                {v.conversion_rate}%
                                            </p>
                                            <p className="text-[10px] text-gray-400 dark:text-gray-500 font-bold">전환율</p>
                                        </div>
                                    </div>
                                </div>
                                {/* Progress Bar */}
                                <div className="mt-3">
                                    <div className="flex items-center gap-2 mb-1">
                                        <span className="text-[10px] font-bold text-gray-400 dark:text-gray-500">신청 현황</span>
                                        <div className="flex items-center gap-3 ml-auto">
                                            <span className="flex items-center gap-1 text-[10px] text-gray-600 dark:text-gray-400"><span className="w-2 h-2 rounded-full bg-emerald-500" /> 승인 {v.approved_count}</span>
                                            <span className="flex items-center gap-1 text-[10px] text-gray-600 dark:text-gray-400"><span className="w-2 h-2 rounded-full bg-yellow-500" /> 대기 {v.pending_count}</span>
                                            <span className="flex items-center gap-1 text-[10px] text-gray-600 dark:text-gray-400"><span className="w-2 h-2 rounded-full bg-red-400" /> 거절 {v.rejected_count}</span>
                                        </div>
                                    </div>
                                    <div className="w-full h-2.5 bg-gray-100 dark:bg-gray-700 rounded-full overflow-hidden flex">
                                        {v.app_count > 0 ? (
                                            <>
                                                <div className="bg-emerald-500 h-full transition-all" style={{ width: `${v.approved_count / v.app_count * 100}%` }} />
                                                <div className="bg-yellow-400 h-full transition-all" style={{ width: `${v.pending_count / v.app_count * 100}%` }} />
                                                <div className="bg-red-400 h-full transition-all" style={{ width: `${v.rejected_count / v.app_count * 100}%` }} />
                                            </>
                                        ) : (
                                            <div className="bg-gray-200 dark:bg-gray-600 h-full w-full" />
                                        )}
                                    </div>
                                </div>
                            </div>
                        );
                    }) : (
                        <div className="text-center py-16">
                            <Store className="mx-auto text-gray-300 dark:text-gray-600 mb-3" size={40} />
                            <p className="text-gray-400 dark:text-gray-500 font-medium">등록된 공간이 없습니다</p>
                        </div>
                    )}
                </div>
            )}

            {/* Trends Tab */}
            {activeTab === 'trends' && (
                <div className="space-y-6">
                    {/* Weekday Heatmap */}
                    {weekdayStats && weekdayStats.length > 0 && (
                        <div className="bg-white dark:bg-gray-900 rounded-2xl border border-gray-200 dark:border-gray-700 p-6">
                            <h3 className="text-sm font-bold text-gray-500 dark:text-gray-400 uppercase tracking-wider mb-4 flex items-center gap-2">
                                <Calendar size={14} /> 요일별 신청 패턴
                                <span className="text-[10px] font-medium text-gray-400 dark:text-gray-500 normal-case tracking-normal ml-1">최근 3개월</span>
                            </h3>
                            <div className="grid grid-cols-7 gap-2 mb-4">
                                {(() => {
                                    const maxCount = Math.max(...weekdayStats.map(d => d.count), 1);
                                    return weekdayStats.map((d, i) => {
                                        const intensity = d.count / maxCount;
                                        const bgClass = intensity >= 0.8 ? 'bg-indigo-600 text-white' :
                                            intensity >= 0.5 ? 'bg-indigo-400 text-white' :
                                                intensity >= 0.2 ? 'bg-indigo-200 dark:bg-indigo-800 text-indigo-800 dark:text-indigo-200' :
                                                    'bg-gray-100 dark:bg-gray-800 text-gray-500 dark:text-gray-400';
                                        return (
                                            <div key={i} className={`rounded-xl p-3 text-center transition-all ${bgClass}`}>
                                                <p className="text-xs font-bold mb-1">{d.day}</p>
                                                <p className="text-xl font-extrabold">{d.count}</p>
                                                <p className="text-[10px] opacity-70"> applications</p>
                                            </div>
                                        );
                                    });
                                })()}
                            </div>
                            {/* Auto insight */}
                            {(() => {
                                const maxDay = weekdayStats.reduce((max, d) => d.count > max.count ? d : max, weekdayStats[0]);
                                const minDay = weekdayStats.reduce((min, d) => d.count < min.count ? d : min, weekdayStats[0]);
                                const total = weekdayStats.reduce((s, d) => s + d.count, 0);
                                if (total === 0) return null;
                                return (
                                    <div className="bg-indigo-50 dark:bg-indigo-950/30 rounded-xl p-3 border border-indigo-100 dark:border-indigo-800">
                                        <p className="text-xs text-gray-700 dark:text-gray-300">
                                            💡 <strong className="text-indigo-600 dark:text-indigo-400">{maxDay.day}요일</strong>에 가장 많은 신청({maxDay.count} applications)이 들어오고,
                                            <strong className="text-gray-500 dark:text-gray-400"> {minDay.day}요일</strong>이 가장 적습니다({minDay.count} applications).
                                        </p>
                                    </div>
                                );
                            })()}
                        </div>
                    )}

                    {/* Venue Performance Ranking */}
                    <div className="bg-white dark:bg-gray-900 rounded-2xl border border-gray-200 dark:border-gray-700 p-6">
                        <h3 className="text-sm font-bold text-gray-500 dark:text-gray-400 uppercase tracking-wider mb-4 flex items-center gap-2">
                            <Trophy size={14} /> 공간 성과 순위
                        </h3>
                        {venueRanking.length > 0 ? (
                            <div className="space-y-2">
                                {venueRanking.map((v, i) => (
                                    <div key={v.id} className="flex items-center gap-4 p-3 bg-gray-50 dark:bg-gray-800 rounded-xl">
                                        <span className={`w-7 h-7 rounded-lg flex items-center justify-center text-xs font-extrabold flex-shrink-0
                                            ${i === 0 ? 'bg-yellow-100 dark:bg-yellow-900/50 text-yellow-700 dark:text-yellow-400' : i === 1 ? 'bg-gray-200 dark:bg-gray-700 text-gray-600 dark:text-gray-300' : i === 2 ? 'bg-amber-100 dark:bg-amber-900/50 text-amber-700 dark:text-amber-400' : 'bg-gray-100 dark:bg-gray-700 text-gray-500 dark:text-gray-400'}`}>
                                            {i + 1}
                                        </span>
                                        <div className="flex-1 min-w-0">
                                            <p className="text-sm font-bold text-gray-900 dark:text-white truncate">{v.name}</p>
                                            <p className="text-xs text-gray-500 dark:text-gray-400">{v.location}</p>
                                        </div>
                                        <div className="flex items-center gap-4 flex-shrink-0">
                                            <div className="flex items-center gap-1 text-xs">
                                                <Eye size={12} className="text-sky-500 dark:text-sky-400" />
                                                <span className="font-bold text-gray-700 dark:text-gray-300">{v.view_count}</span>
                                            </div>
                                            <div className="flex items-center gap-1 text-xs">
                                                <Users size={12} className="text-violet-500 dark:text-violet-400" />
                                                <span className="font-bold text-gray-700 dark:text-gray-300">{v.app_count}</span>
                                            </div>
                                            <div className="flex items-center gap-1 text-xs">
                                                <TrendingUp size={12} className={v.conversion_rate >= 50 ? 'text-emerald-500 dark:text-emerald-400' : 'text-gray-400 dark:text-gray-500'} />
                                                <span className="font-bold text-gray-700 dark:text-gray-300">{v.conversion_rate}%</span>
                                            </div>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        ) : (
                            <p className="text-gray-400 dark:text-gray-500 text-sm text-center py-8">데이터가 없습니다</p>
                        )}
                    </div>

                    {/* Tips */}
                    <div className="bg-gradient-to-br from-indigo-50 to-violet-50 dark:from-gray-800 dark:to-gray-800 rounded-2xl border border-indigo-100 dark:border-gray-700 p-6">
                        <h3 className="text-sm font-bold text-indigo-600 dark:text-indigo-400 uppercase tracking-wider mb-3">💡 성과 개선 팁</h3>
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                            {[
                                { title: '사진을 추가하세요', desc: '사진이 5장 이상인 공간은 신청률이 평균 2배 높습니다.', icon: '📷' },
                                { title: '가격을 검토하세요', desc: '시세보다 10~20% 낮은 가격대가 가장 높은 전환율을 보입니다.', icon: '💰' },
                                { title: '빠른 응답이 핵심', desc: '24시간 내 승인/거절 응답하면 재신청률이 3배 높아집니다.', icon: '⚡' },
                            ].map((tip, i) => (
                                <div key={i} className="bg-white/60 dark:bg-gray-900/60 backdrop-blur rounded-xl p-4">
                                    <span className="text-2xl">{tip.icon}</span>
                                    <h4 className="text-sm font-bold text-gray-900 dark:text-white mt-2">{tip.title}</h4>
                                    <p className="text-xs text-gray-600 dark:text-gray-400 mt-1 leading-relaxed">{tip.desc}</p>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default HostAnalyticsReport;

import React, { useState, useEffect } from 'react';
import { useAuth } from '../../context/AuthContext';
import { useNavigate } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { Store, MessageSquare, CheckCircle, XCircle, ChevronDown, ChevronLeft, ChevronRight, Mail, Phone, Instagram, Search, Calendar, Clock, Tag, AlertTriangle, X, Paperclip, FileText, Download, Eye, User, ImageIcon, Zap, BadgeCheck, MessageCircle } from 'lucide-react';
import { useDemoGuard } from '../../hooks/useDemoGuard';

const API_BASE = '/api';

const HostApplications = () => {
    const { user } = useAuth();
    const navigate = useNavigate();
    const { t } = useTranslation('host');
    const { isDemoUser, demoAlert } = useDemoGuard();

    const CATEGORY_LABELS = {
        fashion: t('applicationsPage.catFashion'), beauty: t('applicationsPage.catBeauty'), food: t('applicationsPage.catFood'),
        living: t('applicationsPage.catLiving'), art: t('applicationsPage.catArt'), stationery: t('applicationsPage.catStationery'),
        digital: t('applicationsPage.catDigital'), activity: t('applicationsPage.catActivity'), eco: t('applicationsPage.catEco'),
        pet: t('applicationsPage.catPet'), kids: t('applicationsPage.catKids'), handmade: t('applicationsPage.catHandmade'),
        vintage: t('applicationsPage.catVintage'), perfume: t('applicationsPage.catPerfume'), book: t('applicationsPage.catBook')
    };

    const timeAgo = (dateStr) => {
        const diff = Date.now() - new Date(dateStr).getTime();
        const mins = Math.floor(diff / 60000);
        if (mins < 60) return t('applicationsPage.minutesAgo', { count: mins });
        const hrs = Math.floor(mins / 60);
        if (hrs < 24) return t('applicationsPage.hoursAgo', { count: hrs });
        const days = Math.floor(hrs / 24);
        if (days < 7) return t('applicationsPage.daysAgo', { count: days });
        return new Date(dateStr).toLocaleDateString('ko-KR');
    };

    const calcExperience = (joinedAt) => {
        if (!joinedAt) return null;
        const diff = Date.now() - new Date(joinedAt).getTime();
        const months = Math.floor(diff / (1000 * 60 * 60 * 24 * 30));
        if (months < 1) return t('applicationsPage.experienceNew');
        if (months < 12) return t('applicationsPage.experienceMonths', { count: months });
        const years = Math.floor(months / 12);
        const rem = months % 12;
        return rem > 0 ? t('applicationsPage.experienceYearsMonths', { years, months: rem }) : t('applicationsPage.experienceYears', { years });
    };
    const [applications, setApplications] = useState([]);
    const [loading, setLoading] = useState(true);
    const [appFilterCategory, setAppFilterCategory] = useState('all');
    const [appFilterStatus, setAppFilterStatus] = useState('all');
    const [expandedId, setExpandedId] = useState(null);
    const [searchQuery, setSearchQuery] = useState('');

    // Confirm modal state
    const [confirmModal, setConfirmModal] = useState(null);
    const [rejectionReason, setRejectionReason] = useState('');
    // Toast notification state
    const [toast, setToast] = useState(null);
    // Seller detail modal state
    const [sellerDetail, setSellerDetail] = useState(null);
    const [sellerDetailLoading, setSellerDetailLoading] = useState(false);
    // Lightbox state  
    const [lightboxPhotos, setLightboxPhotos] = useState([]);
    const [lightboxIndex, setLightboxIndex] = useState(0);
    // Priority viewing subscription state
    const [hasViewingSub, setHasViewingSub] = useState(false);

    const showToast = (message, type = 'success') => {
        setToast({ message, type });
        setTimeout(() => setToast(null), 3000);
    };

    const fetchApplications = () => {
        setLoading(true);
        fetch(`${API_BASE}/applications/get_applications.php`, { credentials: 'include' })
            .then(res => res.json())
            .then(data => {
                if (Array.isArray(data)) setApplications(data);
            })
            .catch(err => console.error(err))
            .finally(() => setLoading(false));
    };

    useEffect(() => { fetchApplications(); }, []);

    // Check priority_viewing subscription
    useEffect(() => {
        fetch(`${API_BASE}/payments/check_subscription.php?category=priority_viewing`, { credentials: 'include' })
            .then(r => r.json())
            .then(d => { if (d.active) setHasViewingSub(true); })
            .catch(() => { });
    }, []);

    const fetchSellerDetail = async (userId) => {
        setSellerDetailLoading(true);
        try {
            const res = await fetch(`${API_BASE}/users/get_public_profile.php?id=${userId}`, { credentials: 'include' });
            const data = await res.json();
            if (data.success) {
                setSellerDetail(data);
            }
        } catch (err) {
            console.error(err);
        } finally {
            setSellerDetailLoading(false);
        }
    };

    const handleApplicationAction = (appId, status, applicantName) => {
        if (isDemoUser) { demoAlert(status === 'approved' ? '신청 승인' : '신청 거절'); return; }
        const isApprove = status === 'approved';
        setRejectionReason('');
        setConfirmModal({
            title: isApprove ? t('applicationsPage.approveTitle') : t('applicationsPage.rejectTitle'),
            message: isApprove ? t('applicationsPage.approveConfirm', { name: applicantName || '' }) : t('applicationsPage.rejectConfirm', { name: applicantName || '' }),
            type: isApprove ? 'success' : 'danger',
            confirmLabel: isApprove ? t('applicationsPage.approveLabel') : t('applicationsPage.rejectLabel'),
            showRejectionReason: !isApprove,
            onConfirm: (reason) => {
                const body = { id: appId, status: status };
                if (!isApprove && reason) {
                    body.rejection_reason = reason;
                }
                fetch(`${API_BASE}/applications/update_status.php`, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    credentials: 'include',
                    body: JSON.stringify(body)
                })
                    .then(res => res.json())
                    .then(data => {
                        if (data.success) {
                            showToast(isApprove ? t('applicationsPage.toastApproved') : t('applicationsPage.toastRejected'), 'success');
                            fetchApplications();
                        } else {
                            showToast(t('applicationsPage.toastFailed') + data.message, 'error');
                        }
                    })
                    .catch(() => showToast(t('applicationsPage.toastError'), 'error'));
                setConfirmModal(null);
                setRejectionReason('');
            }
        });
    };

    // Stats
    const pendingApps = applications.filter(a => a.status === 'pending').length;
    const approvedApps = applications.filter(a => a.status === 'approved').length;
    const rejectedApps = applications.filter(a => a.status === 'rejected').length;

    // Filtered
    const filteredApplications = applications.filter(app => {
        const matchesCategory = appFilterCategory === 'all' || app.applicant_category === appFilterCategory ||
            (appFilterCategory === 'other' && !Object.keys(CATEGORY_LABELS).includes(app.applicant_category));
        const matchesStatus = appFilterStatus === 'all' || app.status === appFilterStatus;

        // Search by name, brand, keywords, email
        let matchesSearch = true;
        if (searchQuery.trim()) {
            const q = searchQuery.toLowerCase();
            const nameMatch = (app.applicant_name || '').toLowerCase().includes(q);
            const brandMatch = (app.applicant_brand || '').toLowerCase().includes(q);
            const emailMatch = (app.applicant_email || '').toLowerCase().includes(q);
            const venueMatch = (app.venue_name || '').toLowerCase().includes(q);
            const kwMatch = Array.isArray(app.applicant_keywords) && app.applicant_keywords.some(kw => kw.toLowerCase().includes(q));
            const catMatch = (CATEGORY_LABELS[app.applicant_category] || app.applicant_category || '').toLowerCase().includes(q);
            matchesSearch = nameMatch || brandMatch || emailMatch || venueMatch || kwMatch || catMatch;
        }

        return matchesCategory && matchesStatus && matchesSearch;
    });

    if (loading) {
        return (
            <div className="flex justify-center items-center min-h-[400px]">
                <div className="animate-spin rounded-full h-10 w-10 border-2 border-indigo-200 border-t-indigo-600"></div>
            </div>
        );
    }

    return (
        <div className="space-y-6 pb-20 max-w-4xl mx-auto">
            {/* Header */}
            <div>
                <h1 className="text-2xl font-extrabold text-gray-900">{t('applicationsPage.title')}</h1>
                <p className="text-sm text-gray-500 mt-1">{t('applicationsPage.subtitle')}</p>
            </div>

            {/* Stats */}
            <div className="grid grid-cols-4 gap-3">
                {[
                    { label: t('applicationsPage.statsAll'), count: applications.length, color: 'text-gray-900', bg: 'bg-white border-gray-200' },
                    { label: t('applicationsPage.statsPending'), count: pendingApps, color: 'text-amber-600', bg: 'bg-amber-50 border-amber-200' },
                    { label: t('applicationsPage.statsApproved'), count: approvedApps, color: 'text-emerald-600', bg: 'bg-emerald-50 border-emerald-200' },
                    { label: t('applicationsPage.statsRejected'), count: rejectedApps, color: 'text-red-500', bg: 'bg-red-50 border-red-200' },
                ].map(s => (
                    <div key={s.label} className={`${s.bg} rounded-xl p-3 border text-center`}>
                        <p className={`text-2xl font-extrabold ${s.color}`}>{s.count}</p>
                        <p className="text-[11px] font-bold text-gray-500 mt-0.5">{s.label}</p>
                    </div>
                ))}
            </div>

            {/* Search + Filter */}
            <div className="space-y-3">
                {/* Search Bar */}
                <div className="relative">
                    <Search size={16} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-gray-400" />
                    <input
                        type="text"
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        placeholder={t('applicationsPage.searchPlaceholder')}
                        className="w-full pl-10 pr-4 py-2.5 border border-gray-200 rounded-xl text-sm focus:ring-2 focus:ring-indigo-500 focus:border-indigo-400 outline-none bg-white"
                    />
                </div>

                <div className="flex items-center justify-between">
                    <p className="text-sm font-bold text-gray-700">
                        {t('applicationsPage.resultCount', { count: filteredApplications.length })}
                    </p>
                    <div className="flex gap-2">
                        <select value={appFilterStatus} onChange={(e) => setAppFilterStatus(e.target.value)}
                            className="px-3 py-1.5 border border-gray-200 rounded-lg bg-white text-xs font-medium outline-none focus:ring-2 focus:ring-indigo-500 cursor-pointer">
                            <option value="all">{t('applicationsPage.filterAllStatus')}</option>
                            <option value="pending">{t('applicationsPage.filterPending')}</option>
                            <option value="approved">{t('applicationsPage.filterApproved')}</option>
                            <option value="rejected">{t('applicationsPage.filterRejected')}</option>
                        </select>
                        <select value={appFilterCategory} onChange={(e) => setAppFilterCategory(e.target.value)}
                            className="px-3 py-1.5 border border-gray-200 rounded-lg bg-white text-xs font-medium outline-none focus:ring-2 focus:ring-indigo-500 cursor-pointer">
                            <option value="all">{t('applicationsPage.filterAllCategory')}</option>
                            <option value="fashion">{t('applicationsPage.catFashion')}</option>
                            <option value="beauty">{t('applicationsPage.catBeauty')}</option>
                            <option value="food">{t('applicationsPage.catFood')}</option>
                            <option value="living">{t('applicationsPage.catLiving')}</option>
                            <option value="art">{t('applicationsPage.catArt')}</option>
                            <option value="other">{t('applicationsPage.catOther')}</option>
                        </select>
                    </div>
                </div>
            </div>

            {/* Application List */}
            {filteredApplications.length === 0 ? (
                <div className="bg-white rounded-2xl border border-gray-100 p-16 text-center">
                    <MessageSquare className="w-10 h-10 mx-auto text-gray-300 mb-3" />
                    <p className="text-gray-400 font-medium text-sm">{t('applicationsPage.noApplications')}</p>
                </div>
            ) : (
                <div className="space-y-3">
                    {filteredApplications.map(app => {
                        const initial = (app.applicant_name || '?')[0];
                        const isExpanded = expandedId === app.id;
                        const experience = calcExperience(app.applicant_joined_at);
                        const keywords = Array.isArray(app.applicant_keywords) ? app.applicant_keywords : [];
                        const statusConfig = {
                            pending: { label: t('applicationsPage.statusPendingLabel'), dot: 'bg-amber-400', text: 'text-amber-700', bg: 'bg-amber-50' },
                            approved: { label: t('applicationsPage.statusApprovedLabel'), dot: 'bg-emerald-400', text: 'text-emerald-700', bg: 'bg-emerald-50' },
                            rejected: { label: t('applicationsPage.statusRejectedLabel'), dot: 'bg-red-400', text: 'text-red-600', bg: 'bg-red-50' },
                        }[app.status] || { label: app.status, dot: 'bg-gray-400', text: 'text-gray-600', bg: 'bg-gray-50' };

                        return (
                            <div key={app.id} className={`bg-white rounded-2xl border transition-all duration-200 ${app.is_priority ? 'border-amber-300 shadow-md ring-1 ring-amber-200/50' : app.status === 'pending' ? 'border-amber-200 shadow-sm' : 'border-gray-100'}`}>
                                {/* Priority Badge Bar */}
                                {app.is_priority ? (
                                    <div className="px-4 py-1.5 bg-gradient-to-r from-amber-400 to-yellow-400 flex items-center gap-1.5 rounded-t-2xl">
                                        <Zap size={12} className="text-white" fill="white" />
                                        <span className="text-white text-[11px] font-extrabold tracking-wide">{t('applicationsPage.fastTrack')}</span>
                                    </div>
                                ) : null}
                                {/* Summary Row */}
                                <div
                                    className="p-4 cursor-pointer hover:bg-gray-50/50 transition-colors rounded-2xl"
                                    onClick={() => setExpandedId(isExpanded ? null : app.id)}
                                >
                                    <div className="flex items-center gap-3">
                                        <div className={`w-11 h-11 rounded-xl flex items-center justify-center text-white text-base font-extrabold flex-shrink-0 ${app.status === 'pending'
                                            ? 'bg-gradient-to-br from-amber-400 to-orange-500'
                                            : app.status === 'approved'
                                                ? 'bg-gradient-to-br from-emerald-400 to-teal-500'
                                                : 'bg-gradient-to-br from-gray-300 to-gray-400'
                                            }`}>
                                            {initial}
                                        </div>
                                        <div className="flex-1 min-w-0">
                                            <div className="flex items-center gap-2">
                                                <h4 className="font-bold text-gray-900 text-sm truncate cursor-pointer hover:text-indigo-600 transition-colors"
                                                    onClick={(e) => { e.stopPropagation(); if (app.user_id) fetchSellerDetail(app.user_id); }}>
                                                    {app.applicant_name || t('applicationsPage.noName')}
                                                </h4>
                                                {app.is_verified ? (
                                                    <span className="inline-flex items-center gap-0.5 px-1.5 py-0.5 bg-emerald-50 text-emerald-600 border border-emerald-200 rounded-full text-[9px] font-extrabold flex-shrink-0">
                                                        <BadgeCheck size={9} /> {t('applicationsPage.verified')}
                                                    </span>
                                                ) : null}
                                                {app.applicant_brand && (
                                                    <span className="text-xs text-indigo-500 font-medium hidden sm:inline truncate">{app.applicant_brand}</span>
                                                )}
                                            </div>
                                            <div className="flex items-center gap-1.5 mt-0.5">
                                                <Store size={11} className="text-gray-400 flex-shrink-0" />
                                                <span className="text-xs text-gray-500 truncate">{app.venue_name}</span>
                                                <span className="text-gray-300 text-xs">·</span>
                                                <span className="text-xs text-gray-400 flex-shrink-0">{timeAgo(app.created_at)}</span>
                                            </div>
                                            {app.selected_period && (
                                                <div className="flex items-center gap-1 mt-0.5">
                                                    <Calendar size={10} className="text-amber-500 flex-shrink-0" />
                                                    <span className="text-[11px] text-amber-600 font-medium truncate">
                                                        {app.selected_period.start ? new Date(app.selected_period.start).toLocaleDateString('ko-KR') : ''} ~ {app.selected_period.end ? new Date(app.selected_period.end).toLocaleDateString('ko-KR') : ''}
                                                    </span>
                                                </div>
                                            )}
                                        </div>
                                        <div className="flex items-center gap-2 flex-shrink-0">
                                            <span className={`px-2 py-0.5 rounded-md text-[11px] font-bold ${statusConfig.bg} ${statusConfig.text} hidden sm:inline-flex items-center gap-1`}>
                                                <span className={`w-1.5 h-1.5 rounded-full ${statusConfig.dot}`}></span>
                                                {statusConfig.label}
                                            </span>
                                            <span className={`w-2 h-2 rounded-full ${statusConfig.dot} sm:hidden`}></span>
                                            <ChevronDown size={16} className={`text-gray-400 transition-transform duration-200 ${isExpanded ? 'rotate-180' : ''}`} />
                                        </div>
                                    </div>
                                </div>

                                {/* Expanded Detail */}
                                {isExpanded && (
                                    <div className="px-4 pb-4 border-t border-gray-100">
                                        <div className="pt-4 grid grid-cols-1 md:grid-cols-2 gap-4">
                                            {/* Left: Message + Actions (moved to top) */}
                                            <div className="space-y-3">
                                                <p className="text-[11px] font-bold text-gray-400 uppercase tracking-wider">{t('applicationsPage.applicationMessage')}</p>
                                                <div className="p-3.5 bg-gray-50 rounded-xl min-h-[80px]">
                                                    <p className={`text-sm leading-relaxed ${app.message ? 'text-gray-700' : 'text-gray-400 italic'}`}>
                                                        {app.message || t('applicationsPage.noMessage')}
                                                    </p>
                                                </div>

                                                {/* Attachments */}
                                                {(() => {
                                                    let atts = [];
                                                    try {
                                                        atts = typeof app.attachments === 'string' ? JSON.parse(app.attachments) : (app.attachments || []);
                                                    } catch { }
                                                    if (!Array.isArray(atts) || atts.length === 0) return null;
                                                    return (
                                                        <div className="pt-2">
                                                            <p className="text-[11px] font-bold text-gray-400 uppercase tracking-wider mb-1.5">{t('applicationsPage.attachments')}</p>
                                                            <div className="space-y-1.5">
                                                                {atts.map((att, i) => (
                                                                    <a key={i} href={`/${att}`} target="_blank" rel="noreferrer"
                                                                        className="flex items-center gap-2 p-2 bg-indigo-50 rounded-lg border border-indigo-100 hover:bg-indigo-100 transition-colors"
                                                                    >
                                                                        <FileText size={14} className="text-indigo-500 flex-shrink-0" />
                                                                        <span className="text-xs font-medium text-indigo-700 flex-1 truncate">{att.split('/').pop()}</span>
                                                                        <Download size={12} className="text-indigo-400 flex-shrink-0" />
                                                                    </a>
                                                                ))}
                                                            </div>
                                                        </div>
                                                    );
                                                })()}

                                                {app.status === 'pending' && (
                                                    <div className="flex gap-2 pt-1">
                                                        <button
                                                            onClick={(e) => { e.stopPropagation(); handleApplicationAction(app.id, 'approved', app.applicant_name); }}
                                                            className="flex-1 py-2.5 bg-indigo-600 text-white rounded-xl text-sm font-bold hover:bg-indigo-700 transition-colors flex items-center justify-center gap-1.5 shadow-sm"
                                                        >
                                                            <CheckCircle size={15} />
                                                            {t('applicationsPage.approve')}
                                                        </button>
                                                        <button
                                                            onClick={(e) => { e.stopPropagation(); handleApplicationAction(app.id, 'rejected', app.applicant_name); }}
                                                            className="flex-1 py-2.5 bg-white border border-gray-200 text-gray-600 rounded-xl text-sm font-bold hover:bg-red-50 hover:text-red-600 hover:border-red-200 transition-colors flex items-center justify-center gap-1.5"
                                                        >
                                                            <XCircle size={15} />
                                                            {t('applicationsPage.reject')}
                                                        </button>
                                                    </div>
                                                )}
                                                {app.status === 'approved' && (
                                                    (() => {
                                                        let canReject = true;
                                                        let deadlineMsg = '';
                                                        if (app.selected_period?.start) {
                                                            const eventStart = new Date(app.selected_period.start);
                                                            const now = new Date();
                                                            const diffMs = eventStart - now;
                                                            const diffDays = Math.ceil(diffMs / (1000 * 60 * 60 * 24));
                                                            if (diffDays < 3) {
                                                                canReject = false;
                                                                deadlineMsg = t('applicationsPage.deadlineWarning');
                                                            }
                                                        }
                                                        return (
                                                            <div className="space-y-2">
                                                                <div className="p-2.5 text-center bg-emerald-50 rounded-xl">
                                                                    <p className="text-xs font-bold text-emerald-600">{t('applicationsPage.approvedMessage')}</p>
                                                                </div>
                                                                {/* Chat with approved seller */}
                                                                <button
                                                                    onClick={(e) => { e.stopPropagation(); navigate(`/host/chat?user=${app.user_id}`); }}
                                                                    className="w-full py-2.5 bg-gradient-to-r from-indigo-500 to-violet-500 text-white rounded-xl text-xs font-bold hover:from-indigo-400 hover:to-violet-400 transition-all flex items-center justify-center gap-1.5 shadow-sm"
                                                                >
                                                                    <MessageCircle size={14} /> 채팅하기
                                                                </button>
                                                                {canReject ? (
                                                                    <button
                                                                        onClick={(e) => { e.stopPropagation(); handleApplicationAction(app.id, 'rejected', app.applicant_name); }}
                                                                        className="w-full py-2 bg-white border border-red-200 text-red-500 rounded-xl text-xs font-bold hover:bg-red-50 transition-colors flex items-center justify-center gap-1"
                                                                    >
                                                                        <XCircle size={13} />
                                                                        {t('applicationsPage.cancelApproval')}
                                                                    </button>
                                                                ) : (
                                                                    <p className="text-[11px] text-red-400 text-center font-medium">{deadlineMsg}</p>
                                                                )}
                                                            </div>
                                                        );
                                                    })()
                                                )}
                                                {app.status === 'rejected' && (
                                                    <div className="space-y-2">
                                                        <div className="p-2.5 text-center bg-red-50 rounded-xl">
                                                            <p className="text-xs font-bold text-red-500">{t('applicationsPage.rejectedMessage')}</p>
                                                        </div>
                                                        {app.rejection_reason && (
                                                            <div className="p-3 bg-red-50/50 border border-red-100 rounded-xl">
                                                                <p className="text-[10px] font-bold text-red-400 uppercase tracking-wider mb-1">{t('applicationsPage.rejectionReason')}</p>
                                                                <p className="text-sm text-red-600 leading-relaxed">{app.rejection_reason}</p>
                                                            </div>
                                                        )}
                                                    </div>
                                                )}
                                            </div>

                                            {/* Right: Seller Profile (subscription gated) */}
                                            <div className="space-y-3 relative">
                                                {!hasViewingSub && (
                                                    <div className="absolute inset-0 z-10 flex flex-col items-center justify-center bg-white/80 backdrop-blur-sm rounded-xl">
                                                        <div className="text-center p-6">
                                                            <div className="w-12 h-12 mx-auto mb-3 bg-gradient-to-br from-violet-100 to-indigo-100 rounded-2xl flex items-center justify-center">
                                                                <Eye size={24} className="text-indigo-500" />
                                                            </div>
                                                            <p className="text-sm font-bold text-gray-800 mb-1">{t('applicationsPage.sellerDetailView')}</p>
                                                            <p className="text-xs text-gray-500 mb-3" dangerouslySetInnerHTML={{ __html: t('applicationsPage.sellerDetailSubscribe').replace('\n', '<br />') }} />
                                                            <a href="/host/payments" className="inline-flex items-center gap-1.5 px-4 py-2 bg-gradient-to-r from-indigo-600 to-violet-600 text-white rounded-xl text-xs font-bold hover:opacity-90 transition-opacity">
                                                                {t('applicationsPage.subscribe')}
                                                            </a>
                                                        </div>
                                                    </div>
                                                )}
                                                <p className="text-[11px] font-bold text-gray-400 uppercase tracking-wider">{t('applicationsPage.sellerDetailInfo')}</p>

                                                {/* Info Items */}
                                                <div className="space-y-2">
                                                    <div className="flex items-center gap-3 text-sm">
                                                        <Tag size={14} className="text-indigo-400 flex-shrink-0" />
                                                        <span className="text-gray-500 w-16 flex-shrink-0">{t('applicationsPage.salesCategory')}</span>
                                                        <span className="font-medium text-gray-800">{CATEGORY_LABELS[app.applicant_category] || app.applicant_category || t('applicationsPage.notEntered')}</span>
                                                    </div>
                                                    <div className="flex items-center gap-3 text-sm">
                                                        <Mail size={14} className="text-gray-400 flex-shrink-0" />
                                                        <span className="text-gray-500 w-16 flex-shrink-0">{t('applicationsPage.email')}</span>
                                                        <span className="text-gray-700">{app.applicant_email || '-'}</span>
                                                    </div>
                                                    <div className="flex items-center gap-3 text-sm">
                                                        <Phone size={14} className="text-gray-400 flex-shrink-0" />
                                                        <span className="text-gray-500 w-16 flex-shrink-0">{t('applicationsPage.phone')}</span>
                                                        <span className="text-gray-700">{app.applicant_phone || t('applicationsPage.notProvided')}</span>
                                                    </div>
                                                    {app.applicant_instagram && (
                                                        <div className="flex items-center gap-3 text-sm">
                                                            <Instagram size={14} className="text-pink-400 flex-shrink-0" />
                                                            <span className="text-gray-500 w-16 flex-shrink-0">{t('applicationsPage.instagram')}</span>
                                                            <a href={`https://instagram.com/${app.applicant_instagram.replace('@', '')}`}
                                                                target="_blank" rel="noopener noreferrer"
                                                                className="text-pink-600 font-medium hover:underline">
                                                                @{app.applicant_instagram.replace('@', '')}
                                                            </a>
                                                        </div>
                                                    )}
                                                    <div className="flex items-center gap-3 text-sm">
                                                        <Clock size={14} className="text-gray-400 flex-shrink-0" />
                                                        <span className="text-gray-500 w-16 flex-shrink-0">{t('applicationsPage.activityPeriod')}</span>
                                                        <span className="text-gray-700">{experience || '-'}</span>
                                                    </div>
                                                    <div className="flex items-center gap-3 text-sm">
                                                        <Calendar size={14} className="text-gray-400 flex-shrink-0" />
                                                        <span className="text-gray-500 w-16 flex-shrink-0">{t('applicationsPage.participationDate')}</span>
                                                        <span className="text-gray-700">{app.created_at ? new Date(app.created_at).toLocaleDateString('ko-KR') : '-'}</span>
                                                    </div>
                                                    {/* Selected Event Period */}
                                                    {app.selected_period && (
                                                        <div className="mt-2 p-2.5 bg-amber-50 border border-amber-100 rounded-xl">
                                                            <div className="flex items-center gap-2 text-sm">
                                                                <Calendar size={14} className="text-amber-500 flex-shrink-0" />
                                                                <span className="text-amber-700 font-medium">{t('applicationsPage.desiredEventPeriod')}</span>
                                                                <span className="font-bold text-gray-800">
                                                                    {app.selected_period.start ? new Date(app.selected_period.start).toLocaleDateString('ko-KR') : t('applicationsPage.undecided')}
                                                                    {' ~ '}
                                                                    {app.selected_period.end ? new Date(app.selected_period.end).toLocaleDateString('ko-KR') : t('applicationsPage.undecided')}
                                                                </span>
                                                            </div>
                                                        </div>
                                                    )}
                                                </div>

                                                {/* Keywords */}
                                                {keywords.length > 0 && (
                                                    <div className="pt-1">
                                                        <p className="text-[10px] font-bold text-gray-400 mb-1.5">{t('applicationsPage.keywords')}</p>
                                                        <div className="flex flex-wrap gap-1.5">
                                                            {keywords.map((kw, i) => (
                                                                <span key={i} className="px-2 py-0.5 bg-indigo-50 text-indigo-600 rounded-md text-[11px] font-bold">{kw}</span>
                                                            ))}
                                                        </div>
                                                    </div>
                                                )}

                                                {/* Bio */}
                                                {app.applicant_description && (
                                                    <div className="p-3 bg-gray-50 rounded-xl">
                                                        <p className="text-[10px] font-bold text-gray-400 mb-1">{t('applicationsPage.sellerBio')}</p>
                                                        <p className="text-sm text-gray-700 leading-relaxed">{app.applicant_description}</p>
                                                    </div>
                                                )}

                                                {/* Seller Detail Button */}
                                                {app.user_id && (
                                                    <button
                                                        onClick={(e) => { e.stopPropagation(); fetchSellerDetail(app.user_id); }}
                                                        className="w-full mt-2 py-2.5 bg-gradient-to-r from-indigo-600 to-violet-600 text-white rounded-xl text-xs font-bold hover:from-indigo-700 hover:to-violet-700 transition-all flex items-center justify-center gap-1.5 shadow-sm"
                                                    >
                                                        <Eye size={14} />
                                                        {t('applicationsPage.viewSellerInfo')}
                                                    </button>
                                                )}
                                            </div>
                                        </div>
                                    </div>
                                )}
                            </div>
                        );
                    })}
                </div>
            )}
            {/* Confirm Modal */}
            {confirmModal && (
                <div className="fixed inset-0 z-[9999] flex items-center justify-center p-4" style={{ backgroundColor: 'rgba(0,0,0,0.5)' }}>
                    <div className="bg-white rounded-2xl shadow-2xl max-w-sm w-full overflow-hidden" onClick={(e) => e.stopPropagation()}>
                        <div className={`p-5 flex items-center gap-3 ${confirmModal.type === 'danger' ? 'bg-red-50' : confirmModal.type === 'success' ? 'bg-emerald-50' : 'bg-amber-50'
                            }`}>
                            <div className={`w-10 h-10 rounded-full flex items-center justify-center flex-shrink-0 ${confirmModal.type === 'danger' ? 'bg-red-100' : confirmModal.type === 'success' ? 'bg-emerald-100' : 'bg-amber-100'
                                }`}>
                                {confirmModal.type === 'success'
                                    ? <CheckCircle size={20} className="text-emerald-500" />
                                    : <AlertTriangle size={20} className={confirmModal.type === 'danger' ? 'text-red-500' : 'text-amber-500'} />}
                            </div>
                            <h3 className="text-base font-bold text-gray-900">{confirmModal.title}</h3>
                        </div>
                        <div className="p-5">
                            <p className="text-sm text-gray-600 leading-relaxed whitespace-pre-line">{confirmModal.message}</p>
                            {confirmModal.showRejectionReason && (
                                <div className="mt-4">
                                    <label className="block text-xs font-bold text-gray-500 mb-1.5">{t('applicationsPage.rejectionReasonLabel')}</label>
                                    <textarea
                                        value={rejectionReason}
                                        onChange={(e) => setRejectionReason(e.target.value)}
                                        placeholder={t('applicationsPage.rejectionReasonPlaceholder')}
                                        rows={3}
                                        className="w-full px-3 py-2.5 bg-gray-50 border border-gray-200 rounded-xl text-sm outline-none focus:border-red-400 focus:ring-2 focus:ring-red-100 resize-none transition-all"
                                    />
                                </div>
                            )}
                        </div>
                        <div className="px-5 pb-5 flex gap-3">
                            <button
                                onClick={() => setConfirmModal(null)}
                                className="flex-1 py-3 bg-gray-100 text-gray-700 rounded-xl text-sm font-bold hover:bg-gray-200 transition-colors"
                            >
                                {t('applicationsPage.cancel')}
                            </button>
                            <button
                                onClick={() => confirmModal.onConfirm(rejectionReason)}
                                className={`flex-1 py-3 rounded-xl text-sm font-bold transition-colors text-white ${confirmModal.type === 'danger' ? 'bg-red-500 hover:bg-red-600'
                                    : confirmModal.type === 'success' ? 'bg-emerald-500 hover:bg-emerald-600'
                                        : 'bg-amber-500 hover:bg-amber-600'
                                    }`}
                            >
                                {confirmModal.confirmLabel || t('applicationsPage.approve')}
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Toast Notification */}
            {toast && (
                <div className="fixed top-6 left-1/2 -translate-x-1/2 z-[9999]">
                    <div className={`flex items-center gap-3 px-5 py-3.5 rounded-2xl shadow-2xl border backdrop-blur-sm ${toast.type === 'success'
                        ? 'bg-emerald-50 border-emerald-200 text-emerald-800'
                        : 'bg-red-50 border-red-200 text-red-800'
                        }`}>
                        {toast.type === 'success'
                            ? <CheckCircle size={18} className="text-emerald-500 flex-shrink-0" />
                            : <XCircle size={18} className="text-red-500 flex-shrink-0" />}
                        <span className="text-sm font-bold">{toast.message}</span>
                        <button onClick={() => setToast(null)} className="ml-2 p-0.5 hover:bg-black/5 rounded-full transition-colors">
                            <X size={14} className="text-gray-400" />
                        </button>
                    </div>
                </div>
            )}

            {/* Seller Detail Modal */}
            {sellerDetail && (
                <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[9998] flex items-center justify-center p-4" onClick={() => setSellerDetail(null)}>
                    <div className="bg-white rounded-3xl shadow-2xl w-full max-w-lg overflow-hidden" onClick={e => e.stopPropagation()}>
                        {/* Header */}
                        <div className="bg-gradient-to-br from-indigo-600 via-violet-600 to-purple-600 p-6 text-white relative overflow-hidden">
                            <div className="absolute inset-0 opacity-10" style={{ backgroundImage: 'radial-gradient(circle at 20% 50%, rgba(255,255,255,0.3) 0%, transparent 50%)' }} />
                            <div className="relative flex justify-between items-start">
                                <div className="flex items-center gap-4">
                                    <div className="w-14 h-14 bg-white/20 backdrop-blur rounded-2xl flex items-center justify-center text-white font-bold text-xl overflow-hidden ring-2 ring-white/30">
                                        {sellerDetail.user?.profile_image ? (
                                            <img src={sellerDetail.user.profile_image} alt="" className="w-full h-full object-cover" />
                                        ) : (
                                            (sellerDetail.user?.name || '?')[0]
                                        )}
                                    </div>
                                    <div>
                                        <h2 className="text-lg font-extrabold">{sellerDetail.user?.name}</h2>
                                        {sellerDetail.user?.category && (
                                            <span className="inline-block mt-1 px-2.5 py-0.5 rounded-lg text-xs font-bold bg-white/20">
                                                {CATEGORY_LABELS[sellerDetail.user.category] || sellerDetail.user.category}
                                            </span>
                                        )}
                                    </div>
                                </div>
                                <button onClick={() => setSellerDetail(null)} className="text-white/80 hover:text-white p-1">
                                    <X size={22} />
                                </button>
                            </div>
                        </div>
                        <div className="p-5 space-y-4 max-h-[65vh] overflow-y-auto">
                            {/* Sales Info */}
                            <div className="p-4 bg-violet-50 rounded-xl border border-violet-100">
                                <p className="text-xs font-bold text-violet-500 uppercase tracking-wider mb-2">{t('applicationsPage.salesInfo')}</p>
                                <div className="flex items-center gap-2 mb-2">
                                    <Tag size={16} className="text-violet-600" />
                                    <span className="text-sm font-bold text-violet-800">{CATEGORY_LABELS[sellerDetail.user?.category] || sellerDetail.user?.category || t('applicationsPage.unspecified')}</span>
                                </div>
                                <p className="text-sm text-gray-700 leading-relaxed">{sellerDetail.user?.description || t('applicationsPage.noBrandIntro')}</p>
                            </div>

                            {/* Product Photos */}
                            {sellerDetail.seller_photos?.length > 0 && (
                                <div>
                                    <p className="text-xs font-bold text-gray-500 uppercase tracking-wider mb-2 flex items-center gap-1">
                                        <ImageIcon size={12} />
                                        {t('applicationsPage.productPhotos')}
                                    </p>
                                    <div className="grid grid-cols-3 gap-2">
                                        {sellerDetail.seller_photos.map((photo, idx) => (
                                            <div key={photo.id || idx}
                                                className="aspect-square rounded-xl overflow-hidden border border-gray-200 bg-gray-50 cursor-pointer hover:ring-2 hover:ring-indigo-400 transition-all"
                                                onClick={() => { setLightboxPhotos(sellerDetail.seller_photos); setLightboxIndex(idx); }}
                                            >
                                                <img src={photo.image_url} alt="" className="w-full h-full object-cover" />
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            )}

                            {/* Stats */}
                            <div className="flex items-center justify-center gap-6 py-3 border-y border-gray-100">
                                <div className="text-center">
                                    <p className="text-2xl font-extrabold text-indigo-600">{sellerDetail.applications?.length || 0}</p>
                                    <p className="text-xs text-gray-400">{t('applicationsPage.applicationCount')}</p>
                                </div>
                            </div>

                            {/* Contact Info */}
                            <div>
                                <p className="text-xs font-bold text-gray-500 uppercase tracking-wider mb-2">{t('applicationsPage.contactInfo')}</p>
                                <div className="grid grid-cols-1 gap-2">
                                    <div className="flex items-center gap-3 p-3 bg-gray-50 rounded-xl">
                                        <Mail size={16} className="text-indigo-400" />
                                        <div>
                                            <p className="text-xs text-gray-400">{t('applicationsPage.email')}</p>
                                            <p className="text-sm font-medium text-gray-800">{sellerDetail.user?.email || '-'}</p>
                                        </div>
                                    </div>
                                    <div className="flex items-center gap-3 p-3 bg-gray-50 rounded-xl">
                                        <Phone size={16} className="text-indigo-400" />
                                        <div>
                                            <p className="text-xs text-gray-400">{t('applicationsPage.phone')}</p>
                                            <p className="text-sm font-medium text-gray-800">{sellerDetail.user?.phone || t('applicationsPage.notRegistered')}</p>
                                        </div>
                                    </div>
                                    {sellerDetail.user?.instagram && (
                                        <div className="flex items-center gap-3 p-3 bg-violet-50 rounded-xl border border-violet-100">
                                            <Instagram size={16} className="text-violet-500" />
                                            <div>
                                                <p className="text-xs text-gray-400">{t('applicationsPage.instagramLabel')}</p>
                                                <a href={`https://instagram.com/${sellerDetail.user.instagram.replace('@', '')}`} target="_blank" rel="noopener noreferrer"
                                                    className="text-sm font-medium text-violet-600 hover:text-violet-700">@{sellerDetail.user.instagram.replace('@', '')}</a>
                                            </div>
                                        </div>
                                    )}
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {/* Photo Lightbox */}
            {lightboxPhotos.length > 0 && (
                <div className="fixed inset-0 bg-black/90 z-[10000] flex items-center justify-center" onClick={() => setLightboxPhotos([])}>
                    <button onClick={() => setLightboxPhotos([])} className="absolute top-4 right-4 text-white/70 hover:text-white p-2 z-10">
                        <X size={28} />
                    </button>
                    <p className="absolute top-5 left-1/2 -translate-x-1/2 text-white/60 text-sm font-bold">{lightboxIndex + 1} / {lightboxPhotos.length}</p>
                    {lightboxIndex > 0 && (
                        <button onClick={(e) => { e.stopPropagation(); setLightboxIndex(i => i - 1); }}
                            className="absolute left-3 top-1/2 -translate-y-1/2 p-2 bg-white/10 hover:bg-white/20 rounded-full text-white transition-colors">
                            <ChevronLeft size={28} />
                        </button>
                    )}
                    {lightboxIndex < lightboxPhotos.length - 1 && (
                        <button onClick={(e) => { e.stopPropagation(); setLightboxIndex(i => i + 1); }}
                            className="absolute right-3 top-1/2 -translate-y-1/2 p-2 bg-white/10 hover:bg-white/20 rounded-full text-white transition-colors">
                            <ChevronRight size={28} />
                        </button>
                    )}
                    <img
                        src={lightboxPhotos[lightboxIndex]?.image_url || ''}
                        alt=""
                        className="max-w-[90vw] max-h-[85vh] object-contain rounded-lg shadow-2xl"
                        onClick={(e) => e.stopPropagation()}
                    />
                </div>
            )}
        </div>
    );
};

export default HostApplications;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { Search, Tag, ShoppingBag, Filter, ChevronDown, ChevronLeft, ChevronRight, X, Users, Instagram, ArrowUpDown, Mail, Phone, Building, Calendar, ImageIcon, Crown, Star, Lock, Unlock, Eye, BadgeCheck, Heart, MessageCircle } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import AdSlot from '../../components/AdSlot';
import { useAuth } from '../../context/AuthContext';
import Toast from '../../components/Toast';

const API_BASE = '/api';

const HostSellerDirectory = () => {
    const { user } = useAuth();
    const navigate = useNavigate();
    const { t } = useTranslation('host');
    const [toast, setToast] = useState(null);
    const showToast = useCallback((message, type = 'success') => { setToast({ message, type }); }, []);

    const CATEGORY_LABELS = {
        fashion: t('applicationsPage.catFashion'),
        beauty: t('applicationsPage.catBeauty'),
        food: t('applicationsPage.catFood'),
        living: t('applicationsPage.catLiving'),
        art: t('applicationsPage.catArt'),
        stationery: t('applicationsPage.catStationery'),
        digital: t('applicationsPage.catDigital'),
        activity: t('applicationsPage.catActivity'),
        eco: t('applicationsPage.catEco'),
        pet: t('applicationsPage.catPet'),
        kids: t('applicationsPage.catKids'),
        handmade: t('applicationsPage.catHandmade'),
        vintage: t('applicationsPage.catVintage'),
        perfume: t('applicationsPage.catPerfume'),
        book: t('applicationsPage.catBook')
    };
    const isAdmin = user?.role === 'admin' || user?.role === 'superadmin';
    const [sellers, setSellers] = useState([]);
    const [loading, setLoading] = useState(true);
    const [searchTerm, setSearchTerm] = useState('');
    const [selectedCategory, setSelectedCategory] = useState('');
    const [sortBy, setSortBy] = useState('newest');
    const [showFilters, setShowFilters] = useState(false);
    const [selectedSeller, setSelectedSeller] = useState(null);
    // Contact access control state
    const [contactAccess, setContactAccess] = useState({ can_view: 0, monthly_limit: 0, remaining: 0, viewed_ids: [] });
    const [unlockedContacts, setUnlockedContacts] = useState({}); // { sellerId: { email, phone, instagram, business_no } }
    const [unlockLoading, setUnlockLoading] = useState(false);
    // Favorites state
    const [favoriteIds, setFavoriteIds] = useState([]);
    const [favoriteLoading, setFavoriteLoading] = useState({});
    // View filter: 'all' | 'viewed' | 'favorites'
    const [viewFilter, setViewFilter] = useState('all');
    // Lightbox state
    const [lightboxPhotos, setLightboxPhotos] = useState([]);
    const [lightboxIndex, setLightboxIndex] = useState(0);

    useEffect(() => {
        fetchSellers();
    }, []);

    const fetchSellers = async () => {
        try {
            const res = await fetch(`${API_BASE}/users/browse_sellers.php`, { credentials: 'include' });
            const data = await res.json();
            if (Array.isArray(data)) {
                setSellers(data);
            }
        } catch (err) {
            console.error(t('sellerDirectoryPage.sellerLoadFailed'), err);
        } finally {
            setLoading(false);
        }
    };

    // Fetch contact access permissions + auto-load viewed contacts
    useEffect(() => {
        fetch(`${API_BASE}/users/seller_contact_access.php`, { credentials: 'include' })
            .then(res => res.json())
            .then(data => {
                if (data.success) {
                    setContactAccess({
                        can_view: data.can_view_contacts,
                        monthly_limit: data.monthly_limit,
                        remaining: data.remaining,
                        viewed_ids: data.viewed_seller_ids || []
                    });
                    // Auto-load contacts for previously viewed sellers
                    (data.viewed_seller_ids || []).forEach(sid => {
                        fetch(`${API_BASE}/users/unlock_seller_contact.php`, {
                            method: 'POST', credentials: 'include',
                            headers: { 'Content-Type': 'application/json' },
                            body: JSON.stringify({ seller_id: sid })
                        })
                            .then(r => r.json())
                            .then(d => {
                                if (d.success) setUnlockedContacts(prev => ({ ...prev, [sid]: d.contact }));
                            })
                            .catch(() => { });
                    });
                }
            })
            .catch(() => { });
    }, []);

    // Fetch favorites
    useEffect(() => {
        fetch(`${API_BASE}/users/seller_favorites.php`, { credentials: 'include' })
            .then(res => res.json())
            .then(data => {
                if (data.success) setFavoriteIds(data.favorite_ids || []);
            })
            .catch(() => { });
    }, []);

    // Toggle favorite
    const handleToggleFavorite = useCallback(async (e, sellerId) => {
        e.stopPropagation();
        setFavoriteLoading(prev => ({ ...prev, [sellerId]: true }));
        try {
            const res = await fetch(`${API_BASE}/users/seller_favorites.php`, {
                method: 'POST', credentials: 'include',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ seller_id: sellerId })
            });
            const data = await res.json();
            if (data.success) {
                setFavoriteIds(prev => data.is_favorite ? [...prev, sellerId] : prev.filter(id => id !== sellerId));
            }
        } catch (e) { console.error(e); }
        finally { setFavoriteLoading(prev => ({ ...prev, [sellerId]: false })); }
    }, []);

    const handleUnlockContact = async (sellerId) => {
        setUnlockLoading(true);
        try {
            const res = await fetch(`${API_BASE}/users/unlock_seller_contact.php`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                credentials: 'include',
                body: JSON.stringify({ seller_id: sellerId })
            });
            const data = await res.json();
            if (data.success) {
                setUnlockedContacts(prev => ({ ...prev, [sellerId]: data.contact }));
                if (!data.already_viewed) {
                    setContactAccess(prev => ({
                        ...prev,
                        remaining: data.remaining,
                        viewed_ids: [...prev.viewed_ids, sellerId]
                    }));
                }
            } else {
                showToast(data.message || t('sellerDirectoryPage.contactLoadFailed'), 'error');
            }
        } catch (err) {
            showToast(t('sellerDirectoryPage.contactLoadFailed'), 'error');
        } finally {
            setUnlockLoading(false);
        }
    };

    // Extract unique categories
    const allCategories = useMemo(() => {
        const cats = new Set();
        sellers.forEach(s => {
            if (s.category) cats.add(s.category);
        });
        return Array.from(cats).sort();
    }, [sellers]);

    // Filtered & sorted sellers
    const filteredSellers = useMemo(() => {
        let result = sellers.filter(seller => {
            // View filter
            if (viewFilter === 'viewed' && !contactAccess.viewed_ids.includes(seller.id)) return false;
            if (viewFilter === 'favorites' && !favoriteIds.includes(seller.id)) return false;
            // Search
            if (searchTerm) {
                const term = searchTerm.toLowerCase();
                const nameMatch = seller.name?.toLowerCase().includes(term);
                const categoryMatch = seller.category?.toLowerCase().includes(term);
                const categoryLabelMatch = Object.entries(CATEGORY_LABELS).some(
                    ([key, label]) => key === seller.category && label.toLowerCase().includes(term)
                );
                const instagramMatch = seller.instagram?.toLowerCase().includes(term);
                if (!nameMatch && !categoryMatch && !categoryLabelMatch && !instagramMatch) return false;
            }
            // Category filter
            if (selectedCategory && seller.category !== selectedCategory) {
                return false;
            }
            return true;
        });

        // Sort
        switch (sortBy) {
            case 'newest':
                result.sort((a, b) => new Date(b.created_at) - new Date(a.created_at));
                break;
            case 'oldest':
                result.sort((a, b) => new Date(a.created_at) - new Date(b.created_at));
                break;
            case 'name_asc':
                result.sort((a, b) => (a.name || '').localeCompare(b.name || '', 'ko'));
                break;
            case 'name_desc':
                result.sort((a, b) => (b.name || '').localeCompare(a.name || '', 'ko'));
                break;
            case 'apps_desc':
                result.sort((a, b) => (b.app_count || 0) - (a.app_count || 0));
                break;
            default:
                break;
        }

        return result;
    }, [sellers, searchTerm, selectedCategory, sortBy, viewFilter, contactAccess.viewed_ids, favoriteIds]);

    const activeFilterCount = [selectedCategory].filter(Boolean).length;

    const featuredSellers = useMemo(() => {
        return sellers.filter(s => s.is_featured);
    }, [sellers]);

    const clearFilters = () => {
        setSelectedCategory('');
        setSearchTerm('');
        setSortBy('newest');
    };

    const getCategoryLabel = (cat) => CATEGORY_LABELS[cat] || cat || t('sellerDirectoryPage.unspecified');
    const getCategoryColor = (cat) => {
        const colors = {
            fashion: 'bg-pink-50 text-pink-600',
            beauty: 'bg-fuchsia-50 text-fuchsia-600',
            food: 'bg-orange-50 text-orange-600',
            living: 'bg-emerald-50 text-emerald-600',
            art: 'bg-violet-50 text-violet-600',
            stationery: 'bg-blue-50 text-blue-600',
            digital: 'bg-cyan-50 text-cyan-600',
            activity: 'bg-lime-50 text-lime-600',
            eco: 'bg-green-50 text-green-600',
            pet: 'bg-amber-50 text-amber-600',
            kids: 'bg-rose-50 text-rose-600',
            handmade: 'bg-yellow-50 text-yellow-600',
            vintage: 'bg-stone-100 text-stone-600',
            perfume: 'bg-purple-50 text-purple-600',
            book: 'bg-sky-50 text-sky-600'
        };
        return colors[cat] || 'bg-gray-50 text-gray-600';
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center h-64">
                <div className="animate-spin rounded-full h-8 w-8 border-2 border-indigo-600 border-t-transparent"></div>
            </div>
        );
    }

    return (
        <>
            <div className="max-w-7xl mx-auto">
                {/* Header */}
                <div className="mb-8">
                    <div className="flex items-center gap-3 mb-2">
                        <div className="w-10 h-10 bg-rose-100 rounded-xl flex items-center justify-center">
                            <ShoppingBag className="text-rose-600" size={22} />
                        </div>
                        <div>
                            <h1 className="text-2xl md:text-3xl font-extrabold text-gray-900">{t('sellerDirectoryPage.title')}</h1>
                            <p className="text-sm text-gray-500">{t('sellerDirectoryPage.subtitle')}</p>
                        </div>
                    </div>
                </div>

                {/* Search & Filter Bar */}
                <div className="bg-white rounded-2xl shadow-sm border border-gray-100 p-4 mb-6">
                    <div className="flex flex-col md:flex-row gap-3">
                        <div className="relative flex-1">
                            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                            <input
                                type="text"
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                                placeholder={t('sellerDirectoryPage.searchPlaceholder')}
                                className="w-full pl-10 pr-4 py-3 bg-gray-50 rounded-xl border border-transparent focus:border-indigo-500 focus:bg-white outline-none transition-all font-medium"
                            />
                        </div>
                        <button
                            onClick={() => setShowFilters(!showFilters)}
                            className={`flex items-center gap-2 px-4 py-3 rounded-xl font-bold transition-all text-sm ${showFilters || activeFilterCount > 0
                                ? 'bg-rose-600 text-white shadow-lg shadow-rose-200'
                                : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
                                }`}
                        >
                            <Filter size={16} />
                            {t('sellerDirectoryPage.filterSort')}
                            {activeFilterCount > 0 && (
                                <span className="bg-white/20 px-1.5 py-0.5 rounded-md text-xs">{activeFilterCount}</span>
                            )}
                        </button>
                    </div>

                    {/* Filter Panel */}
                    {showFilters && (
                        <div className="mt-4 pt-4 border-t border-gray-100 grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div>
                                <label className="block text-xs font-bold text-gray-500 uppercase mb-2">{t('sellerDirectoryPage.categoryLabel')}</label>
                                <div className="relative">
                                    <select
                                        value={selectedCategory}
                                        onChange={(e) => setSelectedCategory(e.target.value)}
                                        className="w-full px-4 py-2.5 bg-gray-50 rounded-xl border border-transparent focus:border-indigo-500 outline-none appearance-none font-medium text-sm"
                                    >
                                        <option value="">{t('sellerDirectoryPage.allCategories')}</option>
                                        {allCategories.map(c => (
                                            <option key={c} value={c}>{getCategoryLabel(c)}</option>
                                        ))}
                                    </select>
                                    <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 pointer-events-none" size={16} />
                                </div>
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-gray-500 uppercase mb-2">{t('sellerDirectoryPage.sortLabel')}</label>
                                <div className="relative">
                                    <select
                                        value={sortBy}
                                        onChange={(e) => setSortBy(e.target.value)}
                                        className="w-full px-4 py-2.5 bg-gray-50 rounded-xl border border-transparent focus:border-indigo-500 outline-none appearance-none font-medium text-sm"
                                    >
                                        <option value="newest">{t('sellerDirectoryPage.sortNewest')}</option>
                                        <option value="oldest">{t('sellerDirectoryPage.sortOldest')}</option>
                                        <option value="name_asc">{t('sellerDirectoryPage.sortNameAsc')}</option>
                                        <option value="name_desc">{t('sellerDirectoryPage.sortNameDesc')}</option>
                                        <option value="apps_desc">{t('sellerDirectoryPage.sortAppsDesc')}</option>
                                    </select>
                                    <ArrowUpDown className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 pointer-events-none" size={16} />
                                </div>
                            </div>
                            {activeFilterCount > 0 && (
                                <div className="md:col-span-2">
                                    <button
                                        onClick={clearFilters}
                                        className="text-xs text-red-500 hover:text-red-700 font-medium flex items-center gap-1"
                                    >
                                        <X size={14} /> {t('sellerDirectoryPage.clearFilters')}
                                    </button>
                                </div>
                            )}
                        </div>
                    )}
                </div>

                {/* View Filter Tabs */}
                <div className="flex items-center gap-2 mb-5">
                    {[
                        { key: 'all', label: t('sellerDirectoryPage.allSellers', '전체 셀러') },
                        { key: 'viewed', label: t('sellerDirectoryPage.viewedSellers', '열람한 셀러'), count: contactAccess.viewed_ids.length },
                        { key: 'favorites', label: t('sellerDirectoryPage.favoriteSellers', '좋아요'), count: favoriteIds.length }
                    ].map(tab => (
                        <button
                            key={tab.key}
                            onClick={() => setViewFilter(tab.key)}
                            className={`flex items-center gap-1.5 px-4 py-2 rounded-xl text-sm font-bold transition-all ${viewFilter === tab.key
                                ? 'bg-rose-600 text-white shadow-lg shadow-rose-200'
                                : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
                                }`}
                        >
                            {tab.key === 'favorites' && <Heart size={14} fill={viewFilter === 'favorites' ? 'white' : 'none'} />}
                            {tab.key === 'viewed' && <Eye size={14} />}
                            {tab.label}
                            {tab.count !== undefined && <span className={`text-xs px-1.5 py-0.5 rounded-full ${viewFilter === tab.key ? 'bg-white/20' : 'bg-gray-200'}`}>{tab.count}</span>}
                        </button>
                    ))}
                </div>

                {/* Featured Sellers Premium Section */}
                {featuredSellers.length > 0 && !searchTerm && !selectedCategory && (
                    <div className="mb-8">
                        <div className="bg-gradient-to-r from-amber-50 via-yellow-50 to-amber-50 rounded-2xl border border-amber-200/60 overflow-hidden shadow-sm">
                            <div className="px-5 py-3 bg-gradient-to-r from-amber-500 to-yellow-500 flex items-center gap-2">
                                <Crown size={18} className="text-white" />
                                <span className="text-white font-extrabold text-sm">PREMIUM</span>
                                <span className="text-white/70 text-xs ml-1">{t('sellerDirectoryPage.premiumExposure')}</span>
                            </div>
                            <div className="p-5">
                                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                                    {featuredSellers.map(seller => (
                                        <div
                                            key={`featured-${seller.id}`}
                                            onClick={() => setSelectedSeller(seller)}
                                            className="relative bg-white rounded-2xl border-2 border-amber-200 shadow-md hover:shadow-xl hover:-translate-y-1 transition-all duration-300 overflow-hidden cursor-pointer group"
                                        >
                                            {/* Premium Badge */}
                                            <div className="absolute top-3 right-3 z-10">
                                                <div className="bg-gradient-to-r from-amber-400 to-yellow-400 text-white text-[10px] font-extrabold px-2.5 py-1 rounded-full flex items-center gap-1 shadow-lg shadow-amber-200/50">
                                                    <Star size={10} fill="white" />
                                                    PREMIUM
                                                </div>
                                            </div>

                                            {/* Decorative top bar */}
                                            <div className="h-1 bg-gradient-to-r from-amber-400 via-yellow-300 to-amber-400"></div>

                                            <div className="p-5">
                                                <div className="flex items-start gap-3">
                                                    <div className="w-14 h-14 bg-gradient-to-br from-amber-400 to-yellow-500 rounded-xl flex items-center justify-center text-white font-bold text-xl flex-shrink-0 shadow-md shadow-amber-200/50 overflow-hidden ring-2 ring-amber-200">
                                                        {seller.profile_image ? (
                                                            <img src={seller.profile_image} alt="seller" className="w-full h-full object-cover" />
                                                        ) : (
                                                            seller.name?.[0] || 'S'
                                                        )}
                                                    </div>
                                                    <div className="min-w-0 flex-1">
                                                        <h3 className="font-extrabold text-gray-900 text-lg truncate">{seller.name}</h3>
                                                        <div className="flex items-center gap-1.5 mt-0.5">
                                                            <span className={`inline-block px-2.5 py-0.5 rounded-lg text-xs font-bold ${getCategoryColor(seller.category)}`}>
                                                                {getCategoryLabel(seller.category)}
                                                            </span>
                                                            {seller.is_verified ? (
                                                                <span className="inline-flex items-center gap-0.5 px-1.5 py-0.5 bg-emerald-50 text-emerald-600 border border-emerald-200 rounded-full text-[9px] font-extrabold">
                                                                    <BadgeCheck size={9} /> {t('sellerDirectoryPage.verified')}
                                                                </span>
                                                            ) : null}
                                                        </div>
                                                    </div>
                                                </div>
                                                {seller.description && (
                                                    <p className="text-xs text-gray-500 mt-3 line-clamp-2 leading-relaxed">{seller.description}</p>
                                                )}
                                                {seller.instagram && (
                                                    <div className="flex items-center gap-1.5 mt-2 text-pink-500">
                                                        <Instagram size={12} />
                                                        <span className="text-xs font-medium">{seller.instagram}</span>
                                                    </div>
                                                )}
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        </div>
                    </div>
                )}

                {/* ━━ Ad Section ━━ */}
                <div className="mb-5">
                    <div className="flex items-center gap-3 mb-3">
                        <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">{t('sellerDirectoryPage.sponsor')}</span>
                        <div className="flex-1 h-px bg-gray-200" />
                    </div>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <AdSlot slotId="directory_c" format="card" />
                        <AdSlot slotId="directory_c2" format="card" />
                    </div>
                </div>

                {/* Results Count */}
                <div className="flex items-center justify-between mb-4">
                    <p className="text-sm text-gray-500 font-medium">
                        {t('sellerDirectoryPage.totalSellers', { count: filteredSellers.length })} </p>
                </div>

                {/* Seller Grid */}
                {filteredSellers.length === 0 ? (
                    <div className="text-center py-20">
                        <Users className="mx-auto text-gray-300 mb-4" size={48} />
                        <h3 className="text-lg font-bold text-gray-400">{t('sellerDirectoryPage.noResults')}</h3>
                        <p className="text-sm text-gray-400 mt-1">{t('sellerDirectoryPage.noResultsHint')}</p>
                    </div>
                ) : (
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5">
                        {filteredSellers.map((seller, idx) => (
                            <React.Fragment key={seller.id}>
                                {idx === 6 && <AdSlot slotId="directory_d" format="card" />}
                                {idx === 12 && <AdSlot slotId="directory_d2" format="card" />}
                                <div
                                    onClick={() => setSelectedSeller(seller)}
                                    className="bg-white rounded-2xl border border-gray-100 shadow-sm hover:shadow-md hover:-translate-y-1 transition-all duration-300 overflow-hidden cursor-pointer"
                                >
                                    {/* Card Header */}
                                    <div className="p-5 pb-0">
                                        <div className="flex items-start gap-3">
                                            <div className="w-12 h-12 bg-gradient-to-br from-rose-500 to-orange-500 rounded-xl flex items-center justify-center text-white font-bold text-lg flex-shrink-0 shadow-sm overflow-hidden">
                                                {seller.profile_image ? (
                                                    <img src={seller.profile_image} alt="seller" className="w-full h-full object-cover" />
                                                ) : (
                                                    seller.name?.[0] || 'S'
                                                )}
                                            </div>
                                            <div className="min-w-0 flex-1">
                                                <div className="flex items-center gap-2">
                                                    <h3 className="font-bold text-gray-900 text-lg truncate">{seller.name}</h3>
                                                    {seller.is_featured ? (
                                                        <span className="bg-gradient-to-r from-amber-400 to-yellow-400 text-white text-[9px] font-extrabold px-1.5 py-0.5 rounded-full flex items-center gap-0.5">
                                                            <Star size={8} fill="white" /> PREMIUM
                                                        </span>
                                                    ) : null}
                                                    {seller.is_verified ? (
                                                        <span className="inline-flex items-center gap-0.5 px-1.5 py-0.5 bg-emerald-50 text-emerald-600 border border-emerald-200 rounded-full text-[9px] font-extrabold">
                                                            <BadgeCheck size={9} /> {t('sellerDirectoryPage.verified')}
                                                        </span>
                                                    ) : null}
                                                </div>
                                                {(isAdmin || unlockedContacts[seller.id]) ? (
                                                    <p className="text-xs text-gray-400 truncate">{unlockedContacts[seller.id]?.email || seller.email}</p>
                                                ) : (
                                                    <p className="text-xs text-gray-400 truncate" style={{ filter: 'blur(4px)', userSelect: 'none' }}>{seller.email || 'email@hidden.com'}</p>
                                                )}
                                            </div>
                                        </div>
                                    </div>

                                    {/* Card Body */}
                                    <div className="p-5 space-y-3">
                                        {/* Category */}
                                        <div className="flex items-center gap-2">
                                            <Tag size={15} className="text-gray-400 flex-shrink-0" />
                                            <span className={`px-2.5 py-1 rounded-lg text-xs font-bold ${getCategoryColor(seller.category)}`}>
                                                {getCategoryLabel(seller.category)}
                                            </span>
                                        </div>

                                        {/* Instagram - Locked */}
                                        <div className="flex items-center gap-2 text-sm">
                                            <Instagram size={15} className="text-gray-300 flex-shrink-0" />
                                            <span className="text-gray-400 flex items-center gap-1"><Lock size={12} /> {t('sellerDirectoryPage.contactLocked')}</span>
                                        </div>

                                        {/* Description */}
                                        {seller.description && (
                                            <p className="text-xs text-gray-500 line-clamp-2 leading-relaxed">
                                                {seller.description}
                                            </p>
                                        )}

                                        {/* App Count */}
                                        <div className="text-xs text-gray-400">
                                            {t('sellerDirectoryPage.appCount', { count: seller.app_count })}
                                        </div>
                                    </div>

                                    {/* Card Footer */}
                                    <div className="px-5 py-3 border-t border-gray-50 flex items-center justify-between bg-gray-50/50">
                                        <span className="text-xs text-gray-400">
                                            {t('sellerDirectoryPage.joinDate')}{new Date(seller.created_at).toLocaleDateString('ko-KR')}
                                        </span>
                                        <div className="flex items-center gap-2">
                                            <button
                                                onClick={(e) => handleToggleFavorite(e, seller.id)}
                                                disabled={favoriteLoading[seller.id]}
                                                className="p-1 rounded-lg hover:bg-rose-50 transition-colors"
                                            >
                                                <Heart size={16} className={favoriteIds.includes(seller.id) ? 'text-rose-500 fill-rose-500' : 'text-gray-300 hover:text-rose-400'} />
                                            </button>
                                            {(isAdmin || unlockedContacts[seller.id]) ? (
                                                <button
                                                    onClick={(e) => { e.stopPropagation(); navigate(`/${user.role}/chat?user=${seller.id}`); }}
                                                    className="flex items-center gap-1 px-2.5 py-1 bg-indigo-50 text-indigo-600 rounded-lg text-xs font-bold hover:bg-indigo-100 transition-colors"
                                                >
                                                    <MessageCircle size={12} /> 채팅
                                                </button>
                                            ) : (
                                                <span className="text-xs text-gray-400 flex items-center gap-1"><Lock size={10} /> {t('sellerDirectoryPage.contact')}</span>
                                            )}
                                        </div>
                                    </div>
                                </div>
                            </React.Fragment>
                        ))}
                    </div>
                )}
                {/* Detail Modal */}
                {selectedSeller && (
                    <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center p-4" onClick={() => setSelectedSeller(null)}>
                        <div className="bg-white rounded-3xl shadow-2xl w-full max-w-lg overflow-hidden" onClick={e => e.stopPropagation()}>
                            {/* Header ??SpaceMatch brand gradient */}
                            <div className="bg-gradient-to-br from-indigo-600 via-violet-600 to-purple-600 p-6 text-white relative overflow-hidden">
                                {/* Subtle pattern overlay */}
                                <div className="absolute inset-0 opacity-10" style={{ backgroundImage: 'radial-gradient(circle at 20% 50%, rgba(255,255,255,0.3) 0%, transparent 50%), radial-gradient(circle at 80% 20%, rgba(255,255,255,0.2) 0%, transparent 50%)' }} />
                                <div className="relative flex justify-between items-start">
                                    <div className="flex items-center gap-4">
                                        <div className="w-16 h-16 bg-white/20 backdrop-blur rounded-2xl flex items-center justify-center text-white font-bold text-2xl overflow-hidden ring-2 ring-white/30">
                                            {selectedSeller.profile_image ? (
                                                <img src={selectedSeller.profile_image} alt="셀러" className="w-full h-full object-cover" />
                                            ) : (
                                                selectedSeller.name?.[0] || 'S'
                                            )}
                                        </div>
                                        <div>
                                            <h2 className="text-xl font-extrabold">{selectedSeller.name}</h2>
                                            <span className="inline-block mt-1 px-2.5 py-0.5 rounded-lg text-xs font-bold bg-white/20 backdrop-blur-sm">
                                                {getCategoryLabel(selectedSeller.category)}
                                            </span>
                                        </div>
                                    </div>
                                    <div className="flex items-center gap-2">
                                        <button
                                            onClick={(e) => handleToggleFavorite(e, selectedSeller.id)}
                                            disabled={favoriteLoading[selectedSeller.id]}
                                            className="p-2 rounded-xl hover:bg-white/10 transition-colors"
                                        >
                                            <Heart size={22} className={favoriteIds.includes(selectedSeller.id) ? 'text-rose-400 fill-rose-400' : 'text-white/60 hover:text-white'} />
                                        </button>
                                        <button onClick={() => setSelectedSeller(null)} className="text-white/80 hover:text-white p-1 transition-colors">
                                            <X size={22} />
                                        </button>
                                    </div>
                                </div>
                            </div>
                            <div className="p-6 space-y-4 max-h-[70vh] overflow-y-auto">
                                {/* What they sell - Most prominent */}
                                <div className="p-4 bg-violet-50 rounded-xl border border-violet-100">
                                    <p className="text-xs font-bold text-violet-500 uppercase tracking-wider mb-2">{t('sellerDirectoryPage.salesInfo')}</p>
                                    <div className="flex items-center gap-2 mb-2">
                                        <Tag size={16} className="text-violet-600" />
                                        <span className="text-sm font-bold text-violet-800">{getCategoryLabel(selectedSeller.category)}</span>
                                    </div>
                                    {selectedSeller.description ? (
                                        <p className="text-sm text-gray-700 leading-relaxed mt-2 whitespace-pre-wrap">{selectedSeller.description}</p>
                                    ) : (
                                        <p className="text-sm text-gray-400 italic mt-2">{t('sellerDirectoryPage.noBrandIntro')}</p>
                                    )}
                                </div>

                                {/* Product Photos */}
                                {selectedSeller.photos && selectedSeller.photos.length > 0 && (
                                    <div>
                                        <p className="text-xs font-bold text-gray-500 uppercase tracking-wider mb-2 flex items-center gap-1">
                                            <ImageIcon size={12} />
                                            {t('sellerDirectoryPage.productPhotos')}
                                        </p>
                                        <div className="grid grid-cols-3 gap-2">
                                            {selectedSeller.photos.map((photo, idx) => (
                                                <div key={photo.id || idx}
                                                    className="aspect-square rounded-xl overflow-hidden border border-gray-200 bg-gray-50 cursor-pointer hover:ring-2 hover:ring-indigo-400 transition-all"
                                                    onClick={() => { setLightboxPhotos(selectedSeller.photos); setLightboxIndex(idx); }}
                                                >
                                                    <img src={photo.image_url?.startsWith?.('uploads/') ? `/${photo.image_url}` : photo.image_url} alt={t('sellerDirectoryPage.productPhotoAlt', { index: idx + 1 })} className="w-full h-full object-cover" />
                                                </div>
                                            ))}
                                        </div>
                                    </div>
                                )}

                                {/* Stats */}
                                <div className="flex items-center justify-center gap-6 py-3 border-y border-gray-100">
                                    <div className="text-center">
                                        <p className="text-2xl font-extrabold text-indigo-600">{selectedSeller.app_count || 0}</p>
                                        <p className="text-xs text-gray-400">{t('sellerDirectoryPage.applicationCount')}</p>
                                    </div>
                                </div>

                                {/* Contact Info - Admins see everything, hosts need unlock */}
                                <div>
                                    <p className="text-xs font-bold text-gray-500 uppercase tracking-wider mb-2">{t('sellerDirectoryPage.contactInfo')}</p>
                                    {isAdmin || unlockedContacts[selectedSeller.id] ? (
                                        <>
                                            <div className="grid grid-cols-1 gap-2">
                                                <div className="flex items-center gap-3 p-3 bg-gray-50 rounded-xl">
                                                    <Mail size={16} className="text-indigo-400" />
                                                    <div>
                                                        <p className="text-xs text-gray-400">{t('sellerDirectoryPage.email')}</p>
                                                        <p className="text-sm font-medium text-gray-800">{isAdmin ? (selectedSeller.email || t('sellerDirectoryPage.notRegistered')) : (unlockedContacts[selectedSeller.id]?.email || t('sellerDirectoryPage.notRegistered'))}</p>
                                                    </div>
                                                </div>
                                                <div className="flex items-center gap-3 p-3 bg-gray-50 rounded-xl">
                                                    <Phone size={16} className="text-indigo-400" />
                                                    <div>
                                                        <p className="text-xs text-gray-400">{t('sellerDirectoryPage.phone')}</p>
                                                        <p className={`text-sm font-medium ${(isAdmin ? selectedSeller.phone : unlockedContacts[selectedSeller.id]?.phone) ? 'text-gray-800' : 'text-gray-400 italic'}`}>
                                                            {isAdmin ? (selectedSeller.phone || t('sellerDirectoryPage.notRegistered')) : (unlockedContacts[selectedSeller.id]?.phone || t('sellerDirectoryPage.notRegistered'))}
                                                        </p>
                                                    </div>
                                                </div>
                                                <div className="flex items-center gap-3 p-3 bg-violet-50 rounded-xl border border-violet-100">
                                                    <Instagram size={16} className="text-violet-500" />
                                                    <div>
                                                        <p className="text-xs text-gray-400">{t('sellerDirectoryPage.instagramLabel')}</p>
                                                        {(isAdmin ? selectedSeller.instagram : unlockedContacts[selectedSeller.id]?.instagram) ? (
                                                            <a href={`https://instagram.com/${(isAdmin ? selectedSeller.instagram : unlockedContacts[selectedSeller.id]?.instagram).replace('@', '')}`} target="_blank" rel="noopener noreferrer" className="text-sm font-medium text-violet-600 hover:text-violet-700 transition-colors">
                                                                {isAdmin ? selectedSeller.instagram : unlockedContacts[selectedSeller.id]?.instagram}
                                                            </a>
                                                        ) : (
                                                            <p className="text-sm font-medium text-gray-400 italic">{t('sellerDirectoryPage.notRegistered')}</p>
                                                        )}
                                                    </div>
                                                </div>
                                                {(isAdmin || unlockedContacts[selectedSeller.id]) && (unlockedContacts[selectedSeller.id]?.business_no || selectedSeller.business_no) && (
                                                    <div className="flex items-center gap-3 p-3 bg-gray-50 rounded-xl">
                                                        <Building size={16} className="text-indigo-400" />
                                                        <div>
                                                            <p className="text-xs text-gray-400">{t('sellerDirectoryPage.businessNo')}</p>
                                                            <p className="text-sm font-medium text-gray-800">{unlockedContacts[selectedSeller.id]?.business_no || selectedSeller.business_no}</p>
                                                        </div>
                                                    </div>
                                                )}
                                            </div>
                                            {/* Chat button for unlocked contacts */}
                                            <button
                                                onClick={() => navigate(`/${user.role}/chat?user=${selectedSeller.id}`)}
                                                className="w-full mt-3 py-3 bg-gradient-to-r from-indigo-500 to-violet-500 text-white rounded-xl font-bold text-sm hover:from-indigo-400 hover:to-violet-400 shadow-lg shadow-indigo-200/50 transition-all flex items-center justify-center gap-2"
                                            >
                                                <MessageCircle size={16} /> 채팅하기
                                            </button>
                                        </>
                                    ) : (
                                        <div className="p-5 bg-gradient-to-br from-indigo-900/80 to-violet-900/80 rounded-2xl border border-indigo-500/30 text-center backdrop-blur-sm">
                                            <div className="w-12 h-12 bg-indigo-500/20 rounded-2xl flex items-center justify-center mx-auto mb-3 ring-2 ring-indigo-400/30">
                                                <Lock size={24} className="text-indigo-300" />
                                            </div>
                                            <p className="text-sm font-bold text-white mb-1">{t('sellerDirectoryPage.contactLockedTitle')}</p>
                                            <p className="text-xs text-indigo-200/70 mb-4">{t('sellerDirectoryPage.contactLockedDesc')}</p>
                                            {contactAccess.can_view ? (
                                                <>
                                                    <button
                                                        onClick={() => handleUnlockContact(selectedSeller.id)}
                                                        disabled={unlockLoading || contactAccess.remaining <= 0}
                                                        className="w-full py-3 bg-gradient-to-r from-indigo-500 to-violet-500 text-white rounded-xl font-bold text-sm hover:from-indigo-400 hover:to-violet-400 disabled:opacity-40 disabled:cursor-not-allowed shadow-lg shadow-indigo-900/30 transition-all flex items-center justify-center gap-2"
                                                    >
                                                        <Eye size={16} />
                                                        {unlockLoading ? t('sellerDirectoryPage.loadingText') : contactAccess.remaining > 0 ? t('sellerDirectoryPage.unlockContact') : t('sellerDirectoryPage.monthlyExhausted')}
                                                    </button>
                                                    <p className="text-xs text-indigo-300/80 mt-2">
                                                        {t('sellerDirectoryPage.monthlyRemaining', { remaining: contactAccess.remaining, limit: contactAccess.monthly_limit })}
                                                    </p>
                                                </>
                                            ) : (
                                                <p className="text-xs text-amber-300 font-bold">{t('sellerDirectoryPage.noPermission')}</p>
                                            )}
                                        </div>
                                    )}
                                </div>

                                {/* Business Info */}
                                <div>
                                    <p className="text-xs font-bold text-gray-500 uppercase tracking-wider mb-2">{t('sellerDirectoryPage.businessInfo')}</p>
                                    <div className="grid grid-cols-1 gap-2">
                                        <div className="flex items-center gap-3 p-3 bg-gray-50 rounded-xl">
                                            <Building size={16} className="text-indigo-400" />
                                            <div>
                                                <p className="text-xs text-gray-400">{t('sellerDirectoryPage.businessNo')}</p>
                                                <p className={`text-sm font-medium ${selectedSeller.business_no ? 'text-gray-800' : 'text-gray-400 italic'}`}>
                                                    {selectedSeller.business_no ? (isAdmin ? selectedSeller.business_no : selectedSeller.business_no.slice(0, 3) + '-**-*****') : t('sellerDirectoryPage.notRegistered')}
                                                </p>
                                            </div>
                                        </div>
                                        <div className="flex items-center gap-3 p-3 bg-gray-50 rounded-xl">
                                            <Calendar size={16} className="text-indigo-400" />
                                            <div>
                                                <p className="text-xs text-gray-400">{t('sellerDirectoryPage.joinDateLabel')}</p>
                                                <p className="text-sm font-medium text-gray-800">{new Date(selectedSeller.created_at).toLocaleDateString('ko-KR')}</p>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                )}

                {/* Photo Lightbox */}
                {lightboxPhotos.length > 0 && (
                    <div className="fixed inset-0 bg-black/90 z-[60] flex items-center justify-center" onClick={() => setLightboxPhotos([])}>
                        <button onClick={() => setLightboxPhotos([])} className="absolute top-4 right-4 text-white/70 hover:text-white p-2 z-10">
                            <X size={28} />
                        </button>
                        <p className="absolute top-5 left-1/2 -translate-x-1/2 text-white/60 text-sm font-bold">{lightboxIndex + 1} / {lightboxPhotos.length}</p>
                        {lightboxIndex > 0 && (
                            <button onClick={(e) => { e.stopPropagation(); setLightboxIndex(i => i - 1); }}
                                className="absolute left-3 top-1/2 -translate-y-1/2 p-2 bg-white/10 hover:bg-white/20 rounded-full text-white transition-colors">
                                <ChevronLeft size={28} />
                            </button>
                        )}
                        {lightboxIndex < lightboxPhotos.length - 1 && (
                            <button onClick={(e) => { e.stopPropagation(); setLightboxIndex(i => i + 1); }}
                                className="absolute right-3 top-1/2 -translate-y-1/2 p-2 bg-white/10 hover:bg-white/20 rounded-full text-white transition-colors">
                                <ChevronRight size={28} />
                            </button>
                        )}
                        <img
                            src={(() => { const url = lightboxPhotos[lightboxIndex]?.image_url || ''; return url.startsWith?.('uploads/') ? `/${url}` : url; })()}
                            alt=""
                            className="max-w-[90vw] max-h-[85vh] object-contain rounded-lg shadow-2xl"
                            onClick={(e) => e.stopPropagation()}
                        />
                    </div>
                )}
            </div>
            {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
        </>
    );
};

export default HostSellerDirectory;

import React, { useState, useMemo } from 'react';
import { useData } from '../../context/DataContext';
import { useTranslation } from 'react-i18next';
import { Store, MapPin, Sparkles, XCircle, AlertTriangle, Send, Clock, CheckCircle, X, Zap } from 'lucide-react';
import { useDemoGuard } from '../../hooks/useDemoGuard';

const API_BASE = '/api';

const SellerApplications = () => {
    const { applications, fetchApplications } = useData();
    const { t } = useTranslation('seller');
    const { isDemoUser, demoAlert } = useDemoGuard();

    React.useEffect(() => {
        fetchApplications();
    }, []);

    const myApplications = applications;

    const [activeTab, setActiveTab] = useState('all');
    const [cancelling, setCancelling] = useState(null);
    // Cancellation request modal state
    const [cancelRequestModal, setCancelRequestModal] = useState(null); // app object
    const [cancelReason, setCancelReason] = useState('');
    const [submittingRequest, setSubmittingRequest] = useState(false);
    // Track which apps have pending cancel requests
    const [cancelRequestStatus, setCancelRequestStatus] = useState({});

    // Fetch cancellation request statuses on mount
    React.useEffect(() => {
        fetchCancelStatuses();
    }, []);

    const fetchCancelStatuses = async () => {
        try {
            const res = await fetch(`${API_BASE}/applications/get_cancellation_requests.php`, { credentials: 'include' });
            const data = await res.json();
            if (data.success && Array.isArray(data.requests)) {
                const statusMap = {};
                data.requests.forEach(req => {
                    // Store the latest request per application_id
                    if (!statusMap[req.application_id] || req.id > statusMap[req.application_id].id) {
                        statusMap[req.application_id] = req;
                    }
                });
                setCancelRequestStatus(statusMap);
            }
        } catch (err) {
            console.error('취소 신청 현황 로드 실패:', err);
        }
    };

    // Direct cancel (pending/rejected only)
    const handleCancel = async (appId, venueName) => {
        if (isDemoUser) { demoAlert('신청 취소'); return; }
        if (!confirm(t('appPage.confirmCancel', { venue: venueName }))) return;
        setCancelling(appId);
        try {
            const res = await fetch(`${API_BASE}/applications/cancel_application.php`, {
                method: 'POST',
                credentials: 'include',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ id: appId })
            });
            const data = await res.json();
            if (data.success) {
                alert(t('appPage.cancelSuccess'));
                fetchApplications();
            } else {
                alert(data.message || t('appPage.cancelFailed'));
            }
        } catch (err) {
            alert(t('common:error'));
        } finally {
            setCancelling(null);
        }
    };

    // Submit cancellation request (approved only)
    const handleCancelRequest = async () => {
        if (isDemoUser) { demoAlert('취소 요청'); return; }
        if (!cancelReason.trim()) {
            alert(t('appPage.cancelReasonRequired'));
            return;
        }
        setSubmittingRequest(true);
        try {
            const res = await fetch(`${API_BASE}/applications/request_cancellation.php`, {
                method: 'POST',
                credentials: 'include',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    application_id: cancelRequestModal.id,
                    reason: cancelReason.trim()
                })
            });
            const data = await res.json();
            if (data.success) {
                alert(data.message);
                setCancelRequestModal(null);
                setCancelReason('');
                fetchCancelStatuses();
            } else {
                alert(data.message || t('appPage.cancelRequestFailed'));
            }
        } catch (err) {
            alert(t('common:error'));
        } finally {
            setSubmittingRequest(false);
        }
    };

    const filteredApplications = useMemo(() => {
        if (activeTab === 'all') return myApplications;
        return myApplications.filter(app => app.status === activeTab);
    }, [myApplications, activeTab]);

    const tabs = [
        { id: 'all', label: t('appPage.tabAll') },
        { id: 'pending', label: t('appPage.tabPending') },
        { id: 'approved', label: t('appPage.tabApproved') },
        { id: 'rejected', label: t('appPage.tabRejected') }
    ];

    // Helper: get cancel request info for an application
    const getCancelInfo = (appId) => cancelRequestStatus[appId] || null;

    return (
        <div className="space-y-8 pb-20">
            {/* Header */}
            <div className="flex flex-col gap-4 md:flex-row md:items-end justify-between">
                <div>
                    <h1 className="text-2xl md:text-3xl lg:text-4xl font-extrabold text-gray-900">
                        {t('appPage.title')}
                    </h1>
                    <p className="text-gray-500 font-medium mt-2">
                        {t('appPage.subtitle')}
                    </p>
                </div>

                {/* Tabs */}
                <div className="flex p-1 bg-gray-100/80 rounded-xl overflow-x-auto">
                    {tabs.map(tab => (
                        <button
                            key={tab.id}
                            onClick={() => setActiveTab(tab.id)}
                            className={`px-4 py-2 rounded-lg text-sm font-bold transition-all duration-200 whitespace-nowrap
                                ${activeTab === tab.id
                                    ? 'bg-white text-gray-900 shadow-sm'
                                    : 'text-gray-500 hover:text-gray-700'}`}
                        >
                            {tab.label}
                            <span className={`ml-2 text-xs py-0.5 px-1.5 rounded-full ${activeTab === tab.id ? 'bg-gray-100' : 'bg-gray-200/50'}`}>
                                {tab.id === 'all' ? myApplications.length
                                    : myApplications.filter(a => a.status === tab.id).length}
                            </span>
                        </button>
                    ))}
                </div>
            </div>

            {/* Application List */}
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                {filteredApplications.length > 0 ? (
                    filteredApplications.map(app => {
                        const cancelInfo = getCancelInfo(app.id);
                        return (
                            <div key={app.id} className={`bg-white rounded-2xl border shadow-sm hover:shadow-lg transition-all duration-300 overflow-hidden group flex flex-col sm:flex-row ${app.is_priority == 1 ? 'border-amber-200 ring-1 ring-amber-100' : 'border-gray-100'}`}>
                                {/* Image Section */}
                                <div className="sm:w-40 h-40 sm:h-auto bg-gray-100 relative shrink-0">
                                    {app.venue_images && app.venue_images.length > 0 ? (
                                        <img
                                            src={app.venue_images[0]}
                                            alt={app.venue_name}
                                            className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
                                        />
                                    ) : (
                                        <div className="w-full h-full flex items-center justify-center text-gray-300">
                                            <Store size={32} />
                                        </div>
                                    )}
                                    <div className="absolute inset-0 bg-black/10 group-hover:bg-transparent transition-colors"></div>
                                </div>

                                {/* Content Section */}
                                <div className="p-5 md:p-6 flex flex-col justify-between flex-1">
                                    <div>
                                        <div className="flex justify-between items-start mb-2">
                                            <div>
                                                <div className="flex items-center gap-2">
                                                    <h4 className="text-lg font-bold text-gray-900 line-clamp-1">{app.venue_name}</h4>
                                                    {app.is_priority == 1 && (
                                                        <span className="inline-flex items-center gap-0.5 px-1.5 py-0.5 bg-gradient-to-r from-amber-400 to-yellow-400 text-white text-[10px] font-extrabold rounded-md flex-shrink-0">
                                                            <Zap size={9} fill="white" />패스트트랙
                                                        </span>
                                                    )}
                                                </div>
                                                <p className="text-sm text-gray-500 flex items-center gap-1 mt-1">
                                                    <MapPin size={14} /> {app.venue_location || t('appPage.noLocation')}
                                                </p>
                                            </div>
                                            <span className={`px-3 py-1 rounded-full text-xs font-bold border flex items-center gap-1.5
                                                ${app.status === 'pending' ? 'bg-yellow-50 text-yellow-700 border-yellow-200' :
                                                    app.status === 'approved' ? 'bg-emerald-50 text-emerald-700 border-emerald-200' :
                                                        app.status === 'cancelled' ? 'bg-gray-50 text-gray-500 border-gray-200' :
                                                            'bg-red-50 text-red-700 border-red-200'}`}>
                                                <div className={`w-2 h-2 rounded-full ${app.status === 'pending' ? 'bg-yellow-500' : app.status === 'approved' ? 'bg-emerald-500' : app.status === 'cancelled' ? 'bg-gray-400' : 'bg-red-500'}`}></div>
                                                {app.status === 'pending' ? t('appPage.statusPending') : app.status === 'approved' ? t('appPage.statusApproved') : app.status === 'cancelled' ? t('appPage.statusCancelled') : t('appPage.statusRejected')}
                                            </span>
                                        </div>

                                        <div className="mt-4 flex items-center gap-4 text-sm">
                                            <div className="px-3 py-1 bg-gray-50 rounded-lg text-gray-600 font-medium">
                                                ₩{app.venue_price ? parseInt(app.venue_price).toLocaleString() : '0'} /일</div>
                                            <div className="text-gray-400 text-xs">
                                                {t('appPage.appliedDate')}: {new Date(app.created_at || Date.now()).toLocaleDateString()}
                                            </div>
                                        </div>

                                        {/* Cancel Request Status Banner */}
                                        {cancelInfo && (
                                            <div className={`mt-3 px-3 py-2 rounded-xl text-xs font-bold flex items-center gap-2
                                                ${cancelInfo.status === 'pending' ? 'bg-amber-50 text-amber-700 border border-amber-200' :
                                                    cancelInfo.status === 'approved' ? 'bg-green-50 text-green-700 border border-green-200' :
                                                        'bg-red-50 text-red-700 border border-red-200'}`}>
                                                {cancelInfo.status === 'pending' && <><Clock size={13} /> {t('appPage.cancelPending')}</>}
                                                {cancelInfo.status === 'approved' && <><CheckCircle size={13} /> {t('appPage.cancelApproved')}</>}
                                                {cancelInfo.status === 'rejected' && <><X size={13} /> {t('appPage.cancelRejected')}{cancelInfo.decision_note ? ` — ${cancelInfo.decision_note}` : ''}</>}
                                            </div>
                                        )}
                                    </div>

                                    {/* Status Progress Bar */}
                                    <div className="mt-5">
                                        <div className="w-full h-1.5 bg-gray-100 rounded-full overflow-hidden flex">
                                            <div className={`h-full ${app.status === 'rejected' || app.status === 'cancelled' ? 'bg-red-500 w-full' : 'bg-indigo-500'} ${app.status === 'pending' ? 'w-1/3' : 'w-full'} transition-all duration-1000`}></div>
                                        </div>
                                        <div className="flex justify-between text-[10px] text-gray-400 mt-1.5 font-medium">
                                            <span className="text-indigo-600">{t('appPage.applicationDone')}</span>
                                            <span className={app.status !== 'pending' ? (app.status === 'rejected' || app.status === 'cancelled' ? 'text-red-500' : 'text-indigo-600') : ''}>
                                                {app.status === 'pending' ? t('appPage.reviewing') : (app.status === 'approved' ? t('appPage.approvedDone') : app.status === 'cancelled' ? t('appPage.statusCancelled') : t('appPage.statusRejected'))}
                                            </span>
                                        </div>
                                    </div>

                                    {/* Action Buttons */}
                                    <div className="mt-4 flex justify-end gap-2">
                                        {/* Show cancel request button for approved apps WITHOUT a pending request */}
                                        {app.status === 'approved' && (!cancelInfo || cancelInfo.status === 'rejected') && (
                                            <button
                                                onClick={() => { setCancelRequestModal(app); setCancelReason(''); }}
                                                className="flex items-center gap-1.5 px-4 py-2 text-sm font-bold text-amber-600 hover:bg-amber-50 border border-amber-200 rounded-xl transition-all"
                                            >
                                                <AlertTriangle size={16} />
                                                {t('appPage.cancelRequest')}
                                            </button>
                                        )}
                                        {/* Show direct cancel for pending only */}
                                        {app.status === 'pending' && (
                                            <button
                                                onClick={() => handleCancel(app.id, app.venue_name)}
                                                disabled={cancelling === app.id}
                                                className="flex items-center gap-1.5 px-4 py-2 text-sm font-bold text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-xl transition-all disabled:opacity-40"
                                            >
                                                <XCircle size={16} />
                                                {cancelling === app.id ? t('appPage.cancelling') : t('appPage.cancelApplication')}
                                            </button>
                                        )}
                                    </div>
                                </div>
                            </div>
                        );
                    })
                ) : (
                    <div className="col-span-full py-16 text-center bg-gray-50 rounded-2xl border border-dashed border-gray-200">
                        <div className="w-16 h-16 bg-white rounded-full flex items-center justify-center mx-auto mb-4 shadow-sm text-gray-300">
                            <Sparkles size={24} />
                        </div>
                        <h4 className="text-gray-900 font-bold mb-1">
                            {activeTab === 'all'
                                ? t('appPage.noAppsAll')
                                : t('appPage.noAppsFiltered', { tab: tabs.find(tb => tb.id === activeTab)?.label })}
                        </h4>
                        <p className="text-gray-500 text-sm">
                            {activeTab === 'all' ? t('appPage.noAppsHint') : t('appPage.noAppsOther')}
                        </p>
                    </div>
                )}
            </div>

            {/* Cancellation Request Modal */}
            {
                cancelRequestModal && (
                    <div className="fixed inset-0 z-50 flex items-center justify-center p-4" onClick={() => setCancelRequestModal(null)}>
                        <div className="absolute inset-0 bg-black/50 backdrop-blur-sm" />
                        <div className="relative bg-white rounded-2xl max-w-md w-full p-6 shadow-2xl" onClick={e => e.stopPropagation()}>
                            <button onClick={() => setCancelRequestModal(null)} className="absolute top-4 right-4 text-gray-400 hover:text-gray-600">
                                <X size={20} />
                            </button>

                            <div className="flex items-center gap-3 mb-5">
                                <div className="w-10 h-10 bg-amber-100 rounded-xl flex items-center justify-center text-amber-600">
                                    <AlertTriangle size={20} />
                                </div>
                                <div>
                                    <h3 className="text-lg font-bold text-gray-900">{t('appPage.cancelModalTitle')}</h3>
                                    <p className="text-sm text-gray-500">{cancelRequestModal.venue_name}</p>
                                </div>
                            </div>

                            <div className="bg-amber-50 border border-amber-200 rounded-xl p-3 mb-5 text-sm text-amber-800">
                                <p className="font-bold mb-1">⚠️ {t('appPage.cancelNotice')}</p>
                                <p>{t('appPage.cancelNoticeDesc')}</p>
                            </div>

                            <label className="block text-sm font-bold text-gray-700 mb-2">
                                {t('appPage.cancelReasonLabel')} <span className="text-red-500">*</span>
                            </label>
                            <textarea
                                value={cancelReason}
                                onChange={e => setCancelReason(e.target.value)}
                                placeholder={t('appPage.cancelReasonPlaceholder')}
                                rows={4}
                                className="w-full border border-gray-200 rounded-xl p-3 text-sm focus:outline-none focus:ring-2 focus:ring-amber-200 focus:border-amber-400 resize-none"
                            />

                            <div className="flex gap-3 mt-5">
                                <button
                                    onClick={() => setCancelRequestModal(null)}
                                    className="flex-1 py-3 border border-gray-200 rounded-xl text-sm font-bold text-gray-600 hover:bg-gray-50 transition-colors"
                                >
                                    {t('appPage.closeBtn')}
                                </button>
                                <button
                                    onClick={handleCancelRequest}
                                    disabled={submittingRequest || !cancelReason.trim()}
                                    className="flex-1 py-3 bg-amber-500 text-white rounded-xl text-sm font-bold hover:bg-amber-600 transition-colors disabled:opacity-50 flex items-center justify-center gap-2"
                                >
                                    <Send size={14} />
                                    {submittingRequest ? t('appPage.sending') : t('appPage.sendCancelRequest')}
                                </button>
                            </div>
                        </div>
                    </div>
                )
            }
        </div>
    );
};

