                                    </div>

                                    {/* Progress Bar */}
                                    <div className="mt-5">
                                        <div className="w-full h-1.5 bg-gray-100 rounded-full overflow-hidden flex">
                                            <div className={`h-full transition-all duration-1000 ${p.status === 'rejected' ? 'bg-red-500 w-full'
                                                : p.status === 'confirmed' ? 'bg-emerald-500 w-full'
