                                {selectedPlan.plan_type === 'package' ? <Layers size={20} /> : <CreditCard size={20} />}
                            </div>
                            <div>
                                <h3 className="text-lg font-bold text-gray-900">{t('paymentsPage.confirmTitle')}</h3>
                                <p className="text-sm text-gray-500">{t('paymentsPage.confirmDesc')}</p>
                            </div>
                        </div>

                        {/* Plan Summary */}
                        <div className={`border rounded-xl p-4 mb-5 ${selectedPlan.plan_type === 'package' ? 'bg-amber-50 border-amber-200' : 'bg-indigo-50 border-indigo-200'}`}>
                            <div className="flex items-center gap-2 mb-1">
                                {selectedPlan.plan_type === 'package' && (
                                    <span className="px-2 py-0.5 bg-amber-200 text-amber-700 rounded-full text-[10px] font-bold">{t('paymentsPage.packageBadge')}</span>
                                )}
                                <h4 className="font-bold text-gray-900 text-lg">{selectedPlan.name}</h4>
                            </div>
                            {selectedPlan.description && <p className="text-sm text-gray-600 mb-2 leading-relaxed whitespace-pre-line">{selectedPlan.description}</p>}
                            <p className={`text-2xl font-extrabold ${selectedPlan.plan_type === 'package' ? 'text-amber-600' : 'text-indigo-600'}`}>
                                ₩{parseInt(selectedPlan.amount || 0).toLocaleString()}
                                <span className="text-sm text-gray-400 font-medium ml-1">/ {PERIOD_LABEL[selectedPlan.period] || t('paymentsPage.periodMonthly')}</span>
                            </p>
                            {selectedPlan.features && selectedPlan.features.length > 0 && (
                                <div className="mt-3 pt-3 border-t border-gray-200 space-y-1.5">
                                    {selectedPlan.features.map((f, i) => (
                                        <div key={i} className="flex items-center gap-2 text-sm text-gray-600">
                                            <CheckCircle size={14} className={`${selectedPlan.plan_type === 'package' ? 'text-amber-500' : 'text-emerald-500'} flex-shrink-0`} /> {f}
                                        </div>
                                    ))}
                                </div>
                            )}
                        </div>

                        {/* Account Preview */}
                        {settings?.bank_name && (
                            <div className="bg-gray-50 border border-gray-200 rounded-xl p-4 mb-5">
                                <p className="text-xs font-bold text-gray-400 mb-2">{t('paymentsPage.depositAccount')}</p>
                                <div className="flex items-center justify-between">
                                    <div>
                                        <p className="text-sm font-bold text-gray-900">{settings.bank_name} {settings.account_number}</p>
                                        <p className="text-xs text-gray-400">{t('paymentsPage.holderLabel', { name: settings.account_holder })}</p>
                                    </div>
                                    <button onClick={() => copyToClipboard(settings.account_number)}
                                        className="p-2 bg-gray-200 text-gray-600 rounded-lg hover:bg-gray-300 transition-colors">
                                        <Copy size={16} />
                                    </button>
                                </div>
                            </div>
                        )}

                        <div className="bg-amber-50 border border-amber-200 rounded-xl p-3 mb-5 text-xs text-amber-700">
                            <p className="font-bold">{t('paymentsPage.paymentNotice')}</p>
                            <p className="text-amber-600">{t('paymentsPage.paymentNoticeDesc')}</p>
                        </div>

                        <div className="flex gap-3">
                            <button onClick={() => setSelectedPlan(null)}
                                className="flex-1 py-3 border border-gray-200 rounded-xl text-sm font-bold text-gray-600 hover:bg-gray-50 transition-colors">{t('paymentsPage.cancelBtn')}</button>
                            <button onClick={() => handleCreatePayment(selectedPlan)} disabled={creating}
                                className={`flex-1 py-3 text-white rounded-xl text-sm font-bold transition-colors disabled:opacity-50 ${selectedPlan.plan_type === 'package' ? 'bg-amber-500 hover:bg-amber-600' : 'bg-indigo-600 hover:bg-indigo-700'}`}>
                                {creating ? t('paymentsPage.creating') : t('paymentsPage.startPayment')}
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* ═══ Submit Deposit Modal ═══ */}
            {submitModal && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4" onClick={() => setSubmitModal(null)}>
                    <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" />
                    <div className="relative bg-white border border-gray-200 rounded-2xl max-w-md w-full p-6 shadow-2xl" onClick={e => e.stopPropagation()}
                        style={{ animation: 'popupScale 0.3s ease' }}>
                        <button onClick={() => setSubmitModal(null)} className="absolute top-4 right-4 text-gray-400 hover:text-gray-600"><X size={20} /></button>

                        <div className="flex items-center gap-3 mb-5">
                            <div className="w-10 h-10 bg-emerald-100 rounded-xl flex items-center justify-center text-emerald-600"><Send size={20} /></div>
                            <div>
                                <h3 className="text-lg font-bold text-gray-900">{t('paymentsPage.depositReportTitle')}</h3>
                                <p className="text-sm text-gray-500">₩{parseInt(submitModal.amount || 0).toLocaleString()}</p>
                            </div>
                        </div>

                        {settings?.bank_name && (
                            <div className="bg-indigo-50 border border-indigo-200 rounded-xl p-4 mb-5">
                                <p className="text-xs font-bold text-indigo-600 mb-2">{t('paymentsPage.depositInstruction')}</p>
                                <div className="flex items-center justify-between">
                                    <div>
                                        <p className="font-bold text-gray-900">{settings.bank_name} {settings.account_number}</p>
                                        <p className="text-xs text-gray-500">{t('paymentsPage.holderLabel', { name: settings.account_holder })}</p>
                                    </div>
                                    <button onClick={() => copyToClipboard(settings.account_number)}
                                        className="p-2 bg-indigo-100 text-indigo-600 rounded-lg hover:bg-indigo-200 transition-colors">
                                        <Copy size={16} />
                                    </button>
                                </div>
                            </div>
                        )}

                        <label className="block text-sm font-bold text-gray-700 mb-2">
                            {t('paymentsPage.depositorName')} <span className="text-red-500">*</span>
                        </label>
                        <input type="text" value={depositorName} onChange={e => setDepositorName(e.target.value)}
                            placeholder={t('paymentsPage.depositorPlaceholder')}
                            className="w-full bg-gray-50 border border-gray-200 rounded-xl px-4 py-3 text-sm text-gray-900 placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-indigo-500/30 focus:border-indigo-400 mb-5" />

                        <div className="bg-amber-50 border border-amber-200 rounded-xl p-3 mb-5 text-xs text-amber-700">
                            <p className="font-bold">{t('paymentsPage.depositNotice')}</p>
                            <p className="text-amber-600">{t('paymentsPage.depositNoticeDesc')}</p>
                        </div>

                        <div className="flex gap-3">
                            <button onClick={() => setSubmitModal(null)}
                                className="flex-1 py-3 border border-gray-200 rounded-xl text-sm font-bold text-gray-600 hover:bg-gray-50 transition-colors">{t('paymentsPage.closeBtn')}</button>
                            <button onClick={handleSubmitDeposit} disabled={submitting || !depositorName.trim()}
                                className="flex-1 py-3 bg-emerald-600 text-white rounded-xl text-sm font-bold hover:bg-emerald-700 transition-colors disabled:opacity-50 flex items-center justify-center gap-2">
                                <Send size={14} /> {submitting ? t('paymentsPage.reporting') : t('paymentsPage.reportDeposit')}
                            </button>
                        </div>
                    </div>
                </div>
            )}

            <style>{`
                @keyframes popupScale {
                    from { transform: scale(0.9) translateY(10px); opacity: 0; }
                    to { transform: scale(1) translateY(0); opacity: 1; }
                }
            `}</style>
        </div>
    );
};

export default SellerPayments;

import React, { useState, useRef, useEffect } from 'react';
import { useAuth } from '../../context/AuthContext';
import { useToast } from '../../context/ToastContext';
import { useTranslation } from 'react-i18next';
import { User, Mail, Phone, Building, Lock, Save, Camera, Tag, Instagram, ImagePlus, Trash2, Eye, EyeOff, ArrowUp, ArrowDown, Globe, FileText } from 'lucide-react';
import { useDemoGuard } from '../../hooks/useDemoGuard';
import KeywordSelector from '../../components/KeywordSelector';
import { formatBusinessNumber } from '../../utils/validation';
import { getBusinessRegConfig } from '../../utils/businessRegConfig';

const SellerProfile = () => {
    const { user, updateUserProfile, refreshUser, changePassword } = useAuth();
    const { showToast } = useToast();
    const { t } = useTranslation('seller');
    const { isDemoUser, demoAlert } = useDemoGuard();

    const CATEGORY_OPTIONS = [
        { value: 'fashion', label: t('profilePage.categoryFashion') },
        { value: 'beauty', label: t('profilePage.categoryBeauty') },
        { value: 'food', label: t('profilePage.categoryFood') },
        { value: 'living', label: t('profilePage.categoryLiving') },
        { value: 'art', label: t('profilePage.categoryArt') },
        { value: 'stationery', label: t('profilePage.categoryStationery') },
        { value: 'digital', label: t('profilePage.categoryDigital') },
        { value: 'activity', label: t('profilePage.categoryActivity') },
        { value: 'eco', label: t('profilePage.categoryEco') },
        { value: 'pet', label: t('profilePage.categoryPet') },
        { value: 'kids', label: t('profilePage.categoryKids') },
        { value: 'handmade', label: t('profilePage.categoryHandmade') },
        { value: 'vintage', label: t('profilePage.categoryVintage') },
        { value: 'perfume', label: t('profilePage.categoryPerfume') },
        { value: 'book', label: t('profilePage.categoryBook') },
        { value: 'other', label: t('profilePage.categoryOther') }
    ];
    const COUNTRY_OPTIONS_LIST = [
        { value: 'ko', label: '🇰🇷 대한민국 (Korea)' },
        { value: 'vi', label: '🇻🇳 Việt Nam' },
        { value: 'ja', label: '🇯🇵 日本 (Japan)' },
        { value: 'en', label: '🇺🇸 United States' },
        { value: 'en-GB', label: '🇬🇧 United Kingdom' },
        { value: 'en-CA', label: '🇨🇦 Canada (English)' },
        { value: 'fr-CA', label: '🇨🇦 Canada (Français)' },
        { value: 'th', label: '🇹🇭 ประเทศไทย (Thailand)' },
        { value: 'km', label: '🇰🇭 កម្ពុជា (Cambodia)' },
        { value: 'ru', label: '🇷🇺 Россия (Russia)' },
        { value: 'uk', label: '🇺🇦 Україна (Ukraine)' },
    ];
    const fileInputRef = useRef(null);
    const [uploading, setUploading] = useState(false);

    // Initialize profile with current user data
    const [profile, setProfile] = useState({
        name: user.name || '',
        email: user.email || '',
        brandName: user.brandName || user.brand_name || '',
        phone: user.phone || '',
        description: user.description || '',
        category: user.category || '',
        instagram: user.instagram || '',
        country: user.country || 'ko',
        realName: user.real_name || '',
        nameEn: user.name_en || '',
        businessNumber: user.business_no || '',
    });
    const [keywords, setKeywords] = useState(() => {
        try {
            if (user.keywords) {
                return typeof user.keywords === 'string' ? JSON.parse(user.keywords) : user.keywords;
            }
        } catch (e) { }
        return [];
    });
    const [saving, setSaving] = useState(false);
    const [sellerPhotos, setSellerPhotos] = useState([]);
    const [photoUploading, setPhotoUploading] = useState(false);
    const photoInputRef = useRef(null);

    const [previewImage, setPreviewImage] = useState(user.profile_image || null);

    // Visibility toggle state
    const [isPublic, setIsPublic] = useState(() => {
        const val = user.is_public;
        return val === undefined || val === null || val === '1' || val === 1 ? true : false;
    });
    const [togglingVisibility, setTogglingVisibility] = useState(false);

    // Sync local profile + preview with user context whenever it changes
    useEffect(() => {
        setProfile({
            name: user.name || '',
            email: user.email || '',
            brandName: user.brandName || user.brand_name || '',
            phone: user.phone || '',
            description: user.description || '',
            category: user.category || '',
            instagram: user.instagram || '',
            country: user.country || 'ko',
            realName: user.real_name || '',
            nameEn: user.name_en || '',
            businessNumber: user.business_no || '',
        });
        try {
            if (user.keywords) {
                setKeywords(typeof user.keywords === 'string' ? JSON.parse(user.keywords) : user.keywords);
            }
        } catch (e) { }
        if (user.profile_image) {
            setPreviewImage(user.profile_image);
        }
        // Sync visibility
        const val = user.is_public;
        setIsPublic(val === undefined || val === null || val === '1' || val === 1 ? true : false);
    }, [user]);

    // Fetch seller product photos
    useEffect(() => {
        const fetchPhotos = async () => {
            try {
                const res = await fetch(`/api/users/get_seller_photos.php`, { credentials: 'include' });
                const data = await res.json();
                if (data.success) {
                    setSellerPhotos(data.photos);
                }
            } catch (err) {
                console.error('Failed to load seller photos:', err);
            }
        };
        fetchPhotos();
    }, []);

    const [passwordData, setPasswordData] = useState({
        newPassword: '',
        confirmPassword: ''
    });

    const handleChange = (e) => {
        setProfile({ ...profile, [e.target.name]: e.target.value });
    };

    const handlePhoneChange = (e) => {
        const raw = e.target.value.replace(/[^0-9]/g, '');
        let formatted = raw;
        if (raw.length > 3 && raw.length <= 7) {
            formatted = raw.slice(0, 3) + '-' + raw.slice(3);
        } else if (raw.length > 7) {
            formatted = raw.slice(0, 3) + '-' + raw.slice(3, 7) + '-' + raw.slice(7, 11);
        }
        setProfile({ ...profile, phone: formatted });
    };

    const handlePasswordChange = (e) => {
        setPasswordData({ ...passwordData, [e.target.name]: e.target.value });
    };

    const handleImageUpload = async (e) => {
        if (isDemoUser) { demoAlert('프로필 이미지 변경'); e.target.value = ''; return; }
        const file = e.target.files[0];
        if (!file) return;

        // Show instant local preview
        const localPreview = URL.createObjectURL(file);
        setPreviewImage(localPreview);

        setUploading(true);
        const formData = new FormData();
        formData.append('image', file);

        try {
            const response = await fetch('/api/users/upload_profile_image.php', {
                method: 'POST',
                credentials: 'include',
                body: formData
            });

            const responseText = await response.text();
            console.log('Upload response status:', response.status);
            console.log('Upload response body:', responseText);

            let data;
            try {
                data = JSON.parse(responseText);
            } catch (parseErr) {
                console.error('Failed to parse response:', responseText);
                showToast(t('profilePage.serverParseError'), 'error');
                // Keep local preview even if server response parsing fails
                return;
            }

            if (data.success) {
                // Use server URL for persistent display
                setPreviewImage(data.imageUrl);
                await refreshUser();
                showToast(t('profilePage.profileImageUpdated'), 'success');
            } else {
                // Revert preview on failure
                setPreviewImage(user.profile_image || null);
                showToast(data.message || t('profilePage.profileUploadFailed'), 'error');
            }
        } catch (error) {
            console.error('Upload error:', error);
            setPreviewImage(user.profile_image || null);
            showToast(t('profilePage.uploadError') + error.message, 'error');
        } finally {
            setUploading(false);
            if (fileInputRef.current) fileInputRef.current.value = '';
            URL.revokeObjectURL(localPreview);
        }
    };

    const triggerFileInput = () => {
        fileInputRef.current.click();
    };

    const handlePhotoUpload = async (e) => {
        if (isDemoUser) { demoAlert('사진 업로드'); e.target.value = ''; return; }
        const files = Array.from(e.target.files);
        if (!files.length) return;

        const remaining = 10 - sellerPhotos.length;
        if (remaining <= 0) {
            showToast(t('profilePage.maxPhotos'), 'warning');
            return;
        }

        const toUpload = files.slice(0, remaining);
        if (files.length > remaining) {
            showToast(t('profilePage.remainingPhotos', { count: remaining }), 'warning');
        }

        setPhotoUploading(true);
        let successCount = 0;
        let lastError = null;

        for (const file of toUpload) {
            const formData = new FormData();
            formData.append('photo', file);

            try {
                const res = await fetch('/api/users/upload_seller_photos.php', {
                    method: 'POST',
                    credentials: 'include',
                    body: formData
                });
                const data = await res.json();
                if (data.success) {
                    setSellerPhotos(prev => [...prev, data.photo]);
                    successCount++;
                } else {
                    lastError = data.message || t('profilePage.photoUploadFailed');
                }
            } catch (err) {
                console.error('Photo upload error:', err);
                lastError = t('profilePage.photoUploadError');
            }
        }

        if (successCount > 0) {
            showToast(t('profilePage.photosUploaded', { count: successCount }), 'success');
        }
        if (lastError) {
            showToast(lastError, 'error');
        }

        setPhotoUploading(false);
        e.target.value = '';
    };

    const handleDeletePhoto = async (photoId) => {
        if (isDemoUser) { demoAlert('사진 삭제'); return; }
        if (!confirm(t('profilePage.deletePhotoConfirm'))) return;
        try {
            const res = await fetch('/api/users/delete_seller_photo.php', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                credentials: 'include',
                body: JSON.stringify({ photo_id: photoId })
            });
            const data = await res.json();
            if (data.success) {
                setSellerPhotos(prev => prev.filter(p => p.id !== photoId));
            } else {
                showToast(data.message || t('profilePage.deleteFailed'), 'error');
            }
        } catch (err) {
            showToast(t('common:error'), 'error');
        }
    };

    const movePhoto = async (index, direction) => {
        if (isDemoUser) { demoAlert('사진 순서 변경'); return; }
        const newPhotos = [...sellerPhotos];
        const targetIndex = index + direction;
        if (targetIndex < 0 || targetIndex >= newPhotos.length) return;
        [newPhotos[index], newPhotos[targetIndex]] = [newPhotos[targetIndex], newPhotos[index]];
        setSellerPhotos(newPhotos);
        try {
            await fetch('/api/users/reorder_seller_photos.php', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                credentials: 'include',
                body: JSON.stringify({ order: newPhotos.map(p => p.id) })
            });
        } catch (err) {
            console.error('Reorder error:', err);
        }
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        if (isDemoUser) { demoAlert('프로필 수정'); return; }
        setSaving(true);
        try {
            const result = await updateUserProfile({ ...profile, keywords });
            if (result?.success !== false) {
                // Re-fetch user from server to ensure AuthContext is fully synced
                await refreshUser();
                showToast(t('profilePage.profileUpdated'), 'success');
            } else {
                showToast(result.message || t('profilePage.profileUpdateFailed'), 'error');
            }
        } catch (error) {
            console.error('Profile update failed:', error);
            showToast(t('profilePage.profileUpdateFailed'), 'error');
        } finally {
            setSaving(false);
        }
    };

    const submitPasswordChange = () => {
        if (isDemoUser) { demoAlert('비밀번호 변경'); return; }
        if (passwordData.newPassword.length < 4) {
            showToast(t('profilePage.passwordMinLength'), 'warning');
            return;
        }
        if (passwordData.newPassword !== passwordData.confirmPassword) {
            showToast(t('profilePage.passwordMismatch'), 'warning');
            return;
        }
        changePassword(user.email, passwordData.newPassword);
        setPasswordData({ newPassword: '', confirmPassword: '' });
        showToast(t('profilePage.passwordChanged'), 'success');
    };

    const toggleVisibility = async () => {
        if (isDemoUser) { demoAlert('공개 설정 변경'); return; }
        setTogglingVisibility(true);
        try {
            const newValue = isPublic ? 0 : 1;
            const result = await updateUserProfile({ is_public: newValue });
            if (result?.success !== false) {
                setIsPublic(!isPublic);
                await refreshUser();
            } else {
                showToast(result.message || t('profilePage.visibilityFailed'), 'error');
            }
        } catch (error) {
            console.error('Visibility toggle failed:', error);
            showToast(t('profilePage.visibilityError'), 'error');
        } finally {
            setTogglingVisibility(false);
        }
    };

    return (
        <div className="max-w-4xl mx-auto pb-20 space-y-12">

            {/* Profile Header */}
            <div className="bg-white rounded-3xl p-6 md:p-8 shadow-sm border border-gray-100 flex flex-col md:flex-row items-center gap-8 relative overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-32 bg-gradient-to-r from-indigo-500 to-purple-500 opacity-10"></div>

                <div className="relative group">
                    <div className="w-32 h-32 rounded-full bg-gradient-to-tr from-indigo-100 to-purple-100 flex items-center justify-center text-4xl font-bold text-indigo-600 shadow-inner border-4 border-white overflow-hidden">
                        {previewImage ? (
                            <img src={previewImage} alt="Profile" className="w-full h-full object-cover" onError={() => setPreviewImage(null)} />
                        ) : (
                            user.name[0]
                        )}
                    </div>

                    <input
                        type="file"
                        ref={fileInputRef}
                        onChange={handleImageUpload}
                        className="hidden"
                        accept="image/*"
                    />

                    <button
                        onClick={triggerFileInput}
                        disabled={uploading}
                        className="absolute bottom-1 right-1 p-2 bg-indigo-600 rounded-full text-white shadow-lg hover:bg-indigo-700 transition-colors disabled:opacity-50"
                    >
                        {uploading ? (
                            <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                        ) : (
                            <Camera size={16} />
                        )}
                    </button>
                </div>

                <div className="text-center md:text-left z-10">
                    <h2 className="text-3xl font-extrabold text-gray-900 mb-2">{user.name}</h2>
                    <p className="text-gray-500 font-medium mb-4">{user.email}</p>
                    <span className="px-4 py-1.5 bg-indigo-50 text-indigo-700 rounded-full text-sm font-bold border border-indigo-100">
                        {user.role === 'superadmin' ? 'Super Admin' : user.role === 'admin' ? 'Admin' : user.role === 'host' ? 'Host Account' : 'Seller Account'}
                    </span>
                </div>
            </div>

            {/* Visibility Toggle Card */}
            {user.role === 'seller' && (
                <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
                    <div className="p-5 md:p-6 flex items-center justify-between gap-4">
                        <div className="flex items-center gap-4">
                            <div className={`w-12 h-12 rounded-xl flex items-center justify-center transition-colors duration-300 ${isPublic
                                ? 'bg-emerald-50 text-emerald-600'
                                : 'bg-gray-100 text-gray-400'
                                }`}>
                                {isPublic ? <Eye size={22} /> : <EyeOff size={22} />}
                            </div>
                            <div>
                                <h3 className="text-sm font-bold text-gray-900">{t('profilePage.visibilityTitle')}</h3>
                                <p className="text-xs text-gray-400 mt-0.5">
                                    {isPublic
                                        ? t('profilePage.visibilityPublic')
                                        : t('profilePage.visibilityHidden')}
                                </p>
                            </div>
                        </div>
                        <button
                            type="button"
                            onClick={toggleVisibility}
                            disabled={togglingVisibility}
                            className={`relative w-14 h-8 rounded-full transition-colors duration-300 focus:outline-none focus:ring-4 focus:ring-offset-1 disabled:opacity-50 flex-shrink-0 ${isPublic
                                ? 'bg-emerald-500 focus:ring-emerald-500/20'
                                : 'bg-gray-300 focus:ring-gray-300/20'
                                }`}
                        >
                            <span className={`absolute top-1 left-1 w-6 h-6 bg-white rounded-full shadow-md transition-transform duration-300 flex items-center justify-center ${isPublic ? 'translate-x-6' : 'translate-x-0'
                                }`}>
                                {togglingVisibility && (
                                    <div className="w-3 h-3 border-2 border-gray-300 border-t-transparent rounded-full animate-spin"></div>
                                )}
                            </span>
                        </button>
                    </div>
                </div>
            )}

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                {/* Main Profile Form */}
                <div className="lg:col-span-2 space-y-8">
                    <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
                        <div className="p-6 border-b border-gray-100">
                            <h3 className="text-lg font-bold text-gray-900 flex items-center gap-2">
                                <User className="text-indigo-500" size={20} />
                                {t('profilePage.basicInfo')}
                            </h3>
                        </div>

                        <form onSubmit={handleSubmit} className="p-5 md:p-8 space-y-6">
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                <div>
                                    <label className="block text-sm font-bold text-gray-700 mb-2">
                                        <User size={14} className="inline mr-1 text-indigo-500" />
                                        {t('profilePage.realName', '실명')}
                                    </label>
                                    <input
                                        type="text"
                                        name="realName"
                                        value={profile.realName}
                                        onChange={handleChange}
                                        className="w-full px-4 py-3 bg-gray-50 border border-transparent rounded-xl focus:bg-white focus:border-indigo-500 focus:ring-4 focus:ring-indigo-500/10 transition-all outline-none font-medium"
                                        placeholder={t('profilePage.realNamePlaceholder', '실명을 입력하세요')}
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm font-bold text-gray-700 mb-2">{t('profilePage.contactName')}</label>
                                    <input
                                        type="text"
                                        name="name"
                                        value={profile.name}
                                        onChange={handleChange}
                                        className="w-full px-4 py-3 bg-gray-50 border border-transparent rounded-xl focus:bg-white focus:border-indigo-500 focus:ring-4 focus:ring-indigo-500/10 transition-all outline-none font-medium"
                                    />
                                </div>
                            </div>

                            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                {!['admin', 'superadmin'].includes(user.role) && (
                                    <div>
                                        <label className="block text-sm font-bold text-gray-700 mb-2">{t('profilePage.brandName')}</label>
                                        <input
                                            type="text"
                                            name="brandName"
                                            value={profile.brandName}
                                            onChange={handleChange}
                                            className="w-full px-4 py-3 bg-gray-50 border border-transparent rounded-xl focus:bg-white focus:border-indigo-500 focus:ring-4 focus:ring-indigo-500/10 transition-all outline-none font-medium"
                                            placeholder={t('profilePage.brandPlaceholder')}
                                        />
                                    </div>
                                )}
                                <div>
                                    <label className="block text-sm font-bold text-gray-700 mb-2">
                                        <Globe size={14} className="inline mr-1 text-indigo-500" />
                                        {t('profilePage.nameEn', '영문 이름')}
                                    </label>
                                    <input
                                        type="text"
                                        name="nameEn"
                                        value={profile.nameEn}
                                        onChange={handleChange}
                                        className="w-full px-4 py-3 bg-gray-50 border border-transparent rounded-xl focus:bg-white focus:border-indigo-500 focus:ring-4 focus:ring-indigo-500/10 transition-all outline-none font-medium"
                                        placeholder={t('profilePage.nameEnPlaceholder', 'English name')}
                                    />
                                    <p className="text-xs text-gray-400 mt-1">{t('profilePage.nameEnHelp', '영문 표기 이름 (선택)')}</p>
                                </div>
                            </div>

                            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                <div>
                                    <label className="block text-sm font-bold text-gray-700 mb-2">{t('profilePage.emailAccount')}</label>
                                    <div className="relative opacity-60">
                                        <Mail className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                                        <input
                                            type="email"
                                            value={profile.email}
                                            disabled
                                            className="w-full pl-12 pr-4 py-3 bg-gray-100 border border-transparent rounded-xl cursor-not-allowed font-medium text-gray-500"
                                        />
                                    </div>
                                    <p className="text-xs text-gray-400 mt-1">{t('profilePage.emailReadOnly', '이메일 계정은 변경할 수 없습니다')}</p>
                                </div>
                                <div>
                                    <label className="block text-sm font-bold text-gray-700 mb-2">{t('profilePage.phone')}</label>
                                    <div className="relative">
                                        <Phone className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                                        <input
                                            type="tel"
                                            name="phone"
                                            value={profile.phone}
                                            onChange={handlePhoneChange}
                                            placeholder="010-0000-0000"
                                            maxLength={13}
                                            className="w-full pl-12 pr-4 py-3 bg-gray-50 border border-transparent rounded-xl focus:bg-white focus:border-indigo-500 focus:ring-4 focus:ring-indigo-500/10 transition-all outline-none font-medium"
                                        />
                                    </div>
                                </div>
                            </div>

                            {/* Country & Business Number */}
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                <div>
                                    <label className="block text-sm font-bold text-gray-700 mb-2">
                                        <Globe size={14} className="inline mr-1 text-indigo-500" />
                                        {t('profilePage.country', '국가')}
                                    </label>
                                    <select
                                        name="country"
                                        value={profile.country}
                                        onChange={(e) => {
                                            setProfile(prev => ({ ...prev, country: e.target.value, businessNumber: '' }));
                                        }}
                                        className="w-full px-4 py-3 bg-gray-50 border border-transparent rounded-xl focus:bg-white focus:border-indigo-500 focus:ring-4 focus:ring-indigo-500/10 transition-all outline-none font-medium appearance-none"
                                    >
                                        {COUNTRY_OPTIONS_LIST.map(c => (
                                            <option key={c.value} value={c.value}>{c.label}</option>
                                        ))}
                                    </select>
                                </div>
                                {!['admin', 'superadmin'].includes(user.role) && (() => {
                                    const bizConfig = getBusinessRegConfig(profile.country);
                                    return (
                                        <div>
                                            <label className="block text-sm font-bold text-gray-700 mb-2">
                                                <FileText size={14} className="inline mr-1 text-indigo-500" />
                                                {t(`profilePage.businessNumber`, t('profilePage.businessNumberDefault', '사업자등록번호'))}
                                            </label>
                                            <input
                                                type="text"
                                                name="businessNumber"
                                                value={profile.businessNumber}
                                                onChange={(e) => {
                                                    const formatted = formatBusinessNumber(e.target.value, profile.country);
                                                    setProfile(prev => ({ ...prev, businessNumber: formatted }));
                                                }}
                                                className="w-full px-4 py-3 bg-gray-50 border border-transparent rounded-xl focus:bg-white focus:border-indigo-500 focus:ring-4 focus:ring-indigo-500/10 transition-all outline-none font-medium"
                                                placeholder={bizConfig.placeholder}
                                                maxLength={bizConfig.maxLength}
                                            />
                                            <p className="text-xs text-gray-400 mt-1">{t('profilePage.businessNumberHelp', '사업자등록번호를 입력하세요')}</p>
                                        </div>
                                    );
                                })()}
                            </div>

                            {/* Category & Instagram */}
                            {user.role === 'seller' && (
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                    <div>
                                        <label className="block text-sm font-bold text-gray-700 mb-2">
                                            <Tag size={14} className="inline mr-1 text-indigo-500" />
                                            {t('profilePage.categoryLabel')}
                                        </label>
                                        <select
                                            name="category"
                                            value={profile.category}
                                            onChange={handleChange}
                                            className="w-full px-4 py-3 bg-gray-50 border border-transparent rounded-xl focus:bg-white focus:border-indigo-500 focus:ring-4 focus:ring-indigo-500/10 transition-all outline-none font-medium appearance-none"
                                        >
                                            <option value="">{t('profilePage.categorySelect')}</option>
                                            {CATEGORY_OPTIONS.map(c => (
                                                <option key={c.value} value={c.value}>{c.label}</option>
                                            ))}
                                        </select>
                                    </div>
                                    <div>
                                        <label className="block text-sm font-bold text-gray-700 mb-2">
                                            <Instagram size={14} className="inline mr-1 text-pink-500" />
                                            {t('profilePage.instagram')}
                                        </label>
                                        <input
                                            type="text"
                                            name="instagram"
                                            value={profile.instagram}
                                            onChange={handleChange}
                                            className="w-full px-4 py-3 bg-gray-50 border border-transparent rounded-xl focus:bg-white focus:border-indigo-500 focus:ring-4 focus:ring-indigo-500/10 transition-all outline-none font-medium"
                                            placeholder="@username"
                                        />
                                    </div>
                                </div>
                            )}

                            {/* Product Photos */}
                            {user.role === 'seller' && (
                                <div>
                                    <label className="block text-sm font-bold text-gray-700 mb-2">
                                        <ImagePlus size={14} className="inline mr-1 text-emerald-500" />
                                        {t('profilePage.productPhotos')}
                                    </label>
                                    <p className="text-xs text-gray-400 mb-3">{t('profilePage.productPhotosDesc')}</p>
                                    <div className="grid grid-cols-3 sm:grid-cols-5 gap-3">
                                        {sellerPhotos.map((photo, idx) => (
                                            <div key={photo.id} className="relative group aspect-square rounded-xl overflow-hidden border border-gray-200 bg-gray-50">
                                                <img src={photo.image_url} alt={t('profilePage.productAlt')} className="w-full h-full object-cover" />
                                                <div className="absolute inset-0 bg-black/0 group-hover:bg-black/30 transition-all" />
                                                <div className="absolute top-1 left-1 flex flex-col gap-0.5 opacity-0 group-hover:opacity-100 transition-opacity">
                                                    {idx > 0 && (
                                                        <button type="button" onClick={() => movePhoto(idx, -1)}
                                                            className="p-1 bg-white/90 rounded-md shadow hover:bg-white transition-colors">
                                                            <ArrowUp size={12} className="text-gray-700" />
                                                        </button>
                                                    )}
                                                    {idx < sellerPhotos.length - 1 && (
                                                        <button type="button" onClick={() => movePhoto(idx, 1)}
                                                            className="p-1 bg-white/90 rounded-md shadow hover:bg-white transition-colors">
                                                            <ArrowDown size={12} className="text-gray-700" />
                                                        </button>
                                                    )}
                                                </div>
                                                <button
                                                    type="button"
                                                    onClick={() => handleDeletePhoto(photo.id)}
                                                    className="absolute top-1 right-1 p-1.5 bg-red-500 text-white rounded-lg opacity-0 group-hover:opacity-100 transition-opacity shadow-lg"
                                                >
                                                    <Trash2 size={12} />
                                                </button>
                                                <span className="absolute bottom-1 left-1 text-[10px] bg-black/50 text-white px-1.5 py-0.5 rounded font-bold opacity-0 group-hover:opacity-100 transition-opacity">{idx + 1}</span>
                                            </div>
                                        ))}
                                        {sellerPhotos.length < 10 && (
                                            <button
                                                type="button"
                                                onClick={() => photoInputRef.current?.click()}
                                                disabled={photoUploading}
                                                className="aspect-square rounded-xl border-2 border-dashed border-gray-300 flex flex-col items-center justify-center text-gray-400 hover:border-indigo-400 hover:text-indigo-500 transition-colors disabled:opacity-50"
                                            >
                                                {photoUploading ? (
                                                    <div className="w-6 h-6 border-2 border-indigo-400 border-t-transparent rounded-full animate-spin"></div>
                                                ) : (
                                                    <>
                                                        <ImagePlus size={24} />
                                                        <span className="text-xs mt-1 font-medium">{t('profilePage.addPhoto')}</span>
                                                        <span className="text-[10px] text-gray-300">{sellerPhotos.length}/10</span>
                                                    </>
                                                )}
                                            </button>
                                        )}
                                    </div>
                                    <input
                                        type="file"
                                        ref={photoInputRef}
                                        onChange={handlePhotoUpload}
                                        className="hidden"
                                        accept="image/*"
                                        multiple
                                    />
                                </div>
                            )}

                            {/* Keywords */}
                            {!['admin', 'superadmin'].includes(user.role) && (
                                <div>
                                    <KeywordSelector
                                        type={user.role === 'host' ? 'host' : 'seller'}
                                        value={keywords}
                                        onChange={setKeywords}
                                    />
                                </div>
                            )}

                            <div>
                                <label className="block text-sm font-bold text-gray-700 mb-2">
                                    {['admin', 'superadmin'].includes(user.role) ? t('profilePage.descriptionAdmin') : t('profilePage.descriptionSeller')}
                                </label>
                                {!['admin', 'superadmin'].includes(user.role) && (
                                    <p className="text-xs text-gray-400 mb-2">{t('profilePage.descriptionHint')}</p>
                                )}
                                <textarea
                                    name="description"
                                    value={profile.description}
                                    onChange={handleChange}
                                    rows="5"
                                    className="w-full p-4 bg-gray-50 border border-transparent rounded-xl focus:bg-white focus:border-indigo-500 focus:ring-4 focus:ring-indigo-500/10 transition-all outline-none font-medium resize-none"
                                    placeholder={t('profilePage.descriptionPlaceholder')}
                                ></textarea>
                            </div>

                            <div className="pt-4 flex justify-end">
                                <button type="submit" disabled={saving} className="px-8 py-3 bg-indigo-600 text-white rounded-xl font-bold hover:bg-indigo-700 shadow-lg shadow-indigo-200 hover:-translate-y-0.5 transition-all flex items-center gap-2 disabled:opacity-50">
                                    <Save size={18} /> {saving ? t('profilePage.saving') : t('profilePage.saveInfo')}
                                </button>
                            </div>
                        </form>
                    </div>
                </div>

                {/* Password Change Area */}
                <div className="space-y-6">
                    <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
                        <div className="p-6 border-b border-gray-100">
                            <h3 className="text-lg font-bold text-gray-900 flex items-center gap-2">
                                <Lock className="text-rose-500" size={20} />
                                {t('profilePage.securitySettings')}
                            </h3>
                        </div>
                        <div className="p-6 space-y-4">
                            <div>
                                <label className="block text-xs font-bold text-gray-500 uppercase tracking-wider mb-2">{t('profilePage.newPassword')}</label>
                                <input
                                    type="password"
                                    name="newPassword"
                                    value={passwordData.newPassword}
                                    onChange={handlePasswordChange}
                                    placeholder={t('profilePage.newPasswordPlaceholder')}
                                    className="w-full px-4 py-3 bg-gray-50 border border-transparent rounded-xl focus:bg-white focus:border-rose-500 focus:ring-4 focus:ring-rose-500/10 transition-all outline-none font-medium"
                                />
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-gray-500 uppercase tracking-wider mb-2">{t('profilePage.confirmPassword')}</label>
                                <input
                                    type="password"
                                    name="confirmPassword"
                                    value={passwordData.confirmPassword}
                                    onChange={handlePasswordChange}
                                    placeholder={t('profilePage.confirmPasswordPlaceholder')}
                                    className="w-full px-4 py-3 bg-gray-50 border border-transparent rounded-xl focus:bg-white focus:border-rose-500 focus:ring-4 focus:ring-rose-500/10 transition-all outline-none font-medium"
                                />
                            </div>
                            <button
                                onClick={submitPasswordChange}
                                type="button"
                                className="w-full py-3 bg-white border border-gray-200 text-gray-700 rounded-xl font-bold hover:bg-gray-50 hover:border-gray-300 transition-all mt-2"
                            >
                                {t('profilePage.changePassword')}
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default SellerProfile;

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { Inbox, Clock, CheckCircle, XCircle, Ban, X, FileText, User, Calendar, MessageCircle, Package, Truck, ShoppingBag, Eye, ThumbsUp, ThumbsDown } from 'lucide-react';
import { useAuth } from '../../context/AuthContext';
import { useTranslation } from 'react-i18next';
import Toast from '../../components/Toast';

const API_BASE = '/api';

const PROPOSAL_TYPES = {
    distribution: { label: '유통', icon: Truck, color: 'teal' },
    consignment: { label: '위탁', icon: Package, color: 'violet' },
    wholesale: { label: '도매', icon: ShoppingBag, color: 'amber' }
};

const STATUS_CONFIG = {
    pending: { label: '대기', icon: Clock, bg: 'bg-amber-50 dark:bg-amber-900/20', text: 'text-amber-600 dark:text-amber-400', border: 'border-amber-200 dark:border-amber-800' },
    accepted: { label: '수락', icon: CheckCircle, bg: 'bg-emerald-50 dark:bg-emerald-900/20', text: 'text-emerald-600 dark:text-emerald-400', border: 'border-emerald-200 dark:border-emerald-800' },
    rejected: { label: '거절', icon: XCircle, bg: 'bg-rose-50 dark:bg-rose-900/20', text: 'text-rose-600 dark:text-rose-400', border: 'border-rose-200 dark:border-rose-800' },
    cancelled: { label: '취소됨', icon: Ban, bg: 'bg-gray-50 dark:bg-gray-800', text: 'text-gray-500 dark:text-gray-400', border: 'border-gray-200 dark:border-gray-700' }
};

const SellerProposals = () => {
    const { user } = useAuth();
    const { t } = useTranslation('seller');
    const [toast, setToast] = useState(null);
    const showToast = useCallback((msg, type = 'success') => setToast({ message: msg, type }), []);

    const [proposals, setProposals] = useState([]);
    const [loading, setLoading] = useState(true);
    const [statusFilter, setStatusFilter] = useState('all');
    const [selectedProposal, setSelectedProposal] = useState(null);
    const [responding, setResponding] = useState(false);
    const [responseNote, setResponseNote] = useState('');

    const fetchProposals = useCallback(async () => {
        try {
            const res = await fetch(`${API_BASE}/proposals/proposals.php`, { credentials: 'include' });
            const data = await res.json();
            if (data.success) setProposals(data.proposals || []);
        } catch (e) { console.error(e); }
        finally { setLoading(false); }
    }, []);

    useEffect(() => { fetchProposals(); }, []);

    const filteredProposals = useMemo(() => {
        if (statusFilter === 'all') return proposals;
        return proposals.filter(p => p.status === statusFilter);
    }, [proposals, statusFilter]);

    const stats = useMemo(() => ({
        total: proposals.length,
        pending: proposals.filter(p => p.status === 'pending').length,
        accepted: proposals.filter(p => p.status === 'accepted').length,
        rejected: proposals.filter(p => p.status === 'rejected').length
    }), [proposals]);

    const handleRespond = async (action) => {
        if (!selectedProposal) return;
        setResponding(true);
        try {
            const res = await fetch(`${API_BASE}/proposals/respond_proposal.php`, {
                method: 'POST', credentials: 'include',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    proposal_id: selectedProposal.id,
                    action,
                    seller_note: responseNote
                })
            });
            const data = await res.json();
            if (data.success) {
                showToast(data.message);
                setSelectedProposal(null);
                setResponseNote('');
                fetchProposals();
            } else {
                showToast(data.message, 'error');
            }
        } catch (e) {
            showToast('처리에 실패했습니다.', 'error');
        } finally { setResponding(false); }
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center h-64">
                <div className="animate-spin rounded-full h-8 w-8 border-2 border-violet-600 border-t-transparent"></div>
            </div>
        );
    }

    return (
        <>
            <div className="max-w-7xl mx-auto p-4 md:p-6">
                {/* Header */}
                <div className="mb-8">
                    <div className="flex items-center gap-3 mb-2">
                        <div className="w-10 h-10 bg-violet-100 dark:bg-violet-900/30 rounded-xl flex items-center justify-center">
                            <Inbox className="text-violet-600 dark:text-violet-400" size={22} />
                        </div>
                        <div>
                            <h1 className="text-2xl md:text-3xl font-extrabold text-gray-900 dark:text-gray-100">유통 제안 수신함</h1>
                            <p className="text-sm text-gray-500 dark:text-gray-400">벤더로부터 받은 유통 제안을 확인하세요</p>
                        </div>
                    </div>
                </div>

                {/* Stats */}
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-6">
                    {[
                        { label: '전체', value: stats.total, color: 'violet', icon: FileText },
                        { label: '대기', value: stats.pending, color: 'amber', icon: Clock },
                        { label: '수락', value: stats.accepted, color: 'emerald', icon: CheckCircle },
                        { label: '거절', value: stats.rejected, color: 'rose', icon: XCircle }
                    ].map(item => (
                        <div key={item.label} className="bg-white dark:bg-gray-800 rounded-2xl border border-gray-100 dark:border-gray-700 p-4 shadow-sm">
                            <div className="flex items-center justify-between">
                                <div>
                                    <p className="text-xs text-gray-400 dark:text-gray-500 font-medium">{item.label}</p>
                                    <p className={`text-2xl font-extrabold text-${item.color}-600 dark:text-${item.color}-400`}>{item.value}</p>
                                </div>
                                <item.icon size={24} className={`text-${item.color}-300 dark:text-${item.color}-700`} />
                            </div>
                        </div>
                    ))}
                </div>

                {/* Pending Alert */}
                {stats.pending > 0 && (
                    <div className="mb-5 p-4 bg-amber-50 dark:bg-amber-900/20 border border-amber-200 dark:border-amber-800 rounded-2xl flex items-center gap-3">
                        <Clock size={20} className="text-amber-500 flex-shrink-0" />
                        <p className="text-sm font-medium text-amber-700 dark:text-amber-300">
                            응답 대기 중인 제안이 <strong>{stats.pending}건</strong> 있습니다. 확인해 주세요!
                        </p>
                    </div>
                )}

                {/* Status Filter */}
                <div className="flex items-center gap-2 mb-5 overflow-x-auto pb-1">
                    {['all', 'pending', 'accepted', 'rejected', 'cancelled'].map(status => {
                        const config = status === 'all' ? { label: '전체' } : STATUS_CONFIG[status];
                        const count = status === 'all' ? proposals.length : proposals.filter(p => p.status === status).length;
                        return (
                            <button
                                key={status}
                                onClick={() => setStatusFilter(status)}
                                className={`flex items-center gap-1.5 px-4 py-2 rounded-xl text-sm font-bold transition-all whitespace-nowrap ${statusFilter === status
                                    ? 'bg-violet-600 text-white shadow-lg shadow-violet-200 dark:shadow-violet-900/50'
                                    : 'bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-600'
                                    }`}
                            >
                                {config.label}
                                <span className={`text-xs px-1.5 py-0.5 rounded-full ${statusFilter === status ? 'bg-white/20' : 'bg-gray-200 dark:bg-gray-600'}`}>{count}</span>
                            </button>
                        );
                    })}
                </div>

                {/* Proposals List */}
                {filteredProposals.length === 0 ? (
                    <div className="text-center py-20">
                        <Inbox className="mx-auto text-gray-300 dark:text-gray-600 mb-4" size={48} />
                        <h3 className="text-lg font-bold text-gray-400 dark:text-gray-500">받은 제안이 없습니다</h3>
                        <p className="text-sm text-gray-400 dark:text-gray-500 mt-1">벤더가 유통 제안을 보내면 여기에 표시됩니다</p>
                    </div>
                ) : (
                    <div className="space-y-3">
                        {filteredProposals.map(proposal => {
                            const statusCfg = STATUS_CONFIG[proposal.status];
                            const typeCfg = PROPOSAL_TYPES[proposal.proposal_type] || PROPOSAL_TYPES.distribution;
                            const StatusIcon = statusCfg.icon;
                            const TypeIcon = typeCfg.icon;
                            const isPending = proposal.status === 'pending';
                            return (
                                <div
                                    key={proposal.id}
                                    onClick={() => { setSelectedProposal(proposal); setResponseNote(''); }}
                                    className={`bg-white dark:bg-gray-800 rounded-2xl border ${isPending ? 'border-amber-200 dark:border-amber-800 ring-1 ring-amber-100 dark:ring-amber-900/30' : 'border-gray-100 dark:border-gray-700'} p-5 shadow-sm hover:shadow-md hover:-translate-y-0.5 transition-all cursor-pointer`}
                                >
                                    <div className="flex items-start justify-between gap-4">
                                        <div className="flex items-start gap-4 min-w-0">
                                            <div className={`w-11 h-11 ${statusCfg.bg} rounded-xl flex items-center justify-center flex-shrink-0 border ${statusCfg.border}`}>
                                                <StatusIcon size={20} className={statusCfg.text} />
                                            </div>
                                            <div className="min-w-0">
                                                <div className="flex items-center gap-2 flex-wrap">
                                                    <h3 className="font-bold text-gray-900 dark:text-gray-100 truncate">{proposal.title}</h3>
                                                    <span className={`px-2 py-0.5 rounded-lg text-[10px] font-bold ${statusCfg.bg} ${statusCfg.text} border ${statusCfg.border}`}>
                                                        {statusCfg.label}
                                                    </span>
                                                    <span className="px-2 py-0.5 rounded-lg text-[10px] font-bold bg-gray-100 dark:bg-gray-700 text-gray-500 dark:text-gray-400 flex items-center gap-0.5">
                                                        <TypeIcon size={10} /> {typeCfg.label}
                                                    </span>
                                                    {isPending && <span className="w-2 h-2 rounded-full bg-amber-400 animate-pulse"></span>}
                                                </div>
                                                <div className="flex items-center gap-3 mt-1 text-xs text-gray-400 dark:text-gray-500">
                                                    <span className="flex items-center gap-1"><User size={12} /> {proposal.vendor_name || proposal.vendor_company || '벤더'}</span>
                                                    <span className="flex items-center gap-1"><Calendar size={12} /> {new Date(proposal.created_at).toLocaleDateString('ko-KR')}</span>
                                                </div>
                                            </div>
                                        </div>
                                        {isPending ? (
                                            <span className="text-xs font-bold text-amber-500 bg-amber-50 dark:bg-amber-900/20 px-2 py-1 rounded-lg whitespace-nowrap">응답 필요</span>
                                        ) : (
                                            <Eye size={16} className="text-gray-300 dark:text-gray-600 flex-shrink-0 mt-1" />
                                        )}
                                    </div>
                                    {proposal.message && (
                                        <p className="text-xs text-gray-500 dark:text-gray-400 mt-3 pl-[60px] line-clamp-2">{proposal.message}</p>
                                    )}
                                </div>
                            );
                        })}
                    </div>
                )}

                {/* Detail & Response Modal */}
                {selectedProposal && (
                    <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center p-4" onClick={() => setSelectedProposal(null)}>
                        <div className="bg-white dark:bg-gray-800 rounded-3xl shadow-2xl w-full max-w-lg overflow-hidden" onClick={e => e.stopPropagation()}>
                            <div className="bg-gradient-to-br from-violet-600 via-purple-600 to-fuchsia-600 p-6 text-white">
                                <div className="flex justify-between items-start">
                                    <div>
                                        <h2 className="text-xl font-extrabold">{selectedProposal.title}</h2>
                                        <div className="flex items-center gap-2 mt-2">
                                            <span className="px-2.5 py-0.5 bg-white/20 rounded-lg text-xs font-bold">{STATUS_CONFIG[selectedProposal.status].label}</span>
                                            <span className="px-2.5 py-0.5 bg-white/20 rounded-lg text-xs font-bold">{PROPOSAL_TYPES[selectedProposal.proposal_type]?.label || '유통'}</span>
                                        </div>
                                    </div>
                                    <button onClick={() => setSelectedProposal(null)} className="text-white/80 hover:text-white p-1"><X size={22} /></button>
                                </div>
                            </div>
                            <div className="p-6 space-y-4 max-h-[60vh] overflow-y-auto">
                                {/* Vendor info */}
                                <div className="flex items-center gap-3 p-4 bg-gray-50 dark:bg-gray-700 rounded-xl">
                                    <div className="w-10 h-10 bg-gradient-to-br from-violet-500 to-purple-500 rounded-lg flex items-center justify-center text-white font-bold">
                                        {(selectedProposal.vendor_name || selectedProposal.vendor_company)?.[0] || 'V'}
                                    </div>
                                    <div>
                                        <p className="font-bold text-gray-900 dark:text-gray-100">{selectedProposal.vendor_name || '벤더'}</p>
                                        <p className="text-xs text-gray-400">{selectedProposal.vendor_company || ''}</p>
                                    </div>
                                </div>

                                {/* Message */}
                                {selectedProposal.message && (
                                    <div className="p-4 bg-violet-50 dark:bg-violet-900/20 rounded-xl border border-violet-100 dark:border-violet-800">
                                        <p className="text-xs font-bold text-violet-500 dark:text-violet-400 uppercase mb-1">제안 상세 내용</p>
                                        <p className="text-sm text-gray-700 dark:text-gray-300 whitespace-pre-wrap">{selectedProposal.message}</p>
                                    </div>
                                )}

                                {/* Dates */}
                                <div className="grid grid-cols-2 gap-3">
                                    <div className="p-3 bg-gray-50 dark:bg-gray-700 rounded-xl">
                                        <p className="text-xs text-gray-400 dark:text-gray-500">받은 날짜</p>
                                        <p className="text-sm font-medium text-gray-800 dark:text-gray-200">{new Date(selectedProposal.created_at).toLocaleDateString('ko-KR')}</p>
                                    </div>
                                    {selectedProposal.responded_at && (
                                        <div className="p-3 bg-gray-50 dark:bg-gray-700 rounded-xl">
                                            <p className="text-xs text-gray-400 dark:text-gray-500">응답 날짜</p>
                                            <p className="text-sm font-medium text-gray-800 dark:text-gray-200">{new Date(selectedProposal.responded_at).toLocaleDateString('ko-KR')}</p>
                                        </div>
                                    )}
                                </div>

                                {/* Already responded */}
                                {selectedProposal.status !== 'pending' && selectedProposal.seller_note && (
                                    <div className={`p-4 rounded-xl border ${selectedProposal.status === 'accepted' ? 'bg-emerald-50 dark:bg-emerald-900/20 border-emerald-200 dark:border-emerald-800' : 'bg-rose-50 dark:bg-rose-900/20 border-rose-200 dark:border-rose-800'}`}>
                                        <p className={`text-xs font-bold uppercase mb-1 ${selectedProposal.status === 'accepted' ? 'text-emerald-500' : 'text-rose-500'}`}>내 답변</p>
                                        <p className="text-sm text-gray-700 dark:text-gray-300 whitespace-pre-wrap">{selectedProposal.seller_note}</p>
                                    </div>
                                )}

                                {/* Response form (pending only) */}
                                {selectedProposal.status === 'pending' && (
                                    <div className="space-y-3 pt-2 border-t border-gray-100 dark:border-gray-700">
                                        <p className="text-xs font-bold text-gray-500 dark:text-gray-400 uppercase">답변하기</p>
                                        <textarea
                                            value={responseNote}
                                            onChange={e => setResponseNote(e.target.value)}
                                            placeholder="답변 메시지를 작성하세요 (선택사항)"
                                            rows={3}
                                            className="w-full px-4 py-3 bg-gray-50 dark:bg-gray-700 rounded-xl border border-transparent focus:border-violet-500 outline-none font-medium text-sm dark:text-gray-100 dark:placeholder-gray-500 resize-none"
                                        />
                                        <div className="grid grid-cols-2 gap-3">
                                            <button
                                                onClick={() => handleRespond('reject')}
                                                disabled={responding}
                                                className="py-3 bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300 rounded-xl font-bold text-sm hover:bg-rose-50 hover:text-rose-600 dark:hover:bg-rose-900/20 dark:hover:text-rose-400 transition-colors flex items-center justify-center gap-2"
                                            >
                                                <ThumbsDown size={16} /> 거절
                                            </button>
                                            <button
                                                onClick={() => handleRespond('accept')}
                                                disabled={responding}
                                                className="py-3 bg-gradient-to-r from-emerald-500 to-teal-500 text-white rounded-xl font-bold text-sm hover:from-emerald-400 hover:to-teal-400 shadow-lg shadow-emerald-200/50 dark:shadow-emerald-900/50 transition-all flex items-center justify-center gap-2"
                                            >
                                                <ThumbsUp size={16} /> {responding ? '처리 중...' : '수락'}
                                            </button>
                                        </div>
                                    </div>
                                )}

                                {/* Chat button for accepted */}
                                {selectedProposal.status === 'accepted' && (
                                    <button
                                        onClick={() => window.location.href = `/seller/chat?user=${selectedProposal.vendor_id}`}
                                        className="w-full py-3 bg-gradient-to-r from-violet-500 to-purple-500 text-white rounded-xl font-bold text-sm hover:from-violet-400 hover:to-purple-400 shadow-lg shadow-violet-200/50 dark:shadow-violet-900/50 transition-all flex items-center justify-center gap-2"
                                    >
                                        <MessageCircle size={16} /> 벤더와 채팅하기
                                    </button>
                                )}
                            </div>
                        </div>
                    </div>
                )}
            </div>
            {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
        </>
    );
};

export default SellerProposals;

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { Wallet, Clock, CheckCircle, X, FileText, User, Calendar, DollarSign, Percent, AlertCircle, Eye, CreditCard, Ban, MessageSquare } from 'lucide-react';
import { useAuth } from '../../context/AuthContext';
import Toast from '../../components/Toast';

const API_BASE = '/api';

const STATUS_CONFIG = {
    pending: { label: '대기', bg: 'bg-amber-50 dark:bg-amber-900/20', text: 'text-amber-600 dark:text-amber-400', border: 'border-amber-200 dark:border-amber-800' },
    confirmed: { label: '확인', bg: 'bg-cyan-50 dark:bg-cyan-900/20', text: 'text-cyan-600 dark:text-cyan-400', border: 'border-cyan-200 dark:border-cyan-800' },
    paid: { label: '지급', bg: 'bg-emerald-50 dark:bg-emerald-900/20', text: 'text-emerald-600 dark:text-emerald-400', border: 'border-emerald-200 dark:border-emerald-800' },
    disputed: { label: '이의', bg: 'bg-red-50 dark:bg-red-900/20', text: 'text-red-600 dark:text-red-400', border: 'border-red-200 dark:border-red-800' }
};

const SellerSettlements = () => {
    const { user } = useAuth();
    const [toast, setToast] = useState(null);
    const showToast = useCallback((msg, type = 'success') => setToast({ message: msg, type }), []);

    const [settlements, setSettlements] = useState([]);
    const [stats, setStats] = useState({});
    const [loading, setLoading] = useState(true);
    const [statusFilter, setStatusFilter] = useState('all');
    const [selectedSettlement, setSelectedSettlement] = useState(null);
    const [updating, setUpdating] = useState(false);
    const [sellerNote, setSellerNote] = useState('');

    const fetchSettlements = useCallback(async () => {
        try {
            const res = await fetch(`${API_BASE}/settlements/settlements.php`, { credentials: 'include' });
            const data = await res.json();
            if (data.success) {
                setSettlements(data.settlements || []);
                setStats(data.stats || {});
            }
        } catch (e) { console.error(e); }
        finally { setLoading(false); }
    }, []);

    useEffect(() => { fetchSettlements(); }, []);

    const filteredSettlements = useMemo(() => {
        if (statusFilter === 'all') return settlements;
        return settlements.filter(s => s.status === statusFilter);
    }, [settlements, statusFilter]);

    const pendingCount = useMemo(() => settlements.filter(s => s.status === 'pending').length, [settlements]);

    const handleAction = async (action) => {
        if (!selectedSettlement) return;
        if (action === 'dispute' && !sellerNote.trim()) {
            showToast('이의 사유를 입력해 주세요.', 'error');
            return;
        }
        setUpdating(true);
        try {
            const body = { settlement_id: selectedSettlement.id, action };
            if (sellerNote.trim()) body.note = sellerNote;

            const res = await fetch(`${API_BASE}/settlements/update_settlement.php`, {
                method: 'POST', credentials: 'include',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(body)
            });
            const data = await res.json();
            if (data.success) {
                showToast(data.message);
                setSelectedSettlement(null);
                setSellerNote('');
                fetchSettlements();
            } else { showToast(data.message, 'error'); }
        } catch (e) { showToast('처리에 실패했습니다.', 'error'); }
        finally { setUpdating(false); }
    };

    const formatCurrency = (n) => Number(n || 0).toLocaleString('ko-KR') + '원';

    if (loading) {
        return (
            <div className="flex items-center justify-center h-64">
                <div className="animate-spin rounded-full h-8 w-8 border-2 border-teal-600 border-t-transparent"></div>
            </div>
        );
    }

    return (
        <>
            <div className="max-w-7xl mx-auto p-4 md:p-6">
                {/* Header */}
                <div className="mb-8">
                    <div className="flex items-center gap-3">
                        <div className="w-10 h-10 bg-teal-100 dark:bg-teal-900/30 rounded-xl flex items-center justify-center">
                            <Wallet className="text-teal-600 dark:text-teal-400" size={22} />
                        </div>
                        <div>
                            <h1 className="text-2xl md:text-3xl font-extrabold text-gray-900 dark:text-gray-100">정산 관리</h1>
                            <p className="text-sm text-gray-500 dark:text-gray-400">받은 정산을 확인하고 관리합니다</p>
                        </div>
                    </div>
                </div>

                {/* Stats */}
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-6">
                    {[
                        { label: '총 거래', value: formatCurrency(stats.total_amount), icon: DollarSign, color: 'teal' },
                        { label: '정산 금액', value: formatCurrency(stats.total_net), icon: Wallet, color: 'violet' },
                        { label: '미확인', value: formatCurrency(stats.pending_amount), icon: Clock, color: 'amber' },
                        { label: '지급 완료', value: formatCurrency(stats.paid_amount), icon: CheckCircle, color: 'emerald' }
                    ].map(item => (
                        <div key={item.label} className="bg-white dark:bg-gray-800 rounded-2xl border border-gray-100 dark:border-gray-700 p-4 shadow-sm">
                            <div className="flex items-center justify-between mb-2">
                                <p className="text-xs text-gray-400 dark:text-gray-500 font-medium">{item.label}</p>
                                <item.icon size={18} className={`text-${item.color}-400 dark:text-${item.color}-600`} />
                            </div>
                            <p className="text-lg font-extrabold text-gray-900 dark:text-gray-100">{item.value}</p>
                        </div>
                    ))}
                </div>

                {/* Pending Alert */}
                {pendingCount > 0 && (
                    <div className="mb-6 bg-gradient-to-r from-amber-50 to-orange-50 dark:from-amber-900/20 dark:to-orange-900/20 border border-amber-200 dark:border-amber-700/50 rounded-2xl p-4 flex items-center gap-3">
                        <AlertCircle className="text-amber-500 flex-shrink-0" size={20} />
                        <p className="text-sm font-medium text-amber-800 dark:text-amber-300">
                            확인 대기 중인 정산이 <strong>{pendingCount}건</strong> 있습니다.
                        </p>
                    </div>
                )}

                {/* Status Tabs */}
                <div className="flex items-center gap-2 mb-5 overflow-x-auto pb-1">
                    {['all', 'pending', 'confirmed', 'paid', 'disputed'].map(status => {
                        const config = status === 'all' ? { label: '전체' } : STATUS_CONFIG[status];
                        const count = status === 'all' ? settlements.length : settlements.filter(s => s.status === status).length;
                        return (
                            <button
                                key={status}
                                onClick={() => setStatusFilter(status)}
                                className={`flex items-center gap-1.5 px-4 py-2 rounded-xl text-sm font-bold transition-all whitespace-nowrap ${statusFilter === status
                                    ? 'bg-teal-600 text-white shadow-lg shadow-teal-200 dark:shadow-teal-900/50'
                                    : 'bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-600'
                                    }`}
                            >
                                {config.label}
                                <span className={`text-xs px-1.5 py-0.5 rounded-full ${statusFilter === status ? 'bg-white/20' : 'bg-gray-200 dark:bg-gray-600'}`}>{count}</span>
                            </button>
                        );
                    })}
                </div>

                {/* List */}
                {filteredSettlements.length === 0 ? (
                    <div className="text-center py-20">
                        <Wallet className="mx-auto text-gray-300 dark:text-gray-600 mb-4" size={48} />
                        <h3 className="text-lg font-bold text-gray-400 dark:text-gray-500">정산 내역이 없습니다</h3>
                        <p className="text-sm text-gray-400 dark:text-gray-500 mt-1">벤더로부터 정산이 등록되면 여기에 표시됩니다</p>
                    </div>
                ) : (
                    <div className="space-y-3">
                        {filteredSettlements.map(st => {
                            const statusCfg = STATUS_CONFIG[st.status];
                            const isPending = st.status === 'pending';
                            return (
                                <div
                                    key={st.id}
                                    onClick={() => { setSelectedSettlement(st); setSellerNote(''); }}
                                    className={`bg-white dark:bg-gray-800 rounded-2xl border p-5 shadow-sm hover:shadow-md hover:-translate-y-0.5 transition-all cursor-pointer ${isPending ? 'border-amber-200 dark:border-amber-700 ring-1 ring-amber-100 dark:ring-amber-900/30' : 'border-gray-100 dark:border-gray-700'}`}
                                >
                                    <div className="flex items-center justify-between gap-4">
                                        <div className="min-w-0">
                                            <div className="flex items-center gap-2 flex-wrap">
                                                <h3 className="font-bold text-gray-900 dark:text-gray-100 truncate">{st.shipment_title || `정산 #${st.id}`}</h3>
                                                <span className={`px-2 py-0.5 rounded-lg text-[10px] font-bold ${statusCfg.bg} ${statusCfg.text} border ${statusCfg.border}`}>{statusCfg.label}</span>
                                                {isPending && <span className="px-2 py-0.5 bg-amber-100 dark:bg-amber-900/30 text-amber-600 dark:text-amber-400 rounded-lg text-[10px] font-bold animate-pulse">확인 필요</span>}
                                            </div>
                                            <div className="flex items-center gap-4 mt-1 text-xs text-gray-400 dark:text-gray-500">
                                                <span className="flex items-center gap-1"><User size={12} /> {st.vendor_name}</span>
                                                <span className="flex items-center gap-1"><Calendar size={12} /> {new Date(st.created_at).toLocaleDateString('ko-KR')}</span>
                                            </div>
                                        </div>
                                        <div className="text-right flex-shrink-0">
                                            <p className="text-lg font-extrabold text-emerald-600 dark:text-emerald-400">{formatCurrency(st.net_amount)}</p>
                                            <p className="text-xs text-gray-400">수수료 {st.commission_rate}%</p>
                                        </div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                )}

                {/* Detail Modal */}
                {selectedSettlement && (
                    <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center p-4" onClick={() => setSelectedSettlement(null)}>
                        <div className="bg-white dark:bg-gray-800 rounded-3xl shadow-2xl w-full max-w-md overflow-hidden" onClick={e => e.stopPropagation()}>
                            <div className="bg-gradient-to-br from-teal-600 via-emerald-600 to-green-600 p-6 text-white">
                                <div className="flex justify-between items-start">
                                    <div>
                                        <h2 className="text-xl font-extrabold">{selectedSettlement.shipment_title || `정산 #${selectedSettlement.id}`}</h2>
                                        <span className="inline-block mt-2 px-2.5 py-0.5 bg-white/20 rounded-lg text-xs font-bold">{STATUS_CONFIG[selectedSettlement.status].label}</span>
                                    </div>
                                    <button onClick={() => setSelectedSettlement(null)} className="text-white/80 hover:text-white p-1"><X size={22} /></button>
                                </div>
                            </div>
                            <div className="p-6 space-y-4 max-h-[60vh] overflow-y-auto">
                                <div className="flex items-center gap-3 p-4 bg-gray-50 dark:bg-gray-700 rounded-xl">
                                    <div className="w-10 h-10 bg-gradient-to-br from-indigo-500 to-violet-500 rounded-lg flex items-center justify-center text-white font-bold">
                                        {selectedSettlement.vendor_name?.[0] || 'V'}
                                    </div>
                                    <div>
                                        <p className="font-bold text-gray-900 dark:text-gray-100">{selectedSettlement.vendor_name}</p>
                                        <p className="text-xs text-gray-400">{selectedSettlement.vendor_company || '벤더'}</p>
                                    </div>
                                </div>

                                <div className="space-y-2">
                                    {[
                                        { label: '거래 금액', value: formatCurrency(selectedSettlement.amount), highlight: false },
                                        { label: `수수료 (${selectedSettlement.commission_rate}%)`, value: `- ${formatCurrency(selectedSettlement.commission_amount)}`, highlight: false },
                                        { label: '받을 금액', value: formatCurrency(selectedSettlement.net_amount), highlight: true }
                                    ].map(row => (
                                        <div key={row.label} className={`flex items-center justify-between p-3 rounded-xl ${row.highlight ? 'bg-emerald-50 dark:bg-emerald-900/20 border border-emerald-200 dark:border-emerald-800' : 'bg-gray-50 dark:bg-gray-700'}`}>
                                            <span className={`text-sm ${row.highlight ? 'font-bold text-emerald-700 dark:text-emerald-300' : 'text-gray-500 dark:text-gray-400'}`}>{row.label}</span>
                                            <span className={`text-sm ${row.highlight ? 'font-extrabold text-emerald-700 dark:text-emerald-300' : 'font-medium text-gray-800 dark:text-gray-200'}`}>{row.value}</span>
                                        </div>
                                    ))}
                                </div>

                                {selectedSettlement.vendor_note && (
                                    <div className="p-4 bg-gray-50 dark:bg-gray-700 rounded-xl">
                                        <p className="text-xs font-bold text-gray-500 dark:text-gray-400 uppercase mb-1">벤더 메모</p>
                                        <p className="text-sm text-gray-700 dark:text-gray-300 whitespace-pre-wrap">{selectedSettlement.vendor_note}</p>
                                    </div>
                                )}

                                <div className="grid grid-cols-2 gap-3">
                                    {[
                                        { label: '등록일', date: selectedSettlement.created_at },
                                        { label: '확인일', date: selectedSettlement.confirmed_at },
                                        { label: '지급일', date: selectedSettlement.paid_at },
                                    ].filter(t => t.date).map(t => (
                                        <div key={t.label} className="p-3 bg-gray-50 dark:bg-gray-700 rounded-xl">
                                            <p className="text-xs text-gray-400">{t.label}</p>
                                            <p className="text-sm font-medium text-gray-800 dark:text-gray-200">{new Date(t.date).toLocaleDateString('ko-KR')}</p>
                                        </div>
                                    ))}
                                </div>

                                {selectedSettlement.status === 'pending' && (
                                    <div className="space-y-3 pt-2 border-t border-gray-100 dark:border-gray-700">
                                        <div>
                                            <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 uppercase mb-2">메모 (이의 제기 시 필수)</label>
                                            <textarea
                                                value={sellerNote}
                                                onChange={e => setSellerNote(e.target.value)}
                                                placeholder="메모를 남기세요"
                                                rows={2}
                                                className="w-full px-4 py-3 bg-gray-50 dark:bg-gray-700 rounded-xl border border-transparent focus:border-teal-500 outline-none font-medium text-sm dark:text-gray-100 dark:placeholder-gray-500 resize-none"
                                            />
                                        </div>
                                        <button
                                            onClick={() => handleAction('confirm')}
                                            disabled={updating}
                                            className="w-full py-3 bg-gradient-to-r from-cyan-500 to-teal-500 text-white rounded-xl font-bold text-sm hover:from-cyan-400 hover:to-teal-400 shadow-lg transition-all flex items-center justify-center gap-2"
                                        >
                                            <CheckCircle size={16} /> {updating ? '처리 중...' : '정산 확인'}
                                        </button>
                                        <button
                                            onClick={() => handleAction('dispute')}
                                            disabled={updating}
                                            className="w-full py-3 bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300 rounded-xl font-bold text-sm hover:bg-red-50 hover:text-red-600 dark:hover:bg-red-900/20 dark:hover:text-red-400 transition-colors flex items-center justify-center gap-2"
                                        >
                                            <Ban size={16} /> 이의 제기
                                        </button>
                                    </div>
                                )}
                            </div>
                        </div>
                    </div>
                )}
            </div>
            {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
        </>
    );
};

export default SellerSettlements;

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { Truck, Clock, CheckCircle, XCircle, Ban, X, FileText, User, Calendar, Package, DollarSign, ClipboardList, MapPin, Eye, AlertCircle } from 'lucide-react';
import { useAuth } from '../../context/AuthContext';
import Toast from '../../components/Toast';

const API_BASE = '/api';

const STATUS_CONFIG = {
    ordered: { label: '발주', icon: ClipboardList, bg: 'bg-blue-50 dark:bg-blue-900/20', text: 'text-blue-600 dark:text-blue-400', border: 'border-blue-200 dark:border-blue-800' },
    confirmed: { label: '확인', icon: CheckCircle, bg: 'bg-cyan-50 dark:bg-cyan-900/20', text: 'text-cyan-600 dark:text-cyan-400', border: 'border-cyan-200 dark:border-cyan-800' },
    shipping: { label: '배송중', icon: Truck, bg: 'bg-violet-50 dark:bg-violet-900/20', text: 'text-violet-600 dark:text-violet-400', border: 'border-violet-200 dark:border-violet-800' },
    delivered: { label: '입고', icon: Package, bg: 'bg-emerald-50 dark:bg-emerald-900/20', text: 'text-emerald-600 dark:text-emerald-400', border: 'border-emerald-200 dark:border-emerald-800' },
    completed: { label: '완료', icon: CheckCircle, bg: 'bg-teal-50 dark:bg-teal-900/20', text: 'text-teal-600 dark:text-teal-400', border: 'border-teal-200 dark:border-teal-800' },
    cancelled: { label: '취소', icon: Ban, bg: 'bg-gray-50 dark:bg-gray-800', text: 'text-gray-500 dark:text-gray-400', border: 'border-gray-200 dark:border-gray-700' }
};

const SellerShipments = () => {
    const { user } = useAuth();
    const [toast, setToast] = useState(null);
    const showToast = useCallback((msg, type = 'success') => setToast({ message: msg, type }), []);

    const [shipments, setShipments] = useState([]);
    const [loading, setLoading] = useState(true);
    const [statusFilter, setStatusFilter] = useState('all');
    const [selectedShipment, setSelectedShipment] = useState(null);
    const [updating, setUpdating] = useState(false);
    const [sellerMemo, setSellerMemo] = useState('');

    const fetchShipments = useCallback(async () => {
        try {
            const res = await fetch(`${API_BASE}/shipments/shipments.php`, { credentials: 'include' });
            const data = await res.json();
            if (data.success) setShipments(data.shipments || []);
        } catch (e) { console.error(e); }
        finally { setLoading(false); }
    }, []);

    useEffect(() => { fetchShipments(); }, []);

    const filteredShipments = useMemo(() => {
        if (statusFilter === 'all') return shipments;
        return shipments.filter(s => s.status === statusFilter);
    }, [shipments, statusFilter]);

    const stats = useMemo(() => ({
        total: shipments.length,
        pending: shipments.filter(s => s.status === 'ordered').length,
        shipping: shipments.filter(s => s.status === 'shipping').length,
        completed: shipments.filter(s => s.status === 'completed').length
    }), [shipments]);

    const handleAction = async (action) => {
        if (!selectedShipment) return;
        setUpdating(true);
        try {
            const body = { shipment_id: selectedShipment.id, action };
            if (sellerMemo) body.memo = sellerMemo;

            const res = await fetch(`${API_BASE}/shipments/update_shipment.php`, {
                method: 'POST', credentials: 'include',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(body)
            });
            const data = await res.json();
            if (data.success) {
                showToast(data.message);
                setSelectedShipment(null);
                setSellerMemo('');
                fetchShipments();
            } else { showToast(data.message, 'error'); }
        } catch (e) { showToast('처리에 실패했습니다.', 'error'); }
        finally { setUpdating(false); }
    };

    const formatCurrency = (n) => Number(n || 0).toLocaleString('ko-KR') + '원';

    if (loading) {
        return (
            <div className="flex items-center justify-center h-64">
                <div className="animate-spin rounded-full h-8 w-8 border-2 border-teal-600 border-t-transparent"></div>
            </div>
        );
    }

    return (
        <>
            <div className="max-w-7xl mx-auto p-4 md:p-6">
                {/* Header */}
                <div className="mb-8">
                    <div className="flex items-center gap-3 mb-2">
                        <div className="w-10 h-10 bg-teal-100 dark:bg-teal-900/30 rounded-xl flex items-center justify-center">
                            <Truck className="text-teal-600 dark:text-teal-400" size={22} />
                        </div>
                        <div>
                            <h1 className="text-2xl md:text-3xl font-extrabold text-gray-900 dark:text-gray-100">배송 관리</h1>
                            <p className="text-sm text-gray-500 dark:text-gray-400">입고 확인 및 배송 현황을 관리합니다</p>
                        </div>
                    </div>
                </div>

                {/* Stats */}
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-6">
                    {[
                        { label: '전체', value: stats.total, color: 'teal', icon: FileText },
                        { label: '대기중', value: stats.pending, color: 'amber', icon: AlertCircle },
                        { label: '배송중', value: stats.shipping, color: 'violet', icon: Truck },
                        { label: '완료', value: stats.completed, color: 'emerald', icon: CheckCircle }
                    ].map(item => (
                        <div key={item.label} className="bg-white dark:bg-gray-800 rounded-2xl border border-gray-100 dark:border-gray-700 p-4 shadow-sm">
                            <div className="flex items-center justify-between">
                                <div>
                                    <p className="text-xs text-gray-400 dark:text-gray-500 font-medium">{item.label}</p>
                                    <p className={`text-2xl font-extrabold text-${item.color}-600 dark:text-${item.color}-400`}>{item.value}</p>
                                </div>
                                <item.icon size={24} className={`text-${item.color}-300 dark:text-${item.color}-700`} />
                            </div>
                        </div>
                    ))}
                </div>

                {/* Pending Alert */}
                {stats.pending > 0 && (
                    <div className="mb-6 bg-gradient-to-r from-amber-50 to-orange-50 dark:from-amber-900/20 dark:to-orange-900/20 border border-amber-200 dark:border-amber-700/50 rounded-2xl p-4 flex items-center gap-3">
                        <AlertCircle className="text-amber-500 flex-shrink-0" size={20} />
                        <p className="text-sm font-medium text-amber-800 dark:text-amber-300">
                            확인 대기 중인 발주가 <strong>{stats.pending}건</strong> 있습니다.
                        </p>
                    </div>
                )}

                {/* Status Tabs */}
                <div className="flex items-center gap-2 mb-5 overflow-x-auto pb-1">
                    {['all', 'ordered', 'confirmed', 'shipping', 'delivered', 'completed', 'cancelled'].map(status => {
                        const config = status === 'all' ? { label: '전체' } : STATUS_CONFIG[status];
                        const count = status === 'all' ? shipments.length : shipments.filter(s => s.status === status).length;
                        return (
                            <button
                                key={status}
                                onClick={() => setStatusFilter(status)}
                                className={`flex items-center gap-1.5 px-4 py-2 rounded-xl text-sm font-bold transition-all whitespace-nowrap ${statusFilter === status
                                    ? 'bg-teal-600 text-white shadow-lg shadow-teal-200 dark:shadow-teal-900/50'
                                    : 'bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-600'
                                    }`}
                            >
                                {config.label}
                                <span className={`text-xs px-1.5 py-0.5 rounded-full ${statusFilter === status ? 'bg-white/20' : 'bg-gray-200 dark:bg-gray-600'}`}>{count}</span>
                            </button>
                        );
                    })}
                </div>

                {/* Shipment List */}
                {filteredShipments.length === 0 ? (
                    <div className="text-center py-20">
                        <Truck className="mx-auto text-gray-300 dark:text-gray-600 mb-4" size={48} />
                        <h3 className="text-lg font-bold text-gray-400 dark:text-gray-500">배송 내역이 없습니다</h3>
                        <p className="text-sm text-gray-400 dark:text-gray-500 mt-1">벤더로부터 발주를 받으면 여기에 표시됩니다</p>
                    </div>
                ) : (
                    <div className="space-y-3">
                        {filteredShipments.map(ship => {
                            const statusCfg = STATUS_CONFIG[ship.status];
                            const StatusIcon = statusCfg.icon;
                            const isPending = ship.status === 'ordered';
                            return (
                                <div
                                    key={ship.id}
                                    onClick={() => { setSelectedShipment(ship); setSellerMemo(''); }}
                                    className={`bg-white dark:bg-gray-800 rounded-2xl border p-5 shadow-sm hover:shadow-md hover:-translate-y-0.5 transition-all cursor-pointer ${isPending ? 'border-amber-200 dark:border-amber-700 ring-1 ring-amber-100 dark:ring-amber-900/30' : 'border-gray-100 dark:border-gray-700'}`}
                                >
                                    <div className="flex items-start justify-between gap-4">
                                        <div className="flex items-start gap-4 min-w-0">
                                            <div className={`w-11 h-11 ${statusCfg.bg} rounded-xl flex items-center justify-center flex-shrink-0 border ${statusCfg.border}`}>
                                                <StatusIcon size={20} className={statusCfg.text} />
                                            </div>
                                            <div className="min-w-0">
                                                <div className="flex items-center gap-2 flex-wrap">
                                                    <h3 className="font-bold text-gray-900 dark:text-gray-100 truncate">{ship.order_title}</h3>
                                                    <span className={`px-2 py-0.5 rounded-lg text-[10px] font-bold ${statusCfg.bg} ${statusCfg.text} border ${statusCfg.border}`}>
                                                        {statusCfg.label}
                                                    </span>
                                                    {isPending && <span className="px-2 py-0.5 bg-amber-100 dark:bg-amber-900/30 text-amber-600 dark:text-amber-400 rounded-lg text-[10px] font-bold animate-pulse">확인 필요</span>}
                                                </div>
                                                <div className="flex items-center gap-3 mt-1 text-xs text-gray-400 dark:text-gray-500">
                                                    <span className="flex items-center gap-1"><User size={12} /> {ship.vendor_name}</span>
                                                    <span className="flex items-center gap-1"><Calendar size={12} /> {new Date(ship.ordered_at).toLocaleDateString('ko-KR')}</span>
                                                    <span className="flex items-center gap-1 font-medium text-gray-600 dark:text-gray-300"><DollarSign size={12} /> {formatCurrency(ship.total_amount)}</span>
                                                </div>
                                                {ship.tracking_number && (
                                                    <p className="text-xs text-violet-500 dark:text-violet-400 mt-1 flex items-center gap-1"><MapPin size={11} /> {ship.courier} {ship.tracking_number}</p>
                                                )}
                                            </div>
                                        </div>
                                        <Eye size={16} className="text-gray-300 dark:text-gray-600 flex-shrink-0 mt-1" />
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                )}

                {/* Detail Modal */}
                {selectedShipment && (
                    <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center p-4" onClick={() => setSelectedShipment(null)}>
                        <div className="bg-white dark:bg-gray-800 rounded-3xl shadow-2xl w-full max-w-lg overflow-hidden" onClick={e => e.stopPropagation()}>
                            <div className="bg-gradient-to-br from-teal-600 via-emerald-600 to-green-600 p-6 text-white">
                                <div className="flex justify-between items-start">
                                    <div>
                                        <h2 className="text-xl font-extrabold">{selectedShipment.order_title}</h2>
                                        <div className="flex items-center gap-2 mt-2">
                                            <span className="px-2.5 py-0.5 bg-white/20 rounded-lg text-xs font-bold">{STATUS_CONFIG[selectedShipment.status].label}</span>
                                            <span className="px-2.5 py-0.5 bg-white/20 rounded-lg text-xs font-bold">{formatCurrency(selectedShipment.total_amount)}</span>
                                        </div>
                                    </div>
                                    <button onClick={() => setSelectedShipment(null)} className="text-white/80 hover:text-white p-1"><X size={22} /></button>
                                </div>
                            </div>
                            <div className="p-6 space-y-4 max-h-[60vh] overflow-y-auto">
                                {/* Vendor */}
                                <div className="flex items-center gap-3 p-4 bg-gray-50 dark:bg-gray-700 rounded-xl">
                                    <div className="w-10 h-10 bg-gradient-to-br from-indigo-500 to-violet-500 rounded-lg flex items-center justify-center text-white font-bold">
                                        {selectedShipment.vendor_name?.[0] || 'V'}
                                    </div>
                                    <div>
                                        <p className="font-bold text-gray-900 dark:text-gray-100">{selectedShipment.vendor_name}</p>
                                        <p className="text-xs text-gray-400">{selectedShipment.vendor_company || '벤더'}</p>
                                    </div>
                                </div>

                                {/* Items */}
                                {selectedShipment.items?.length > 0 && (
                                    <div>
                                        <p className="text-xs font-bold text-gray-500 dark:text-gray-400 uppercase mb-2">품목 내역</p>
                                        <div className="space-y-2">
                                            {selectedShipment.items.map((item, i) => (
                                                <div key={i} className="flex items-center justify-between p-3 bg-gray-50 dark:bg-gray-700 rounded-xl">
                                                    <span className="text-sm font-medium text-gray-800 dark:text-gray-200">{item.name}</span>
                                                    <span className="text-sm text-gray-500 dark:text-gray-400">{item.quantity}개 × {formatCurrency(item.unit_price)}</span>
                                                </div>
                                            ))}
                                            <div className="flex justify-between p-3 bg-teal-50 dark:bg-teal-900/20 rounded-xl border border-teal-200 dark:border-teal-800">
                                                <span className="text-sm font-bold text-teal-700 dark:text-teal-300">합계</span>
                                                <span className="text-sm font-extrabold text-teal-700 dark:text-teal-300">{formatCurrency(selectedShipment.total_amount)}</span>
                                            </div>
                                        </div>
                                    </div>
                                )}

                                {/* Tracking */}
                                {selectedShipment.tracking_number && (
                                    <div className="p-4 bg-violet-50 dark:bg-violet-900/20 rounded-xl border border-violet-200 dark:border-violet-800">
                                        <p className="text-xs font-bold text-violet-500 uppercase mb-1">배송 정보</p>
                                        <p className="text-sm text-gray-700 dark:text-gray-300">{selectedShipment.courier} — {selectedShipment.tracking_number}</p>
                                    </div>
                                )}

                                {/* Vendor Memo */}
                                {selectedShipment.vendor_memo && (
                                    <div className="p-4 bg-gray-50 dark:bg-gray-700 rounded-xl">
                                        <p className="text-xs font-bold text-gray-500 dark:text-gray-400 uppercase mb-1">벤더 메모</p>
                                        <p className="text-sm text-gray-700 dark:text-gray-300 whitespace-pre-wrap">{selectedShipment.vendor_memo}</p>
                                    </div>
                                )}

                                {/* Timeline */}
                                <div className="grid grid-cols-2 gap-3">
                                    {[
                                        { label: '발주일', date: selectedShipment.ordered_at },
                                        { label: '확인일', date: selectedShipment.confirmed_at },
