            const expData = filteredExpenses.map(e => [e.expense_date, parseInt(e.amount), getExpenseCatLabel(e.category), e.payment_method, e.memo || '']);
            const ws3 = XLSX.utils.aoa_to_sheet([...expHeader, ...expData]);
