    const workflowPresets = useMemo(() => [
        { id: 'churn_followup', name: t('statsPage.wfChurnFollowup', '이탈 위험 팔로업'), trigger: 'churn_risk', action: 'send_reminder', icon: '🚨', desc: t('statsPage.wfChurnDesc', '90일 이상 미구매 고객 자동 알림') },
